    def clockwise(maxDist: Long, weight: Long): Long = {
      findMax(p.indices, identity, maxDist, weight)
    }

    def counterClockwise(maxDist: Long, weight: Long): Long = {
      findMax(p.indices.reverse, C - _, maxDist, weight)
    }

    def turnOver: Long = {
      // 左 -> 右
      val lr = clockwise(C / 2, 2) + counterClockwise(C / 2, 1)

      // 右 -> 左
      val rl = counterClockwise(C / 2, 2) + clockwise(C / 2, 1)

      math.max(lr, rl)
