#include <bits/stdc++.h>
#define rep(i,n) for (int i = 0; i < (n); ++i)
#define all(v) v.begin(), v.end()
using namespace std;
typedef long long ll;

const ll INF = -1 * 1LL<<60;
ll N = 1;

void update(vector<ll> &value, int i, ll x) {
    // i 番目の葉の値を x に変える
    i += N - 1; // i 番目の葉のノード番号
    value[i] = x;
    while (i > 0) {
        i = (i - 1) / 2; // ノード i の親ノードの番号に変える
        value[i] = max(value[i * 2 + 1],
                       value[i * 2 + 2]); // 左右の子の max を計算しなおす
    }
}


ll query(vector<ll> &value, int a, int b, int k, int l, int r) {
    // [a, b) の区間に対するクエリについて
    // ノード k （区間 [l, r) 担当）が答える
    if (r <= a || b <= l) return INF; // 区間が被らない場合は INF を返す
    if (a <= l && r <= b)
        return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)
                         // に完全に含まれる
    else {
        ll c1 = query(value, a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
        ll c2 = query(value, a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
        return max(c1, c2); // 左右の子の値の max を取る
    }
}


int main() {
	ll n, c;
	cin >> n >> c;
	vector<ll> x(n), v(n);
	rep(i, n) cin >> x[i] >> v[i];
	vector<ll> cw(n), ccw(n);
	for(int i = 0; i < n; i++) {
		if(i > 0) {
			cw[i] = cw[i-1] + v[i] - (x[i] - x[i-1]);
			ccw[i] = ccw[i-1] + v[n-1-i] - ((c - x[n-1-i]) - (c - x[n-i]));
		} else {
			cw[i] = v[i] - x[i];
			ccw[i] = v[n-1-i] - (c - x[n-1-i]);
		}
	}
	while(N < n) N *= 2;
	vector<ll> CW(2*N-1, INF), CCW(2*N-1, INF);
	rep(i, n) {
		update(CW, i, cw[i]);
		update(CCW, i, ccw[i]);
	}
	ll ans = 0;
	rep(i, n) {
		// 時計回りにiまで行くのみ
		ans = max(ans, cw[i]);
		// 時計回りにiまで行った後、入口まで戻り、反時計回りに行く
		ll now = cw[i] - x[i] + query(CCW, 0, n-i-1, 0, 0, N);
		ans = max(ans, now);
	}
	rep(i, n) {
		// 反時計回りにiまで行くのみ
		ans = max(ans, ccw[i]);
		// 反時計回りにiまで行った後、入口まで戻り、時計回りに行く
		ll now = ccw[i] - (c - x[n-1-i]) + query(CW, 0, n-i-1, 0, 0, N);
		ans = max(ans, now);
	}

	cout << ans << endl;
	return 0;
}

