void solve(void){
	int N; ll C;
	cin >> N >> C;
	vector <ll> xs(N), vs(N), rs(N), ls(N);
	rep(N, i) {
		cin >> xs[i] >> vs[i];
	}
	ll sum = 0LL;
	rep(N, i) {
		sum += vs[i];
		rs[i] = sum - xs[i];
	}
	rep(N, i) {
		ls[i] = sum - C + xs[i];
		sum -= vs[i];
	}

	ll ans = max({rs[0], ls[0], 0LL});
	rep(N-1, i) {
		rs[i+1] = max(rs[i], rs[i+1]);
		ls[N-i-2] = max(ls[N-i-1], ls[N-i-2]);
		ans = max({rs[i+1], ls[N-i-2], ans});
	}
	//cout << rs << endl << ls << endl;
	rep(N-1, i) {
		ans = max(ans, rs[i] + ls[i+1] - min(xs[i], C - xs[i+1]));
	}
	cout << ans << endl;
}

