  //i番めまでで最大効率の通り方を保存
  macl[0] = 0;
  maic[0] = 0;
  matc[0] = 0;
  mati[0] = 0;
  for (int i = 0; i < N; i ++) {
    macl[i + 1] = macl[i] + va[i] - cl[i];
    maic[i + 1] = maic[i] + va[N - i + 1] - icl[i];
    if (macl[i + 1] < macl[i]) macl[i + 1] = macl[i];
    if (maic[i + 1] < maic[i]) maic[i + 1] = maic[i];
    matc[i + 1] = macl[i + 1] - cl[i];
    mati[i + 1] = mati[i + 1] - icl[i];
    if (matc[i + 1] < matc[i]) matc[i + 1] = matc[i];
    if (mati[i + 1] < mati[i]) mati[i + 1] = mati[i];
  }
  int ans = 0;
  for (int i = 0; i < N; i ++) {
    long long k = matc[i] + maic[N - i];
    long long j = mati[i] + macl[N - i];
    if (ans < k) ans = k;
    if (ans < j) ans = j;
  }
  cout << ans << endl;
}

