    using sushi_vect_type = std::vector<std::pair<int64_t, int64_t>>;
    sushi_vect_type sushi_vect(N);
    for(auto& i : sushi_vect){
        std::cin >> i.first >> i.second;
    }

    //Accumulated val and Max value with Clock Wise route
    int64_t accumulated = 0;
    int64_t max_score = 0;
    std::vector<int64_t> accumulate_l(N,0);
    std::vector<int64_t> left_score(N,0);
    for(int32_t i = 0; i < N; i++){
       accumulated += sushi_vect[i].second;
       accumulate_l[i] = accumulated;
       left_score[i] = std::max(max_score, accumulated - sushi_vect[i].first);
       max_score = std::max(max_score, accumulated - sushi_vect[i].first);
    }
    //Accumulated val and Max value with Coutner Clock Wise route
    accumulated = 0;
    max_score = 0;
    std::vector<int64_t> accumulate_r(N,0);
    std::vector<int64_t> right_score(N,0);
    for(int32_t i = 0; i < N; i++){
       accumulated += sushi_vect[N-1-i].second;
       accumulate_r[i] = accumulated;
       right_score[i] = std::max(max_score, accumulated - C + sushi_vect[N-1-i].first);
       max_score = std::max(max_score, accumulated - C + sushi_vect[N-1-i].first);
    }

    //debug
    //for(auto& i : left_score){
    //    std::cout << "left_score : " << i << std::endl;
    //}
    //for(auto& i : right_score){
    //    std::cout << "right_score : " << i << std::endl;
    //}

    //Score start with left and then go right
    max_score = 0;
    for(int32_t i = 0; i < N - 1; i++){
        max_score = std::max(max_score, left_score[i]);
        max_score = std::max(max_score, accumulate_l[i] - 2*sushi_vect[i].first + right_score[N-2-i]);
    }
    max_score = std::max(max_score, left_score[N-1]);

    //Score start with right and then go left
    for(int32_t i = 0; i < N - 1; i++){
        max_score = std::max(max_score, right_score[i]);
        max_score = std::max(max_score, accumulate_r[i] - 2 * (C - sushi_vect[N-1-i].first) + left_score[N-2-i]);
    }
    max_score = std::max(max_score, right_score[N-1]);

    std::cout << max_score << std::endl;
    return 0;

}

