int main() {
    int N; cin >> N;
    ll C; cin >> C;
    vector<ll> x(N);
    vector<ll> v(N);
    vector<ll> xr(N);
    vector<ll> vr(N);
    rep(i, N){
        cin >> x[i] >> v[i];
    }
    rep(i, N){
        xr[i] = C - x[N-1-i];
        vr[i] = v[N-1-i];
    }

    vector<ll> vtotal(N+1);
    vector<ll> vrtotal(N+1);
    rep(i, N){
        vtotal[i+1] = vtotal[i] + v[i];
        vrtotal[i+1] = vrtotal[i] + vr[i];
    }

    vector<ll> f(N+1);
    rep(i, N){
        f[i+1] = vtotal[i+1] - x[i];
    }
    vector<int> fmax(N+1);
    ll now = 0;
    int nownum = 0;
    for (int i = 1; i <= N; i++){
        if(f[i] > now){
            now = f[i];
            nownum = i;
        }
        fmax[i] = nownum;
    }

    ll ans = 0;
    rep(i, N+1){
        ll now = f[fmax[N-i]];
        if(i == 0){
            ans = max(ans, now);
            //cout << i << " " << now << endl;
            continue;
        }
        if(i == N){
            ll now2 = vrtotal[i] - xr[i-1];
            ans = max(ans, now2);
            continue;
        }
        //cout << i << " " << now;
        ll now2 = now;
        if(fmax[N-i] != 0){
            now2 -= x[fmax[N-i]-1];
        }
        now2 += vrtotal[i];
        if(i != 0){
            now2 -= xr[i-1];
        }
        ll now3 = now2;
        if(fmax[N-i] != 0){
            now3 += x[fmax[N-i]-1];
        }
        if(i != 0){
            now3 -= xr[i-1];
        }
        //cout << " " << now2 << " " << now3 << endl;
        now = max(now, now2);
        now = max(now, now3);
        ans = max(ans, now);
    }

    cout << ans << endl;

    return 0;
}

