		w[N+1-i]=v[i];
	}
	ll tokei[N+2];
	tokei[0]=0;
	rep(i,N){
		tokei[i]=tokei[i-1]+v[i]-x[i]+x[i-1];
	}
	ll ans;
	ans = 0;
	rep(i,N){
		if(tokei[i]>=ans){
			ans=tokei[i]; //普通の最大値
		}
	}
	ll hantai[N+2];
	hantai[0]=0;
	rep(i,N){
		hantai[i]=hantai[i-1]+w[i]-y[i]+y[i-1];
	}
	rep(i,N){
		if(hantai[i]>=ans){
			ans=hantai[i]; //逆向きの最大値
		}
	}

	rep(k,N){
		rep(j,N-k){
			if(tokei[k]-x[k]+hantai[j]>=ans){
				ans=tokei[k]-x[k]+hantai[j];
			}
		}
	}

	rep(k,N){
		rep(j,N-k){
			if(hantai[k]-y[k]+tokei[j]>=ans){
				ans=hantai[k]-y[k]+tokei[j];
			}
		}
	}

	cout<<ans<<endl;




	  return 0;
  }

