        x[i+N] = C - x[i];
        v[i+N] = v[i];
    }
    //0からスタートして右に行くか
    //Nからスタートして左に行くかの2通り試す
    ll ans = 0;
    //0からスタートして右に行く場合dp[i]:=i個取った時の摂取カロリー
    rep(i,N){
        if(i==0){
            dp[1] = v[0] - x[0];
            dpmax[1] = max(0LL,dp[1]);
        }
        else{
            dp[i+1] = dp[i] + v[i] - (x[i]-x[i-1]);
            dpmax[i+1] = max(dp[i+1],dpmax[i]);
        }
    }
    //Nからスタートして左に行く
    //dp2[i] := 左にi個取った場合の摂取カロリー
    for(int i=2*N-1;i>=N;i--){
