const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, c;
vl xls, xrs, vls, vrs;
ll svl[MAX_N], svr[MAX_N];
ll memo[2][2][MAX_N];

pl func(ll l, ll r){
    /*
    svl[l] + svr[r] - (xls[l] * 2 + xrs[r]) (l + r <= n)
    svl[l] + svr[r] - (xls[l] + xrs[r] * 2) (l + r <= n)
    */
    ll v = svl[l] + svr[r];
    ll x1 = xls[l] * 2 + xrs[r];
    ll x2 = xls[l] + xrs[r] * 2;
    return mp(v - x1, v - x2);
}

void solve(){
    xls = xrs = vls = vrs = vl(n + 1);
    svl[0] = svr[0] = 0; xls[0] = xrs[0] = 0;
    vls[0] = vrs[0] = 0;
    rep(i, n){
        ll x, v; in2(x, v);
        xls[i + 1] = x; xrs[n - i] = c - x;
        vls[i + 1] = v; vrs[n - i] = v;
    }

    rep(i, n + 1) memo[0][0][i] = memo[1][0][i] = memo[0][1][i] = memo[1][1][i] = 0;
    rep(i, n){
        svl[i + 1] = svl[i] + vls[i + 1];
        svr[i + 1] = svr[i] + vrs[i + 1];
    }

    For(l, 1, n + 1){
        ll r = 0;
        pl fs = func(l, r);
        memo[0][1][l] = max(fs.e1, memo[0][1][l - 1]); // left longer
        memo[0][0][l] = max(fs.e2, memo[0][0][l - 1]); // left shorter
    }

    For(r, 1, n + 1){
        ll l = 0;
        pl fs = func(l, r);
        memo[1][0][r] = max(fs.e1, memo[1][0][r - 1]); // right shorter
        memo[1][1][r] = max(fs.e2, memo[1][1][r - 1]); // right longer
    }

    rep(l, n + 1){
        ll r = n - l;
        chmax(answer, memo[0][1][l] + memo[1][0][r]);
        chmax(answer, memo[0][0][l] + memo[1][1][r]);
    }

    prl(answer);

    // check negative MOD
    // check index flow
    // check overwrite of the input variables
}

int main(void){
    in2(n, c);
    assert(n <= 10000);
    solve();

    return 0;
}

