ll N, C;

ll f(VI& X, VI& V){
  VI A(N); // iまで食べて戻ってきたらどれだけ正か
  ll eat = 0;
  rep(i, N){
    eat += V[i];
    A[i] = eat - 2*X[i];
  }

  VI B(N); // iまで行ける中で最大のカロリーが得られる値
  ll ma = 0;
  rep(i, N){
    chmax(ma, A[i]);
    B[i] = ma;
  }

  // 一方通行の方は全探索
  ll ans = B[N-1]; // 一方通行なしの場合
  eat = 0;
  for(int i=N-1; i>=0; i--){
    eat += V[i];
    ll walk = C-X[i];
    ll cal = eat - walk;
    // その場合のMaxカロリー
    ll max_cal;
    if(i==0){
      max_cal = cal;
    }else{
      max_cal = cal + B[i-1];
    }
    chmax(ans, max_cal);
  }
  return ans;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    cin >> N >> C;

    VI X(N);
    VI V(N);
    rep(i, N){
        cin >> X[i] >> V[i];
    }

    ll ma = f(X, V);

    // 反転
    reverse(ALL(X));
    reverse(ALL(V));
    rep(i, N){
      X[i] = C-X[i];
    }

    chmax(ma, f(X, V));
    p(ma);

    return 0;
}

