        S[i] = S[i - 1] + v[i];
        // cout << i << "=" << S[i] << endl; 
    }

    ll ans = 0;
    custom_priority_queue<ll> q1, q2;
    for (int i = 1; i <= N - 1; i++) {
        // cout << i << " " << S[N - 1] - S[i - 1] - (C - x[i]) << ":" << S[N - 1] - S[i - 1] - 2 * (C - x[i]) << endl;
        q1.push(S[N - 1] - S[i - 1] - (C - x[i]));
        q2.push(S[N - 1] - S[i - 1] - 2 * (C - x[i]));
    }
    for (int i = 1; i <= N - 1; i++) {
        // cout << i << " " << q1.top() << endl;;
        ans = max(ans, S[i - 1] - 2 * x[i - 1] + q1.top());
        ans = max(ans, S[i - 1] - x[i - 1] + q2.top());
        q1.remove(S[N - 1] - S[i - 1] - (C - x[i]));
        q2.remove(S[N - 1] - S[i - 1] - 2 * (C - x[i]));
    }
    for (int i = 0; i < N; i++) {
        ans = max(ans, S[i] - x[i]);
        if (i < N - 1) {
            ans = max(ans, S[N - 1] - S[N - 2 - i] - (C - x[N - 1 - i]));
        } else {
            ans = max(ans, S[N - 1] - (C - x[0]));
        }
    }

    cout << ans << endl;
    return 0;
}

