ll n, c;

ll solve(vector<ll> &x, vector<ll> &v){
	vector<ll> rmax(n);
	rmax[0] = max(v[0] - x[0] * 2, 0LL);
	ll sum = v[0];
	for(ll i = 1; i < n; ++i){
		sum += v[i];
		rmax[i] = max(sum - 2 * x[i], rmax[i-1]);
	}
	ll res = 0, lsum = 0;
	for(ll i = n-1; i > 0; --i){
		lsum += v[i];
		chmax(res, lsum - (c - x[i]) + rmax[i-1]);
	}
	lsum += v[0];
	chmax(res, sum - x[n-1]);
	chmax(res, sum - c + x[0]);
	return res;
}

