using namespace std;

typedef long long ll;
const ll INF = 1LL<<60;

ll gcd(ll a, ll b) {
  if(b == 0) return a;
  return gcd(b, a % b);
}

template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }
template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }

ll modpow(ll a, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  // まず左回りの方を沢山歩く
  ll N, C;
  cin >> N >> C;
  vector<ll> x(N), v(N);
  for(int i = 0; i < N; i++){
    cin >> x[i] >> v[i];
  }

  vector<ll> rOA(N);
  vector<ll> lOA(N);

  rOA[0] = v[0] - x[0];
  for(int i = 1; i < N; i++){
    rOA[i] = rOA[i-1] - (x[i] - x[i-1]) + v[i];
  }

  vector<ll> maxrOA(N);
  maxrOA[0] = rOA[0];
  for(int i = 1; i < N; i++){
    maxrOA[i] = max(maxrOA[i-1], rOA[i]);
  }

  lOA[N-1] = v[N-1] - 2 * (C - x[N-1]);
  for(int i = N-2; i >= 0; i--){
    lOA[i] = lOA[i+1] + v[i] - 2 * (x[i+1] - x[i]);
  }

  ll ans_r = 0;
  chmax(ans_r, lOA[0]);
  chmax(ans_r, maxrOA[N-1]);
  for(int i = 1; i < N; i++){
    chmax(ans_r, lOA[i] + maxrOA[i-1]);
  }

  vector<ll> rOB(N);
  vector<ll> lOB(N);

  rOB[0] = v[0] - 2 * x[0];
  for(int i = 1; i < N; i++){
    rOB[i] = rOB[i-1] - 2*(x[i] - x[i-1]) + v[i];
  }

  lOB[N-1] = v[N-1] - (C - x[N-1]);
  for(int i = N-2; i >= 0; i--){
    lOB[i] = lOB[i+1] + v[i] - (x[i+1] - x[i]);
  }

  vector<ll> maxlOB(N);
  maxlOB[N-1] = lOB[N-1];
  for(int i = N-2; i >= 0; i--){
    maxlOB[i] = max(maxlOB[i+1], lOB[i]);
  }

  ll ans_l = 0;
  chmax(ans_l ,rOB[N-1]);
  chmax(ans_l, maxlOB[0]);
  for(int i = N-2; i >= 0; i--){
    chmax(ans_l, rOB[i] + maxlOB[i+1]);
  }

  cout << max(ans_r, ans_l) << endl;

  return 0;
}

