void dfs(int i,bool bClockwise, long long cur, int back) //back=折返点；尚未折返=-1 
{
	cur+=v[i];
	ans=max(ans,cur);
	if(bClockwise){
		if(i>=n-1) return;//顺时针到头了 
		if(back>=0 && i>=back-1) return;//折返到头了 
		dfs(i+1,true,cur-(x[i+1]-x[i]),back); //继续沿原方向走 
		if(back<0) dfs(n-1,false,cur-(c-(x[n-1]-x[i])),i);//折返,从i逆时针走到n-1 
	} else {
		if(i<=0) return;//逆时针到头了 
		if(back>=0 && i<=back+1) return;//折返到头了 
		dfs(i-1,false,cur-(x[i]-x[i-1]),back); //继续沿原方向走 
		if(back<0) dfs(0,true,cur-(c-(x[i]-x[0])),i);//折返，从i顺时针走到0 		
	}	
}

