ll C;

ll sol(const std::vector<P> &s) {
  ll ans = 0;
  int N = sz(s);

  // cyclic only
  ll D = 0;
  rep(i,N) {
    if ( i != 0 ) D += s[i].second-(s[i].first - s[i-1].first);
    else D += (s[i].second - s[i].first);
    chmax(ans, D);
  }

  // mae keisann
  std::vector<ll> L(N);
  ll tmp = 0;
  D = 0;
  for(int k=N-1; k>=0; k--) {
    if ( k != N-1 ) D += s[k].second - (s[k+1].first - s[k].first);
    else D += (s[k].second - (C-s[k].first));
    chmax(tmp, D);
    L[k] = tmp;
  }

  // cyclic i, un-cyc j
  rep(i,N) {
    D = 0;
    rep(k,i) {
      if ( k != 0 ) D += s[k].second-(s[k].first - s[k-1].first);
      else D += (s[k].second - s[k].first);
    }
    D -= s[i-1].first;
    D += L[i];
    chmax(ans, D);
  }

  return ans;
}

