      rroad[i] =  (C - x[i]);
    }else
      rroad[i] = (C - x[i]);
  }

  for(int i=N-1;i>=0;i--)
    if(i != N-1){
      right[i] = (ruiwa){i,right[i+1].num + v[i] - abs(x[i] - x[i+1])};
    }else{
      right[i] = (ruiwa){i,v[i] - (C-x[i])};
    }

  MAX = 0;
  sort(right,right+N,comp);
  MAX = right[N-1].num;
  ind = N-1;
  m = right[N-1].num;
  REP(i,N){
    m = max(m,MAX);
    while(right[ind].index <= i){
      ind--;
      if(ind <= -1)
        break;
      MAX = right[ind].num;
    }

    if(ind >= 0){
      m = max(left[i].num,max(left[i].num - lroad[i] + MAX,m));
      m = max(MAX - rroad[right[ind].index] +left[i].num ,max( MAX , m));

    }else{
      m = max(m,left[i].num);
    }


  }
  m = max(m,(long long int)0);
  cout << m << endl;
  return 0;

}

int par[MAX_N];
int ranks[MAX_N];

//n要素で初期化
void init(int n){
  REP(i,n){
    par[i] = i;
    ranks[i] = 0;
  }

}

//木の根を求める
int find(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

void unite(int x,int y){
  x = find(x);
  y = find(y);
  if(x == y) return ;
  if(ranks[x] < ranks[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(ranks[x] == ranks[y]) ranks[x]++;
  }
}

bool same(int x, int y){
  return find(x) == find(y);
}

