/*片方ある位置までいって
もう片方へmaxのとこまで行くときに俺はSparseTable使ったけど
これ累積MAXをとっておけばO(NlogN)じゃなくてO(N)での解答が可能
なんでSparseTableじゃなくて累積MAXで十分かというと
範囲の最大値を求めるんだけど左端は0で固定だからだよね
*/

signed main(){
    cin.tie(0);
    ios::sync_with_stdio(0);

    ll n,c;cin>>n>>c;
    vector<ll> x(n),v(n);
    rep(i,n) cin>>x[i]>>v[i];
    ll a1=0,a2=0,a3=0,a4=0;
    ll ans=0;
    //右回りだけ
    vector<ll> vv;
    ll cal=0;
    for(int i=0;i<n;i++){
        cal+=v[i];
        vv.push_back(cal-x[i]);
        a1=max(a1,cal-x[i]);
    }
    //左回りだけ
    vector<ll> vvv;
    cal=0;
    for(int i=n-1;i>=0;i--){
        cal+=v[i];
        vvv.push_back(cal-(c-x[i]));
        a2=max(a2,cal-(c-x[i]));
    }

    //折り返す。
    //それぞれ左にいったとこから右の最大まで行く
    SparseTable<ll> sp(vv);
    cal=0;
    for(int i=n-1;i>0;i--){
        ll dis=c-x[i];
        cal+=v[i];
        ll tmp=cal-2*dis+sp.f(0,i);
        a3=max(a3,tmp);
    }


    //右に行って左の最大までいく
    SparseTable<ll> st(vvv);
    cal=0;
    for(int i=0;i<n-1;i++){
        ll dis=x[i];
        cal+=v[i];
        ll tmp=cal-2*dis+st.f(0,n-i-1);
        a4=max(a4,tmp);
    }

    // cout<<a1<<endl;
    // cout<<a2<<endl;
    // cout<<a3<<endl;
    // cout<<a4<<endl;

    ans=max({a1,a2,a3,a4});
    cout<<ans<<endl;
    return 0;
}

