            maxProfit = dA;
            _maxDAX = x[i];
        }

        maxDA[i] = maxProfit;
        maxDAX[i] = _maxDAX;
    }


    ll rProfit = 0;
    ll maxRProfit = 0;
    ll maxRProfitDist = 0;

    for (ll j = n - 1; j >= 0; --j) {
        ll rDist = c - x[j];
        rProfit = rProfit + v[j] - rDist;
        if (j < n - 1) {
            ll prevDist = c - x[j+1];
            rProfit = rProfit + prevDist;
        }

        if (rProfit > maxProfit) {
            maxProfit = rProfit;
        }

        if (rProfit > maxRProfit) {
            maxRProfit = rProfit;
            maxRProfitDist = rDist;
        }

        if (j > 0) {
            ll lrProfit = maxDA[j - 1] + maxRProfit;
            ll shortestDist = std::min(maxRProfitDist, maxDAX[j-1]);
