		ans=max(ans,sz[i]);//右回りの行ったきり
		ans=max(ans,sj[i]-2*x[i]+nz[i+1]);//右回りのi番目まで行って、左回りのi+1番目までの最大値
	}
	for(int i=n;i>=1;i--){
		ans=max(ans,nz[i]);
		ans=max(ans,nj[i]-2*(c-x[i])+sz[i-1]);
	}

	cout<<ans<<endl;
}

