    for(int i=1; i<=n; i++){
        vc[i] = vc[i-1] + v[i];//     v[0]=0,   v[1], v[1]+v[2],   ...
        va[i] = va[i-1] + v[n+1-i];// v[n+1]=0, v[n], v[n]+v[n-1], ...
    }

    vector<long long int> g_ac(n+1), h_ac(n+2), g_ca(n+1), h_ca(n+2);// h[i] = optimal c-endpoint for each ac-endpoint i
    // g_ac[0] = 0 = 0 - 0, // g_ca[0] = 0 = 0 - 0
    // h_ac[1] = 0, // h_ca[1] = 0
    int rec_ac = 0;
