    for(int i=1; i<=n; i++){
        g_ac[i] = max(g_ac[i-1], vc[i] - x[i]);
        g_ca[i] = max(g_ca[i-1], vc[i] - 2 * x[i]);

        if(g_ac[i-1] < vc[i] - x[i]) rec_ac = i;
        h_ac[i+1] = rec_ac;
        if(g_ca[i-1] < vc[i] - 2 * x[i]) rec_ca = i;
