    for(i=0; i<n; i++) {
        x_r = x[0];
        x_l = x[n-i-1];
        v_r = v[0];
        v_l = v[n-i-1];
        c_r = max(calorie, calorie+v_r-min(abs(x_r-p), c-abs(x_r-p)));
        c_l = max(calorie, calorie+v_l-min(c-abs(x_l-p), abs(x_l-p)));
        if(c_r == calorie && c_l == calorie) break;
        if(c_r > c_l) {
            calorie = c_r;
            p = x_r;
            x.erase(x.begin());
            v.erase(v.begin());
        } else {
            calorie = c_l;
            p = x_l;
            x.pop_back();
            v.pop_back();
        }
    }
    cout << calorie << endl;
}

