	    }

	    sort(l.begin(), l.end());
	    sort(r.begin(), r.end());

	    vector<ll> lc(n+1), rc(n+1);
	    lc[0] = rc[0] = 0;
	    for(int i=0; i<n; i++){
            lc[i+1] = lc[i] + (l[i].first.second - l[i].first.first);
            rc[i+1] = rc[i] + (r[i].first.second - r[i].first.first);
            if(i-1 >= 0){
                lc[i+1] += l[i-1].first.first;
                rc[i+1] += r[i-1].first.first;
            }
	    }

	    ll res = max(lc[n], rc[n]);

        ll posr = 0, posl = 0;
