    vector<size_t> sumc22;
    size_t sumc1tmp = 0;
    for(size_t i=0;i<x.size();i++){
        sumc1tmp += v[i];
        sumc11.push_back(sumc1tmp>  x[i]? sumc1tmp -   x[i]:0);
        sumc12.push_back(sumc1tmp>2*x[i]? sumc1tmp - 2*x[i]:0);
    }
    size_t sumc2tmp = 0;
    for(unsigned long i=x.size()-1; i!=ULONG_MAX; i--){
        sumc2tmp += v[i];
        sumc21.push_back(sumc2tmp>  (C - x[i])? sumc2tmp -   (C - x[i]):0);
        sumc22.push_back(sumc2tmp>2*(C - x[i])? sumc2tmp - 2*(C - x[i]):0);
    }
    size_t maxc = 0;
    size_t candidate1 = *(max_element(sumc11.begin(), sumc11.end()));
    size_t candidate2 = *(max_element(sumc21.begin(), sumc21.end()));
    maxc = max(candidate1, candidate2);

    size_t ctmp=0;
    for(size_t i=0;i<x.size()-1;i++){
        ctmp = sumc21[i] + *(max_element(sumc12.begin(), sumc12.end() - i - 1));
        if(ctmp > maxc) maxc = ctmp;
        ctmp = sumc11[i] + *(max_element(sumc22.begin(), sumc22.end() - i - 1));
        if(ctmp > maxc) maxc = ctmp;
    }
