void solve(){
    ll n,c;
    cin >> n >> c;
    Vi x(n),v(n);
    rp(i,n) cin >> x.at(i) >> v.at(i);
    Vi sum(n),revsum(n);
    Vi d_sum(n),d_revsum(n);
    rp(i,n){
        if(i==0){
            sum.at(0)=v.at(0)-x.at(0);
            d_sum.at(0)=v.at(0)-2*x.at(0);
            continue;
        }
        sum.at(i)=sum.at(i-1)+v.at(i)-x.at(i)+x.at(i-1);
        d_sum.at(i)=d_sum.at(i-1)+v.at(i)-2*(x.at(i)-x.at(i-1));
    }
    rp(i,n){
        if(i==0){
            revsum.at(0)=v.at(n-1)-(c-x.at(n-1));
            d_revsum.at(0)=v.at(n-1)-2*(c-x.at(n-1));
            continue;
        }
        revsum.at(i)=revsum.at(i-1)+v.at(n-1-i)-(x.at(n-i)-x.at(n-1-i));
        d_revsum.at(i)=d_revsum.at(i-1)+v.at(n-1-i)-2*(x.at(n-i)-x.at(n-1-i));
    }
    Vi summax(n),revsummax(n);
    rp(i,n){
        if(i==0){
            summax.at(0)=max(0ll,sum.at(0));
            continue;
        }
        summax.at(i)=max(summax.at(i-1),sum.at(i));
    }
    rp(i,n){
        if(i==0){
            revsummax.at(0)=max(0ll,revsum.at(0));
            continue;
        }
        revsummax.at(i)=max(revsummax.at(i-1),revsum.at(i));
    }
    ll ans=0;
    rp(i,n-1){
        chmax(ans,d_sum.at(i)+revsummax.at(n-2-i));
    }
    rp(i,n-1){
        chmax(ans,d_revsum.at(i)+summax.at(n-2-i));
    }
    Sort(sum);
    Sort(revsum);
    chmax(ans,sum[0]);
    chmax(ans,revsum[0]);
    print(ans);
    return;
}
