inline int pd(ll w,int l,int r)
{
	int mid,ret=0;
	while (l<r)
	{
		mid=l+r+1>>1;
		if (t[mid]==w) return mid;
		if (t[mid]>w) l=mid,ret=mid;
		else r=mid-1;
	}
	if (ret==0) return mid;
	else return ret;
}

inline void create(int o,int l,int r)
{
	le[o]=l;ri[o]=r;
	if (l==r)
	{
		m1[o]=h[l]-t[l];
		return ;
	}
	int mid=l+r>>1;
	create(o<<1,l,mid);
	create(o<<1|1,mid+1,r);
	m1[o]=m1[o<<1]+m1[o<<1|1];
}

inline void build(int o,int l,int r)
{
	if (l==r)
	{
		m2[o]=h[l];
		return ;
	}
	int mid=l+r>>1;
	create(o<<1,l,mid);
	create(o<<1|1,mid+1,r);
	m2[o]=m2[o<<1]+m2[o<<1|1];
}

inline ll query1(int o,int x,int y)
{
	int l=le[o],r=ri[o];
	if (x==l&&y==r) return m1[o];
	int mid=l+r>>1;
	ll ans=0;
	if (y<=mid) ans=query1(o<<1,x,y);
	if (x>mid) ans=query1(o<<1|1,x,y);
	if (x<=mid&&y>mid) ans=max(query1(o<<1,x,mid),query1(o<<1|1,mid+1,y));
	return ans;
}

inline ll query2(int o,int x,int y)
{
	int l=le[o],r=ri[o];
	if (x==l&&y==r) return m2[o];
	int mid=l+r>>1;
	ll ans=0;
	if (y<=mid) ans=query2(o<<1,x,y);
	if (x>mid) ans=query2(o<<1|1,x,y);
	if (x<=mid&&y>mid) ans=max(query2(o<<1,x,mid),query2(o<<1|1,mid+1,y));
	return ans;
}

