        [](ll a,ll b){return std::max(a,b);},
        [](ll a,ll b){return b;},
        cw
    );
    SegmentTree<ll,ll> st2(n,
        [](ll a,ll b){return std::max(a,b);},
        [](ll a,ll b){return b;},
        ccw
    );

    ll ans = 0;
    ll tans;
    for(int i = 0;i < n;++i) {
        tans=cw[i+1];
//cerr<<i<<" "<<st2.query(0,n-1-i)<<endl;
        if(i!=n-1&&st2.query(0,n-1-i)>d[i].first){
//cerr<<i<<" "<<st2.query(0,n-1-i)<<endl;
            tans-=d[i].first;
            tans+=st2.query(0,n-1-i);
        }
