int N;
std::vector<long> x, v;

long effect_cw(int i) {
  if (i >= 1) {
    return v[i] - (x[i] - x[i-1]);
  } else {
    return v[i] - x[i];
  }
}

long effect_ccw(int i) {
  if (i < N-1) {
    return v[i] - (x[i] - x[i+1]);
  } else {
    return v[i] - x[N-1];
  }
}

long double_effect_cw(int i) {
  if (i >= 1) {
    return v[i] - (x[i] - x[i-1]) * 2;
  } else {
    return v[i] - x[i] * 2;
  }
}

long double_effect_ccw(int i) {
  if (i < N-1) {
    return v[i] - (x[i] - x[i+1]) * 2;
  } else {
    return v[i] - x[N-1] * 2;
  }
}

int main() {
  long C;
  cin >> N >> C;

  x.resize(N);
  v.resize(N);

  int middle_idx = -1;
  for (int i=0; i < N; i++) {
    cin >> x[i] >> v[i];
  }

  std::sort(v.begin(), v.end(), [&x](const size_t& lhs, const size_t& rhs){ return x[lhs] < x[rhs]; });
  std::sort(x.begin(), x.end());

  for (int i=0; i < N; i++) {
    if (middle_idx == -1 && x[i] > C / 2) {
      if (i >= 1) {
        middle_idx = i - 1;
      } else {
        middle_idx = -2;
      }
    }
  }

  long long max_cal = 0;
  long long current_cal = 0;

  // cw
  for (int i=0; i < N; i++) {
    current_cal += effect_cw(i);
    std::cout << current_cal << std::endl;
    max_cal = std::max(max_cal, current_cal);
  }
  current_cal = 0;

  // ccw
  for (int i=N-1; i >= 0; i--) {
    current_cal += effect_ccw(i);
    max_cal = std::max(max_cal, current_cal);
  }

  if (middle_idx < 0) {
    cout << max_cal;
    return 0;
  }

  // cw and reverse
  current_cal = 0;
  long long max_cal_temp = 0;
  for (int i = 0; i <= middle_idx; i++) {
    current_cal += double_effect_cw(i);
    max_cal_temp = std::max(max_cal_temp, current_cal);
  }
  for (int i = N-1; i >= middle_idx + 1; i--) {
    current_cal += effect_ccw(i);
    max_cal_temp = std::max(max_cal_temp, current_cal);
  }
  max_cal = std::max(max_cal, max_cal_temp);

  // ccw and reverse
  current_cal = 0;
  max_cal_temp = 0;
  for (int i = N-1; i >= middle_idx + 1; i--) {
    current_cal += double_effect_ccw(i);
    max_cal_temp = std::max(max_cal_temp, current_cal);
  }
  for (int i = 0; i <= middle_idx; i++) {
    current_cal += effect_cw(i);
    max_cal_temp = std::max(max_cal_temp, current_cal);
  }
  max_cal = std::max(max_cal, max_cal_temp);

  cout << max_cal;
  return 0;
}

