int main()
{
  int n;
  ll C;
  scanf("%d %lld", &n, &C);
  vector<ll> dist(n, 0), calories(n, 0);
  for (int i = 0; i < n; ++i) {
    ll x, v;
    scanf("%lld %lld", &x, &v);
    dist[i] = x;
    calories[i] = v;
  }

  vector<ll> cwise(n, 0), ccwise(n, 0);
  ll val = calories[0] - dist[0];
  cwise[0] = max(0LL, val);
  for (int i = 1; i < n; ++i) {
    val += calories[i] - (dist[i] - dist[i - 1]);
    cwise[i] = max(val, cwise[i - 1]);
  }
  val = calories[n - 1] - (C - dist[n - 1]);
  ccwise[n - 1] = max(0LL, val);
  for (int i = n - 2; i >= 0; --i) {
    val += calories[i] - (dist[i + 1] - dist[i]);
    ccwise[i] = max(val, ccwise[i + 1]);
  }

  ll ans = 0;
  for (int i = 0; i < n; ++i) {
    ans = max(ans, cwise[i]);
    ans = max(ans, ccwise[i]);
    if (i + 1 < n) {
      // clockwise => counter clockwise
      ans = max(ans, cwise[i] - dist[i] + ccwise[i + 1]);
      // counter clockwise => clockwise
      ans = max(ans, ccwise[i + 1] - (C - dist[i + 1]) + cwise[i]);
    }

  }
  printf("%lld\n", ans);

  return 0;
}

