using namespace std;

typedef pair<ll, ll> tup;


class D {
	ll n, c;
	vector<ll> pos;
	vector<ll> val;
	vector<tup> clock_memo;
	vector<tup> counter_memo;

public:
	D()
	{
		cin >> n >> c;
		pos.resize(n + 1);
		val.resize(n);
		clock_memo.resize(n+1);
		counter_memo.resize(n+1);
		clock_memo[n] = MP(0, 0);
		counter_memo[n] = MP(0, 0);
		pos[n] = 0;

		REP(i, n)
			cin >> pos[i] >> val[i];
	}

	void debug()
	{
		//cout << "clockwise debug..." << endl;
		//REP(i, n)
		//{
		//	cout << "You can use upto index " << i << " : ";
		//	cout << "max_val = " << clock_memo[i].first << ", (index " << clock_memo[i].second << ")" << endl;
		//}

		cout << "counterclockwise debug..." << endl;
		REP(i, n)
		{
			cout << "You can use upto index " << i << " : ";
			cout << "max_val = " << counter_memo[i].first << ", (index " << counter_memo[i].second << ")" << endl;
		}

	}

	void solve()
	{
		ll ans{ 0 };
		ll tmp, ma, now;
		ll maxi;

		// clockwise
		tmp = ma = 0;
		now = 0; maxi = -1;
		REP(i, n)
		{
			tmp += (val[i] - (pos[i] - now));
			if (chmax(ma, tmp))
				maxi = i;
			clock_memo[i] = MP(ma, maxi);
			now = pos[i];
		}

		// counterclockwise
		tmp = ma = 0;
		now = c;
		maxi = n;
		RREP(i, n)
		{
			tmp += (val[i] - (now - pos[i]));
			if (chmax(ma, tmp))
				maxi = i;
			counter_memo[i] = MP(ma, maxi);
			now = pos[i];
		}

		REP(i, n)
		{
			ll val_clock{ clock_memo[i].F };
			ll id_clock{ clock_memo[i].S };
			ll d_clock;
			if (id_clock == -1)
				d_clock = 0;
			else
				d_clock = pos[id_clock];

			ll val_counter{ counter_memo[id_clock + 1].F };
			ll d_counter{ c - pos[counter_memo[id_clock + 1].S] };

			tmp = val_clock + val_counter - min(d_clock, d_counter);
			chmax(ans, tmp);
		}


		cout << ans << endl;
	}
};


