			max_x2[i] = max_x2[i - 1];
			sum_max2[i] = sum_max2[i - 1];
		}
		else {
			max_x2[i] = x[i];
			sum_max2[i] = sum2[i];
		}
	}
	x[n + 1] = c;

	for (int i = n; i > 0; i--) { //反時計回り
		sumN[n - i + 1] = sumN[n - i] + v[i];
	}

	ll ans = 0, MAX = 0;
	for (int i = 0; i <= n; i++) {
		ans = sum_max1[n - i] + sumN[i];
		ans -= (c - x[n + 1 - i])*2;
		MAX = max(MAX, ans);

		ans = sum_max2[n - i] + sumN[i];
		ans -= (c - x[n + 1 - i]);
		MAX = max(MAX, ans);
	}
	cout << MAX << endl;
}

