template<typename T>
class CulSum {
private:
    long long N;
    vector<T> a;
    vector<T> aa;
    vector<T> b;
    vector<T> bb;

    function<T(T, T)> func;

public:

    /// @param a original array
    CulSum(vector<T> _a) {
        N = _a.size();
        a = _a;
        b = _a;
        reverse(b.begin(), b.end());
        this->aa = vector<T>(N + 1, T{});
        this->bb = vector<T>(N + 1, T{});
        for (int i = 0; i < N; i++) aa[i + 1] = a[i] + aa[i];
        for (int i = 0; i < N; i++) bb[i + 1] = b[i] + bb[i];
    }

    /// @param a original array
    CulSum(vector<T> _a, function<T(T, T)> func) : func(func) {
        N = _a.size();
        a = _a;
        b = _a;
        reverse(b.begin(), b.end());
        this->aa = vector<T>(N + 1, T{});
        this->bb = vector<T>(N + 1, T{});
        for (int i = 0; i < N; i++) aa[i + 1] = func(a[i], aa[i]);
        for (int i = 0; i < N; i++) bb[i + 1] = func(b[i], bb[i]);
    }

    /// @brief 0-index original
    /// @param l original close
    /// @param r original open
    T get_sum(int l, int r) {
        return aa[r] - aa[l];
    }

    /// @brief 0-index original
    /// @param l original close
    /// @param r original open
    T get_sum_reverse(int l, int r) {
        l = N - l;
        r = N - r;
        return bb[l] - bb[r];
    }

    /// @brief 0-index original
    /// @param k length
    T get_sum_lead_k_len(int k) {
        return get_sum(0, k);
    }

    /// @brief 0-index original
    /// @param k length
    T get_sum_tail_k_len(int k) {
        return get_sum_reverse(N - k, N);
    }

    void show() {
        for (int i = 0; i < N + 1; i++) cout << aa[i] << " ";
        cout << endl;
    }

    void show_reverse() {
        for (int i = N; i >= 0; i--) cout << bb[i] << " ";
        cout << endl;
    }

};

template<typename T>
struct SegmentTree {
private:
    using Func = function<T(T, T)>;

    int n;
    vector<T> node;

    T init_v;
    Func func;

public:

    SegmentTree(vector<T> a, Func _func, T _init_v) {
        int sz = a.size();
        n = 1;
        init_v = _init_v;
        func = _func;

        while (n < sz) n *= 2;
        node.resize(2 * n, init_v);
        for (int i = 0; i < sz; i++) node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--) node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int pos, T v) {
        int k = pos + n - 1;
        node[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = func(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    T get(int pos) {
        int k = pos + n - 1;
        return node[k];
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return init_v;
        if (a <= l && r <= b)return node[k];
        T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return func(lv, rv);
    }

};

void half_path(LL N, vector<LL> &x, vector<LL> &v, LL &ans) {
    CulSum<LL> culSum(v);
    for (int i = 0; i < N; i++) {
        LL d = culSum.get_sum(0, i + 1) - x[i];
        ans = max(ans, d);
    }
}

void half_half_half(LL N, vector<LL> &x, vector<LL> &v, vector<LL> &rx, vector<LL> &rv, LL &ans) {
    CulSum<LL> culSum(v);
    CulSum<LL> r_culSum(rv);
    vector<LL> other_score(N);
    for (int i = 0; i < N; i++) {
        LL d = r_culSum.get_sum(0, i + 1) - rx[i];
        other_score[i] = d;
    }

    SegmentTree<LL> segmentTree(other_score, [](const LL a, const LL b) { return max(a, b); }, -INF);

    for (int i = 0; i < N; i++) {
        LL d = culSum.get_sum(0, i + 1) - 2 * x[i];
        d += segmentTree.query(0, N - i - 1);
        ans = max(ans, d);
    }
}

int main() {

    LL N, C;
    cin >> N >> C;

    vector<LL> x(N), v(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> v[i];

    vector<LL> rx = x, rv = v;
    REVERSE(rx);
    for (int i = 0; i < N; i++) rx[i] = C - rx[i];
    REVERSE(rv);

    LL ans = 0;
    half_path(N, x, v, ans);
    half_path(N, rx, rv, ans);

    half_half_half(N, x, v, rx, rv, ans);
    half_half_half(N, rx, rv, x, v, ans);

    cout << ans << endl;

    return 0;
}

