  for (int i = 1; i <= N; i++) {
    tmpB = max(tmpB, sumV.at(N) - sumV.at(N-i) - (C - X.at(N-i)));
    maxB.at(i) = tmpB;
  }

  long long ans = 0;
  for (int i = 0; i <= N; i++) {
    long long cost = i ? (2 * (C - X.at(N-i))) : 0;
    ans = max(ans, sumV.at(N) - sumV.at(N-i) - cost + maxA.at(N-i));
  }
  for (int i = 0; i <= N; i++) {
    long long cost = i ? (2 * X.at(i-1)) : 0;
    ans = max(ans, sumV.at(i) - cost + maxB.at(N-i));
  }
  cout << ans << endl;
}

