		static type op(const type&l, const type&r) {
			return max(l, r);
		}
		static type upd(const type&l, const type&r) {
			return r;
		}
	};

	LL N, C; cin >> N >> C;
	vector<LL> x(N + 2), add(N + 2);
	for (int i = 0; i < N; ++i) {
		cin >> x[i + 1] >> add[i + 1];
	}
