		FOR(i, 1, N + 1) {
			a[i] = add[i] - (x[i]-x[i-1]);
		}
	}
	Cumusum cumToR(a);
	SegmentTreeFastAry<MaxUpd>segToR(N + 10); {
		LL xsum = 0;
		FOR(i, 0, N + 1) {
			xsum = x[i];
			LL updval = cumToR.query(0, i + 1) - xsum;
			DD(de(updval));
			segToR.update(i, cumToR.query(0, i + 1) - xsum);
		}
	}
	DD(De(x));
	FOR(i, 1, N + 1) {
		x[i] = C - x[i];
	}
	reverse(ALL(x));
	DD(De(x));
	DD(De(add));
	reverse(ALL(add));
	DD(De(add));
	VL b(N + 1); {
		FOR(i, 1, N + 1) {
			b[i] = add[i] - (x[i]-x[i-1]);
		}
	}
	Cumusum cumToL(b);
	SegmentTreeFastAry<MaxUpd> segToL(N + 10); {
		LL xsum = 0;
		FOR(i, 0, N + 1) {
			xsum = x[i];
			LL updval = cumToL.query(0, i + 1) - xsum;
			DD(de(updval));
			segToL.update(i, cumToL.query(0, i + 1) - xsum);
		}
	}

	LL ans = 0;
	FOR(i, 0, N + 1) {
		{
			LL sub = cumToR.query(0, i + 1);
			sub += max(0LL, segToL.query(0, N - i+1));
			DD(de(cumToR.query(0, i + 1),sub));
			ans = max(ans, sub);
		}
		{
			LL sub = cumToL.query(0, i + 1);
			sub += max(0LL, segToR.query(0, N - i+1));
			DD(de(cumToL.query(0, i + 1),sub));
			ans = max(ans, sub);

		}
	}



	cout << (ans) << "\n";

	return 0;
}

