	rb(i,1,n) cin>>a[i].FIR>>a[i].SEC;
	val[1][0]=c;
	rb(i,1,n) val[1][i]=val[1][i-1]+a[i].SEC;
	val[0][n+1]=c;//cout<<endl;
	rl(i,n,1) val[0][i]=val[0][i+1]+a[i].SEC;
	dp[1][0][0]=c;dp[0][1][0]=c;
	rb(i,1,n){
		dp[1][1][i]=val[1][i]-2*(a[i].FIR);
		dp[1][0][i]=val[1][i]-(a[i].FIR);
//		cout<<"r"<<dp[1][1][i]<<" , "<<dp[1][0][i]<<endl;
	}
	rl(i,n,1){
		if(i==n){
		dp[0][1][i]=val[0][i]-2*(finalc-a[i].FIR);
		dp[0][0][i]=val[0][i]-(finalc-a[i].FIR);	
		}
		else{
		dp[0][1][i]=val[0][i]-2*(finalc-a[i].FIR);
		dp[0][0][i]=val[0][i]-(finalc-a[i].FIR);	
		}
//		cout<<"l"<<dp[0][1][i]<<" , "<<dp[0][0][i]<<endl;
	}
	_max[1][1][0]=0;
	_max[1][0][0]=0;
	_max[0][1][n+1]=0;
	_max[0][0][n+1]=0;
	rb(i,1,n){
		_max[1][1][i]=max(_max[1][1][i-1],dp[1][1][i]);
		_max[1][0][i]=max(_max[1][0][i-1],dp[1][0][i]);
	}
	rl(i,n,1){
		_max[0][1][i]=max(_max[0][1][i+1],dp[0][1][i]);
		_max[0][0][i]=max(_max[0][0][i+1],dp[0][0][i]);
	}
	res=0;
	rl(i,n-1,0){
		LL res1,res2;
		if(i==0){
			res1=_max[0][0][0]+_max[1][1][n];
			res2=_max[0][1][0]+_max[1][0][n];
//			cout<<_max[0][1][0]<<" "<<_max[1][0][n-1]<<endl;
		}
		else{
			res1=_max[0][0][i]+_max[1][1][i-1];
			res2=_max[0][1][i]+_max[1][0][i-1];
		}
//		cout<<res1<<" "<<res2<<endl;
		res=max(res,max(res1,res2));
	}
	cout<<res;
	return 0;
}

