    v = new llong[n];

    llong maxProfit = 0;

    llong dA = 0;
    llong _maxDAX = 0;

    for (llong i = 0; i < n; ++i) {
        std::cin >> x[i] >> v[i];
        dA += i > 0 ? x[i - 1] : 0;
        dA += v[i] - x[i];

        if (dA > maxProfit) {
            maxProfit = dA;
            _maxDAX = x[i];
        }

        maxDA[i] = maxProfit;
        maxDAX[i] = _maxDAX;
    }

    llong dB = 0;
    for (llong j = n - 1; j >= 0; --j) {
