const int N_MAX = 1e5;
const ll C_MAX = 1e14;
const int V_I_MAX = 1e9;
const ll INF = 1e15;

int N;
ll C;
ll x[N_MAX];
ll v[N_MAX];

ll f1[N_MAX + 1];
ll f2[N_MAX + 1];
ll r1[N_MAX + 1];
ll r2[N_MAX + 1];

void solve() {
  // fill(f1, f1 + N, -INF);
  // fill(f2, f2 + N, -INF);
  ll sum = 0;
  f1[0] = f2[0] = 0;
  REP(i, N) {
    sum += v[i];
    f1[i + 1] = max(f1[i], sum - x[i]);
    f2[i + 1] = max(f2[i], sum - x[i] * 2);
  }
  ll rsum = 0;
  r1[N] = r2[N] = 0;
  for (int i = N - 1; i >= 0; i--) {
    rsum += v[i];
    r1[i] = max(r1[i + 1], rsum - (C - x[i]));
    r2[i] = max(r2[i + 1], rsum - (C - x[i]) * 2);
  }
  ll ans = 0;
  REP(i, N + 1) {
    ans = max(ans, f1[i]);
    ans = max(ans, r2[i] + f1[i]);
    ans = max(ans, r1[i]);
    ans = max(ans, f2[i] + r1[i]);
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d%lld", &N, &C);
  REP(i, N) scanf("%lld%lld", x + i, v + i);
}

int main() {
  input();
  solve();
  return 0;
}

