const int N=1e5+10;
int c[N];
int n,i,d,l,r,L,R;
ll Ans;
inline void Ins(int i){ for(;i<=n+1;i+=i&(-i))c[i]++;}
inline int Qry(int i){ int Ans=0;for(;i;i-=i&(-i))Ans+=c[i];return Ans;}
struct Po{
    ll v;
    int id;
    bool operator <(const Po &a)const{ return v<a.v;}
}S[N],Pre[N];
int GetL(int l,int r,ll V){
    while(l<r){
        int mid=(l+r)>>1;
        if(S[mid].v>=V)r=mid;
        else l=mid+1;
    }
    return l;
}
int GetR(int l,int r,ll V){
    while(l<r){
        int mid=((l+r)>>1)+1;
        if(S[mid].v<=V)l=mid;
        else r=mid-1;
    }
    return l;
}
int main(){
    read(n);read(L);read(R);
    for(i=1;i<=n;i++){
        read(d);
        Pre[i].v=Pre[i-1].v+d;
    }
    for(i=0;i<=n;i++)S[i].v=Pre[i].v,S[i].id=i;
    sort(S,S+n+1);
    for(i=0;i<=n;i++)Pre[S[i].id].id=i;
    Ins(Pre[0].id+1);
    for(i=1;i<=n;i++){
        r=GetR(0,n,Pre[i].v-L);if(S[0].v>(Pre[i].v-L))r=-1;
        l=GetL(0,n,Pre[i].v-R);if(S[n].v<(Pre[i].v-R))l=n+1;
        if(l<=r) Ans+=Qry(r+1)-Qry(l);
        Ins(Pre[i].id+1);
    }
    printf("%lld",Ans);
    return 0;
}

