using namespace std;
vector<long long> x,c;
long long N,C,ans;
void dfs(long long pos,long long walk,long long cls)
{
	ans=max(ans,cls-walk);
	if(!x.size())
		return ;
	int pnt=lower_bound(x.begin(),x.end(),pos)-x.begin();
	vector<long long> tmp=x,tcp=c;
	long long to=x[pnt%x.size()],cl=c[pnt%x.size()];
	x.erase(x.begin()+pnt%x.size());
	c.erase(c.begin()+pnt%c.size());
	dfs(to,walk+(to-pos+C)%C,cl+cls);
	c=tcp;
	x=tmp;
	pnt--;
	pnt+=x.size();
	to=x[pnt%x.size()],cl=c[pnt%x.size()];
	x.erase(x.begin()+pnt%x.size());
	c.erase(c.begin()+pnt%c.size());
	dfs(to,walk+(pos-to+C)%C,cl+cls);
	x=tmp;
	c=tcp;
	return ;
}
