int main(int argc, char* argv[])
{
  ll N, C;
  std::vector< std::pair< ll, ll > > vp;
  std::vector< std::pair< ll, ll > > vp2;
  std::vector< std::pair< ll, ll > >::iterator it;
  std::vector< std::pair< ll, ll > >::iterator it2;

  std::cin >> N >> C;  
  for (ll i = 0; i < N; i++) {
    ll x, v;
    std::cin >> x >> v;
    std::pair< ll, ll > p(x, v);
    vp.push_back(p);
    vp2.push_back(p);
  }

  std::vector< std::pair< ll, ll > > v_cost;
  {
    ll all_sum = 0;
    ll pre_pos = 0;
    v_cost.push_back(std::pair< ll, ll >(0, 0));    
    for (it = vp.begin(); it != vp.end(); it++) {
      all_sum += it->second - (it->first - pre_pos);
      v_cost.push_back(std::pair< ll, ll >((it-vp.begin())+1, all_sum));
      pre_pos = it->first;
    }
  }

  std::reverse(vp2.begin(), vp2.end());
  for (it = vp2.begin(); it != vp2.end(); it++) {
    it->first = C - it->first;
  }

  std::vector< std::pair< ll, ll > > v_cost2;  
  {
    ll all_sum = 0;
    ll pre_pos = 0;
    v_cost2.push_back(std::pair< ll, ll >(0, 0));    
    for (it = vp2.begin(); it != vp2.end(); it++) {
      all_sum += it->second - (it->first - pre_pos);
      v_cost2.push_back(std::pair< ll, ll >((it-vp2.begin())+1, all_sum));
      pre_pos = it->first;
    }
  }

  // Forward -> Backward
  ll max_cal = 0;
  for (it = v_cost.begin(); it != v_cost.end(); it++) {
    for (it2 = v_cost2.begin(); it2 != v_cost2.end(); it2++) {    
      if (it->first + it2->first > N) { break; }      
      ll step = it->first == 0 || it2->first == 0 ? 0 : vp[it - v_cost.begin()-1].first;
      ll all_cal = it->second + it2->second - step;
      max_cal = all_cal > max_cal ? all_cal : max_cal;
      //std::cout << it->first << " " << it2->first << " " << it->second << " " << it2->second << " " << all_cal << std::endl;
    }
  }

  // Backward -> Forward
  for (it = v_cost.begin(); it != v_cost.end(); it++) {    
    for (it2 = v_cost2.begin(); it2 != v_cost2.end(); it2++) {
      if (it->first + it2->first > N) { break; }
      ll step = it->first == 0 || it2->first == 0 ? 0 : vp2[it2 - v_cost2.begin()-1].first;      
      ll all_cal = it2->second + it->second - step;
      max_cal = all_cal > max_cal ? all_cal : max_cal;
      //std::cout << it->first << "*" << it2->first << " " << it->second << " " << it2->second << " " << step << " " << all_cal << std::endl;
    }
  }

  std::cout << max_cal << std::endl;

  return 0;
}

