#include <iostream>
#include <algorithm>

using namespace std;

typedef long long ll;

ll x[100001], v[100001];
ll v_sum_right[100001], v_sum_left[100001];
ll g[100001][2];

int main() {
    ll N, C;
    ll i;
    ll ans;
    ll t;

    cin >> N >> C;
    for (i = 0; i < N; i++) {
        cin >> x[i] >> v[i];
    }

    v_sum_right[0] = v[0];
    for (i = 1; i < N; i++) {
        v_sum_right[i] = v_sum_right[i - 1] + v[i];
    }

    v_sum_left[N] = 0;
    for (i = N - 1; i >= 0; i--) {
        v_sum_left[i] = v_sum_left[i + 1] + v[i];
    }


    // g計算
    g[0][0] = 0;
    g[0][1] = 0;
    for (i = 1; i <= N; i++) {
        g[i][0] = max(g[i - 1][0], v_sum_right[i - 1] - x[i - 1]);
        if (g[i - 1][0] == g[i][0]) {
            g[i][1] = g[i - 1][1];
        }
        else {
            g[i][1] = x[i - 1];
        }
    }

    // 探査
    ans = v_sum_left[0] - C + x[0];
    for (i = 1; i < N; i++) {
        t = g[i - 1][0] + v_sum_left[i] - C + x[i];
        ans = max(ans, t - C + x[i]);
        ans = max(ans, t - g[i - 1][1]);
    }
    ans = max(ans, g[N][0]);

    cout << ans << endl;

    return 0;
}

