const int N = 200005;
ll x[N], v[N];
ll sumv[N];
int n; ll C;
ll solve() {
	rep(i, n + n + 1) sumv[i + 1] = sumv[i] + v[i];
	ll ans = 0;
	set <ll> st;
	st.insert(0);
	for (int i = n + n; i >= n; -- i) {
		ans = max(ans, sumv[i + 1] - sumv[n] - (x[i] - C) + *st.rbegin());
		st.insert(sumv[n] - sumv[i - n] - (C - x[i - n]) * 2);
	}
	return max(ans, *st.rbegin());
}
int main() {
	n = read();
	scanf("%lld", &C);
	rep(i, n) {
		scanf("%lld", &x[i]);
		v[i] = read();
	}
	x[n] = C;
	v[n] = 0;
	rep(i, n) {
		x[i + 1 + n] = x[i] + C;
		v[i + 1 + n] = v[i];
	}
	ll ans = solve();
	rep(i, n + n + 1) {
		x[i] = C + C - x[i];
	}
	reverse(x, x + n + n + 1);
	reverse(v, v + n + n + 1);
	ans = max(ans, solve());
	printf("%lld\n", ans);
	return 0;
}

