using namespace std;

vector<uint64_t> X;
vector<uint32_t> V;

uint32_t N;
uint64_t C;

int64_t exec()
{
  vector<uint64_t> sum_V_start, sum_V_stop;
  sum_V_start.reserve(N+1);
  sum_V_stop.reserve(N+1);

  sum_V_start.push_back(V[N+1]);
  sum_V_stop.push_back(V[0]);
  for (uint32_t n=1; n<=N; ++n) {
    sum_V_start.push_back(sum_V_start.back() + V[N-n+1]);
    sum_V_stop.push_back(sum_V_stop.back() + V[n]);    
  }

  int64_t max_calory = 0;

  for (int32_t start=-N; start<=0; ++start) {
    uint64_t dist_to_start = C - X[start+N+1];
    int64_t calory_to_start = 0;
    // for (uint32_t n=N+1; n>=start+N+1; --n)
    // 	calory_to_start += V[n];
    calory_to_start = sum_V_start[-start];

    for (int32_t stop=0; stop - start <= N; ++stop) {
      uint64_t dist_to_stop = X[stop];

      uint64_t dist = min (2*dist_to_start + dist_to_stop, dist_to_start + 2*dist_to_stop);

      int64_t calory_to_stop = 0;
      // for (uint32_t n=0; n<=stop; ++n)
      // 	calory_to_stop += V[n];
      calory_to_stop = sum_V_stop[stop];

      int64_t calory = calory_to_start + calory_to_stop - dist;
      if (calory > max_calory)
	max_calory = calory;
    }
  }
  return max_calory;
}

int main()
{
  cin >> N >> C;

  X.reserve(N+2);
  V.reserve(N+2);
  X.push_back(0);
  V.push_back(0);

  for (uint32_t n = 0; n < N; ++n) {
    uint64_t x;
    uint32_t v;
    cin >> x >> v;
    X.push_back(x);
    V.push_back(v);
  }

  X.push_back(C);
  V.push_back(0);

  cout << exec() << endl;

  return 0;
}

