  set<pair<ll, ll>> sushi;  // 登場位置、カロリー
  for (ll i = 0; i < n; i++) {
    ll x, v;
    cin >> x >> v;
    sushi.insert(make_pair(x, v));
  }

  ll sowa, ans = 0;

  // 入り口から時計回り
  sowa = 0;
  for (auto it = sushi.begin(); it != sushi.end(); it++) {
    sowa += it->second;
    ans = max(ans, sowa - it->first);
  }

  // 入り口から半時計回り
  sowa = 0;
  for (auto it = sushi.rbegin(); it != sushi.rend(); it++) {
    sowa += it->second;
    ans = max(ans, sowa - (c - it->first));
  }

  // 入り口から時計回りーの反時計回り
  ll res = 0;
  sowa = 0;
  for (auto it = sushi.begin(); it != sushi.end() && it->first < c / 2; it++) {
    sowa += it->second;
    res = max(res, sowa - (it->first) * 2);
  }
  sowa = 0;
  for (auto it = sushi.rbegin(); it != sushi.rend() && it->first > c / 2; it++) {
    sowa += it->second;
    ans = max(ans, res + sowa - (c - it->first));
  }

  // 入り口から反時計回りーの時計回り
  res = 0;
  sowa = 0;
  for (auto it = sushi.rbegin(); it != sushi.rend() && it->first > c / 2; it++) {
    sowa += it->second;
    res = max(res, sowa - (c - it->first) * 2);
  }
  sowa = 0;
  for (auto it = sushi.begin(); it != sushi.end() && it->first < c / 2; it++) {
    sowa += it->second;
    ans = max(ans, res + sowa - it->first);
  }

  cout << ans << endl;
}

