using namespace std;
const int maxn = 1e5 + 5;
const long long inf = 1e14 + 5;
int n,v[maxn];
long long c, ans,x[maxn];
long long dp[2][maxn], m[2][maxn];
int main(){
    scanf("%d %lld",&n, &c);
    for(int i = 0; i < n; i++){
        scanf("%lld %d",&x[i],&v[i]);
    }
    for(int i = 0; i < n; i++) dp[0][i] = dp[1][i] = -inf;//初始化
    long long sum = 0;
    for(int i = 0; i < n; i++){
        sum += v[i];
        dp[0][i] = max(dp[0][i - 1], sum - x[i]);//走或不走这个点
        m[0][i] = sum - 2 * x[i];//走回去自然是两倍
    }
    sum = 0;//置为0
    for(int i = n - 1; i >= 0; i--){//反着来
        sum += v[i];
        dp[1][i] = max(dp[1][i + 1], sum - (c - x[i]));
        m[1][i] = sum - 2 * (c - x[i]);
    }
    ans = max(dp[0][n-1], dp[1][0]);//正着走到n-1和反着走到0的最大值
    for(int i = 0; i < n; i++){
        ans = max(ans, m[0][i] + dp[1][i + 1]);//反着走中途倒回去
        ans = max(ans, m[1][n - i] + dp[0][n - i - 1]);//正着走中途倒回去
    }
    if(ans != 0)
        printf("%lld\n",ans);
    else
        printf("0\n");
return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;


ll solve(ll n, ll c, vector<ll> x, vector<ll> v) {

  ll res = 0;
  vector<ll> s(n);
  s[0] = v[0];
  for(ll i=1;i<n;i++) {
    s[i] = s[i-1] + v[i];
  }
  // clockwise
  for(ll i=0;i<n;i++) {
    res = max(s[i] - x[i], res);
  }
  // counter clockwise
  for(ll i=n-1;i>=1;i--) {
    res = max((s[n-1] - s[i-1]) - (c-x[i]) , res);
  }
  res = max(s[n-1] - (c-x[0]), res);

  if(n<=1)
    return res;
  // n >= 2
  //
  vector<ll> a(n-1);
  a[n-2] = s[n-1] - s[n-2] - (c-x[n-1]);
  for(ll i=n-3;i>=0;i--) {
    a[i] = max((s[n-1] - s[i]) - (c - x[i+1]), a[i+1]);
  }
  // oa + ab = 2oa + ob
  for(ll i=0;i<n-1;i++) {
    ll vv = s[i]; // 2oa
    ll xx = 2*x[i]; // 2oa
    res = max(vv - xx + a[i], res);
  }

  vector<ll> b(n-1, 0);
  b[1] = s[0] - x[0];
  for(ll i=2;i<n-1;i++) {
    b[i] = max(s[i-1] - x[i-1], b[i-1]);
  }

  for(ll i = n-1;i>0;i--) {
    ll vv = s[n-1] - s[i-1];
    ll xx = 2 * (c - x[i]);
    res = max(vv - xx + b[i], res);
  }

  return res;
}

int main() {
  ll n, c;
  cin >> n >> c;
  vector<ll> x(n), v(n);

  for(ll i=0;i<n;i++) {
    cin >> x[i] >> v[i];
  }
  cout << solve(n, c, x, v);
}

