long long int calc_max_cal(const vector<pair<long long int, long long int>>& sushi){
  long long int sum_sushi_cal = 0;
  long long int max_cal = 0;
  for (auto& s : sushi) {
    sum_sushi_cal += s.second;
    max_cal = max(max_cal, sum_sushi_cal - s.first);
  }
  return max_cal;
}
int main() {
  int N;
  long long int C;
  cin >> N >> C;

  vector<pair<long long int, long long int>> sushi_forward;
  vector<pair<long long int, long long int>> sushi_backward;
  sushi_forward.reserve(N);
  sushi_backward.reserve(N);
  for (int ii = 0; ii<N; ii++) {
    long long int x;
    long long int v;
    cin >> x >> v;
    sushi_forward.push_back(make_pair(x, v));
    sushi_backward.push_back(make_pair(C-x, v));
  }

  sort(sushi_forward.begin(), sushi_forward.end(),
       [](const auto& item1, const auto& item2) {return item1.first < item2.first; });
  sort(sushi_backward.begin(), sushi_backward.end(),
       [](const auto& item1, const auto& item2) {return item1.first < item2.first; });
  long long int max_cal_forward = calc_max_cal(sushi_forward);
  long long int max_cal_backward = calc_max_cal(sushi_backward);

  long long int max_cal = max(max_cal_forward, max_cal_backward);
  long long int sum_sushi_cal = 0;
  for (auto& s : sushi_forward) {
    sum_sushi_cal += s.second;
    max_cal = max(max_cal, sum_sushi_cal - s.first - s.first + max_cal_backward);
  }
  sum_sushi_cal = 0;
  for (auto& s : sushi_backward) {
    sum_sushi_cal += s.second;
    max_cal = max(max_cal, sum_sushi_cal - s.first - s.first + max_cal_forward);
  }

  cout << max_cal;
  return 0;
}

