const int MAX_N = (int) 1e5;
ll N, C, x[MAX_N], v[MAX_N], dp[MAX_N + 1], dpr[MAX_N + 1];

void solve() {
    ll ans = 0;
    REP(i, N) {
        REP(j, N - i) {
            ll oa = dp[i + 1] - x[i];
            ll ob = dpr[j + 1] - (C - x[N - j]);
            ll ab = dp[i + 1] + dpr[j + 1] - 2 * x[i] - (C - x[N - j]);
            ll ba = dp[i + 1] + dpr[j + 1] - 2 * (C - x[N - j]) - x[i];
            ans = max({ans, oa, ob, ab, ba});
        }
    }
    cout << ans << endl;
}

