	cin >> N >> C;

	for (int i=0; i<N; i++) {
		cin >> x[i] >> v[i];
		r_v[i] = v[i];
	}
	reverse(r_v, r_v+N);

	for (int i=0; i<N; i++) {
		d[i+1] = x[i];
		r_d[i+1] = C - x[N-1-i];
	}

	for (int i=0; i<N; i++) {
		cum_v[i+1] = cum_v[i] + v[i];
		r_cum_v[i+1] = r_cum_v[i] + r_v[i];
	}

	ll tmp_max_cal = 0;
	for (int i=1; i<=N; i++) {
		ll cal = cum_v[i] - d[i];
		tmp_max_cal = max(tmp_max_cal, cal);
		max_cal[i] = tmp_max_cal;
	}

	tmp_max_cal = 0;
	for (int i=1; i<=N; i++) {
		ll cal = r_cum_v[i] - r_d[i];
		tmp_max_cal = max(tmp_max_cal, cal);
		r_max_cal[i] = tmp_max_cal;
	}

	ll ans = 0;

	/*
	// 時計回りのみ
	for (int i=0; i<=N; i++) {
		ll cal = cum_v[i] - d[i];
