            max_2L[N - 1 - i] = max(max_2L[N - i], sum - 2 * (C - x[N - 1 - i]));
        }
    }
    sum = 0;
    REP(i, N){
        sum += v[i];
        if(i == 0){
            max_R[i] = max(0LL, sum - x[i]);
            max_2R[i] = max(0LL, sum - 2 * x[i]);
        }else{
            max_R[i] = max(max_R[i - 1], sum - x[i]);
            max_2R[i] = max(max_2R[i - 1], sum - 2 * x[i]);
        }
    }
    ll ans = 0;
    REP(i, N){
        if(i == 0) ans = max(ans, max_L[0]);
        ans = max(ans, max_2R[i - 1] + max_L[i]);
    }
    REP(i, N){
        if(i == N - 1) ans = max(ans, max_R[N - 1]);
        ans = max(ans, max_2L[i + 1] + max_R[i]);
    } 
    PRINT(ans);
    return 0;
}

