    if(f[i]-x[i]<g[i]){
      a[i]=a[i-1];
    }else{
      a[i]=i;
    }
  }
  vector<long long> p(n+1);
  p[n]=v[n]-(c-x[n]);
  for(int i=n-1;i>0;i--){
    p[i]=p[i+1]+v[i]+(c-x[i+1])-(c-x[i]);
  }

  long long ans=0;
  for(int i=n;i>1;i--){
    ans=max(ans,p[i]);
    ans=max(ans,g[i-1]);
    ans=max(ans,p[i]+g[i-1]-min(c-x[i],x[a[i-1]]));
  }
  if(ans<g[n]) ans=g[n];
  if(ans<p[1]) ans=p[1];
  cout<<ans<<endl;
  return 0;
}

