        cin >> X.at(i);
        cin >> V.at(i);
    }

    // 価値の累積和
    vector<ll> Ac(N+1);

    // i個目まで食べたときの満腹度
    vector<ll> f(N+1);

    // iまで行けるときのMax満腹度
    vector<ll> g(N+1);

