    // mode 1 : Aで折り返す
    FOR(mode, 0, 2){

        if(mode==1){
            reverse(X.begin()+1, X.end());
            FOR(i, 1, N+1){
                X[i] = C - X[i];
            }
            reverse(V.begin()+1, V.end());
        }

        Ac[0] = V[0];
        FOR(i, 1, N+1){
            Ac[i] = Ac[i-1] + V[i];
        }

        FOR(i, 0, N+1){
            f[i] = Ac[i] - X[i];
