int N;
ll C;

ll x[MAX_N + 2], v[MAX_N + 2];
ll f[MAX_N + 2];
ll g[MAX_N + 2];

void init()
{
  f[0] = 0;
  ll vsum = 0;
  for (int i = 0; i < N; i++) {
    vsum += v[i];
    f[i + 1] = vsum - x[i];
  }
  for (int i = 0; i < N; i++) {
    g[i + 1] = max(f[i + 1], g[i]);
  }
}

int main(void)
{
  cin >> N >> C;
  REP(i, N) cin >> x[i] >> v[i];

  init();

  ll ans = 0;
  ll vsum = 0;

  // REP(i, N + 1) cout << f[i] << SLN(i, N + 1);
  // REP(i, N + 1) cout << i << ":" << g[i] << SLN(i, N + 1);

  // return 0;
  x[N] = C, v[N] = 0;
  for (int i = N; i >= 0; i--) {
    vsum += v[i];
    ll xb = vsum - (C - x[i]);
    ll ga = g[i];
    // N のとき (A だけでいったとき) と
    // 0 のとき (B だけでいったとき) は
    // 被りがないのでマイナスする必要がない
    if (i < N && i != 0) {
      // どっち周りの方が安くつくかを判定してマイナス
      int idx = lower_bound(g, g + N, ga) - g - 1;
      // cout << "idx: " << idx << endl;
      // cout << x[idx] << ":" << (C - x[i]) << endl;
      // cout << g[i] << " : "
      //      << "idx: " << idx << ": " << x[idx] << ":" << (C - x[i]) << endl;
      // -1 の場合 A の方に取りに行かないのが正解
      if (idx != -1) {
        xb -= min(x[idx], (C - x[i]));
      }
    }
    ans = max(ans, xb + ga);
  }
  cout << ans << endl;

  return 0;
}

