using namespace std;

struct S { ll val, dist; };

int main() {
	ll N, C;
	cin >> N >> C;
	vector<ll> x(N);
	vector<ll> v(N);
	for (int i = 0; i < N; i++) {
		cin >> x[i] >> v[i];
	}

	vector<ll> d1(N + 1, 0);
	vector<ll> d2(N + 1, 0);
	for (int i = 1; i < d1.size(); i++) {
		d1[i] = d1[i - 1] + v[i - 1];
		d2[i] = d2[i - 1] + v[N - i];
	}

	vector<S> val1(N + 1);
	vector<S> val2(N + 1);
	val1[0].val = 0;
	val1[0].dist = 0;
	val2[0].val = 0;
	val2[0].dist = 0;
	for (int i = 1; i < val1.size(); i++) {
		if (val1[i - 1].val < (d1[i] - x[i - 1])) {
			val1[i].val = d1[i] - x[i - 1];
			val1[i].dist = x[i - 1];
		} else {
			val1[i].val = val1[i - 1].val;
			val1[i].dist = val1[i - 1].dist;
		}
		if (val2[i - 1].val < (d2[i] - (C - x[N - i]))) {
			val2[i].val = d2[i] - (C - x[N - i]);
			val2[i].dist = C - x[N - i];
		} else {
			val2[i].val = val2[i - 1].val;
			val2[i].dist = val2[i - 1].dist;
		}
	}

	ll res = 0;
	for (int i = 1; i <= N; i++) {
		ll min_dist = min(val1[i].dist, val2[N - i].dist);
		res = max(res, val1[i].val + val2[N - i].val - min_dist);
	}

	cout << res << endl;
	return 0;
}

