int main(void) {

	int n, i, k;
	long long int c, x[10000], v[10000], sum[10000] = {}, max = 0,y=0;

	scanf("%d %d", &n, &c);

	for (i = 1; i < n+1; i++) {
		scanf("%d %d", &x[i], &v[i]);
	}

	x[0] = 0;
	v[0] = 0;
	for (k = 1; k < n+1; k++) {
		for (i = 0; i < k; i++) {
			y = x[i + 1] - x[i];
			sum[k] += v[i+1];
			if (0 <= y && y <= c / 2) {
				sum[k] -= y;
			}
			else if (-c / 2 <= y && y < 0) {
				sum[k] -= -y;
			}
			else if (y > c / 2) {
				sum[k] -= c - y;
			}
			else {
				sum[k] -= c + y;
			}
		}
	}

	for (k = 1; k < n+1; k++) {
		if (sum[k] > max) {
			max = sum[k];
		}
	}

	printf("%d\n", max);

	return 0;
}

