signed main() {
  init();
  ll N, C;
  cin >> N >> C;
  vll x(N), v(N);
  rep(i, N) cin >> x[i] >> v[i];

  vll A(N), B(N);
  ll before = 0;
  rep(i, N) {
    A[i] = v[i] - (x[i] - before);
    before = x[i];
  }

  before = 0;
  repr(i, N - 1) {
    B[N - 1 - i] = v[i] - (C - x[i] - before);
    before = C - x[i];
  }

  ll ans = 0;
  ll a = 0, b = 0;
  rep(i, N) {
    a += A[i];
    b += B[i];
    chmax(ans, a);
    chmax(ans, b);
  }

  vll Am(N), Bm(N);
  ll m = 0;
  ll c = 0;
  rep(i, N) {
    c += A[i];
    chmax(m, c);
    Am[i] = m;
  }

  m = 0;
  c = 0;
  rep(i, N) {
    c += B[i];
    chmax(m, c);
    Bm[i] = m;
  }

  ll current = 0;
  rep(i, N) {
    current += A[i];
    ll score = current - x[i];
    score += Bm[N - i - 2];
    chmax(ans, score);
  }

  current = 0;
  rep(i, N) {
    current += B[i];
    ll score = current - (C - x[N - 1 - i]);
    score += Am[N - i - 2];
    chmax(ans, score);
  }

  ANS;
  return 0;
}

