typedef long long ll;
int main(int argc, char **argv){
  int N;
  ll C;
  std::cin >> N >> C;

  std::vector<ll> posx(N+1,0),negx(N+1,0),v(N+1,0),posco(N+1,0),negco(N+1,0),posrco(N,0),negrco(N,0);

  for(int i = 0; i < N; i++){
    std::cin >> posx[i] >> v[i];
    negx[N-1-i]=C-posx[i];
  }

  posco[0]=v[0]-posx[0];
  posrco[0]=posco[0]-posx[0];
  negco[0]=v[N-1]-negx[0];
  negrco[0]=negco[0]-negx[0];

  std::vector<ll> maxvec(3,0),posmax(2,0),negmax(2,0);
  maxvec[0]=posco[0];
  maxvec[1]=negco[0];

  //single direction
  for(int i = 1; i < N; i++){
    posco[i]+=posco[i-1]+v[i]-posx[i]+posx[i-1];
    posrco[i]=posco[i]-posx[i];
    negco[i]+=negco[i-1]+v[N-1-i]-negx[i]+negx[i-1];
    negrco[i]=negco[i]-negx[i];
    maxvec[0]=std::max(maxvec[0],posco[i]);
    maxvec[1]=std::max(maxvec[1],negco[i]);
  }
  //ここまでok

  //rev
  for(int i = 0; i < N; i++){
    if(posrco[i]<0) continue;
    for(int j = 0; j < N-1-i; j++){
      if(negrco[j]<0) continue;
      ll bufsum=posco[i]+negco[j];
      ll bufmax=bufsum-std::min(posx[i],negx[j]);
      maxvec[2]=std::max(maxvec[2], bufmax);
    }
  }

  ll maxcal=*std::max_element(maxvec.begin(), maxvec.end());
  std::cout << maxcal << std::endl;

  return 0;
}

