    ios::sync_with_stdio(false);
    // std::ifstream in("input.txt");
    // std::cin.rdbuf(in.rdbuf());
    ll n, c;
    cin >> n >> c;
    vector<pair<ll, ll>> xv(n);
    rep(i, n) cin >> xv[i].first >> xv[i].second;
    vector<pair<ll, ll>> dpr(n + 1), dpl(n + 1);
    dpr[0] = make_pair(0, 0);
    dpl[0] = make_pair(0, 0);
    ll plus = 0, minus = 0, score = 0;
    rep(i, n) {
        plus += xv[i].second;
        if (score < (plus - xv[i].first)) {
            minus = xv[i].first;
            score = plus - minus;
        }
        dpr[i + 1] = make_pair(score, minus);
    }
    plus = 0, minus = 0, score = 0;
    rep(i, n) {
        plus += xv[n - 1 - i].second;
        if (score < (plus - (c - xv[n - 1 - i].first))) {
            minus = c - xv[n - 1 - i].first;
            score = plus - minus;
        }
        dpl[i + 1] = make_pair(score, minus);
    }
    ll ans = 0;
    rep(i, n + 1) {
        ans = max(ans, dpr[i].first + dpl[n - i].first - min(dpr[i].second, dpl[n - i].second));
    }
    cout << ans << endl;
    return 0;
}

