using namespace std;


int main()
{
    long long N, C;
    cin >> N >> C;
    vector<long long> x(N), v(N);
    for( int i = 0; i < N; i++ ) cin >> x[i] >> v[i];


    vector<long long> vSumCW(N), vSumCCW(N);
    vSumCW = vSumCCW = v;
    for( int i = 0; i < N-1; ++i ) vSumCW[i+1] += vSumCW[i];
    for( int i = N-1; i > 0; --i ) vSumCCW[i-1] += vSumCCW[i];

    // maxEneCW[i]: v[0] + ... + v[j] - x[j] ( i <= j ) のうちの最大値
    vector<long long> maxEneCW(N), maxEneCCW(N);
    maxEneCW[0] = max( 0LL, vSumCW[0] - x[0] );
    maxEneCCW[N-1] = max( 0LL, vSumCCW[N-1] - (C-x[N-1]) );
    for( int i = 1; i < N; ++i )
        maxEneCW[i] = max( maxEneCW[i-1], vSumCW[i]-x[i] );
    for( int i = N-2; i > 0; --i )
        maxEneCCW[i] = max( maxEneCCW[i+1], vSumCCW[i]-(C-x[i]) );

    long long ansCW = 0, ansCCW = 0;
    // 始め時計回りに回る場合
    for( int i = 0; i < N; ++i ){
        if( maxEneCCW[i+1] <= 0 or i == N-1 ) ansCW = max( ansCW, vSumCW[i] - x[i] );
        else ansCW = max( ansCW, vSumCW[i] - 2*x[i] + maxEneCCW[i+1] );
    }
    // 始め反時計回りに回る場合
    for( int i = N-1; i >= 0; --i ){
        if( maxEneCW[i-1] <= 0 or i == 0 ) ansCCW = max( ansCCW, vSumCCW[i] - (C-x[i]) );
        else ansCCW = max( ansCCW, vSumCCW[i] - 2*(C-x[i]) + maxEneCW[i-1] );
    }
    cout << max( ansCW, ansCCW ) << endl;

    return 0;

}

