	HLN = 0;
	QRN = 0;
	QLN = 0;

	R = 0;
	L = 0;

	for (ll a = 0; a < N; a++)
	{
		if (RValue[a].first > C / 2) break;

		R += RValue[a].second;

		if (HR < R - RValue[a].first)
		{
			HR = R - RValue[a].first;
			HRN = RValue[a].first;
		}

	}

	for (ll a = 0; a < N; a++)
	{
		if (LValue[a].first > C / 2) break;

		L += LValue[a].second;

		if (HL < L - LValue[a].first)
