		if (QL < L - LValue[a].first)
		{
			QL = L - LValue[a].first;
			QLN = LValue[a].first;
		}

	}

	Ans = max(Ans, max(QR + HL - min(QRN, HLN), QL + HR - min(QLN, HRN)));

	OUT << Ans << endl;

	return 0;
}

