int n;
long long ans, sum[100005];
long long f[100005];
long long c;
struct ss{
    long long x;
    long long v;
    bool operator < (const ss& other) {
        if (x == other.x) return v < other.v;
        return x < other.x;
    }
}s[100005];

long long g[100005];

void solve() {
    sort(s+1,s+n+1);
    g[0] = 0;
    long long now = 0, mx = 0;
    for (int i = 1; i <= n; i++) {
        now += s[i].v-(s[i].x-s[i-1].x);
        mx=max(now,mx);
        g[i]=mx;
    }
    ans=max(ans,g[n]);
    long long res = 0;
    for (int i = n; i>=1;i--) {
        res+=s[i].v-(s[i].x-s[i+1].x);
        ans=max(ans,g[i-1]+res-2*(c-s[i].x));
    }
}

int main() {
    cin>>n>>c;
    for (int i = 1; i <= n; i++) {
        scanf("%lld%lld", &s[i].x, &s[i].v);
    }
    solve();
    for (int i = 1; i <= n; i++) s[i].x=c-s[i].x;
    solve();
    cout<<ans;
    return 0;
}

