int main(){
  cin >> n >> c;
  for(int i=0;i<n;i++) cin >> x[i] >> v[i];
  ll ans = 0;
  ll now = 0, maxi = 0;
  for(int i=0;i<n;i++){
    now += v[i] - x[i] + ((i>0) ? x[i-1] : 0);
    maxi = max(maxi, now);
    cv[i] = now;
    cm[i] = maxi;
  }
  ans = max(ans, cm[n-1]); // ->->->
  now = 0, maxi = 0;
  for(int i=n-1;i>=0;i--){
    now += v[i] - ((i+1<n) ? x[i+1] : c) + x[i];
    maxi = max(maxi, now);
    acv[i] = now;
    acm[i] = maxi;
  }
  ans = max(ans, acm[0]); // <-<-<-
  // -> <- <-
  for(int i=0;i+1<n;i++){
    ans = max(ans, cv[i] - x[i] + acm[i+1]);
  }
  // <- -> ->
  for(int i=n-1;i>0;i--){
    ans = max(ans, acv[i] - (c - x[i]) + cm[i-1]);
  }
  cout << ans << endl;
