int main(void) {
	int N;
	ll C;
	cin >> N >> C;
	for (int i = 1; i <= N; i++) {
		cin >> x[i] >> v[i];
	}
	int pos = 0;
	for (int i = 1; i <= N; i++) {
		ll cal1 = 0, cal2 = 0;
		int pos1 = 0, pos2 = 0;
		for (int j = pos; j < pos + N; j++) {
			int t = j % (N + 1);
			if (v[t] > 0) {
				cal1 = v[t] - (x[t] > x[pos] ? abs(x[t] - x[pos]) : C - x[pos] + x[t]);
				pos1 = t;
				break;
			}
		}
		for (int j = pos; j > pos - N; j--) {
			int t = (j + N + 1) % (N + 1);
			if (v[t] > 0) {
				cal2 = v[t] - (x[t] < x[pos] ? abs(x[t] - x[pos]) : C + x[pos] - x[t]);
				pos2 = t;
				break;
			}
		}
		dp[i] += dp[i - 1] + max(cal1, cal2);
		if (cal1 > cal2) {
			v[pos1] = 0;
			pos = pos1;
		}
		else {
			v[pos2] = 0;
			pos = pos2;
		}
	}
	ll ma = dp[0];
	for (int i = 1; i <= N; i++) {
		ma = max(dp[i], ma);
	}
	cout << ma << endl;
	//system("pause");
}

