    for (int i = 0; i < n; i++) cin >> x.at(i) >> v.at(i);
    long maxClockFirst = 0;
    long cntClockFirst = 0;
    for (int i = 0; i < n; i++) {
        cntClockFirst += v.at(i);
        if (maxClockFirst < cntClockFirst - x.at(i)) {
            maxClockFirst = cntClockFirst - x.at(i);
        }
        long maxCounterSecond = 0;
        long cntCounterSecond = 0;
        for (int j = n - 1; j > i; j--) {
            cntCounterSecond += v.at(j);
            if (maxCounterSecond < cntCounterSecond - x.at(i) + x.at(j) - c) {
                maxCounterSecond = cntCounterSecond - x.at(i) + x.at(j) - c;
            }
        }
        long cntBoth = cntClockFirst + maxCounterSecond;
        if (maxClockFirst < cntBoth - x.at(i)) {
            maxClockFirst = cntBoth - x.at(i);
        }
    }
    long maxCounterFirst = 0;
    long cntCounterFirst = 0;
    for (int i = n - 1; i >= 0; i--) {
        cntCounterFirst += v.at(i);
        if (maxCounterFirst < cntCounterFirst + x.at(i) - c) {
            maxCounterFirst = cntCounterFirst + x.at(i) - c;
        }
        long maxClockSecond = 0;
        long cntClockSecond = 0;
        for (int j = 0; j < i; j++) {
            cntClockSecond += v.at(j);
            if (maxClockSecond < cntClockSecond - x.at(j) + x.at(i) - c) {
                maxClockSecond = cntClockSecond - x.at(j) + x.at(i) - c;
            }
        }
        long cntBoth = cntCounterFirst + maxClockSecond;
        if (maxCounterFirst < cntBoth + x.at(i) - c) {
            maxCounterFirst = cntBoth + x.at(i) - c;
        }
    }

    cout << max(maxClockFirst, maxCounterFirst) << endl;
    return 0;
}

