typedef long long ll;
ll rsum[100005];        // (0...i)の時計回りの累積和
ll lsum[100005];        // (i...(n+1)(=0))の反時計回りの累積和
ll max_rsum[100005];
ll max_lsum[100005];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll c;
    cin >> n >> c;
    vector<ll> x(n + 2);
    vector<int> v(n + 2);
    x[0] = 0, x[n + 1] = c;
    v[0] = 0, v[n + 1] = 0;
    for(int i = 1; i <= n; ++i){
        cin >> x[i] >> v[i];
    }

    ll temp = 0;
    for(int i = 0; i < n; ++i){
        rsum[i + 1] = rsum[i] + v[i + 1] - (x[i + 1] - x[i]);
        temp = max(temp, rsum[i]);
        max_rsum[i + 1] = temp;
    }
    temp = 0;
    for(int i = n + 1; i > 1; --i){
        lsum[i - 1] = lsum[i] + v[i - 1] - (x[i] - x[i - 1]);
        temp = max(temp, lsum[i - 1]);
        max_lsum[i - 1] = temp;
    }

    ll res = *max_element(rsum, rsum + n + 2);
    res = max(res, *max_element(lsum, lsum + n + 2));

    // 時計回りor反時計回りから始めてi個取るときを考える
    for(int i = 1; i < n; ++i){
        // 時計回りの(0...i)間の累積和と、残りの要素で反時計回りの累積和の最大値の合計
        res = max(res, max_rsum[i] - x[i] + max_lsum[i + 1]);
        // 反時計回りの((n+1)...(n+1-i))間の累積和と、残りの要素で時計回りの累積和の最大値の合計
        res = max(res, max_lsum[n + 1 - i] - (c - x[n + 1 - i]) + max_rsum[n - i]);
    }

    cout << res << endl;
}

