			maxfsi = fm[i - 1].second;
		}
		fm[i] = pair<long long,long long>(maxfs,maxfsi);
		fp = xl[i];
	}
	for (int i = N - 1; i >= 0; i--)
	{
		bs += vl[i] - (bp - xl[i]);
		if (bs > maxbs) {
			maxbs = bs;
			maxbsi = xl[i];
		}
		else if(i < (N - 1)){
			maxbs = bm[i + 1].first;
			maxbsi = bm[i + 1].second;
		}
		bm[i] = pair<long long, long long>(maxbs, maxbsi);
		bp = xl[i];
	}


	for (size_t i = 0; i < N; i++)
	{
		if (i < N - 1) {
			long long p1 = fm[i].first - fm[i].second + bm[i + 1].first;
			long long p2 = fm[i].first - (C - bm[i].second) + bm[i + 1].first;
			maxv = max(maxv, max(p1, max(p2, max(fm[i].first, bm[i + 1].first))));
		}
		else {
			maxv = max(maxv, fm[i].first);
		}
	}
	cout << maxv;
	return 0;
}

