    vl[i+1] = vsum[n]-vsum[n-i-1]-xl[i+1];
  }

  ll ans = 0;
  set<P> st;
  st.insert(make_pair(0,0));
  IREP(l,n+1){
    ll e = 0;
    //左からl個とる
    e += vl[l];
    //右からとる
    auto it = prev(st.end());
    e += it->first;
    //右と左どっちで往復するか？小さい方のコスト引く
    ll r = it->second;
    e -= min(xr[r],xl[l]); 
    ans = max(ans,e);
    //lが1個減るので，setに候補を追加
    ll i = n-l+1;
    st.insert(make_pair(vr[i],i));
  } 
  cout << ans << endl;
}

