lli fn(lli x[], lli v[], lli c, const int N)
{
  lli y[N + 1];
  y[0] = 0;
  for (int i = 0; i < N; ++i) {
    y[i + 1] = v[i] - (x[i] + x[i]);
    y[i + 1] = max(y[i + 1], y[i]);
  }

  lli mx = 0;

  lli sum = 0;
  for (int i = N - 1; 0 <= i; --i) {
    sum += v[i];
    lli z = sum - (c - x[i]) + y[i];
    mx = max(mx, z);
  }

  return mx;
}

