int n;
pair<ll, int> tree[N<<2];
ll C, x[2][N], v[N], cum[2][N], arr[2][N];
void build(int node, int l, int r) {
  if (l == r) { tree[node] = {cum[0][l] - x[0][l], l}; return; } 
  int mid = (l + r) >> 1;
  build(node << 1, l, mid);
  build(node << 1|1, mid + 1, r);
  if (tree[node << 1].first >= tree[node << 1|1].first) {
    tree[node] = tree[node << 1];
  } else tree[node] = tree[node << 1|1];
}
pair<ll, int> query(int node, int l, int r, int i, int j) {
  if (r < i || l > j) return {-1, -1};
  if (i <= l && r <= j) {
    return tree[node]; 
  } int mid = (l + r) >> 1;
  auto lft = query(node << 1, l, mid, i, j);
  auto rgt = query(node << 1|1, mid+1, r, i, j);
  if (lft.first >= rgt.first) return lft;
  return rgt;
}

