  for (int i = 1; i <= n; ++i) {
    cum[0][i] = cum[0][i - 1] + v[i];
    cum[1][i] = cum[1][i - 1] + v[n - i + 1];
  }
  build(1, 1, n);
  ll ans = 0;
  for (int lft = 0; lft <= n; lft++) {
    pair<ll, int> val = query(1, 1, n, 1, n-lft);
    if (val.first < 0) val = {0, 0};
    ans = max(ans, cum[1][lft] - x[1][lft]);
    // debug(cum[1][lft] - x[1][lft]);
    ans = max(ans, val.first);
    // debug(ans);
    ll tot = cum[1][lft] - x[1][lft] + val.first;
    // debug(lft, tot, x[1][lft], val.second, cum[1][lft]);
    ans = max(ans, tot - x[1][lft]);
    ans = max(ans, tot - x[0][val.second]);
  }
  cout << ans << '\n';
}

