// AtCoder Beginner Contest 095 - Problem D: Static Sushi (https://atcoder.jp/contests/abc095/tasks/arc096_b) 
#include <bits/stdc++.h>

using namespace std;
using ll = long long;
using ii = pair<ll, ll>;

struct Info { ll cals, dist, best; };

ll solve(ll N, ll C, const vector<ii>& xs)
{
    vector<Info> Ls(N + 1), Rs(N + 1);
    ll ans = 0;

    Rs[0] = Info { 0, 0, 0 };
    Ls[0] = Rs[0];

    for (ll i = 1; i <= N; ++i)
    {
        auto x = xs[i - 1].first;
        auto v = xs[i - 1].second;

        Rs[i].cals = Rs[i - 1].cals + v;
        Rs[i].dist = x;

        ans = max(ans, Rs[i].cals - Rs[i].dist);
        Rs[i].best = max(Rs[i - 1].best, Rs[i].cals - Rs[i].dist);

#ifdef DEBUG
cout << "i = " << i << ", x = " << x << ", v = " << v << '\n';
cout << "R cals = " << Rs[i].cals << ", dist = " << Rs[i].dist << ", best = " << Rs[i].best << '\n';
#endif
    }

    for (ll i = 1; i <= N; ++i)
    {
        auto x = xs[N - i].first;
        auto v = xs[N - i].second;

        Ls[i].cals = Ls[i - 1].cals + v;
        Ls[i].dist = C - x;

        ans = max(ans, Ls[i].cals - Ls[i].dist);
        Ls[i].best = max(Ls[i - 1].best, Ls[i].cals - Ls[i].dist);

#ifdef DEBUG
cout << "i = " << i << ", x = " << x << ", v = " << v << '\n';
cout << "L cals = " << Ls[i].cals << ", dist = " << Ls[i].dist << ", best = " << Ls[i].best << '\n';
#endif
    }

    for (ll i = 1; i <= N; ++i)
    {
        auto r = (Rs[i].cals - 2*Rs[i].dist) + Ls[N - i].best;
        auto l = (Ls[i].cals - 2*Ls[i].dist) + Rs[N - i].best;

        ans = max(ans, r);
        ans = max(ans, l);

#ifdef DEBUG
cout << "i = " << i << ", r = " << r << ", l = " << l << '\n';
#endif
    }

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);

    ll N, C;
    cin >> N >> C;

    vector<ii> xs(N);

    for (int i = 0; i < N; ++i)
        cin >> xs[i].first >> xs[i].second;

    auto ans = solve(N, C, xs);

    cout << ans << '\n';

    return 0;
}

