    for(int i=0;i<n;i++){
        int mal = segL.getmax(0, n-1-i).F;
        int tmp = resultR[i];
        chmax(ans, tmp + mal - x[i]);
    }
    rrep(i, n){
        int mar = segR.getmax(0, n-1-i).F;
        int tmp = resultL[i];
        chmax(ans, tmp + mar - rx[i]);
    }
    print(ans);
}

