int N;

void eraser(int *x,int *v,int address){

		int temp = address + i;

	for(int i = 0;i < N - address;i++){

		x[temp] = x[temp + 1];
		v[temp] = v[temp + 1];

	}


	N -= 1;

}	

int main(void){

	int C;

	int *x;
	int *v;

	int min_add = 0;
	int loca = 0;
	int after_sum = 0;
	int sum = 0;

	cin >> N >> C;

	x = new int[N];
	v = new int[N];

	for(int i = 0;i < N;i++){

		cin >> x[i] >> v[i];

	}


	for(int i = 0;i < N;i++){

		if(x[i] > (C / 2))
			x[i] = x[i] - C;
	}

	min_add = abs(x[0]) < abs(x[N - 1]) ? 0 : N - 1;

	after_sum = v[min_add] - abs(x[min_add]);

	if(after_sum < sum){

		cout << sum;

		return 0;

	}

	sum = after_sum;

	for(int i = 0;i < N;i++){

		int compare1,compare2;

		loca = x[min_add];

		int plus = (min_add + 1) > N - 1 ? 0 : min_add + 1;
		int minus = (min_add - 1) < 0 ? N - 1 : min_add - 1;

		sum = after_sum;

		compare1 = v[plus] - abs(x[plus] - loca);
		compare2 = v[minus] - abs(x[minus] - loca);

		if(compare1 < compare2){

			after_sum += compare2;

			eraser(x,v,minus);
			min_add = minus;


		}else{

			after_sum += compare1;

			eraser(x,v,plus);
			min_add = plus;

		}		


		if(sum > after_sum){

			break;

		}

	}

	cout << sum;

	return 0;

	}

