//Range Minimum Query
struct segment {
    int n;
    vector<int64_t> dat;
    // n_は範囲
    segment(int n_) { // nはn_以上の2^?
        n = 1<<(32-__builtin_clz(n_));
        if(n == 2*n_) n >>= 1;
        dat.assign(2*n-1, INT64_MIN);
    }
    //更新の手順
    inline int64_t theorem(int i) {
        int64_t chld = dat[i*2+1];
        int64_t chrd = dat[i*2+2];
        return max(chld, chrd);
    }
    inline int chld(int i) {return 2*i+1;}
    inline int chrd(int i) {return 2*i+2;}
    //初期化(初期状態はINT64_MAX)
    void init(const vector<int64_t> &vec) {
        int num = vec.size();
        rep(i, num) {
            dat[i+n-1] = vec[i];
        }
        rep(i, n-1) {
            dat[n-2-i] = theorem(n-2-i);
        }
    }
    // k番目の値をaに変更
    void update(int k, int64_t a) {
        // 葉の節点
        k += n-1;
        dat[k] = a;
        // 登りながら更新
        while(k>0) {
            k = (k-1)/2;
            dat[k] = theorem(k);
        }
    }
    //kは節点の番号, [l, r)に節点が対応
    // (a, b, 0, 0, n)で呼ぶ
    int64_t query_(int a, int b, int k, int l, int r) {
        if(a>=r || l>=b) return INT64_MIN;
        if(a<=l && r<=b) return dat[k];
        else {
            int chl = k*2+1;
            int chr = k*2+2;
            int64_t vl = query_(a, b, chl, l, (l+r)/2);
            int64_t vr = query_(a, b, chr, (l+r)/2, r);
            return max(vl, vr);
        }
    }
};

int main() {
    int n;
    cin >> n;
    ll c;
    cin >> c;
    vector<pair<ll, ll> > x(n);
    rep(i, n) {
        cin >> x[i].first >> x[i].second;
    }

    sort(all(x));

    vector<ll> migi(n), hidari(n);
    migi[0] = x[0].second - x[0].first;
    hidari[n-1] = x[n-1].second - c + x[n-1].first;
    rep(i, n-1) {
        migi[i+1] = migi[i] + x[i+1].second - x[i+1].first + x[i].first;
        hidari[n-2-i] = hidari[n-1-i] + x[n-2-i].second + x[n-2-i].first - x[n-1-i].first;
    }
    hidari.push_back(0);

    segment seg(n+1);
    seg.init(hidari);
    ll ans = 0;
    ll now;
    rep(i, n) {
        now = migi[i];
        ll g = seg.query_(i+1, n+1, 0, 0, n+1);
        now = max(now-x[i].first + g, now);
        ans = max(ans, now);
    }

    segment segr(n+1);
    reverse(all(migi));
    migi.push_back(0);
    segr.init(migi);
    rep(i, n) {
        now = hidari[n-1-i];
        ll g = segr.query_(i+1, n+1, 0, 0, n+1);
        now = max(now-c+x[n-1-i].first+g, now);
        ans = max(ans, now);
    }

    cout << ans << endl;
}

