                if(b2-a2>c6)
                    c6=b2-a2;
            }
            if(c4+c6>z2)
                z2=c4+c6;
        }
    }
    e= c1 > c2 ? c1 :c2;
    f= z1 > z2 ? z1 :z2;
    e= e > f ? e : f;
    cout<<e<<endl;
    return 0;
}

