using namespace std;

long long MAX1(vector<long long> v, int a) {
  long long max;
  max = v[0];
  for (int i = 0; i <= a; i++) {
    if (max < v[i]) max = v[i];
  }
  return max;
}

long long MAX2(vector<long long> v, int a, int N) {
  long long max;
  max = v[N];
  for (int i = N; i >= a; i--) {
    if (max < v[i]) max = v[i];
  }
  return max;
}

int main() {
  int N;
  long long C,E1,E2;
  cin>>N>>C;
  vector<long long> x(100001,0),v(100001,0),s1(100001,0),s2(100001,0),f1(100001,0),g1(100001,0),f2(100001,0),g2(100001,0);
  for (int i = 1; i <= N; i++) cin>>x[i]>>v[i];
  for (int i = 1; i <= N; i++) {
    s1[i] = 0;
    for (int j = 0; j <= i; j++) s1[i] += v[j];
  }
  for (int i = N; i >= 0; i--) {
    s2[i] = 0;
    for (int j = N; j >= i; j--) s2[i] += v[j];
  }
  for (int i = 0; i <= N; i++) {
    f1[i] = s1[i] - x[i];
    f2[i] = s2[i] - (C - x[i]);
  }
  for (int i = 0; i <= N; i++) {
    g1[i] = MAX1(f1,i);
    g2[i] = MAX2(f2,i,N);
  }
  E1 = 0;
  for (int i = N; i > 0; i--) {
    long long tmp;
    if (g1[i-1] <= 0) tmp = s2[i]  - (C - x[i]);
    else tmp = s2[i] + g1[i-1] - 2*(C - x[i]);
    if (E1 < tmp) E1 = tmp;
  }
  E2 = 0;
  for (int i = 0; i < N; i++) {
    long long tmp;
    if (g2[i+1] <= 0) tmp = s1[i] - x[i];
    else tmp = s1[i] + g2[i+1] - 2*x[i];
    if (E2 < tmp) E2 = tmp;
  }
  cout<<max(E1,E2)<<endl;
  return 0;
}

