using namespace std;
using ll = long long;

inline int lg(ll n) {
    return 64 - __builtin_clzll(n);
}

struct sparse_table {
    vector<vector<ll>> st;

    sparse_table(const vector<ll>& a) {
        const int w = lg(a.size());
        st.reserve(w);
        st.emplace_back(a);
        for (int k = 1; k < w; k++) {
            st.emplace_back(vector<ll>(a.size() - (1 << k) + 1));
            for (int i = 0; i < (int) a.size() - (1 << k) + 1; i++)
                st[k][i] = max(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        }
    }

    inline ll query(int l, int r) {
        if (l > r)
            return 0;
        int k = lg(r - l + 1) - 1;
        return max(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

int main() {
#ifdef LOCAL
    freopen("in", "r", stdin);
    //    freopen("out", "w", stdout);
#endif
