    vector<ll> x(n), v(n), F(n), B(n);
    for (int i = 0; i < n; i++) {
        scanf("%lld%lld", &x[i], &v[i]);
    }

    F[0] = v[0];
    for (int i = 1; i < n; i++)
        F[i] = F[i - 1] + v[i];
    for (int i = 0; i < n; i++)
        F[i] -= x[i];

    B[0] = v[n - 1];
    for (int i = 1; i < n; i++)
        B[i] = B[i - 1] + v[n - i - 1];
    for (int i = 0; i < n; i++)
        B[i] -= (c - x[n - i - 1]);

    sparse_table fst(F), bst(B);

    ll ans = LLONG_MIN;
    for (int i = 0; i < n; i++) {
        ll cur = max(F[i], F[i] + bst.query(0, n - 2 - i) - x[i]);
        ans = max(ans, cur);
    }

    ll res = LLONG_MIN;
    for (int i = 0; i < n; i++) {
        ll cur = max(B[i], B[i] + fst.query(0, n - 2 - i) - (c - x[n - i - 1]));
        res = max(res, cur);
    }

    cout << max({0LL, res, ans}) << endl;

