        y.at(n-i+1) = c - x.at(i);
        vy.at(n-i+1) = vx.at(i);
    }

    // 時計回りに行くときの最大
    for(int i = 0; i <= n; ++i) A.at(i+1) = A.at(i) + vx.at(i+1) - (x.at(i+1) - x.at(i));
