using namespace std;
typedef long long ll;

int main(){
    ll n, c;
    cin >> n >> c;
    vector<pair<ll, ll>> s(n);
    for(int i = 0; i < n; ++i){
        cin >> s.at(i).first >> s.at(i).second;
    }

    ll ans = 0;

    // clockwise
    vector<ll> cs1(n + 1, 0);
    ll cv = 0;
    for(int i = n - 1; i > 0; --i){
        cv += s.at(i).second;
        cs1.at(i) = max(
            cs1.at(i + 1),
            cv - 2 * (c - s.at(i).first)
        );
    }

    cv = 0;
    for(int i = 0; i < n; ++i){
        cv += s.at(i).second;
        ans = max(
            ans,
            cv - s.at(i).first + cs1.at(i + 1)
        );
    }

    // anticlockwise
    vector<ll> cs2(n + 1, 0);
    cv = 0;
    for(int i = 1; i <= n; ++i){
        cv += s.at(i - 1).second;
        cs2.at(i) = max(
            cs2.at(i - 1),
            cv - 2 * s.at(i - 1).first
        );
    }

    cv = 0;
    for(int i = n - 1; i >= 0; --i){
        cv += s.at(i).second;
        ans = max(
            ans,
            cv - (c - s.at(i).first) + cs2.at(i)
        );
    }

    cout << ans << endl;
    return 0;
}

