void solve() {
	int n;
	int64 C;
	cin >> n >> C;

	vector<int64> x(n);
	vector<int64> v(n);

	for(int i = 0; i < n; ++i) {
		cin >> x[i] >> v[i];
	}

	vector<int64> pref(n + 1, 0), pref2(n + 1, 0);

	for(int i = 1; i <= n; ++i) {
		pref[i] = v[i - 1] + pref[i - 1];
		pref2[i] = pref[i];
	}

	DBG(pref);

	for(int i = 1; i <= n; ++i) {
		pref[i] -= x[i - 1];
		pref2[i] -= 2 * x[i - 1];

		pref[i] = std::max(pref[i], pref[i - 1]);
		pref2[i] = std::max(pref2[i], pref2[i - 1]);
	}

	vector<int64> suff(n + 1, 0), suff2(n + 1, 0);

	for(int i = 1; i <= n; ++i) {
		suff[i] = v[n - i] + suff[i - 1];
		suff2[i] = suff[i];
	}

	for(int i = 1; i <= n; ++i) {
		suff[i] -= abs(C - x[n - i]);
		suff2[i] -= 2 * abs(C - x[n - i]);

		suff[i] = std::max(suff[i], suff[i - 1]);
		suff2[i] = std::max(suff2[i], suff2[i - 1]);
	}

	int64 answ = -INF64;

	DBG(pref);

	for(int l = 0; l <= n; ++l) {
		int64 opt1 = pref2[l] + suff[n - l];
		int64 opt2 = pref[l]  + suff2[n - l]; 

		answ = std::max({answ, opt1, opt2});
	}

	cout << answ << '\n';
}

