int n;
pair<ll, int> tree[2][N<<2];
ll C, x[2][N], v[N], cum[2][N], arr[2][N];
void build(int id, int node, int l, int r) {
  if (l == r) { 
    if (id == 0) tree[0][node] = {cum[0][l] - x[0][l], l}; 
    else tree[1][node] = {cum[0][l] - 2LL*x[0][l], l};
    return;
  } 
  int mid = (l + r) >> 1;
  build(id, node << 1, l, mid);
  build(id, node << 1|1, mid + 1, r);
  if (tree[id][node << 1].first >= tree[id][node << 1|1].first) {
    tree[id][node] = tree[id][node << 1];
  } else tree[id][node] = tree[id][node << 1|1];
}
pair<ll, int> query(int id, int node, int l, int r, int i, int j) {
  if (r < i || l > j) return {-INF, -INF};
  if (i <= l && r <= j) {
    return tree[id][node]; 
  } int mid = (l + r) >> 1;
  auto lft = query(id, node << 1, l, mid, i, j);
  auto rgt = query(id, node << 1|1, mid+1, r, i, j);
  if (lft.first >= rgt.first) return lft;
  return rgt;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> C;
  for (int i = 1; i <= n; ++i) cin >> x[0][i] >> v[i];
  for (int i = 1; i <= n; ++i) x[1][n - i + 1] = C - x[0][i];
  for (int i = 1; i <= n; ++i) {
    cum[0][i] = cum[0][i - 1] + v[i];
    cum[1][i] = cum[1][i - 1] + v[n - i + 1];
  }
  build(0, 1, 1, n);
  build(1, 1, 1, n);
  ll ans = 0;
  for (int lft = 0; lft <= n; lft++) {
    pair<ll, int> val = query(0, 1, 1, n, 1, n-lft);
    if (val.first < 0) val = {0, 0};
    ll lval = cum[1][lft] - x[1][lft];
    ans = max(ans, lval);
    // debug(cum[1][lft] - x[1][lft]);
    ans = max(ans, val.first);
    // debug(ans);
    ans = max(ans, lval + val.first - x[1][lft]);
    val = query(1, 1, 1, n, 1, n-lft);
    if (val.first < 0) val = {0, 0};
    ans = max(ans, lval + val.first);
  }
  cout << ans << '\n';
}

