template <class T, class U> void amax(T& x, U y) {if (x < y) x = y;}

int main() {
    int N;
    ll C;
    cin >> N >> C;
    ll *x = new ll[N + 2] + 1;
    vector<ll> v(N);
    x[-1] = 0;
    x[N] = C;
    REP(i, N) cin >> x[i] >> v[i];

    vector<ll> accl_v(N + 1), accr_v(N + 1), accl_max_cal(N + 1), accr_max_cal(N + 1);
    accl_v[0] = accr_v[0] = accl_max_cal[0] = accr_max_cal[0] = 0;
    REP(i, N) {
        accl_v[i + 1] = accl_v[i] + v[i];
        accr_v[i + 1] = accr_v[i] + v[N - 1 - i];
        accl_max_cal[i + 1] = max(accl_max_cal[i], accl_v[i + 1] - x[i]);
        accr_max_cal[i + 1] = max(accr_max_cal[i], accr_v[i + 1] - (C - x[N - 1 - i]));
    }

    ll cal_max = 0;
    REP(l, N + 1) {
        ll cal = accl_v[l] - 2 * x[l - 1] + accr_max_cal[N - l];
        amax(cal_max, cal);
    }
    REP(r, N + 1) {
        ll cal = accr_v[r] - 2 * (C - x[N - r]) + accl_max_cal[N - r];
        amax(cal_max, cal);
    }
    cout << cal_max << endl;

    --x;
    delete [] x;
    return 0;
}

