using namespace std;


class D {
	ll n, c;
	vector<ll> pos;
	vector<ll> val;
public:
	D()
	{
		cin >> n >> c;
		pos.resize(n);
		val.resize(n);

		REP(i, n)
		{
			cin >> pos[i] >> val[i];
		}

	}

	void debug()
	{
		cout << n << " " << c << endl;
		REP(i, n)
			cout << pos[i] << " " << val[i] << endl;
	}

	void solve()
	{
		ll ans{ 0 };
		ll tmpval, tmpmax, now;

		// clockwise
		tmpval = tmpmax = 0;
		now = 0;
		REP(i, n)
		{
			tmpval += (val[i] - (pos[i] - now));

			if (chmax(tmpmax, tmpval))
			{
				// go counterclockwise and return to the start point
				ll tmpopp{ 0 };
				ll oppmax{ 0 };
				ll nowopp{ c };
				for (int j{ n - 1 }; j > i; j--)
				{
					tmpopp += (val[j] - 2 * (nowopp - pos[j]));
					chmax(oppmax, tmpopp);
					nowopp = pos[j];
				}

				chmax(ans, tmpmax + oppmax);
			}

			now = pos[i];
		}

		// counterclockwise
		tmpval = tmpmax = 0;
		now = c;
		RREP(i, n)
		{
			tmpval += (val[i] - (now - pos[i]));

			//cout << "counterclock tmpval = " << tmpval << endl;

			if (chmax(tmpmax, tmpval))
			{
				// go clockwise and return to the start point
				ll tmpopp{ 0 };
				ll oppmax{ 0 };
				ll nowopp{ 0 };
				for (int j{ 0 }; j < i; j++)
				{
					tmpopp += (val[j] - 2 * (pos[j] - nowopp));
					chmax(oppmax, tmpopp);
					nowopp = pos[j];
				}

				chmax(ans, tmpmax + oppmax);
			}
			now = pos[i];
		}


		cout << ans << endl;
	}
};


int main()
{
	D solution;
	solution.solve();

	return 0;
}

