  for(i=0;i<n;i++){
    walk_r[i+1]=x[i];
    walk_l[i+1]=c-x[n-1-i];
  }
  for(i=0;i<n;i++){//右回りと左回りのカロリーの和
    cal_r[i+1]=cal_r[i]+v[i];
    cal_l[i+1]=cal_l[i]+v[n-1-i];
  }
  for(i=0;i<n;i++){
