    best_l[i+1]=max(best_l[i],cal_l[i+1]-(c-x[n-1-i]));
  }
  for(i=0;i<=n;i++){
    long long left,right;
    right=cal_r[i]-2*walk_r[i]+best_l[n-i];
    left=cal_l[i]-2*walk_l[i]+best_r[n-i];
    ans=max({ans,right,left});
  }
  cout << ans << endl;
  return 0;
}

