struct BIT{
    vector<ll> li;
    int size;
    BIT (int n){
        li=vector<ll>(n+1,LLONG_MIN);
        size=n;
    }
    ll maxim (int i){
        if(i==0){
            return -1000000000000000;
        }
        ll s=0;
        while(i>0){
            s = max(s,li[i]);
            i-=i & -i;
        }
        return s;
    }
    void add(int i, ll x){
        if(i==0){
            return;
        }
        while(i<=size){
            li[i] = max(li[i],x);
            i+=i & -i;
        }
    }
};

