vector<ll> MAXCAL(vector<ll> x, vector<ll> v){
    vector<ll> S(N),cal(N),maxcal(N);
    ll M = 0;
    for ( int i = 0; i < N; ++i){
        if ( i == 0 ) S[i] = v[i];
        else S[i] = S[i-1] + v[i];
        cal[i] = S[i] - 2 * x[i];
        if ( cal[i] > M ) M = cal[i];
        maxcal[i] = M;
    }
    return maxcal;
}


