using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
const int MAXN = 100010;

ll n, c;
ll x[MAXN], v[MAXN];

P calc(int end, bool rev) {
  ll sum = 0;
  ll tmp = 0;
  ll dist = 0;
  if (rev) {
    for (int i=n-1;i>=end;i--) {
      tmp += v[i];
      if (sum < tmp - (c - x[i])) {
        sum = tmp - (c - x[i]);
        dist = (c - x[i]);
      }
    }
  } else {
    for (int i=0;i<end;i++) {
      tmp += v[i];
      if (sum < tmp - x[i]) {
        sum = tmp - x[i];
        dist = x[i];
      }
    }
  }
  return P(sum, dist);
}

void solve() {
  int midPos = lower_bound(x, x+n, c / 2) - x;

  P clockWise = calc(n, false);
  P reverseClockWise = calc(0, true);
  P combineClockWise = calc(midPos, false);
  P combineReverseClockWise = calc(midPos, true);

  cout << max(clockWise.first - clockWise.second,
          max(reverseClockWise.first - reverseClockWise.second,
          combineClockWise.first + combineReverseClockWise.first - min(combineClockWise.second, combineReverseClockWise.second))) << endl;
}

int main() {
  cin >> n >> c;
  for (int i=0;i<n;i++) {
    cin >> x[i] >> v[i];
  }
  solve();
}

