template< typename T>
struct SparseTable{
    vector<vector<T> > st;
    vector<int> lookup;
    T op(T a,T b){
        //max , min or etc...
        return max(a,b);
    }

    SparseTable(const vector<T> &v){
        int b=0;
        while((1<<b)<=v.size()) b++;
        //resize  st[k][i]:iの2^k先までの範囲の
        st.assign(b,vector<T>(1<<b));
        for(int i=0;i<v.size();i++) st[0][i]=v[i];
        for(int i=1;i<b;i++){
            for(int j=0;j+(1<<i)<=(1<<b);j++){
                st[i][j]=op(st[i-1][j],st[i-1][j+(1<<(i-1))]);
            }
        }
        lookup.resize(v.size()+1);
        for(int i=2;i<lookup.size();i++){
            lookup[i]=lookup[i>>1]+1;
        }
    }
    //[)
    T f(int l,int r){
        assert(l<=r);
        //a[l~l+2^k],a[r-2^k~r]が区間を覆うように
        int b=lookup[r-l];
        return op(st[b][l],st[b][r-(1<<b)]);
    }
};
