    clockw2[i] = max(clockw1[i], clockw2[i - 1]);
  }

  ll ans = max(0LL, *max_element(clockw1.begin(), clockw1.end()));

  aclockw1[N - 1] = aclockw2[N - 1] = V[N - 1] - (C - X[N - 1]);
