int main()
{
    long long N, C;
    cin >> N >> C;

    long long ans = 0;
    long long positive[N + 1][2] = {};
    long long positive_max[N + 1] = {};
    for (int i = 1; i <= N; i++)
    {
        long long x, v;
        cin >> x >> v;

        positive[i][0] = x;
        positive[i][1] = positive[i - 1][1] + v;

        positive_max[i] = max(positive_max[i - 1], positive[i][1] - positive[i][0]);
        ans = max(ans, positive_max[i]);
    }

    long long negative[N + 1][2] = {};
    long long negative_max[N + 1] = {};
    for (int i = 1; i <= N; i++)
    {
        negative[i][0] = C - positive[N - i + 1][0];
        negative[i][1] = positive[N][1] - positive[N - i][1];

        negative_max[i] = max(negative_max[i - 1], negative[i][1] - negative[i][0]);
        ans = max(ans, negative_max[i]);
    }

    for (int i = 1; i < N; i++)
    {
        long long value = positive[i][1] - 2 * positive[i][0];
        value += negative_max[N - i];
        ans = max(ans, value);
    }

    for (int i = 1; i < N; i++)
    {
        long long value = negative[i][1] - 2 * negative[i][0];
        value += positive_max[N - i];
        ans = max(ans, value);
    }

    cout << ans << endl;
}

