		cin >> x[i] >> v[i];
	}

	long long c = 0;
	for(int a = 0; a <= N - 1; a++) {
		long long tc = 0;
		for(int i = 0; i <= a; i++) {
			tc += v[i];
		}

		for(int b = a + 1; b <= N; b++) {
			long long ttc = 0;
			for(int i = b; i <= N; i++) {
