	int N;
	lint C;
	cin >> N >> C;

	vector<lint> x(N), v(N);
	for (int i = 0; i < N; i++) cin >> x[i] >> v[i];

	vector<lint> rcw(N), ccw(N), Midx(N);
	lint sum = 0;
	for (int i = 0; i < N; i++) {
		sum += v[i];
		rcw[i] = sum - x[i];
	}
	for (int i = 1; i < N; i++) {
		if (rcw[i] <= rcw[i - 1]) {
			rcw[i] = rcw[i - 1];
			Midx[i] = Midx[i - 1];
		}
		else {
			Midx[i] = i;
		}
	}

	sum = 0;
	for (int i = N - 1; i >= 0; i--) {
		sum += v[i];
		ccw[i] = sum - (C - x[i]);
	}

	lint ans = 0;
	for (int i = 0; i < N; i++) {
		ans = max(ans, (i > 0 ? rcw[i - 1] : 0) + max(ccw[i] - min((i > 0 ? x[Midx[i - 1]] : 0), (C - x[i])), 0LL));
	}

	cout << ans << "\n";

	return 0;
}

