	    }

	    sort(l.begin(), l.end());
	    sort(r.begin(), r.end());

	    vector<ll> lc(n+1), rc(n+1);
	    lc[0] = rc[0] = 0;
	    for(int i=0; i<n; i++){
            lc[i+1] = lc[i] + (l[i].second - l[i].first);
            rc[i+1] = rc[i] + (r[i].second - r[i].first);
            if(i-1 >= 0){
                lc[i+1] += l[i-1].first;
                rc[i+1] += r[i-1].first;
            }
	    }

	    ll res = -inf;
	    for(int i=0; i<n; i++){
            chmax(res, max(lc[i], rc[i]));
	    }

        ll posr = 0, posl = 0;
        ll mx = -inf;
        ll cost = 0;
	    while(posl + posr < n) {
            if(lc[posl+1] - lc[posl] - l[posl].first + (posl>0 ? l[posl-1].first : 0) > rc[posr+1] - rc[posr]){
                cost += lc[posl+1] - lc[posl] - l[posl].first;
                if(posl > 0) cost += l[posl-1].first;
                posl++;
            }else{
                cost += rc[posr+1] - rc[posr];
                posr++;
            }
            chmax(mx, cost);
	    }

	    chmax(res, mx);

        posr = 0, posl = 0;
        mx = -inf;
        cost = 0;
        while(posl + posr < n) {
            if(rc[posr+1] - rc[posr] - r[posr].first + (posr>0 ? r[posr-1].first : 0) > lc[posl+1] - lc[posl]){
                cost += rc[posr+1] - rc[posr] - r[posr].first;
