vector<ll> calcRui(const vector<ll>& z) {
  ll n = SZ(z);
  vector<ll> l(n + 1, 0);
  REP(i, n) { l[i + 1] = l[i] + v[i]; }
  REP(i, n) { l[i + 1] -= z[i]; }
  return l;
}
vector<ll> calcMax(const vector<ll>& a) {
  ll n = SZ(a);
  vector<ll> l(n, 0);
  l[0] = a[0];
  FOR(i, 1, n) { l[i] = max(l[i - 1], a[i]); }
  return l;
}

