ll g[MAX_N + 2];

void init()
{
  f[0] = 0;
  ll vsum = 0;
  for (int i = 0; i < N; i++) {
    vsum += v[i];
    f[i + 1] = vsum - x[i];
  }
  for (int i = 0; i < N; i++) {
    g[i + 1] = max(f[i + 1], g[i]);
  }
}

int main(void)
{
