  init();

  ll ans = 0;
  ll vsum = 0;

  // REP(i, N + 1) cout << f[i] << SLN(i, N + 1);
  // REP(i, N + 1) cout << i << ":" << g[i] << SLN(i, N + 1);

  // return 0;
  x[N] = C, v[N] = 0;
  for (int i = N; i >= 0; i--) {
    vsum += v[i];
    ll xb = vsum - (C - x[i]);
    ll ga = g[i];
    // N のとき (A だけでいったとき) と
    // 0 のとき (B だけでいったとき) は
    // 被りがないのでマイナスする必要がない
    if (i != N && i != 0) {
      // どっち周りの方が安くつくかを判定してマイナス
      int idx = lower_bound(g, g + N + 1, ga) - g - 1;
