      // cout << g[i] << " : "
      //      << "idx: " << idx << ": " << x[idx] << ":" << (C - x[i]) << endl;
      // -1 の場合 A の方に取りに行かないのが正解
      if (idx != -1) {
        xb -= min(x[idx], (C - x[i]));
      }
    }
    ans = max(ans, xb + ga);
  }
  cout << ans << endl;

