int main(){
	long N;
	long long C;
	cin >> N >> C;

	long long x0 = 0;
	long long x[N+2];
	long long upcum[N+2];
	long long dncum[N+2];
	long long upx[N+2];
	long long dnx[N+2];
	long v[N+2];

	for(int i=1; i<=N; ++i){
		cin >> x[i] >> v[i];
	}

	x[0] = 0;
	x[N+1] = C;
	v[0] = 0;
	v[N+1] = 0;
	upcum[0] = 0;
	dncum[N+1] = 0;
	upx[0] = 0;
	dnx[N+1] = 0;

	long long vi = 0;
	for(long i=1;i<=N;++i){
		vi += v[i];
		long cum = vi-x[i];
		if(cum>upcum[i-1]){
			upcum[i] = cum;
			upx[i] = x[i];
		}else{
			upcum[i] = upcum[i-1];
			upx[i] = x[i-1];
		}
	}
	vi = 0;
	for(long i=N;i>=1;--i){
		vi += v[i];
		long cum = vi-C+x[i];
		if(cum>dncum[i+1]){
			dncum[i] = cum;
			dnx[i] = C-x[i];
		}else{
			dncum[i] = dncum[i+1];
			dnx[i] = C-x[i+1];
		}
	}

	long long result = 0;
	for(long i=0;i<=N;++i){
		result = max(upcum[i]+dncum[i+1]-min(upx[i],dnx[i+1]),result);
	}

	cout << result << endl;
	return 0;
}

