            now_ow += V[i] - (X[i + 1] - X[i]);
            now_tw += V[i] - (X[i + 1] - X[i]) * 2;
            countercw_oneway[i] = max(countercw_oneway[i + 1], now_ow);
            countercw_twoway[i] = max(countercw_twoway[i + 1], now_tw);
        }
