		num2 = first_sushi_num;
	}
	for (int i = 1; i <= num1; ++i) {
		sum_cal += v[i];
	}
	for (int i = n; i >= num2; --i) {
		sum_cal += v[i];
	}
	sum_cal -= x[num1];
	sum_cal -= (c - x[num2]);
	if (x[num1] < c - x[num2]) {
		sum_cal -= x[num1];
	}
	else if (x[num1] >= c - x[num2]) {
		sum_cal -= (c - x[num2]);
	}
	return sum_cal;
}

