pl func(ll l, ll r){
    /*
    svl[l] + svr[r] - (xls[l] * 2 + xrs[r]) (l + r <= n)
    svl[l] + svr[r] - (xls[l] + xrs[r] * 2) (l + r <= n)
    */
    ll v = svl[l] + svr[r];
    ll x1 = xls[l] * 2 + xrs[r];
    ll x2 = xls[l] + xrs[r] * 2;
    return mp(v - x1, v - x2);
}

