struct eat
{
	long long l;
	long long e;
	long long h;
	long long f;
}p[100010];
int cam(eat x,eat y)
{
	return x.h>y.h;
 } 
int cam2(eat x,eat y)
{
	return x.h<y.h;
}
int cam3(eat x,eat y)
{
	return x.f<y.f;
}
long long b[100010];
int main()
{
	int n;
	long long r;
	cin>>n>>r;
	for(int i=0;i<n;i++)cin>>p[i].l>>p[i].e;
	int s=n;
    long long tem=0;
	long long ans=0;
	int y=0;
	while(s--)
	{
		for(int i=0;i<=s;i++)
		{
			if(abs(p[i].l-tem)*2>r)
			{
				if(tem<p[i].l)p[i].h=p[i].e-abs(r-(p[i].l-tem));
				else p[i].h=p[i].e-abs(r-(tem-p[i].l));
				p[i].f=abs(r-abs(p[i].l-tem));
			}
			else 
			{
				p[i].h=p[i].e-abs(p[i].l-tem);
				p[i].f=abs(p[i].l-tem);
			}
		}
		sort(p,p+s+1,cam3);
		int k=0;
		for(int i=0;i<=s;i++)
		{
			if(p[i].h>0)
			{
				ans+=p[i].h;
				tem=p[i].l;
				p[i].h=100000000000001;
				sort(p,p+s+1,cam2);
				k=1;
				break;
			}
		}
		if(k==0)
		{
			b[y]=ans;
			ans+=p[0].h;
			tem=p[0].l;
			p[0].h=100000000000001;
			sort(p,p+s+1,cam2);
		}
		y++;
		//cout<<s<<" "<<ans<<endl;
	}
	sort(b,b+y);
	cout<<b[y-1]<<endl;
	return 0;
 }

