ll N, C;
vector<PL> sushi;
VL sum, rsum;
VL opt, ropt;

signed main() {
    cin >> N >> C;
    REP(i, N) {
        LCIN(x, v);
        sushi.emplace_back(x, v);
    }
    sum.resize(N + 2);
    rsum.resize(N + 2);
    opt.resize(N + 2);
    ropt.resize(N + 2);
    REP(i, N) {
        sum[i + 1] = sum[i] + (sushi[i].se - sushi[i].fi);
        rsum[N - i] =
            rsum[N + 1 - i] + sushi[N - 1 - i].se - (C - sushi[N - 1 - i].fi);
        if(i > 0) {
            sum[i + 1] += sushi[i - 1].fi;
            rsum[N - i] += C - sushi[N - i].fi;
        }
    }
    REP(i, N + 1) {
        opt[i + 1] = max(opt[i], sum[i + 1]);
        ropt[N - i] = max(ropt[N + 1 - i], rsum[N - i]);
    }

    ll ans = 0;
    // clock-counterclock
    REP(i, N + 1) {
        if(i == 0)
            ans = max(ans, ropt[0]);
        else
            ans = max({ans, sum[i] - sushi[i - 1].fi + ropt[i + 1], sum[i]});
    }

    // counterclock-clock
    REP(i, N + 1) {
        if(i == 0)
            ans = max(ans, opt[N + 1]);
        else
            ans = max({ans, rsum[N + 1 - i] - (C - sushi[N - i].fi) + opt[N - i], rsum[N + 1 - i]});
    }
    cout << ans << "\n";
}

