int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll N, C;
	cin >> N >> C;
	vector<P> VP(N);
	vll V(N);
	ll sum = 0;
	REP(i, N) {
		ll x;
		cin >> x >> V[i];
		sum += V[i];
		VP[i] = P(x, sum);
	}
	vector<P> VPR = VP;
	rev(VPR); rev(V);
	sum = 0;
	REP(i, N) {
		sum += V[i];
		VPR[i].first = C - VPR[i].first;
		VPR[i].second = sum;
	}
	ll ans = 0;

	vll VA(N);//時計回りにi+1個以下食べた時の栄養価のMAX

	//時計回りにi+1個食べる
	REP(i, N) {
		ans = max(ans,VP[i].second - VP[i].first);
		VA[i] = ans;
	}

	vll VB(N);
	ll ansb = 0;
	//反時計回りにi+1個食べる
	REP(i, N) {
		ansb = max(ansb, VPR[i].second - VPR[i].first);
		VB[i] = ansb;
	}
	ans = max(ans,ansb);
	//反時計回りにi+1個食べる
	REP(i, N - 1) {
		ll now = VPR[i].second - VPR[i].first * 2;
		//そのあと時計回りに最適な個数分食べる。
		now += VA[N - i - 2];
		ans = max(ans, now);
	}
	//時計回りにi+1個食べる
	REP(i, N - 1) {
		ll now = VP[i].second - VP[i].first * 2;
		//そのあと反時計回りに最適な個数分食べる。
		now += VB[N - i - 2];
		ans = max(ans, now);
	}

	cout << ans << endl;
	PAU;
	return 0;
}

