	vector<long long int> vq(n, 0);
	vector<long long int> vp2(n, 0);
	vector<long long int> vq2(n, 0);

	for (long long int i = 0; i < n; i++) {
		cin >> x[i] >> v[i];
		x2[i] = c - x[i];
	}

	long long int ans = 0;

	vp[0] = v[0];
	for (long long int i = 1; i < n; i++) {
		vp[i] = vp[i - 1] + v[i];
	}
	for (long long int i = 0; i < n; i++) {
		vp[i] -= x[i];
	}

	vq[n - 1] = v[n - 1];
	for (long long int i = n - 2; i >= 0; i--) {
		vq[i] = vq[i + 1] + v[i];
	}

	for (long long int i = 0; i < n; i++) {
		vq[i] -= x2[i];
	}

	vp2 = vp;
	vq2 = vq;

	vp2[0] = max(vp2[0], 0LL);
	for (long long int i = 1; i < n; i++) {
		vp2[i] = max(vp2[i - 1], vp2[i]);
	}

	vq2[n - 1] = max(vq2[n - 1], 0LL);
	for (long long int i = n - 2; i >= 0; i--) {
		vq2[i] = max(vq2[i + 1], vq2[i]);
	}
	/*
	for (long long int i = 0; i < n; i++) {
		cout << vp[i] << ' ';
