	}
	cout << endl;

	for (long long int i = 0; i < n; i++) {
		cout << vq2[i] << ' ';
	}
	cout << endl;
	*/

	ans = max(ans, vq2[0]);
	for (long long int i = 0; i < n; i++) {
		long long int ans2 = vp[i] - x[i];
		if (i + 1 < n) {
			ans2 += vq2[i + 1];
		}
		ans = max(ans, ans2);
	}

	ans = max(ans, vp2[n - 1]);
	for (long long int i = n - 1; i >= 0; i--) {
		long long int ans2 = vq[i] - x2[i];
		if (i - 1 >= 0) {
			ans2 += vp2[i - 1];
		}
		ans = max(ans, ans2);
	}

	cout << ans << endl;

