constexpr int MAX = 100010;

ll n, c, x[MAX], v[MAX], a[MAX], y[MAX], b[MAX], d[MAX];

ll solve() {
	a[0] = v[0];
	Rep(i, n) a[i] = a[i - 1] + v[i];

	rep(i, n) y[i] = c - x[i];
	b[n - 1] = v[n - 1];
	for (int i = n - 2; i >= 0; i--) b[i] = b[i + 1] + v[i];

	d[n - 1] = b[n - 1] - y[n - 1];
	for (int i = n - 2; i >= 0; i--) {
		d[i] = b[i] - y[i];
		chmax(d[i], d[i + 1]);
	}

	ll ans = 0;
	rep(i, n) {
		ll sm = 0;

		sm -= x[i];
		sm += a[i];
		chmax(ans, sm);

		sm -= x[i];
		if (i < n - 1) sm += d[i + 1];
		chmax(ans, sm);
	}
	return ans;
}

