  for(int i = 0; i < N; i++){
    if(posrco[i]<0) continue;
    for(int j = 0; j < N-1-i; j++){
      if(negrco[j]<0) continue;
      int bufsum=posco[i]+negco[j];
      int bufmax=bufsum-std::min(posx[i],negx[j]);
      maxvec[2]=std::max(maxvec[2], bufmax);
    }
  }

  int maxcal=*std::max_element(maxvec.begin(), maxvec.end());
