const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, c;
ll x[MAX_N], vs[MAX_N], v;
ll memo[2][MAX_N];

void solve(ll n, ll c){
    vs[0] = 0;
    rep(i, n) {in2(x[i], v); vs[i + 1] = vs[i] + v;}
    memo[0][0] = 0; memo[1][0] = 0;
    rep(i, n){
        memo[0][i + 1] = max(memo[0][i], vs[n] - vs[n - 1 - i] - 2 * (c - x[n - 1 - i]));
        memo[1][i + 1] = max(memo[1][i], vs[n] - vs[n - 1 - i] - c + x[n - 1 - i]);
    }

    answer = max(0LL, vs[n] - min(c - x[0], x[n - 1]));
    For(l, -1, n){
        ll idx = n - l - 1;
        if (l == -1) answer = max(answer, memo[1][n]);
        else answer = max(answer, max(vs[l + 1] - x[l] + memo[0][idx], vs[l + 1] - 2 * x[l] + memo[1][idx]));
    }

    prl(answer);
}

int main(void){
    in2(n, c);
    solve(n, c);

    return 0;
}

