template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }
template<class T> std::ostream& operator<< (std::ostream& os, const std::vector<T>& vc) { for(auto it = vc.begin(); it != vc.end(); ++it) { if (std::next(it) == vc.end()) os << *it; else os << *it << VECTOR_COUT_SEPARATOR; } return os; }
template<class T1, class T2> inline std::ostream & operator<< (std::ostream & os, const std::pair<T1, T2> & p) { return os << p.first << ' ' << p.second; }

void solve(void)
{
  ll N, C; cin >> N >> C;
  using Pair = pair<ll, ll>;
  vector<Pair> X(N);
  for(auto& x : X) cin >> x.first >> x.second;

  vector<ll> v_sumr(N);
  for(size_t i = 0; i < v_sumr.size(); ++i){
    v_sumr[i] = X[i].second;
    if(i){
      v_sumr[i] += v_sumr[i - 1];
    }
  }
  vector<Pair> r_max(N);
  for(size_t i = 0; i < r_max.size(); ++i){
    r_max[i].second = v_sumr[i] - X[i].first;
    r_max[i].first = X[i].first;
    if(i){
      if(r_max[i].second < r_max[i - 1].second){
        r_max[i] = r_max[i - 1];
      }
    }else{
      // Do Nothing?
    }
  }
  vector<ll> v_suml(N);
  for(auto l_it = v_suml.rbegin(); l_it != v_suml.rend(); ++l_it){
    auto r_index = (N - 1) - std::distance(v_suml.rbegin(), l_it);
    *l_it = X[r_index].second;
    if(l_it != v_suml.rbegin()){
      *l_it += *std::prev(l_it);
    }
  }

//  cout << "X :" << X << CRLF;
//  cout << "v_sumr :" << v_sumr << CRLF;
//  cout << "r_max :" << r_max << CRLF;
//  cout << "v_suml :" << v_suml << CRLF;
  ll ans{};
  for(size_t i = 0; i < N; ++i){
    auto l_dis = C - X[i].first;
    auto l_val = v_suml[i];
    auto r_dis = i ? r_max[i - 1].first : 0;
    auto r_sum = i ? r_max[i - 1].second : 0;
    if(r_sum < 0){
      r_sum = 0;
      r_dis = 0;
    }

    auto res0 = l_val - l_dis - r_dis + r_sum;
    auto res1 = l_val - l_dis - l_dis + r_sum;
    auto res = std::max(res0, res1);
    chmax(ans, res);
  }
  chmax(ans, r_max.back().second);

  cout << ans << CRLF;

  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

