struct Sushi
{
	int64_t x;
	int64_t v;
};

int main() {
	int n;
	int64_t c;
	cin >> n >> c;
	auto sushi = new Sushi[n];
	for (int i = 0; i < n; i++) {
		cin >> sushi[i].x >> sushi[i].v;
	}
	int64_t maxCal = 0;

	// 時計回り、方向転換なし。
	auto clockWiseVSum = new int64_t[n];
	clockWiseVSum[0] = sushi[0].v;
	maxCal = max(static_cast<int64_t>(0), sushi[0].v - sushi[0].x);
	for (int i = 1; i < n; i++) {
		clockWiseVSum[i] = (sushi[i].v + clockWiseVSum[i - 1]);
		if (clockWiseVSum[i] - sushi[i].x > maxCal) {
			maxCal = clockWiseVSum[i] - sushi[i].x;
		}
	}

	// 反時計回り、方向転換なし。
	auto counterClockWiseVSum = new int64_t[n];
	counterClockWiseVSum[0] = sushi[n - 1].v;
	maxCal = max(static_cast<int64_t>(0), sushi[n - 1].v - (c - sushi[n - 1].x));
	for (int i = 1; i < n; i++) {
		counterClockWiseVSum[i] = (sushi[n - i - 1].v + counterClockWiseVSum[i - 1]);
		if (counterClockWiseVSum[i] - (c - sushi[n - i - 1].x) > maxCal) {
			maxCal = counterClockWiseVSum[i] - (c - sushi[n - i - 1].x);
		}
	}

	// 時計回り、方向転換あり。
	// スタート地点に戻った時のカロリー値が最も大きい点から戻る。
	// ただし既に半分以上進んでいたら、そのまま進んだほうが良いので方向転換しない。
	auto returnPoint = 0;
	int64_t returnVMax = 0;
	for (int i = 0; i < n; i++) {
		if (sushi[i].x >= c / 2) {
			break;
		}
		int64_t returnV = clockWiseVSum[i] - sushi[i].x * 2;
		if (returnV > returnVMax) {
			returnVMax = returnV;
			returnPoint = i;
		}
	}
	if (returnVMax > 0) {
		for (int i = 0; i < n - returnPoint - 1; i++) {
			if (returnVMax + counterClockWiseVSum[i] - (c - sushi[n - i - 1].x) > maxCal) {
				maxCal = returnVMax + counterClockWiseVSum[i] - (c - sushi[n - i - 1].x);
			}
		}
	}

	// 反時計回り、方向転換あり。
	returnPoint = 0;
	returnVMax = 0;
	for (int i = 0; i < n; i++) {
		if (sushi[n - 1 - i].x <= c / 2) {
			break;
		}
		int64_t returnV = counterClockWiseVSum[i] - (c - sushi[n - 1 - i].x) * 2;
		if (returnV > returnVMax)
		{
			returnVMax = returnV;
			returnPoint = n - 1 - i;
		}
	}
	if (returnVMax > 0)
	{
		for (int i = 0; i < returnPoint; i++) {
			if (returnVMax + clockWiseVSum[i] - sushi[i].x > maxCal) {
				maxCal = returnVMax + clockWiseVSum[i] - sushi[i].x;
			}
		}
	}
	// 結果
	cout << maxCal;
	return 0;
}

