		for (int j = i + 1; j < N; j++) {
			ans[i] = max(ans[i], cw[i] + ccw[j] - min(x[i], (C - x[j])));
		}
	}
	cout << *max_element(ans.begin(), ans.end()) << "\n";

	return 0;
}

