// セグ木
template<typename T,typename F>
struct ST{

  int size;
  vector<T> seg;
  const F func;
  const T UNIT;

  ST(int N,F func , T UNIT): func(func) , UNIT(UNIT) {
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
  }

  ST(const vector<T> &v,F func , T UNIT) : func(func) , UNIT(UNIT){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size , UNIT);
    // set
    for(int i = 0; i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k, T x){
    seg[k + size] = x;
  }

  void build(){
    for(int k = size-1; k > 0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func( seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void add(int k , T x){
    k += size; seg[k] += x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  // 半開区間[a,b)へのクエリ
  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

void solve(){
  ini(N); inl(C);
  vp v(N); in(v);

  auto f=[](ll a,ll b){return max(a , b);};

  vl clockdat(N) , countdat(N);
  // 時計回り
 for(ll i = 0 , cur = 0 ; i < N ; i++){
   cur += v[i].se;
   // 
   clockdat[i] = cur - v[i].fi;
 }

 for(ll i = N - 1 , cur = 0 ; i >= 0 ; i--){
   cur += v[i].se;
   countdat[i] = cur - (C - v[i].fi);
 }

  ST<ll,decltype(f)> cl(clockdat,f,-infLL) , co(countdat,f,-infLL);

  ll ans = 0;
  // 初手時計回りにiまで食べる
  rep(i , N){
    // 食べる
    ll cur = cl[i];
    // 原点に戻って逆回りをする
    ll nya = max(0LL , -v[i].fi + co.query(i + 1 , N));
    amax(ans , cur + nya);
  }

  // 初手反時計
  rep(i , N){
    // i ~ N + 1を食べる
    ll cur = co[i];
    // 原点に戻り逆回り
    ll nya = max(0LL , -(C - v[i].fi) + cl.query(0 , i));
    amax(ans , cur + nya);
  }

  out(ans);

}

