typedef long long ll;
ll rsum[100005];        // (0...i)の時計回りの摂取カロリーのみの累積和
ll lsum[100005];        // (i...(n+1)(=0))の反時計回りの摂取カロリーのみの累積和
// 上記のものに消費カロリーも考慮したものの最大値を保存
ll max_rsum[100005];
ll max_lsum[100005];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll c;
    cin >> n >> c;
    vector<ll> x(n);
    vector<int> v(n);
    ll tmp = 0;
    for(int i = 0; i < n; ++i){
        cin >> x[i] >> v[i];
        rsum[i+1] = rsum[i] + v[i];
        tmp = max(tmp, rsum[i+1] - x[i]);
        max_rsum[i+1] = tmp;
    }
    tmp = 0;
    // rsumとindexを揃える
    for(int i = n; i > 0; --i){
        lsum[i] = lsum[i+1] + v[i-1];
        tmp = max(tmp, lsum[i] - (c - x[i-1]));
        max_lsum[i] = tmp;
    }

    ll res = 0;
    res = max(res, *max_element(max_rsum, max_rsum + n + 1));
    res = max(res, *max_element(max_lsum, max_lsum + n + 1));

    for(int i = 1; i <= n; ++i){
        ll temp = rsum[i] - 2 * x[i - 1] + max_lsum[i + 1];
        res = max(res, temp);

        temp = lsum[n + 1 - i] - 2 * (c - x[n - i]) + max_rsum[n - i];
        res = max(res, temp);
    }

    cout << res << endl;
}

