    v_sum_right[0] = v[0];
    for (i = 1; i < N; i++) {
        v_sum_right[i] = v_sum_right[i - 1] + v[i];
    }

    v_sum_left[N] = 0;
    for (i = N - 1; i >= 0; i--) {
        v_sum_left[i] = v_sum_left[i + 1] + v[i];
    }


    // g計算
    g[0] = 0;
    g2[0] = 0;
    for (i = 1; i <= N; i++) {
        g[i] = max(g[i - 1], v_sum_right[i - 1] - x[i - 1]);
        g2[i] = max(g2[i - 1], v_sum_right[i - 1] - 2 * x[i - 1]);
    }

    // 探査
    ans = v_sum_left[0] - C + x[0];
    for (i = 1; i < N; i++) {
        ans = max(ans, v_sum_left[i] + g[i] - 2 * (C - x[i]));
