		L += LValue[a].second;

		RX = RValue[a].first;
		LX = LValue[a].first;

		Ans = max(max(R - RX, L - LX), Ans);

	}

	HR = 0;
	HL = 0;

	R = 0;
	L = 0;

	for (ll a = 0; a < N; a++)
	{
		if (RValue[a].first > C / 2) break;

		R += RValue[a].second;

		HR = max(HR, R - RValue[a].first);

	}

	for (ll a = 0; a < N; a++)
	{
		if (LValue[a].first > C / 2) break;

		L += LValue[a].second;

		HL = max(HL, L - LValue[a].first);

	}


