	{
		if (LValue[a].first > C / 4) break;

		L += LValue[a].second;

		QL = max(QL, L - LValue[a].first * 2);

	}

	Ans = max(Ans, max(QR + HL, QL + HR));

	OUT << Ans << endl;

	return 0;
}

