	vector<ll> slv(n+1), srv(n+1);
	slv[0] = 0, srv[0] = 0;

	for (int i = 1; i <= n; i++){
		slv[i] = slv[i-1] + lv[i];
		srv[i] = srv[i-1] + rv[i];		
	}

	ll lmax = 0, rmax = 0, mmax = 0;
	for (int i = 1; i <= n; i++){
		lmax = llmax(lmax, slv[i] - lx[i]);
		rmax = llmax(rmax, srv[i] - rx[i]);
	}

	vector<ll> lrmax(n+1), rlmax(n+1);
	ll lrtmp = 0, rltmp = 0;
	for (int i = 1; i <= n; i++){
		if (lrtmp < slv[i] - 2*lx[i]){
			lrtmp = slv[i] - 2*lx[i];
		}
		lrmax[i] = lrtmp;
		if (rltmp < slv[i] - 2*rx[i]){
			rltmp = srv[i] - 2*rx[i];
		}
		rlmax[i] = rltmp;
	}

	for (int i = 1; i < n; i++){
		int j = n - i;
		mmax = llmax(mmax, slv[i] + rlmax[j] - lx[i]);
		mmax = llmax(mmax, srv[i] + lrmax[j] - rx[i]);
	}

	cout << llmax(lmax, llmax(rmax, mmax)) << endl;
	return 0;
}

