int main() {
    scanf("%lld%lld", &n, &C);
    // 1
    for (int i = 1; i <= n; i++) {
        scanf("%lld%lld", &x[i], &v[i]);
        pre[i] = pre[i - 1] + v[i];
    }
    for (int i = 1; i <= n; i++) {
        ll tmp = pre[i] - x[i];
        a[i] = tmp;
        ans1 = max(ans1, tmp);
    }

    // 2
    for (int i = 1; i <= n; i++) pre[i] = v[i];
    for (int i = n; i >= 1; i--) pre[i] += pre[i + 1];
    for (int i = n; i >= 1; i--) {
        ll tmp = pre[i] - (C - x[i]);
        b[i] = tmp;
        ans2 = max(ans2, tmp);
    }
    ans = max(ans1, ans2);

    // 3
    for (int i = 1; i <= n; i++) {
        if (ans3 < a[i] - x[i]) {
            ans3 = a[i] - x[i];
            p = i;
        }
    }
    for (int i = n; i > p; i--) {
        if (ans4 < b[i]) ans4 = b[i];
    }
    ans = max(ans, ans3 + ans4);

    // 4
    ans3 = ans4 = 0;
    for (int i = n; i >= 1; i--) {
        if (ans4 < b[i] - (C - x[i])) {
            ans4 = b[i] - (C - x[i]);
            p = i;
        }
    }
    for (int i = 1; i < p; i++) {
        if (ans3 < a[i]) ans3 = a[i];
    }
    ans = max(ans, ans3 + ans4);

    printf("%lld\n", ans);
    return 0;
}

