ll const C_MAX = 100000000000000;
int const N_MAX = 100000;

int N;
ll C;
vector<Pl> ct;

ll ls[N_MAX + 1];
ll rs[N_MAX + 1];

ll fs[N_MAX + 1];
Pl gs[N_MAX + 1];

int main() {
  scanf("%d %lld", &N, &C);
  ct.push_back(Pl(0, 0));
  rep(i, N) {
    ll x, v;
    scanf("%lld %lld", &x, &v);
    ct.push_back(Pl(x, v));
  }
  ct.push_back(Pl(0, 0));

  FOR(i, 1, N + 1) {
    ls[i] = ls[i - 1] + ct[i].second;
    rs[i] = rs[i - 1] + ct[N - i + 1].second;
  }

  FOR(i, 1, N + 1) {
    Pl g = gs[i - 1];
    ll cal = ls[i] - ct[i].first;
    if (g.second >= cal) {
      gs[i] = g;
    } else {
      gs[i] = Pl(ct[i].first, cal);
    }
  }

  ll max_cal = 0;
  rep(i, N + 1) {
    ll r = rs[i];
    ll r_dist = C - ct[N - i + 1].first;
    if (r_dist == C) r_dist = 0;
    ll r_cal = r - r_dist;

    int l_idx = N - i;
    Pl g = gs[l_idx];
    ll l_dist = g.first;
    ll l_cal = g.second;

    max_cal = max(max_cal, r_cal + l_cal - min(l_dist, r_dist));
  }
  printf("%lld\n", max_cal);
}

