const double PI = acos(-1);
const ll MOD = 1e9+7;

ll n, c;

int main() {
    cin >> n >> c;
    V<Pll> s(n+2);
    s[0] = {0, 0};
    s[n+1] = {c, 0};
    REP2(i, 1, n+1) {
        ll x, v; cin >> x >> v;
        s[i] = {x, v};
    }

    ll res = 0;

    V<Pll> left = {{-(n+1), 0}};
    ll maxi = 0, sum = 0;
    RREP(i, n, 1) {
        sum += s[i].second - (s[i+1].first - s[i].first);
        if (sum > maxi) {
            left.push_back({-i, sum});
            maxi = sum;
        }
    }

    sum = 0;
    REP2(i, 1, n+1) {
        sum += s[i].second - (s[i].first - s[i-1].first);
        auto iter = lower_bound(ALL(left), make_pair((ll)-i, 0LL));
        iter--;
        res = max({res, sum, sum - s[i].first + iter->second});
    }

    V<Pll> right = {{0, 0}};
    maxi = 0, sum = 0;
    REP2(i, 1, n+1) {
        sum += s[i].second - (s[i].first - s[i-1].first);
        if (sum > maxi) {
            right.push_back({i, sum});
            maxi = sum;
        }
    }

    sum = 0;
    RREP(i, n, 1) {
        sum += s[i].second - (s[i+1].first - s[i].first);
        auto iter = lower_bound(ALL(right), make_pair((ll)i, 0LL));
        iter--;
        res = max({res, sum, sum - (c - s[i].first) + iter->second});
    }

    cout << res << '\n';

    return 0;
}

