        res = max(res, l[i+1].second - l[i+1].first);
        fl[i+1] = max(fl[i], l[i+1].second - l[i+1].first);
    }
    l[N+1].first = C;
    l[N+1].second = sum;
    fl[N+1] = fl[N];

    //右から舐めたときの値をそれぞれとる(区間:i~N-1)の値
    vector <pair<ll, ll> > r(N+2);

    vector <ll> fr(N+2);

    fr[0] = 0;
    r[0].first = C;
