    {
        r[i+1].first = x[N-1-i];
        r[i+1].second = r[i].second + c[N-1-i];

        res = max(res, r[i+1].second - (C - r[i+1].first));
        fr[i+1] = max(fr[i], r[i+1].second - (C - r[i+1].first));
    }
    r[N+1].first = 0;
    r[N+1].second = sum;
    fr[N+1] = fr[N];

