    for(ll i = 0; i < N + 1; ++i)
    {
        ll tmp;
        tmp = l[i].second - 2 * l[i].first + fr[N - i];
        res = max(res, tmp);
    }
    //反時計回り
    for(ll i = 0; i < N + 1; ++i)
    {
        ll tmp;
        tmp = r[i].second - 2 * (C - r[i].first) + fl[N - i];
        res = max(res, tmp);
