int N;
LL C;
LL X[100001],V[100001],Q[100002];

const int MAX_N=1e6+1;
LL cum[MAX_N];
LL f() {
  REP(i,N+1) cum[i+1]=cum[i]+V[i];
  vector<LL> left(N+1,0);
  for(int i=N-1; i>=0; --i) {
    left[i]=max(left[i+1],cum[N]-cum[i]-(C-X[i]));
  }

  //dumpc(left);
  LL res=0;
  REPE(r,N) {
    LL base=cum[r]-(r==0?0:X[r-1]);
    SMAX(res,base);
    SMAX(res, base-(r==0?0:X[r-1])+left[r]);
  }
  //dump(res);
  return res;
}
LL solve() {
  LL res=f();
  reverse(V,V+N);
  vector<LL> ys(N);
  REP(i,N) ys[i]=C-X[N-i-1];
  REP(i,N)X[i]=ys[i];
  SMAX(res,f());
  return res;
}

LL f(int N, LL C) {
  LL res=0;
  ZERO(Q);
  LL cur=0;
  REP(i,N) {
    LL x=X[i],v=V[i];
    cur+=v;
    LL vv=cur-x;
    Q[i+1]=max(Q[i],vv); // Q[i] for [0,i)
  }

  cur=0;
  for(int i=N; i>=0; --i) {
    LL a=Q[i];
    LL b=0;
    if(i<N) {
      LL x=C-X[i],v=V[i];
      cur+=v;
      b=cur-2*x;
    }
    SMAX(res,a+b);
  }
  return res;
}
LL solve_org(int N, LL C) {
  LL res=0;
  SMAX(res,f(N,C));
  reverse(X,X+N); REP(i,N) X[i]=C-X[i];
  reverse(V,V+N);
  SMAX(res,f(N,C));
  return res;
}

int main() {
  cin >> N >> C;
  REP(i,N) {
    LL x,v;
    cin >> x >> v;
    X[i]=x,V[i]=v;
  }
  cout << solve() << endl;
  return 0;
}

