int main() {
	int n;
	long long c, tot, mx = 0;

	scanf("%d %lld", &n, &c);

	for (int i = 0;i < n;++i)
		scanf("%lld %lld", &x[i], &v[i]);

	tot = v[0];
	cw1[0] = max((long long)0, v[0] - x[0]);
	cw2[0] = max((long long)0, v[0] - x[0] * 2);

	mx = cw1[0];

	for (int i = 1;i < n;++i) {
		tot += v[i];
		cw1[i] = max(cw1[i - 1], tot - x[i]);
		cw2[i] = max(cw2[i - 1], tot - x[i] * 2);

		mx = max(mx, cw1[i]);
	}

	tot = v[n - 1];
	ccw1[n - 1] = max((long long)0, v[n - 1] - (c - x[n - 1]));
	ccw2[n - 1] = max((long long)0, v[n - 1] - (c - x[n - 1]) * 2);

	mx = max(mx, ccw1[n - 1]);
	if (n > 1) {
		mx = max(mx, ccw1[n - 1] + cw2[n - 2]);
		mx = max(mx, ccw2[n - 1] + cw1[n - 2]);
	}

	for (int i = n - 2;i >= 0;--i) {
		tot += v[i];
		ccw1[i] = max(ccw1[i + 1], tot - (c - x[i]));
		ccw2[i] = max(ccw2[i + 1], tot - (c - x[i]) * 2);

		mx = max(mx, ccw1[i]);

		if (i > 0) {
			mx = max(mx, ccw1[i] + cw2[i - 1]);
			mx = max(mx, ccw2[i] + cw1[i - 1]);
		}
	}

	printf("%lld", mx);

	return 0;
}

