  }
  for (int i = 0; i < N; i++)
  {
    xb[i] = (C - xa[i]);
    vb[i] = va[i];
  }
  reverse(xb.begin(), xb.end());
  reverse(vb.begin(), vb.end());
  for (int i = 1; i <= N; i++)
  {
    sva[i] = sva[i - 1] + va[i - 1];
    svb[i] = svb[i - 1] + vb[i - 1];
  }
  for (int i = 1; i <= N; i++)
  {
    sva[i] -= xa[i - 1];
    svb[i] -= xb[i - 1];
  }
  int64_t mxa = -(1LL << 62), mxb = -(1LL << 62);
  vector<int64_t> mxsva(N + 1), mxsvb(N + 1);
  for (int i = 1; i <= N; i++)
  {
    mxa = mxsva[i] = max(mxa, sva[i]);
    mxb = mxsvb[i] = max(mxb, svb[i]);
  }
  // pattern 1 & pattern 2
  ans = max(ans, mxsva[N]);
  ans = max(ans, mxsvb[N]);
  // 時計回り -> 反時計回り
  for (int i = 1; i <= N - 1; i++)
  {
    ans = max(ans, sva[i] - xa[i - 1] + mxsvb[N - i]);
  }
  // 反時計回り -> 時計回り
  for (int i = 1; i <= N - 1; i++)
  {
    ans = max(ans, svb[i] - xb[i - 1] + mxsva[N - i]);
  }
  cout << ans << endl;
