using namespace std;

int N;
long long C;

long long Soa[100000] = {0};
long long Sob[100000] = {0};

// OA + 2OB
long long solve_oa_2ob(const vector<long long>& x) {
  long long ans = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = N; j > i; --j) {
      if (j == N) {  // OA
        ans = max(ans, Soa[i] - x[i]);
      } else {
        const auto w_oa = Soa[i] - x[i];
        const auto w_2ob = Sob[j] - 2 * (C - x[j]);
        ans = max(ans, w_oa + w_2ob);
      }
    }
  }
  return ans;
}

// 2OA + OB
long long solve_2oa_ob(const vector<long long>& x) {
  long long ans = 0;
  for (int i = N - 1; i >= 0; --i) {
    for (int j = -1; j < i; ++j) {
      if (j == -1) {  // OB
        ans = max(ans, Sob[i] - (C - x[i]));
      } else {
        const auto w_ob = Sob[i] - (C - x[i]);
        const auto w_2oa = Soa[j] - 2 * x[j];
        ans = max(ans, w_2oa + w_ob);
      }
    }
  }
  return ans;
}

int main() {
  cin >> N >> C;

  vector<long long> x(N);
  vector<long long> v(N);

  long long sum = 0;
  for (int i = 0; i < N; ++i) {
    cin >> x[i] >> v[i];

    sum += v[i];
    Soa[i] = sum;
  }

  sum = 0;
  for (int i = N - 1; i >= 0; --i) {
    sum += v[i];
    Sob[i] = sum;
  }

  const long long ans = max(solve_oa_2ob(x), solve_2oa_ob(x));
  cout << ans << endl;

  return 0;
}

