		}
		sort(x + 1, x + 1 + n,cmp);
		for(long long i = 1;i <= n;i++)
		{
			b[i].sum = b[i - 1].sum + x[i].v - x[i].f + x[i - 1].f;
			b[i].id = x[i].f;
			ans = max(ans,b[i].sum);
	//		printf("%lld %lld\n",b[i].id,b[i].sum);
		}
		sort(b + 1,b + 1 + n,cmp1);
		for(long long i = 1;i <= n;i++)
		{
			biu = 1;
