				biu++;
				if(biu > n) break;
			}
			if(biu > n) break;
			piu = b[biu].sum + a[i].sum - a[i].id;
			ans = max(piu,ans);
		}
		sort(b + 1,b + 1 + n,cmp2);
		sort(a + 1,a + 1 + n,cmp1);
		for(long long i = 1;i <= n;i++)
		{
			biu = 1;
			while(a[biu].id + b[i].id >= c)
			{
				biu++;
				if(biu > n) break;
