int main() {
  i64 N, C;
  std::cin >> N >> C;
  std::vector<i64> x, v;
  x.reserve(N);
  v.reserve(N);
  for (i64 i = 0; i < N; ++i) {
    i64 x_i, v_i;
    std::cin >> x_i >> v_i;
    x.push_back(x_i);
    v.push_back(v_i);
  }

  std::vector<i64> l_gains;
  l_gains.reserve(N);
  for (i64 i = 0; i < N; ++i) {
    l_gains.push_back(v[i] - (x[i] - (i == 0 ? 0 : x[i - 1])));
  }

  std::vector<i64> l_strategies;
  l_strategies.reserve(N);
  for (const i64& l_gain : l_gains) {
    l_strategies.push_back((l_strategies.empty() ? 0 : l_strategies.back()) + l_gain);
  }

  std::vector<i64> l_optimums;
  l_optimums.reserve(N);
  for (const i64& l_strategy : l_strategies) {
    l_optimums.push_back(std::max(l_strategy, l_optimums.empty() ? 0 : l_optimums.back()));
  }
  std::reverse(l_optimums.begin(), l_optimums.end());

  std::vector<i64> r_gains;
  r_gains.reserve(N);
  for (i64 i = 0; i < N; ++i) {
    r_gains.push_back(v[N - 1 - i] - ((i == 0 ? C : x[N - i]) - x[N - 1 - i]));
  }

  std::vector<i64> r_strategies;
  r_strategies.reserve(N);
  for (const i64& r_gain : r_gains) {
    r_strategies.push_back((r_strategies.empty() ? 0 : r_strategies.back()) + r_gain);
  }

  std::vector<i64> r_optimums;
  r_optimums.reserve(N);
  for (const i64& r_strategy : r_strategies) {
    r_optimums.push_back(std::max(r_strategy, r_optimums.empty() ? 0 : r_optimums.back()));
  }
  std::reverse(r_optimums.begin(), r_optimums.end());

  i64 answer = 0;
  for (const i64& l_strategy : l_strategies) {
    answer = std::max(answer, l_strategy);
  }
  for (const i64& r_strategy : r_strategies) {
    answer = std::max(answer, r_strategy);
  }
  for (i64 i = 0; i < N; ++i) {
    answer = std::max(answer, (i == 0 ? 0 : l_strategies[i - 1]) - (i == 0 ? 0 : x[i - 1]) + r_optimums[i]);
    answer = std::max(answer, (i == 0 ? 0 : r_strategies[i - 1]) - (i == 0 ? 0 : C - x[N - i]) + l_optimums[i]);
  }
  std::cout << answer << std::endl;
  return 0;
}

