using namespace std;
const int MAX = 1e5+10;


int64_t A[MAX], B[MAX], v[MAX], x[MAX];
int main(){
    int N; cin >> N;
    int64_t C; cin >> C;
    for(int i=1;i<=N;i++){
        cin >> x[i] >> v[i];
        A[i] = A[i-1] + x[i-1] - x[i] + v[i];
    }
    x[N+1] = C;
    for(int i=N;i>=1;i--){
        B[i] = B[i+1] - x[i+1] + x[i] + v[i];
    }
    for(int i=2;i<=N;i++){
        A[i] = max(A[i], A[i-1]);
    }
    for(int i=N-1;i>=1;i--){
        B[i] = max(B[i], B[i+1]);
    }
    int64_t ans = 0;
    for(int i=1;i<=N;i++){
        ans = max(ans, max(A[i], B[i]));
        ans = max(ans, max(A[i] - x[i] + B[i+1], B[i] - (C-x[i]) + A[i-1]));
    }
    cout << ans << endl;
    return 0;
}

