using namespace std;
// using namespace atcoder;
void Main()
{
    ll n, C;
    cin >> n >> C;

    vector<ll> x(n), v(n);
    rep(i, n) cin >> x[i] >> v[i];

    typedef pair<ll, ll> P;
    vector<P> sushi(x.size());
    rep(i, x.size()) sushi[i] = P(x[i], v[i]);

    sort(all(sushi));

    vector<ll> Sv(n + 1);
    rep(i, n) {
        Sv[i+1] = Sv[i] + sushi[i].second;
    }
    vector<ll> f(n);
    ll best = -1e18;
    ll bestA = -1;
    rep(i, n) {
        ll score = Sv[i+1] - sushi[i].first;
        if (best < score) {
            best = score;
            bestA = i;
        }
        f[i] = bestA;
    }

    ll res = 0;
    for (ll b = 0; b <= n; b++) {
        if (b == n) {
            ll a = f[n-1];
            if (a >= 0) {
                res = max(res, Sv[a+1] - sushi[a].first);
            }
        }
        else if (b == 0) {
            res = max(res, Sv[n] - (C - x[0]));
        }
        else {
            ll a = f[b - 1];
            ll t = Sv[a+1] + Sv[n] - Sv[b];
            ll xa = a < 0 ? 0 : x[a];
            ll xb = C - x[b];
            res = max(res, t - xa - 2 * xb);
            res = max(res, t - 2 * xa - xb);
        }
    }

    put(res);

}
