int N;
llint C;
llint x[100010];
int v[100010];
llint dp[2][100010];


void makeDP(){
	llint cal = 0;
	dp[0][0] = cal = v[0]-x[0];
	rep(i, 1, N){
		cal += v[i]-(x[i]-x[i-1]);
		dp[0][i] = max(dp[0][i-1], cal);
	}
	dp[1][N-1] = cal = v[N-1]-(C-x[N-1]);
	reper(i, N-2, 0){
		cal += v[i]-(x[i+1]-x[i]);
		dp[1][i] = max(dp[1][i+1], cal);
	}
}


llint solve(){
	llint ans = 0;
	rep(i, 0, N) ans = max({ ans, dp[0][i], dp[0][i]-x[i]+dp[1][i+1] });
	reper(i, N-1, 0) ans = max({ ans, dp[1][i], dp[1][i]-(C-x[i])+dp[0][i-1] });
	return ans;
}


signed main(){
	cin >> N >> C;
	rep(i, 0, N) cin >> x[i] >> v[i];

	makeDP();

	cout << solve() << endl;

	return 0;
}

