#define FOR(i, a, b) for(int (i) = (a); (i) < (b); ++(i))
#define FOReq(i, a, b) for(int (i) = (a); (i) <= (b); ++(i))
#define REP(i, n) FOR(i, 0, n)

using lli = long long int;

template <class T> inline bool chmax(T& a, T b){
    if(a < b){a = b; return true;}
    return false;
}

std::vector<lli> S, T;
std::vector<lli> SB, TB;
std::vector<lli> X;

int main(void){
    int n; lli C;
    scanf("%d%lld", &n, &C);
    S.resize(n+1), T.resize(n+1), X.resize(n+2);
    X[0] = 0, X[n+1] = C; S[0] = 0; T[0] = 0;
    FOReq(i, 1, n){ scanf("%lld%lld", &X[i], &S[i]); T[n-i+1] = S[i];}

    REP(i, n){ S[i+1] += S[i]; T[i+1] += T[i];}
    SB.resize(n+1); TB.resize(n+1);
    FOReq(i, 0, n){
        SB[i] = S[i] - 2 * X[i];
        TB[i] = T[i] - 2 * (C - X[n-i+1]);
    }
    REP(i, n){
        if(SB[i] > SB[i+1]) SB[i+1] = SB[i];
        if(TB[i] > TB[i+1]) TB[i+1] = TB[i];
    }
    lli res = -1;
    FOReq(i, 0, n){
        chmax(res, S[i] - X[i] + TB[n-i]);
        chmax(res, T[i] - (C - X[n-i+1]) + SB[n-i]);
    }
    printf("%lld\n", res);

    return 0;
}

#include <cstdio>
#include <iostream>
#include <vector>
int main(int argc, char **argv){
  int N,C;
  std::cin >> N >> C;

  std::vector<int> posx(10000);
  std::vector<int> negx(10000);
  std::vector<int> v(10000);
  int stai;
  for(int i = 0; i < N; i++){
    int buf;
    std::cin >> buf >> v[i];

    if (buf<C/2) posx[i] = buf;
    else negx[i] = C - buf;

    if ((i!=0) && (negx[i-1]==0) && (negx[i]!=0)) stai = i;
  }

  int poscal=0,negcal=0;
  bool pos_m=false,neg_m=false;
  bool finflag=false;
  int maxcal=0;

  //FOR ALL POSITIVE
  if (negx[N-1]==0) {
    for(int i = 0; i < N; i++){
      if(i==0) poscal = v[0] - posx[i];
      else poscal += v[i] - posx[i] + posx[i-1];
      if(poscal<=0) continue;
      maxcal=std::max(maxcal,poscal);
    }
  }else if (posx[0]==0) {
    for(int j = N-1; j >= stai; j--){
      if(j==N-1) negcal=v[j]-negx[j];
      else negcal=v[j]-negx[j]+negx[j+1];
      if(negcal <= 0) continue;
      maxcal=std::max(maxcal,negcal);
    }
  }else{
    for(int i = 0; i < stai; i++){
      if(i==0) poscal = v[0] - posx[i];
      else poscal += v[i] - posx[i] + posx[i-1];

      if(poscal <= 0) pos_m = true;

      for(int j = N-1; j >= stai; j--){
        if(j==N-1) negcal=v[j]-negx[j];
        else negcal+=v[j]-negx[j]+negx[j+1];

        if(negcal <= 0) neg_m = true;

        int cpcal;
        if (pos_m&&neg_m) continue;
        else if(!pos_m&&!neg_m) cpcal=poscal+negcal-std::min(posx[i],negx[j]);
        else if(neg_m) cpcal=poscal;
        else cpcal=negcal;

        maxcal=std::max(maxcal,cpcal);
        neg_m=false;
      }
      pos_m=false;
    }
  }
  std::cout << maxcal << std::endl;

  return 0;
}

