using namespace std;

int main(){
    int n;
    long long int C;
    cin >> n >> C;

    vector<long long int> x(n+2), v(n+2);
    x[0] = 0;
    x[n+1] = C;
    for(int i=1; i<=n; i++){
        cin >> x[i] >> v[i];
    }

    vector<long long int> vc(n+1), va(n+1);
    for(int i=1; i<=n; i++){
        vc[i] = vc[i-1] + v[i];
        va[i] = va[i-1] + v[n+1-i];
    }

    vector<long long int> g(n+1), h(n+1);// g[0] = 0 = 0 - 0
    int rec = 0;
    for(int i=1; i<n+1; i++){
        g[i] = max(g[i-1], vc[i] - x[i]);

        if(g[i-1] < vc[i] - x[i]) rec = i;
        h[i] = rec;
    }

    long long int ans = 0;// 0 -> 0 (exit without eating)
    for(int j=1; j<=n+1; j++){
        long long int c = x[h[j-1]];
        long long int a = C - x[j];
        long long int ca = c + 2 * a;
        long long int ac = a + 2 * c;
        long long int test = vc[h[j-1]] + va[n+1-j] - min(ca, ac);
        ans = max(ans, test);
    }
    cout << ans << endl;
    return 0;
}

