const int INF = (1 << 30) - 1;
const ll INF64 = ((ll)1 << 62) - 1;
const double PI = 3.1415926535897932384626433832795;

const int dx[] = { 0, 1, 0, -1 };
const int dy[] = { -1, 0, 1, 0 };

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	ll n, c;
	cin >> n >> c;
	vector<ll> x(n), v(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> v[i];
	}

	vector<ll> dp1(n);
	dp1[0] = v[0] - x[0];
	for (int i = 1; i < n; i++) {
		dp1[i] = dp1[i - 1] + v[i] - (x[i] - x[i - 1]);
	}
	for (int i = 1; i < n; i++) {
		dp1[i] = max(dp1[i], dp1[i - 1]);
	}

	vector<ll> dp2(n);
	dp2[n - 1] = v[n - 1] - (c - x[n - 1]);
	for (int i = n - 2; i >= 0; --i) {
		dp2[i] = dp2[i + 1] + v[i] - (x[i + 1] - x[i]);
	}
	for (int i = n - 2; i >= 0; --i) {
		dp2[i] = max(dp2[i], dp2[i + 1]);
	}

	ll ans = max(0LL, dp2[0]);
	for (int i = 0; i < n; i++) {
		ll tmp = dp1[i];
		if (i + 1<n && dp2[i + 1] - x[i] > 0) tmp += dp2[i + 1] - x[i];
		ans = max(ans, tmp);
	}
	for (int i = n - 1; i >= 0; --i) {
		ll tmp = dp2[i];
		if (i >= 1 && dp1[i - 1] - (c - x[i]) > 0) tmp += dp1[i - 1] - (c - x[i]);
		ans = max(ans, tmp);
	}

	cout << ans << endl;
	return 0;
}

