long long int max1, max2;
long long int N, C;
vector<long long int> x, v, toRight, toRightMax, toRight2, toLeft, toLeftMax, toLeft2;
int main() {
	cin >> N >> C;
	long long int temp_x, temp_v;
	for(int i=0; i<N; i++) {
		cin >> temp_x >> temp_v;
		x.push_back(temp_x);
		v.push_back(temp_v);
		toRight.push_back(0);
		toRightMax.push_back(0);
		toRight2.push_back(0);
		toLeft.push_back(0);
		toLeftMax.push_back(0);
		toLeft2.push_back(0);
	}

	// 時計回りオンリー
	toRight[0] = v[0] - x[0];
	toRightMax[0] = toRight[0];
	toRight2[0] = toRight[0] - x[0];
	for(int i=1; i<N; i++) {
		toRight[i] = toRight[i-1] + v[i] - (x[i] - x[i-1]);
		if(toRightMax[i-1] < toRight[i])
			toRightMax[i] = toRight[i];
		else
			toRightMax[i] = toRightMax[i-1];
		toRight2[i] = toRight2[i-1] - 2 * (x[i] - x[i-1]) + v[i];
	}
	// 半時計回りオンリー
	toLeft[N-1] = v[N-1] - (C - x[N-1]);
	toLeftMax[N-1] = toLeft[N-1];
	toLeft2[N-1] = toLeft[N-1] - (C - x[N-1]);
	for(int i=1; i<N; i++) {
		toLeft[N-1-i] = toLeft[N-i] + v[N-1-i] - (x[N-i] - x[N-1-i]);
		if(toLeftMax[N-i] < toLeft[N-1-i])
			toLeftMax[N-1-i] = toLeft[N-1-i];
		else
			toLeftMax[N-1-i] = toLeftMax[N-i];
		toLeft2[N-1-i] = toLeft2[N-i] - 2 * (x[N-i] - x[N-1-i]) + v[N-1-i];
	}

	// 右に行ってから左へ
	long long int temp_max1;
	for(int i=0; i<N-1; i++) {
		temp_max1 = toRight2[i] + toLeftMax[i+1];
		if(max1 < temp_max1)
			max1 = temp_max1;
	}
	// 左に行ってから右へ
	long long int temp_max2;
	for(int i=N-1; i>=1; i--) {
		temp_max2 = toLeft2[i] + toRightMax[i-1];
		if(max2 < temp_max2)
			max2 = temp_max2;
	}

	if(max1 < max2)
		max1 = max2;
	if(max1 < toLeftMax[0])
		max1 = toLeftMax[0];
	if(max1 < toRightMax[N-1])
		max1 = toRightMax[N-1];
	if(0 > max1)
		max1 = 0;
	cout << max1 << endl;

	return 0;
}

