using namespace std;

vector<int64_t> X;
vector<uint32_t> V;

int32_t N;
int64_t C;

int64_t exec()
{
  vector<int64_t> sum_V_start, sum_V_stop;
  sum_V_start.reserve(N+1);
  sum_V_stop.reserve(N+1);

  sum_V_start.push_back(V[N+1]);
  sum_V_stop.push_back(V[0]);
  for (uint32_t n=1; n<=N; ++n) {
    sum_V_start.push_back(sum_V_start.back() + V[N-n+1]);
    sum_V_stop.push_back(sum_V_stop.back() + V[n]);    
  }  

  int64_t max_calory = 0;

  vector<int64_t> calory_to_start1, calory_to_start2;
  vector<int64_t> calory_to_stop1, calory_to_stop2;
  vector<int64_t> max_calory_to_start1, max_calory_to_start2;
  vector<int64_t> max_calory_to_stop1, max_calory_to_stop2;

  calory_to_start1.reserve(N+1);
  calory_to_start2.reserve(N+1);
  calory_to_stop1.reserve(N+1);
  calory_to_stop2.reserve(N+1);
  max_calory_to_start1.reserve(N+1);
  max_calory_to_start2.reserve(N+1);
  max_calory_to_stop1.reserve(N+1);
  max_calory_to_stop2.reserve(N+1);

  for (int32_t start=0; start>=-N; --start) {
    int64_t dist_to_start = C - X[start+N+1];
    int64_t calory_to_start = sum_V_start[-start];

    calory_to_start1.push_back(calory_to_start - dist_to_start);
    calory_to_start2.push_back(calory_to_start - 2*dist_to_start);
    if (start==0) {
      max_calory_to_start1.push_back(calory_to_start1.back());
      max_calory_to_start2.push_back(calory_to_start2.back());
    } else {
      max_calory_to_start1.push_back(max(calory_to_start1.back(),max_calory_to_start1.back()));
      max_calory_to_start2.push_back(max(calory_to_start2.back(),max_calory_to_start2.back()));
    }
  }

  for (int32_t stop=0; stop <= N; ++stop) {
    int64_t dist_to_stop = X[stop];
    int64_t calory_to_stop = sum_V_stop[stop];

    calory_to_stop1.push_back(calory_to_stop - dist_to_stop);
    calory_to_stop2.push_back(calory_to_stop - 2*dist_to_stop);
    if (stop==0) {
      max_calory_to_stop1.push_back(calory_to_stop1.back());
      max_calory_to_stop2.push_back(calory_to_stop2.back());
    } else {
      max_calory_to_stop1.push_back(max(calory_to_stop1.back(),max_calory_to_stop1.back()));
      max_calory_to_stop2.push_back(max(calory_to_stop2.back(),max_calory_to_stop2.back()));
    }
  }

  for (int32_t stop = 0; stop <= N; ++stop) {
    max_calory = max(max(max_calory_to_stop1[stop] + max_calory_to_start2[N-stop],
			 max_calory_to_stop2[stop] + max_calory_to_start1[N-stop]),
		     max_calory);
  }

  return max_calory;
}

