const int MAX_N=1e6+1;
LL C,X[MAX_N],V[MAX_N];
int N;

LL cum[MAX_N];
LL f() {
  REP(i,N+1) cum[i+1]=cum[i]+V[i];
  vector<LL> left(N+1,0);
  for(int i=N-1; i>=0; --i) {
    left[i]=max(left[i+1],cum[N]-cum[i]-(C-X[i]));
  }

  //dumpc(left);
  LL res=0;
  REPE(r,N) {
    LL base=cum[r]-(r==0?0:X[r-1]);
    SMAX(res,base);
    SMAX(res, base-(r==0?0:X[r-1])+left[r]);
  }
  //dump(res);
  return res;
}
void solve() {
  LL res=f();
  reverse(V,V+N);
  vector<LL> ys(N);
  REP(i,N) ys[i]=C-X[N-i-1];
  REP(i,N)X[i]=ys[i];
  SMAX(res,f());
  cout<<res<<endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N>>C;
  REP(i,N) cin>>X[i]>>V[i];
  solve();

  return 0;
}

