int main()
{    
    i64 n,c;
    cin >> n >> c;
    vector<i64> x(n);
    vector<i64> v(n);
    rep(i,n) cin >> x[i] >> v[i];

    vector<pair<int,i64>> r_oneway(n+1, {0,0});
    vector<pair<int,i64>> l_oneway(n+1, {0,0});
    vector<pair<int,i64>> r_round(n+1, {0,0});
    vector<pair<int,i64>> l_round(n+1, {0,0});

    i64 tmp_cal = 0;
    i64 tmp_dis = 0;
    rep(i,n)
    {
        i64 d = i==0 ? x[i] : x[i] - x[i-1];
        tmp_cal += v[i] - d;
        tmp_dis += d;

        if(tmp_cal>r_oneway[i].second)
        {
            r_oneway[i+1].first = i;
            r_oneway[i+1].second = tmp_cal;
        }
        else
        {
            r_oneway[i+1] = r_oneway[i];
        }

        if(tmp_cal-tmp_dis>r_round[i].second)
        {
            r_round[i+1].first = i;
            r_round[i+1].second = tmp_cal-tmp_dis;
        }
        else
        {
            r_round[i+1] = r_round[i];
        }
    }

    tmp_cal = 0;
    tmp_dis = 0;
    rep(i,n)
    {
        i64 d = i==0 ? c-x[n-1] : x[n-i] - x[n-i-1];
        tmp_cal += v[n-1-i] - d;
        tmp_dis += d;

        if(tmp_cal>l_oneway[i].second)
        {
            l_oneway[i+1].first = i;
            l_oneway[i+1].second = tmp_cal;
        }
        else
        {
            l_oneway[i+1] = l_oneway[i];
        }

        if(tmp_cal-tmp_dis>l_round[i].second)
        {
            l_round[i+1].first = i;
            l_round[i+1].second = tmp_cal-tmp_dis;
        }
        else
        {
            l_round[i+1] = l_round[i];
        }
    }

    i64 max_cal = 0;
    rep2(i,1,n+1)
    {
        // r
        int max_idx_oneway = r_oneway[i].first;
        i64 max_cal_oneway = r_oneway[i].second;

        int max_idx_round = n - (max_idx_oneway + 1);
        i64 max_cal_round = l_round[max_idx_round].second;

        max_cal = max(max_cal, max_cal_oneway+max_cal_round);

        // l
        max_idx_oneway = l_oneway[i].first;
        max_cal_oneway = l_oneway[i].second;

        max_idx_round = n - (max_idx_oneway + 1);
        max_cal_round = r_round[max_idx_round].second;

        max_cal = max(max_cal, max_cal_oneway+max_cal_round);
    }
    cout << max_cal << endl;
    return 0;
}

