int main(void) {
  ios::sync_with_stdio(false);
  int64_t N, C;
  cin >> N >> C;
  vector<int64_t> X(N);
  vector<int64_t> V(N);
  rep(i, N) { cin >> X[i] >> V[i]; }

  vector<int64_t> RXV(N + 1);
  RXV[0] = 0;
  int64_t sumRV = 0;
  rep(i, N) {
    sumRV += V[i];
    RXV[i + 1] = sumRV - X[i];
    RXV[i + 1] = max(RXV[i + 1], RXV[i]);
  }

  vector<int64_t> LXV(N + 1);
  LXV[0] = 0;
  int64_t sumLV = 0;
  rep(i, N) {
    sumLV += V[N - (i + 1)];
    LXV[i + 1] = sumLV - (C - X[N - (i + 1)]);
    LXV[i + 1] = max(LXV[i + 1], LXV[i]);
  }

  // pattern 1 clockwise
  // pattern 2 unticlockwise
  int64_t answer = max(RXV[N], LXV[N]);

  rep(i, N) {
    // pattern 3 clockwise -> back to start -> unticlockwise
    int64_t tmp0 = RXV[i + 1] - X[i] + LXV[N - i - 1];
    // pattern 4 unticlockwise -> back to start -> clockwise
    int64_t tmp1 = LXV[i + 1] - (C - X[N - (i + 1)]) + RXV[N - i - 1];
    answer = max(answer, max(tmp0, tmp1));
  }
  cout << answer << endl;
  return 0;
}

