#include<iostream>
#include<vector>
#include<algorithm>
using namespace std;

int main(){
    int N;//<=10^5
    long long C;//<=10^9
    cin>>N>>C;
    vector<long long> x;//位置記録
    vector<int> v;//カロリー記録

    //入力
    for(int i=0;i<N;i++){
        long long x_temp;
        int v_temp;
        cin>>x_temp>>v_temp;
        x.push_back(x_temp);
        v.push_back(v_temp);
    }
    //部分和,O(N)
    vector<long long> right;
    vector<long long> left;
    right.push_back(v[0]);
    left.push_back(v[N-1]);
    for(int i=1;i<N;i++){
        right.push_back(right[i-1]+v[i]);
        left.push_back(left[i-1]+v[N-1-i]);
    }
    reverse(left.begin(),left.end());

    //0<=a<=iのとき,f(a):v[0]+v[1]+...+v[a]-x[a]の最大値,O(N)
    vector<long long> r_col;
    vector<long long> l_col;
    r_col.push_back(right[0]-2*x[0]);
    l_col.push_back(left[N-1]-2*(C-x[N-1]));
    for(int i=1;i<N;i++){
        r_col.push_back(max(r_col[i-1],right[i]-2*x[i]));
        l_col.push_back(max(l_col[i-1],left[N-1-i]-2*(C-x[N-1-i])));
    }
    reverse(l_col.begin(),l_col.end());

    long long ans=0;
    //ans,//右回りのみor左回りのみ,O(N)
    for(int i=0;i<N;i++){
        ans=max(ans,right[i]-x[i]);
        ans=max(ans,left[i]-(C-x[i]));
    }
    //両方のとき,O(N)
    for(int i=0;i<N;i++){
        if(i<N-1)ans=max(ans,right[i]-x[i]+l_col[i+1]);
        if(0<i)ans=max(ans,left[i]-(C-x[i])+r_col[i-1]);
    }
    cout<<ans<<endl;
    return 0;
}

