    g[i] = max(g[i-1], {f[i], -i});
  }

  for(int i=n; i>=1; i--){
    unsum[i] = v[i] + unsum[(i+1)%(n+1)];
  }

  ll ans = g[n].first;
  for(int i=1; i<=n; i++){
    int a = -g[i-1].second;
    ll dis = min(cl[a], c-cl[i]);

    ans = max(unsum[i]-(c-cl[i])+g[i-1].first-dis, ans);
  }

  assert(ans >= 0);
  cout << ans << endl;

  return 0;
}

