int main()
{
	ll ans=0;
	n=read(),c=read();f=n;
	for (int i=1;i<=n;++i) d[i]=read(),t[i]=c-d[i],v[i]=read();
	for (int i=1;i<=n;++i) ww+=v[i],s[i]=ww-d[i],ans=max(ans,s[i]);ww=0;
	for (int i=n;i>=1;--i) ww+=v[i],h[i]=ww-t[i],ans=max(ans,h[i]);
	create(1,1,n),build(1,1,n);
	for (int i=1;i<n;++i)
	{
		int j,pd=0;
		for (j=f;j>=i+1;--j) if (d[i]<=t[j]) {pd=1;break;}
		if (!pd) ans=max(ans,s[i]+query1(1,i+1,n));
		else if (j==n) ans=max(ans,s[i]-d[i]+query2(1,i+1,n));
		else if (j==i||j==i+1) ans=max(ans,s[i]+query1(1,i+1,n)),f=j+1;
		else ans=max(ans,max(s[i]-d[i]+query2(1,i+1,j),s[i]+query1(1,j+1,n))),f=j;
	}
	write(ans);
	return 0;
}

