    llong *x;
    llong *v;
    llong *maxDA;
    llong *maxDAX;

    std::cin >> n >> c;

    maxDA = new llong[n];
    maxDAX = new llong[n];
    x = new llong[n];
    v = new llong[n];

    llong maxProfit = 0;

    llong dA = 0;
    llong _maxDAX = 0;

    for (llong i = 0; i < n; ++i) {
        std::cin >> x[i] >> v[i];
        dA += i > 0 ? x[i - 1] : 0;
        dA += v[i] - x[i];

        if (dA > maxProfit) {
            maxProfit = dA;
            _maxDAX = x[i];
        }

        maxDA[i] = maxProfit;
        maxDAX[i] = _maxDAX;
    }

    llong dB = 0;
    for (llong j = n - 1; j >= 0; --j) {
        llong dr = c - x[j];
        if (j < (n-1)) {
            dB = dB + c - x[j + 1];
        }
        dB = dB + v[j] - dr;

        llong tBest = dB;
        if (j > 0) {
            llong dl = maxDAX[j - 1];
            llong dd = dl;

            if (dr < dd) {
                dd = dr;
            }

            llong alter = dB + maxDA[j - 1] - dd;
            if (alter > tBest) {
                tBest = alter;
            }
        }

        if (tBest > maxProfit) {
            maxProfit = tBest;
        }

    }
    std::cout << std::endl;
    std::cout << maxProfit << std::endl;

    delete[](x);
    delete[](v);
    delete[](maxDA);
    delete[](maxDAX);

    return 0;
}

