        right1[i+1] = right1[i] + v[i+1] - (x[i+1] - x[i]);
        right2[i+1] = right2[i] + v[i+1] - 2*(x[i+1]-x[i]);
        left1[i+1] = left1[i] + v[n-i] - (x[n+1-i] - x[n-i]);
        left2[i+1] = left2[i] + v[n-i] - 2*(x[n+1-i] - x[n-i]);
    }
    rep(i,n)
    {
        dpr1[i+1] = max(dpr1[i], right1[i+1]);
        dpl1[i+1] = max(dpl1[i], left1[i+1]);
        dpr2[i+1] = max(dpr2[i], right2[i+1]);
        dpl2[i+1] = max(dpl2[i], left2[i+1]);
    }
    for(int i=0; i<=n; i++)
    {
        ans = max(ans, dpr1[i] + dpl2[n-i]);
        ans = max(ans, dpl2[i] + dpr2[n-i]);
    }
    cout << ans << endl;
    return 0;
}

