        else{
            tmp+=v[i];
            a[i]=max(a[i-1],tmp-x[i]);
            d[i]=(a[i]==tmp-x[i])? x[i]:d[i-1];
        }
    }
    reverse(x.begin(),x.end());
    reverse(v.begin(),v.end());
    tmp=0;
    rep(i,n){
        x[i]=c-x[i];
        if(i==0){
            tmp+=v[i];
            b[i]=max(tmp-x[i],(ll)0);
            e[i]=(b[i]==tmp-x[i])? x[i]:0;
        }
        else{
            tmp+=v[i];
            b[i]=max(b[i-1],tmp-x[i]);
            e[i]=(b[i]==tmp-x[i])? x[i]:e[i-1];
        }
    }

    reverse(b.begin(),b.end());
    reverse(e.begin(),e.end());
    ll res=0;
    rep(i,n){
        //cout<<i<<endl;
        if(i!=n-1){
            ll left=a[i],right=b[i+1];
            //cout<<left<<" "<<right<<endl;
            ll now=right+left;
            now-=min(d[i],e[i+1]);
            res=max(res,now);
        }
        if(i!=0){
            ll left=a[i-1],right=b[i];
            //cout<<left<<" "<<right<<endl;
            ll now=right+left;
            now-=min(d[i-1],e[i]);
            res=max(res,now);
        }
    }
    cout<<res<<endl;
}

