	for(int i = 0; i < n; i++) {
		if(i == 0) {
			sum_1[i] = v[i] - x[i];
		} else {
			sum_1[i] = sum_1[i - 1] + v[i] - (x[i] - x[i - 1]);
		}
	}

	for(int i = n - 1; i >= 0; i--) {
		if(i == n-1) {
			sum_2[i] = v[i] - (c - x[i]);
		} else {
			sum_2[i] = sum_2[i + 1] + v[i] - (x[i+1] - x[i]);
		}
	}

	long long int MAX_CW_originTOI[n];
	long long int MAX_CCW_originTOI[n];
	for(int i = 0; i < n; i++) {
		MAX_CW_originTOI[i] = 0;
		MAX_CCW_originTOI[i] = 0;
	}

	for(int i = 0; i < n; i++) {
		if(i == 0) MAX_CW_originTOI[i] = max(sum_1[i],0LL);
		else       MAX_CW_originTOI[i] = max(sum_1[i],MAX_CW_originTOI[i - 1]);
	}
	for(int i = n - 1; i >= 0; i--) {
		if(i == n-1) MAX_CCW_originTOI[i] = max(sum_2[i],0LL);
