		ans = max(ans,MAX_CCW_originTOI[i]);

		//CCW ORIGIN - > I AND CW ORIGIN - > I - 1
		if(i != 0)
		ans = max(ans,MAX_CCW_originTOI[i] + MAX_CW_originTOI[i - 1] - (c - x[i]));
	}






