static const ll MAX_N = 200000;
ll par[MAX_N];
ll ran[MAX_N];

void init(ll n) {
	rep(i, 0, n) {
		par[i] = i;
		ran[i] = 0;
	}
}

ll find(ll x) {
	if (par[x] == x)  return x;
	else return par[x] = find(par[x]);
}

void unite(ll x, ll y) {
	x = find(x);
	y = find(y);
	if (x == y) return;

	if (ran[x] < ran[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (ran[x] == ran[y]) ran[x]++;
	}
}
bool same(ll x, ll y) {
	return find(x) == find(y);
}

ll P[100001] = {};
ll SumP[100001] = {};
ll MaxP[100001] = {};

ll R[100001] = {};
ll SumR[100001] = {};
ll MaxR[100001] = {};

vector<pair<ll, ll>> p;
vector<pair<ll, ll>> p_r;

int main() {
	ll N, C; cin >> N >> C;
	p.push_back({ 0,0 });
	p_r.push_back({ C,0 });
	repe(i, 1, N) {
		ll x, v; cin >> x >> v;
		p.push_back({ x,v });
		p_r.push_back({ C - x,v });
	}
	sort(p.begin(), p.end());
	reverse(p_r.begin() + 1, p_r.end());
	p_r[0].first = 0;

	//p1
	ll maxPV = 0;
	ll maxRV = 0;
	repe(i, 1, N) {
		P[i] += -(p[i].first - p[i - 1].first) + p[i].second;
		SumP[i] = SumP[i - 1] + P[i];
		if (maxPV < SumP[i]) {
			maxPV = SumP[i];
			MaxP[i] = maxPV;
		}
		else {
			MaxP[i] = MaxP[i - 1];
		}

		/////////////////////
		R[i] += -(p_r[i].first - p_r[i - 1].first) + p_r[i].second;
		SumR[i] = SumR[i - 1] + R[i];
		if (maxRV < SumR[i]) {
			maxRV = SumR[i];
			MaxR[i] = maxRV;
		}
		else {
			MaxR[i] = MaxR[i - 1];
		}
	}

	ll ans = 0;

	repe(i, 0, N) {
		ll tmp = MaxP[i] - p[i].first + MaxR[N - i];
		ans = max(ans, tmp);
		tmp = MaxR[i] - p_r[i].first + MaxP[N - i];
		ans = max(ans, tmp);
	}

	cout << ans << endl;

	return 0;
}

