    p[n-1] = b[n-1];
    for(int i = n-2;i>=0;i--)
    {
        p[i]=p[i+1]+b[i];
    }
    for(int i = 0;i<n;i++)
    {
        pro+=b[i] - (a[i]-now);
        now= a[i];
        long long acc = 0;
        for(int j = i+1;j<n;j++)
        {
            acc+=a[j] - a[j-1];
            long long dis = m  - acc;
            sol = max(sol , pro - dis + b[j] );
