ll f1(void) {
    vector<ll> A(N); // a[i]: i番目までの(取得カロリー - 移動カロリー)の中で最大値
    A[0] = v[0].second - v[0].first;
    rep(i,1,N){
        A[i] = A[i-1] + v[i].second - (v[i].first - v[i-1].first);
    }
    rep(i,1,N){
        A[i] = max(A[i], A[i-1]);
    }

    ll ans = A[N-1];

    ll B = v[N-1].second - (C-v[N-1].first) * 2;
    ans = max(ans, B + A[N-2]);

    for (ll b = N-2; b >= 0; b--){
        B = B + v[b].second - (v[b+1].first - v[b].first) * 2;
        if (b > 0){
            ans = max(ans, B+A[b-1]);
        } else {
            ans = max(ans, B);
        }
    }

    return ans;
}

ll f2(void) {
    vector<ll> B(N); // B[i]: N-1~i番目までの(取得カロリー - 移動カロリー)の中で最大値
    B[N-1] = v[N-1].second - (C- v[N-1].first);
    for (ll i = N-2; i>=0; i--){
        B[i] = B[i+1] + v[i].second - (v[i+1].first - v[i].first);
    }
    for (ll i = N-2; i>=0; i--){
        B[i] = max(B[i], B[i+1]);
    }

    ll ans = B[0];

    ll A = v[0].second - v[0].first * 2;
    ans = max(ans, A + B[1]);

    for (ll a = 1; a < N; a++){
        A = A + v[a].second - (v[a].first - v[a-1].first) * 2;
        if (a < N-1){
            ans = max(ans, A+B[a+1]);
        } else {
            ans = max(ans, A);
        }
    }

    return ans;
}

