ll N, C;

ll solve(vector<ll> x, vector<ll> v) {
    vector<ll> S(N, 0);
    S[0] = v[0];
    FOR(i, 1, N) S[i] = S[i-1] + v[i];
    REP(i, N) S[i] -= x[i];

    vector<ll> T(N, 0); 
    T[N-1] = v[N-1];
    RREP(i, N-2) T[i] = T[i+1] + v[i];
    RREP(i, N-1) T[i] -= (C - x[i]);
    RREP(i, N-2) T[i] = max(T[i], T[i+1]);

    ll res = 0;
    REP(i, N) {
        ll val = 0;

        val += S[i];
        res = max(res, val);

        val -= x[i];
        if (i != N-1) val += T[i+1];

        res = max(res, val);
    }
    return res;
}

