        l_best.resize(N + 1, 0);
        ll acc = 0;
        for (int i = 1; i <= N; i++) {
            acc += r_sushis[i].second;
            r_best[i] = max(r_best[i - 1], acc - 2 * r_sushis[i].first);
        }

        acc = 0;
        for (int i = 1; i <= N; i++) {
            acc += l_sushis[i].second;
            l_best[i] = max(l_best[i - 1], acc - 2 * l_sushis[i].first);
