int main() {
    ll N, C;
    cin >> N >> C;
    vector<P> p(N);
    rep(i, N) cin >> p[i].first >> p[i].second;

    vector<ll> clockwise_sum(N + 1); // 時計回りにi個まで取ったときのカロリー
    ll pos = 0;
    rep(i, N) {
        clockwise_sum[i + 1] = clockwise_sum[i] + p[i].second - (p[i].first - pos);
        pos = p[i].first;
    }

    vector<ll> counter_clockwise_sum(N + 1); // 反時計回りにi個まで取ったときのカロリー
    pos = C;
    rep(i, N) {
        counter_clockwise_sum[i + 1] = counter_clockwise_sum[i] + p[N - 1 - i].second - (pos - p[N - 1 - i].first);
        pos = p[N - 1 - i].first;
    }

    vector<ll> clockwise_max(N + 1); // clockwise_max[i]:時計回りにi個まで取って良いときのmax値
    rep(i, N) clockwise_max[i + 1] = max(clockwise_max[i], clockwise_sum[i + 1]);

    vector<ll> counter_clockwise_max(N + 1); // counter_clockwise_max[i]:反時計回りにi個まで取ってよいときのmax値
    rep(i, N) counter_clockwise_max[i + 1] = max(counter_clockwise_max[i], counter_clockwise_sum[i + 1]);

    ll ans = 0;

    // 時計回り
    rep(i, N) {
        chmax(ans, clockwise_sum[i + 1]); // 時計回りに取るだけの場合
        chmax(ans, clockwise_sum[i + 1] - p[i].first + counter_clockwise_max[N - 1 - i]);
    }

    // 反時計回り
    rep(i, N) {
        chmax(ans, counter_clockwise_sum[i + 1]); // 反時計回りに取るだけの場合
        chmax(ans, counter_clockwise_sum[i + 1] - (C - p[N - 1 - i].first) + clockwise_max[N - 1 - i]);
    }

    cout << ans << endl;
}

