using namespace std;
typedef pair<int, int> pii;
typedef pair<double,double>pdd;
struct Edge{int to,cap,rev;};//ikisaki youryou gyakuhen
class Dinic{//max flow
public:
    int n;
    vector<vector<Edge> >G;//[MAX];
    vector<int> level,iter;//[MAX];
    Dinic(int size){
        n=size;
        G=vector<vector<Edge> >(n);
    }
    //edge : G[from][index] can access : to, cap, rev
    //acess reverse edge  G[e.to][e.rev]
    //G[e.to][e.rev].to = e.from
    //G[e.to][e.rev].rev = index
    void add_edge(int from, int to, int cap){
        Edge q={to,cap,int(G[to].size())};
        G[from].push_back(q);
        q={from,0,int(G[from].size()-1)};
        G[to].push_back(q);
    }
    int getmaxflow(int s,int t) {//from s to t,ford_fulkerson
        int flow=0;

        while(1){
            bfs(s);
            if(level[t]<0)return flow;
            iter=vector<int>(n);
            int f;
            while((f=dfs(s,t,INF))>0)flow+=f;
        }
    }
private:
    void bfs(int s){
        level=vector<int>(n,-1);
        queue<int>q;
        level[s]=0;
        q.push(s);
        while(!q.empty()){
            int v=q.front();q.pop();
            for(int i=0;i<G[v].size();i++){
                Edge &e=G[v][i];
                if(e.cap>0&&level[e.to]<0){
                    level[e.to]=level[v]+1;
                    q.push(e.to);
                }
            }
        }
    }
    int dfs(int v,int t, int f) {
        if(v==t)return f;
        for(int &i=iter[v];i<G[v].size();i++){
            Edge &e=G[v][i];
            if(level[v]>=level[e.to]||e.cap<=0) continue;
            int d =dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;
                G[e.to][e.rev].cap+=d;
                return d;
            }
        }
        return 0;
    }
};
signed main(){
    int n,c; cin >> n >> c;
    vector<vector<Edge>>g;
    int source = n;
    Dinic fl(n+1);
    vector<pii>v;
    rep(i,n){
        pii temp; cin >> temp.first >> temp.second;
        v.push_back(temp);
        int cost = temp.second-temp.first;
        fl.add_edge(source, i, cost);
        rep(j,v.size()-1){
            fl.add_edge(i, j,max(0,v[j].second-abs(temp.first-v[j].first)));
            fl.add_edge(j, i,max(0,temp.second-abs(temp.first-v[j].first)));
        }
    }
    g = fl.G;
    int ans = 0;
    rep(i,n+1){
        rep(j,n+1){
            if (i == j)continue;
            fl.G = g;
            cmax(ans, fl.getmaxflow(i, j));
        }
    }
    cout << ans << endl;
}

