#define LL long long

void solve(long long N, long long C, std::vector<long long> x, std::vector<long long> v){
    vector<LL> l2r(2*N, 0);
    vector<LL> r2l(2*N, 0);
    LL accr=0, accl=0;

    for(LL i=0; i<N; i++){
        accr += v[i];
        accl += v[N-i-1];
        r2l[N+i] = max(accr-2*x[i], (i>0 ? r2l[N+i-1] : 0));
        l2r[N+i] = max(accr-x[i], (i>0 ? l2r[N+i-1] : 0));
        l2r[N-i-1] = max(accl-2*(C-x[N-i-1]), (i>0 ? l2r[N-i] : 0));
        r2l[N-i-1] = max(accl-(C-x[N-i-1]), (i>0 ? r2l[N-i] : 0));
    }

    auto ans=max(r2l[0], l2r[2*N-1]);
    for(int i=1; i<=N-1; i++){
        ans = max(ans, r2l[i]+r2l[i+N-1]);
        ans = max(ans, l2r[i]+l2r[i+N-1]);
    }
    cout << ans << endl;

}

