using namespace std;

typedef long long int LL;
typedef pair<LL, LL> PLL;


int main(int argc, char *argv[]) {
  LL N, C;
  cin >> N >> C;
  N+=2;
  vector<PLL> sushi(N);
  sushi[0].first = sushi[0].second = 0;
  sushi[1].first = C;
  sushi[1].second = 0;
  for (int i = 2; i < N; ++i) {
    cin >> sushi[i].first >> sushi[i].second;
  }
  sort(sushi.begin(), sushi.end());

  // Sum of all calories going counter-clockwise.
  vector<LL> acum_ccw(N);
  LL acum = 0;

  // Best result up to i if going ccw once.
  vector<LL> best_ccw(N);
  LL best = 0;

  // Best result up to i if going ccw and back.
  vector<LL> best_ccw_back(N);
  LL best_back = 0;

  for (int i = N - 1; i >= 0; i--) {
    acum += sushi[i].second;
    acum_ccw[i] = acum;
    LL cost = C - sushi[i].first;

    LL benefit = acum_ccw[i] - cost;
    LL benefit_back = acum_ccw[i] - 2 * cost;
    if (i == N - 1) {
      best = benefit;
      best_back = benefit_back;
      best_ccw[i] = best_ccw_back[i] = i;
      continue;
    }
    best_ccw[i] = best_ccw[i + 1];
    best_ccw_back[i] = best_ccw_back[i + 1];

    if (benefit > best) {
      best = benefit;
      best_ccw[i] = i;
    }

    if (benefit_back > best_back) {
      best_back = benefit_back;
      best_ccw_back[i] = i;
    }
  }

  best = 0;
  LL benefit_cw = 0;
  for (int i = 0; i < N-1; ++i) {
    LL walk_cw = sushi[i].first;
    benefit_cw += sushi[i].second;
    LL benefit_one_dir = benefit_cw - walk_cw;
    best = max(best, benefit_one_dir);


    LL pos_ccw = best_ccw[i + 1];
    LL walk_ccw = C - sushi[pos_ccw].first;
    LL benefit_ccw = acum_ccw[pos_ccw];
    LL benefit_two_dir = benefit_one_dir + benefit_ccw - walk_ccw - walk_cw;
    best = max(best, benefit_two_dir);

    LL pos_ccw_back = best_ccw_back[i + 1];
    LL walk_ccw_back = C - sushi[pos_ccw_back].first;
    LL benefit_ccw_back = acum_ccw[pos_ccw_back];
    LL benefit_two_dir_back = benefit_one_dir + benefit_ccw_back - 2*walk_ccw_back;
    best = max(best, benefit_two_dir_back);
  }

  cout << best << endl;
  return EXIT_SUCCESS;
}

