int main() {
  int N;
  ll C;
  cin >> N >> C;
  vector<ll> x(N, 0), v(N, 0);
  for (int i = 0; i < N; i++) {
    cin >> x[i] >> v[i];
  }

  // 累積和
  vector<ll> rwv(N + 1, 0);
  for (int i = 0; i < N; i++) {
    rwv[i + 1] = rwv[i] + v[i];
  }

  // 最大値
  vector<ll> r(N + 1, 0);
  for (int i = 0; i < N; i++) {
    r[i + 1] = max(r[i], rwv[i + 1] - x[i]);
  }
  vector<ll> l(N + 1, 0);
  for (int i = 0; i < N; i++) {
    l[i + 1] = max(l[i], rwv[N] - rwv[N - (i + 1)] - (C - x[N - (i + 1)]));
  }

  // cout << endl;
  // for (int i = 0; i <= N; i++) {
  //   cout << r[i] << " ";
  // }
  // cout << endl;
  // for (int i = 0; i <= N; i++) {
  //   cout << l[i] << " ";
  // }
  // cout << endl;
  // cout << endl;

  ll ans = 0;
  for (int i = 1; i <= N; i++) {
    ans = max(ans, rwv[i] - x[i - 1]);
    if (i < N) {
      ans = max(ans, rwv[i] - 2 * x[i - 1] + l[N - i]);
    }
  }

  for (int i = N - 1; i >= 0; i--) {
    ans = max(ans, rwv[N] - rwv[i] - (C - x[i]));
    if (i > 0) {
      ans = max(ans, rwv[N] - rwv[i] - 2 * (C - x[i]) + r[i - 1]);
    }
  }

  cout << ans << endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

int N = 0;
long long C = 0;
long long dist[100020] = {0};
int energy[100020] = {0};
long long table[100020][2] = {0};

void input() {
  cin >> N >> C;
  for (int i = 0; i < N; i++) {
    cin >> dist[i] >> energy[i];
  }
}

void output() {
  printf("%lld\n", table[N-1][1]);
}

void solve() {
  for (int i = 0; i < N; i++) {
    if (i == 0) table[i][0] = energy[i] - dist[i];
    else table[i][0] = table[i-1][0] + energy[i] - (dist[i]-dist[i-1]);
  }
  for (int i = 0; i < N; i++) {
    if (i == 0) table[i][1] = max((long long)0, table[i][0]);
    else table[i][1] = max(table[i-1][1], table[i][0]);
  }
}

int main() {
  input();
  solve();
  output();
  return 0;
}

