template <typename T>
class Combination {
 public:
  Combination(ll _max_n) : max_n(_max_n), factional(max_n + 1), inv(max_n + 1) {
    factional[0] = 1;
    inv[0] = 1;
    for (ll i = 0; i < max_n; i++) {
      factional[i + 1] = factional[i] * (i + 1); // n!(mod M)
      inv[i + 1] = inv[i] / (i + 1);             // k!^(M-2) (mod M)
    }
  }

  // nCk
  T choose(ll n, ll k) {
    if (n == 0 && k == 0)
      return 1;
    if (n < k || n < 0)
      return 0;
    T tmp = inv[n - k] * inv[k];
    return tmp * factional[n];
  }

 private:
  const ll max_n;
  std::vector<T> factional;
  std::vector<T> inv;
};

using Comb = Combination<mint>;

template <typename T>
class SegTree {
  int n;
  vector<T> data;
  T initial_value;
  function<T(T a, T b)> operation;
  function<T(T prev_val, T new_val)> _update;

  // [a,b)
  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return initial_value;
    }

    if (a <= l && r <= b) {
      return data[k];
    } else {
      T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
      T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
      return operation(vl, vr);
    }
  }

 public:
  SegTree(size_t _n, T _initial_value, function<T(T a, T b)> _operation,
          function<T(T prev_val, T new_val)> update_function)
    : initial_value(_initial_value), operation(_operation), _update(update_function) {
    n = 1;
    while (n < _n) {
      n <<= 1;
    }
    data = vector<T>(2 * n - 1, initial_value);
  }

  // update i-th value (0-indexed)
  void update(int i, T x) {
    i += n - 1;
    data[i] = _update(data[i], x);
    while (i > 0) {
      i = (i - 1) / 2;
      data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
    }
  }

  // execute query of section [a, b)
  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }

  // get i-th value
  T operator[](int i) {
    return data[i + n - 1];
  }
};

ll n, c;
vector<P> sushi;

ll solve() {
  SegTree<ll> st(
    n + 1, ll(0), [](ll a, ll b) { return max(a, b); }, [](ll prev_val, ll new_val) { return new_val; });

  vll memo(n + 1);

  ll pos = 0;
  rep(i, n) {
    memo[i + 1] = memo[i] + sushi[i].second - (sushi[i].first - pos);
    st.update(i + 1, memo[i + 1]);
    pos = sushi[i].first;
  }

  ll ans = st.query(0, n + 1);
  ll cal = 0;
  pos = c;
  for (ll i = n - 1; i >= 0; i--) {
    cal += -2 * abs(pos - sushi[i].first) + sushi[i].second;
    pos = sushi[i].first;
    ll v = cal + st.query(0, i + 1);
    chmax(ans, v);
  }

  return ans;
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);

  cin >> n >> c;

  sushi = vector<P>(n);
  rep(i, n) {
    cin >> sushi[i].first >> sushi[i].second;
  }

  ll ans = solve();

  rep(i, n) {
    sushi[i].first = (c - sushi[i].first) % c;
  }
  sort(all(sushi));

  chmax(ans, solve());
  cout << ans << endl;

  return 0;
}

