ll res = 0;

ll mymax(ll a, ll b)
{
  if (a > b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

ll mymin(ll a, ll b)
{
  if (a < b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

int main()
{
  cin >> N >> C;
  v = vector<ll>(N);
  x = vector<ll>(N);
  l = vector<ll>(N);
  r = vector<ll>(N);
  for (int i = 0; i < N; i++)
  {
    cin >> x[i] >> v[i];
  }
  for (int i = 0; i < N; i++)
  {
    r[i] = (i == 0 ? 0 : r[i - 1]) + v[i] - (x[i] - (i == 0 ? 0 : x[i - 1]));
  }
  for (int i = N - 1; i >= 0; i--)
  {
    l[i] = (i == N - 1 ? 0 : l[i + 1]) + v[i] - ((i == N - 1 ? C : x[i + 1]) - x[i]);
  }
  //iで方向転換
  for (int i = 0; i < N; i++)
  {
    ll temp = 0;
    temp += r[i];
    res = mymax(res, temp);

    for (int j = N - 1; j > i; j--)
    {
      res = mymax(res, temp + l[j] - mymin(x[i], (C - x[j])));
    }
  }

  cout << res << endl;
  return 0;
}

