typedef struct {
	long long int x;
	long long int v;
} xv;

void printSeqInv(int *, int);
void countUpBinary(int *, int);

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	long long int N, C;
	vector<xv> input;

	cin >> N >> C;

	int flags[N+1];
	input.resize(N+1);

	input[0].x = input[0].v = 0;
	for (int i = 1; i <= N; i++) {
		cin >> input[i].x >> input[i].v;
	}

	for (int i = 0; i <= N; i++) {
		flags[i] = 0;
	}


	long long int max = 0;
	for (long long int n = 0; n < pow(2, N); n++) {
		long long int totalLost = 0;
		long long int totalGain = 0;
		int pos = 0;
		int l, r;
		long long int disL, disR;

		//printSeqInv(flags, N);

		l = 1;
		r = N;
		while (l < r) {
			while (flags[l] == 0 and l <= N) l++;
			while (flags[r] == 0 and r > 0) r--;

			if (l >= r and flags[l] == 0) {
				//cout << "break" << endl;
				break;
			}

			if (l == N+1 or r == 0) {
				//cout << "break" << endl;
				break;
			}

			disL = abs(input[l].x - input[pos].x);
			disR = abs(input[r].x - input[pos].x);
			if (disL > (C - disL)) disL = C - disL;
			if (disR > (C - disR)) disR = C - disR;
			if (disL < disR) {
				totalLost += disL;
				totalGain += input[l].v;
				pos = l;
				l++;
			} else {
				totalLost += disR;
				totalGain += input[r].v;
				pos = r;
				r--;
			}
			//cout << "l : " << l << ", r: " << r << endl;
		}

		if (l == r and flags[l] == 1) {
			disR = abs(input[r].x - input[pos].x);
			if (disR > (C - disR)) {
				disR = C - disR;
			}

			totalLost += disR;
			totalGain += input[r].v;
		}


		long long int total = totalGain - totalLost;
		if (max < total) {
			max = total;
		}

		countUpBinary(flags, N);
		//cout << "max: " << max << ", total: " << total << endl;
	}

	cout << max << endl;

	return 0;
}

void printSeqInv(int *array, int N) {
	for (int i = N; i > 0; i--) {
		cout << array[i] << flush;
	}
	cout << endl;
}

void countUpBinary(int *flags, int N) {
	int i;

	for (i = 1; i <= N and flags[i] != 0; i++) {
		flags[i] = 0;
	}

	if (i != N+1) {
		flags[i] = 1;
	}
}

