long long f(int n, long long c, vector<long long>& xs, vector<long long>& vs){
    vector<long long> cost1(n+1);
    long long acc=0;
    for(int i=0; i<n; ++i){
        acc+=vs[i];
        cost1[i+1]=acc-xs[i];
    }
    vector<long long> cost2(n+1);
    acc=0;
    for(int i=n-1; i>=0; --i){
        acc+=vs[i];
        cost2[i+1]=max(cost2[(i+2)%(n+1)], acc-(c-xs[i])*2);
    }
    long long ans=0;
    for(int i=1; i<=n; ++i){
        ans=max(ans, cost1[i]+cost2[(i+1)%(n+1)]);
    }
    return ans;
}

int main(){
    int n; cin >> n;
    long long c; cin >> c;
    vector<long long> xs(n), vs(n);
    for(int i=0; i<n; ++i){
        cin >> xs[i] >> vs[i];
    }
    long long ans=f(n, c, xs, vs);
    reverse(xs.begin(), xs.end());
    for(int i=0; i<n; ++i){
        xs[i]=c-xs[i];
    }
    reverse(vs.begin(), vs.end());
    ans=max(ans, f(n, c, xs, vs));
    cout << ans << endl;
    return 0;
}

