		sumLR[i] = sumLR[i - 1] + x1[i].second - 2 * d1;
		sumR[i] = sumR[i - 1] + x2[i].second - d2;
		sumRL[i] = sumRL[i - 1] + x2[i].second - 2 * d2;
	}

	cout << max(solve(sumL, sumRL, N), solve(sumR, sumLR, N)) << endl;

	return 0;
}

