static const ll MAX_N = 200000;
ll par[MAX_N];
ll ran[MAX_N];

void init(ll n) {
	rep(i, 0, n) {
		par[i] = i;
		ran[i] = 0;
	}
}

ll find(ll x) {
	if (par[x] == x)  return x;
	else return par[x] = find(par[x]);
}

void unite(ll x, ll y) {
	x = find(x);
	y = find(y);
	if (x == y) return;

	if (ran[x] < ran[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (ran[x] == ran[y]) ran[x]++;
	}
}
bool same(ll x, ll y) {
	return find(x) == find(y);
}

