        v_sum_right[i] = v_sum_right[i - 1] + v[i];
    }

    v_sum_left[N] = 0;
    for (i = N - 1; i >= 0; i--) {
        v_sum_left[i] = v_sum_left[i + 1] + v[i];
    }


    // g計算
    g[0][0] = 0;
    g[0][1] = 0;
    for (i = 1; i <= N; i++) {
        g[i][0] = max(g[i - 1][0], v_sum_right[i - 1] - x[i - 1]);
        if (g[i - 1][0] == g[i][0]) {
            g[i][1] = g[i - 1][1];
        }
        else {
            g[i][1] = x[i - 1];
        }
    }

    // 探査
    ans = v_sum_left[0] - C + x[0];
    for (i = 1; i < N; i++) {
        t = v_sum_left[i] - C + x[i];
        ans = max(ans, t);
        ans = max(ans, t + g[i][0] - C + x[i]);
        ans = max(ans, t + g[i][0] - g[i][1]);
    }
    ans = max(ans, g[N][0]);


