  }

  vector<ll> acl(N + 2);
  temp = 0;
  repr(i, N + 1, 1) {
    temp += v[i];
    acl[i] = temp - (C - x[i]);
  }

  vector<int> clmaxind(N + 2);
  temp = -1;
  repp(i, 0, N) {
    if (chmax(temp, cl[i]))
      clmaxind[i] = i;
    else
      clmaxind[i] = clmaxind[i - 1];
  }

  ll ans = 0;
  repr(i, N + 1, 1) {
    int j = clmaxind[i - 1];
    ll temp = acl[i] + cl[j];
    temp -= min(x[j], (C - x[i]));
    chmax(ans, temp);
  }
  cout << ans << endl;
}

