ll n, c;
const int N = 1e5+5;
ll a[N], b[N], v[N], type1[N], type2[N];

void solve()
{
       cin>>n>>c;
       rep(i, 1, n+1)
       {
              cin>>a[i]>>v[i];
              b[i] = c - a[i];
       }
       // a[i] - distance in clockwise from O, b[i] - dis in anti clock from O
       // type 1: 2*OA + OB
       // fix one x_a, then search for best x_b => can only be x_b + 1, x_b + 2, ...., x_b + n, O
       // in anti clock best up to all x_i calculate
       ll sum = 0;
       for(ll i = n; i > 0; i--)
       {
              type1[i] = type1[i+1];
              sum += v[i];
              if(sum - b[i] > type1[i]) type1[i] = sum - b[i];
       }
       // type1: for anticlockwise move
       //for(ll i=1; i<=n; i++) cout<<"type1["<<i<<"] : "<<type1[i]<<" \n";
       //cout<<endl;
       ll mx = 0;
       sum = 0;
       for(ll i=1; i < n; i++)
       {
              sum += v[i];
              ll x = sum - 2*a[i] + type1[i+1];
              ll y = sum - a[i];
              x = max(x, y);
              mx = max(mx, x);
       }
       mx = max(mx, sum + v[n] - a[n]);
       sum=0;
       type2[0] = 0;
       for(ll i = 1; i <= n; i++)
       {
              type2[i] = type2[i-1];
              sum += v[i];
              if(sum - a[i] > type2[i]) type2[i] = sum - a[i];
       }
       sum = 0;
       for(ll i = n; i > 1; i--)
       {
              sum += v[i];
              ll x = sum - 2*b[i] + type2[i-1];
              ll y = sum - b[i];
              x = max(x, y);
              mx = max(mx, x);
       }
       mx = max(mx, sum + v[1] - b[1]);
       cout<<mx<<endl;
}


int main()
{
       speed_up;
       ll T=1;
       //cin>>T;
       while(T--) solve();
	return 0;
}

