int main(){
  ll n, c; cin >> n >> c;
  //xr[i] =  原点から右へ歩き，i個取ったときに移動した距離
  //xl[i] =  原点から左へ歩き，i個取ったときに移動した距離
  //vsum[i] = v[1] + ... + v[i]
  //vr[i] =  vsum[i] - xr[i] 原点から右へ歩きi個とったときの実質スコア
  //vl[i] =  vsum[n]-vsum[n-i]-xl[i] 原点から左へ歩きi個とったときの実質スコア
  vector<ll> xr(n+2,0), xl(n+2,0), vsum(n+1,0), vr(n+2,0), vl(n+2,0);
  xr[n+1] = c; xl[n+1] = c; 
  REP(i,n) {
    ll v; cin >> xr[i+1] >> v;
    vsum[i+1] = vsum[i] + v;
    vr[i+1] = vsum[i+1] - xr[i+1];
  }
  REP(i,n){
    xl[i+1] = c - xr[n-i];
    vl[i+1] = vsum[n]-vsum[n-i-1]-xl[i+1];
  }
  ll ans = 0;
  ll vlmax = 0, vrmax = 0;//左からl個とる条件下で原点から右へ行く場合の実質スコアのmax（左で往復する場合，右で往復する場合）
  IREP(l,n+1){
    ll e = 0;
    //左からl個とる
    e += vl[l];
    // i) 左で往復する場合
    e -= xl[l];
    // 右からとる
    e += vlmax;
    ans = max(ans,e);
    // vlmax更新
    ll idx = n-l+1;
    vlmax = max(vlmax,vr[idx]);
    // ii) 右で往復する場合
    //左からとる
    e = vl[l];
    //右からとる
    e += vrmax;
    ans = max(ans,e);
    //vrmax更新
    vrmax = max(vrmax,vr[idx]-xr[idx]);
  } 
  cout << ans << endl;
}

