  }
  loop(i,1,n+1) {
    ans = max(ans, acc[n] - acc[n-i] - (c - A[n-i].x)); // 左にi個とる時の最大価値.
  }

  // 3) 右にi個とり、Oに戻って最大でn-i個とる時の最大値 O(N)
  // 左側: 事前計算
  vector<ll> maxL(n+1, 0); // 右にiまで取った時の左の最大価値.
  for (int i=n-1; i>=1; i--) { // 右に1個もとらない or 全部取るのは考慮不要.
    int j = n-i; // 残り数
    ll left = acc[n] - acc[n-j] - (c - A[n-j].x);
    maxL[i] = max(maxL[i+1], left);
  }

  // 右側: 全探索
  loop(i,1,n) { // 1個からn-1まで. 0個の場合は左からしか取らない、nの場合は右からしか取らないので.
    ll right = acc[i] - 2 * A[i-1].x; // 往復コスト
    ll left = maxL[i];
    ans = max(ans, right+left);
  }

  // 4) 左にi個とり、Oに戻って最大でn-i個とる時の最大値O(N^2)
  vector<ll> maxR(n+1, 0); // 左にiまで取った時の右の最大価値.
  for (int i=n-1; i>=1; i--) {
    int j = n-i;
    ll right = acc[j] - A[j-1].x;
    maxR[i] = max(maxR[i+1], right);
  }

  loop(i,1,n) {
    ll left = acc[n] - acc[n-i] - 2 * (c - A[n-i].x); // 往復コスト
    ll right = maxR[i];
    ans = max(ans, left+right);
  }
  print(ans);
  return 0;
}

