  for(int i=0; i<N; i++){
    for(int j=0; j<2; j++){
      cin >> A.at(i).at(j);
    }
    B.at(i).at(0) = A.at(i).at(0);
    B.at(i).at(1) = A.at(i).at(1);
  }

  int64_t A_pos = 0;
  int64_t A_MAX = 0;
  int64_t B_pos = 0;
  int64_t B_MAX = 0;

  vector<int64_t> A_sum(N,0);
  vector<int64_t> B_sum(N,0);
  vector<int64_t> A_good(N,0);
  vector<int64_t> B_good(N,0);


  for(int i=0; i<N; i++){
    if(i == 0){
      A_sum.at(i) = A.at(i).at(1);
    }
    else{
      A_sum.at(i) = A_sum.at(i-1) + A.at(i).at(1);
    }
    if(A_sum.at(i) - A.at(i).at(0) >= A_MAX){
      A_pos = i;
      A_MAX = A_sum.at(i) - A.at(i).at(0);
    }
    A_good.at(i) = A_MAX;
  }
  for(int i=N-1; i>=0; i--){
    if(i == N-1){
      B_sum.at(i) = B.at(i).at(1);
    }
    else{
      B_sum.at(i) = B_sum.at(i+1) + B.at(i).at(1);
    }
    if(B_sum.at(i)  - (C - B.at(i).at(0)) >= B_MAX){
      B_pos = i;
      B_MAX = B_sum.at(i) - (C - B.at(i).at(0));
    }
    B_good.at(i) = B_MAX;
  }


  int64_t ans = max(A_MAX, B_MAX);
  for(int i=0; i<A_pos; i++){
