		cin >> x[i] >> v[i];
	}

	MAXA[0] = v[0] - x[0];
	llong masa = v[0];

	for (int i = 1; i < N; i++) {
		masa += v[i];
		MAXA[i] = max(masa - x[i], MAXA[i - 1]);
	}

	MAXB[N - 1] = v[N - 1] - C + x[N - 1];
	llong masb = v[N - 1];

	for (int i = N - 2; i >= 0; i--) {
		masb += v[i];
		MAXB[i] = max(masb - C + x[i], MAXB[i + 1]);
