int main()
{
    int64_t N, C;
    std::cin >> N >> C;

    struct S {
        int64_t x;
        int64_t v;
    };

    std::vector<S> sr;
    for (size_t i = 0; i < N; ++i) {
        S s;
        std::cin >> s.x >> s.v;
        sr.push_back(s);
    }

    auto sl = sr;

    std::sort(std::begin(sr), std::end(sr),
              [](const auto& a, const auto& b) {
                  return a.x < b.x;
              });

    std::sort(std::begin(sl), std::end(sl),
              [](const auto& a, const auto& b) {
                  return a.x > b.x;
              });


    std::vector<int64_t> rmax, lmax;
    rmax.push_back(0);
    lmax.push_back(0);
    {
        int64_t rm, lm, re, le, rpos, lpos;
        rm = lm = re = le = rpos = 0;
        lpos = C;

        for (size_t i = 0; i < N; ++i) {
            re = re + sr[i].v - (sr[i].x - rpos);
            rm = std::max(rm, re);
            rmax.push_back(rm);
            rpos = sr[i].x;

            le = le + sl[i].v - (lpos - sl[i].x);
            lm = std::max(lm, le);
            lmax.push_back(lm);
            lpos = sl[i].x;
        }
    }

    int64_t rlmax, lrmax;
    {
        int64_t re, le, rpos, lpos;
        rlmax = lrmax = re = le = rpos = 0;
        lpos = C;

        for (size_t i = 0; i < N; ++i) {
            re = re + sr[i].v - (sr[i].x - rpos);
            rlmax = std::max(rlmax, re + lmax[N-i-1] - sr[i].x);
            rpos = sr[i].x;

            le = le + sl[i].v - (lpos - sl[i].x);
            lrmax = std::max(lrmax, le + rmax[N-i-1] - (C - sl[i].x));
            lpos = sl[i].x;
        }
    }

    std::cout
        << std::max(
                   {*std::max_element(rmax.begin(), rmax.end()),
                    *std::max_element(lmax.begin(), lmax.end()),
                    lrmax,
                    rlmax})
        << std::endl;

    return 0;
}

