        cin >> x[i] >> v[i];
    }
    for(int i=1;i<=n;i++){
        fwd[i] = v[i] - x[i] + x[i-1] + fwd[i-1];
        goo[i] = max(fwd[i], goo[i-1]);
    }
    x[n+1] = c;
    for(int i=n;i>=1;i--){
        rev[i] = v[i] - x[i+1] + x[i] + rev[i+1];
