int main() {
    int n, c;
    cin >> n >> c;
    vector<ll> x(n), v(n);
    rep(i, n) cin >> x[i] >> v[i];

    vector<ll> dp1(n, 0), dp2(n, 0);
    dp1[0] = v[0] - x[0];
    for (int i=1; i<n; ++i) dp1[i] = dp1[i-1]+v[i]-(x[i]-x[i-1]);
    for (int i=1; i<n; ++i) dp1[i] = max(dp1[i], dp1[i-1]);

    dp2[n-1] = v[n-1] - (c - x[n-1]);
    for (int i=n-2; i>=0; --i) dp2[i] = dp2[i+1]+v[i]-(x[i+1]-x[i]);
    for (int i=n-2; i>=0; --i) dp2[i] = max(dp2[i], dp2[i+1]);

    int ans = max(0LL, dp2[0]);
    rep(i, n) {
        int tmp = dp1[i];
        if (i+1<n and dp2[i+1]-x[i]>0) tmp += dp2[i+1] - x[i];
        ans = max(ans, tmp);
    }
    for (int i=n-1; i>=0; --i) {
        int tmp = dp2[i];
        if (i >= 1 and dp1[i-1] - (c - x[i]) > 0) tmp += dp1[i-1] - (c - x[i]);
        ans = max(ans, tmp);
    }
    cout << ans << endl;
}

