const ll MAX_N = (int)1e5 + 5;

struct dist_cal {ll dist, cal;};

ll n, c;
vector<dist_cal> xv;
vector<dist_cal> xv_rev;

ll ans;

ll solve(vector<dist_cal> dsv) {
  /****************************************************/
  ll score_a[MAX_N];
  ll score_b[MAX_N];
  ll score_g[MAX_N];

  ll tmp_a = 0;
  for (int i = 0; i < dsv.size(); ++i) {
    tmp_a += dsv[i].cal;
    score_a[i] = tmp_a - dsv[i].dist;
  }

  ll tmp_b = 0;
  for (int i = n - 1; i >= 0; --i) {
    tmp_b += dsv[i].cal;
    score_b[i] = tmp_b - (c - dsv[i].dist);
  }

  ll tmp_max = -1;
  score_g[0] = 0;
  for (int i = 1; i < dsv.size(); ++i) {
    score_g[i] = max(score_g[i - 1], score_a[i - 1]);
  }

  ll last_max = score_g[n - 1];
  for (int i = n - 1; i >= 0; --i) {
    ll cur_score = score_b[i] - (c - dsv[i].dist) + score_g[i];
    last_max = max(last_max, cur_score);
  }
  /****************************************************/

  return last_max;
}

