    xv_rev.push_back(tmp);
  }

  sort(xv.begin(), xv.end(), [](dist_cal a, dist_cal b) { return a.dist < b.dist; });
  sort(xv_rev.begin(), xv_rev.end(), [](dist_cal a, dist_cal b) { return a.dist < b.dist; });

  ans = max(solve(xv), solve(xv_rev));
