typedef long long lint;
int ab(int x) { return (x < 0 ? -x : x); }
int gr(int x) { return (x < 0 ? 0 : x); }
const int maxn = 1e5+5;

int n, i;
lint m, ans;

struct xy {
    lint x, y;
};

xy v[maxn];
lint d[maxn];

// id, how many were eaten, direction, calories
void dfs(int id, int et, int dr, lint cal)
{
    d[id] = cal;
    if(cal > ans) { ans = cal; }
    if(et == n) { return; }

    if(et == 0) {
        dfs(1, 1, 1, v[1].y - v[1].x);
        dfs(n, 1, 0, v[n].y - (m - v[n].x));
        return;
    }
    int nxt = 0;
    if(dr == 1) { // right
        nxt = id + 1; if(nxt > n) {
            nxt -= n;
            if(d[nxt] <= cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)) { dfs(nxt, et + 1, 1, cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)); }
        } else
        if(d[nxt] <= cal + v[nxt].y - ab(v[id].x - v[nxt].x)) {
            dfs(nxt, et + 1, 1, cal + v[nxt].y - ab(v[id].x - v[nxt].x));
        }
        nxt = id - et; if(nxt < 1)
        {
            nxt += n;
            if(d[nxt] <= cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)) { dfs(nxt, et + 1, 0, cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)); }
        } else
        if(d[nxt] <= cal + v[nxt].y - ab(v[id].x - v[nxt].x)) {
            dfs(nxt, et + 1, 0, cal + v[nxt].y - ab(v[id].x - v[nxt].x));
        }
    } else { // left
        nxt = id - 1; if(nxt < 1) {
            nxt += n;
            if(d[nxt] <= cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)) { dfs(nxt, et + 1, 0, cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)); }
        } else
        if(d[nxt] <= cal + v[nxt].y - ab(v[id].x - v[nxt].x)) {
            dfs(nxt, et + 1, 0, cal + v[nxt].y - ab(v[id].x - v[nxt].x));
        }
        nxt = id + et; if(nxt > n) {
            nxt -= n;
            if(d[nxt] <= cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)) { dfs(nxt, et + 1, 1, cal + v[nxt].y - m+ab(v[id].x - v[nxt].x)); }
        } else
        if(d[nxt] <= cal + v[nxt].y - ab(v[id].x - v[nxt].x)) {
            dfs(nxt, et + 1, 1, cal + v[nxt].y - ab(v[id].x - v[nxt].x));
        }
    }
}

