#define N 100000

int n;
long long c;
long long  x[N];
int v[N];

long long rsum[N+1];
long long lsum[N+1];

int main()
{
	long long ans = 0;

	cin >> n >> c;
	for( int i = 0; i < n; i++ ) {
		cin >> x[i] >> v[i];
	}

	rsum[0] = 0;
	lsum[0] = 0;
	long long vr = 0;
	long long vl = 0;
	for( int i = 0; i < n; i++ ) {
		vr += v[i];
		rsum[i + 1] = max(rsum[i], vr - x[i]);
		vl += v[n - (i + 1)];
		lsum[i + 1] = max(lsum[i], vl - (c - x[n - (i + 1)]));
	}

	for( int i = 0; i < n + 1; i++ ) {
		long long sum = rsum[i] + lsum[n - i];
		long long turn = x[i - 1];
		if( i == 0 ) {
			turn = 0;
		}
		long long rans = sum - turn;
		turn = c - x[i];
		if( i == n ) {
			turn = 0;
		}
		long long lans = sum - turn;
		ans = max(ans, max(rans, lans));
	}

	cout << ans << endl;

	return 0;
}

