int main(){
	int N; 
	long long int C; 
	cin >> N >> C; 
	long long int X[100010] = {}; 
	long long int V[100010] = {};
	long long int W[100010] = {}; //カロリーの累積和 
	long long int R[100010] = {}; //時計回りにi番まで進んだときの得の最大値
	long long int L[100010] = {}; //反時計回りにi番まで進んだときの得の最大値
	for(int i = 1; i <= N; i++){
		cin >> X[i] >> V[i]; 
		W[i] = W[i-1] + V[i]; 
	}
	X[N+1] = C; //便宜上そうしておく．
	for(int i = 1; i <= N; i++){
		R[i] = max(R[i-1], W[i] - X[i]); 
	}
	for(int i = N; i >= 1; i--){
		L[i] = max(L[i+1], (W[N] - W[i-1]) - (C - X[i])); 
	}
	long long int ans = 0; 
	for(int i = 0; i <= N; i++){//まず時計回りにi番まで行って反時計回りに最適化
		long long int sesshu = W[i] - X[i] * 2 + L[i+1]; 
		ans = max(ans, sesshu); 
	}
	for(int i = 1; i <= N+1; i++){//まず反時計回りにi番まで行って時計回りに最適化
		long long int sesshu = W[N] - W[i-1] - (C - X[i]) * 2 + R[i-1]; 
		ans = max(ans, sesshu); 
	}
	cout << ans << endl;
}

