typedef pair<int, ll> P;
typedef pair<ll, ll> pll;
int n;
ll c;
vector<P> toleft, toright;
vll val;
vll pos;

void init()
{
	cin >> n >> c;

	val.resize(n + 1, 0);
	pos.resize(n + 1, 0);
	REP1C(i, n) { cin >> pos[i] >> val[i]; }

	toleft.resize(n + 1);
	toright.resize(n + 1);
	toright[0] = toleft[0] = P(0, 0);
}


int main()
{
	init();
	ll best, tmp, lastpos;

	best = tmp = lastpos = 0LL;
	REP1C(i, n)
	{
		tmp += val[i] - pos[i] + lastpos;
		lastpos = pos[i];

		if (chmax(best, tmp))
			toright[i] = P(i, best);
		else
			toright[i] = toright[i - 1];
	}

	best = tmp = 0; lastpos = c;
	for (int i = n; i >= 1; --i)
	{
		tmp += val[i] + pos[i] - lastpos;
		lastpos = pos[i];

		if (chmax(best, tmp))
			toleft[i] = P(i, best);
		else
		{
			if (i == n)
				toleft[i] = P(0, 0);
			else
				toleft[i] = toleft[i + 1];
		}
