vector<pair<long long int, long long int> > P, Q;
vector<long long int> x, v;

long long int CLM[100005],CRM[100005];

int main(void) {

	cin >> N >> C;

	x.push_back(0); v.push_back(0);

	long long int tmp;
	for (int i = 1; i <= N; i++) {
		cin >> tmp; x.push_back(tmp);
		cin >> tmp; v.push_back(tmp);
	}

	//===== P ====================
	for (int i = 0; i <= N; i++) {
		P.push_back(pair<long long int, long long int>(x[i], v[i]));
	}
	sort(P.begin(), P.end());

	//====== Q ======================
	Q.push_back(pair<long long int, long long int >(0, 0));
	for (int i = 1; i <= N; i++) {
		Q.push_back(pair<long long int, long long int>(C - P[i].first, P[i].second));
	}
	sort(Q.begin(), Q.end());

	//=============================

	long long int sum = 0; CLM[0] = 0; 
	long long int tmp_max=0;
	for (int i = 1; i <= N; i++) {
		sum += Q[i].second;      tmp_max = max(tmp_max, sum - 2 * Q[i].first); CLM[i] = tmp_max;
	}
	//====================
	sum = 0; CRM[0] = 0; tmp_max = 0;
	for (int i = 1; i <= N; i++) {
		sum += P[i].second;  tmp_max = max(tmp_max, sum - 2 * P[i].first); CRM[i] = tmp_max; /*cout << "tmp_max= " << tmp_max << endl;*/
	}


	//======= R rotation
	long long int ans = 0; sum = 0;
	for (int i = 1; i <= N; i++) {
		sum += P[i].second;   ans = max(ans, sum - P[i].first + CLM[N - i]);
	}
	//===== L rotation
	sum = 0;
	for (int i = 1; i <= N; i++) {
		sum += Q[i].second; ans = max(ans, sum - Q[i].first + CRM[N - i]);
	}


	cout << ans << endl;


	//system("pause");
	return 0;
}

