int main() {
  int n;
  long long int c;
  long long int nakabashi = 0;
  int value = 0;
  std::cin >> n >> c;
  sushi S[int(1e5)+10];
  bool visited[int(1e5)+10];
  for(int i=0; i<n; ++i) {
    std::cin >> S[i].x >> S[i].v;
    visited[i] = false;
  }


  while(true) {
    long long int minipoint = c;
    int maxvalue = -1;
    int maxindex = -1;
    bool close = true;
    int maxpoint = -1;

    // 行ける場所を探す
    for(int i=0; i<n; ++i) {
      long long int calory = std::min(std::abs(nakabashi - S[i].x), std::abs((c+nakabashi) - S[i].x));
      if(S[i].v > calory && minipoint > calory && !visited[i]) {
        maxvalue = S[i].v - calory;
        maxpoint = S[i].x;
        maxindex = i;
        minipoint = calory;
        close = false;
      }
    }

    if(close) {
      break;
    } else {
      nakabashi = maxpoint;
      value += maxvalue;
      visited[maxindex] = true;
    }
  }

  std::cout << value << std::endl;
}

