    ll tmp=0;
    rep(i,n){
        if(i==0){
            tmp+=v[i];
            sv[i]=max(tmp-x[i],(ll)0);
            sx[i]=(sv[i]==tmp-x[i])? x[i]:0;
        }
        else{
            tmp+=v[i];
            sv[i]=max(sv[i-1],tmp-x[i]);
            sx[i]=(sv[i]==tmp-x[i])? x[i]:sx[i-1];
        }
    }
