    reverse(v.begin(),v.end());
    tmp=0;

    rep(i,n){
        x[i]=c-x[i];
        if(i==0){
            tmp+=v[i];
            isv[i]=max(tmp-x[i],(ll)0);
            isx[i]=(isv[i]==tmp-x[i])? x[i]:0;
        }
        else{
            tmp+=v[i];
            isv[i]=max(isv[i-1],tmp-x[i]);
            isx[i]=(isv[i]==tmp-x[i])? x[i]:isx[i-1];
        }
    }


    reverse(isv.begin(),isv.end());
    reverse(isx.begin(),isx.end());
    ll res=0;

    rep(i,n){
        //cout<<i<<endl;
        if(i==n-1){
            ll now=sv[i];
            res=max(res,now);
        }
        else{
            ll left=sv[i],right=isv[i+1];
            //cout<<left<<" "<<right<<endl;
            ll now=right+left;
            now-=min(sx[i],isx[i+1]);
            res=max(res,now);
        }
        if(i==0){
