	vector<ll> x(n), v(n);
	for(int i = 0; i < n; i++) {
		cin >> x[i] >> v[i];
	}	

	ll ans = 0;

	vector<ll> mxsuf(n);
	ll suf = v[n - 1] - (c - x[n - 1]), mx = v[n - 1] - (c - x[n - 1]);
	ans = max(ans, suf);
	mxsuf[n - 1] = v[n - 1] - (c - x[n - 1]);
