	for(int i = 0; i < n; i++) {
		if(!i) pre += v[i] - x[i];
		else pre += v[i] - x[i] + x[i - 1];

		ans = max(ans, pre);
		if(i != n - 1) ans = max(ans, pre - x[i] + mxsuf[i + 1]);
	}

	cout << ans << endl;
}

