		v.push_back(make_pair(a, b));
	}
	long long sum = 0;
	long long last_pos = 0;
	long long maxx1 = 0, maxx2 = 0, maxx3 = 0, maxx4 = 0;
	for (int i = 0; i < n; ++i) {
		sum += v[i].second - (v[i].first - last_pos);
		dp1[i] = sum;
		last_pos = v[i].first;
		dp3[i] = dp1[i] - v[i].first;
		maxx1 = max(maxx1, dp1[i]);
		maxx3 = max(maxx3, dp3[i]);
		max1[i] = maxx1;
		max3[i] = maxx3;
	}
 	sum = 0;
	last_pos = c;
	long long ans = 0;
	for (int i = n - 1; i >= 0; --i) {
		sum += v[i].second - (last_pos - v[i].first);
		dp2[i] = sum;
		last_pos = v[i].first;
		dp4[i] = dp2[i] - (c - v[i].first);
		maxx2 = max(maxx2, dp2[i]);
