    ls[i] = ls[i - 1] + vs[i];
    rs[i] = rs[i - 1] + vs[N - i + 1];
  }

  FOR(i, 1, N + 1) {
    ll g = gs[i - 1];
    ll dist = C - xs[N - i + 1];
    ll cal = rs[i] - dist;
    if (g >= cal) {
      gs[i] = g;
      g_dist[i] = g_dist[i - 1];
    } else {
      gs[i] = cal;
      g_dist[i] = dist;
    }
