void solve(vector<ll> &x, vector<ll> &v){
    vector<ll> M(N, 0);
    ll ma = 0;
    ll V = 0;
    REP(i, N){
        V += v[i];
        chmax(ma, V-x[i]);
        M[i] = ma;
