	smx1[i] = max(sm1[i], smx1[i - 1]);
	sm2[i] = sm2[i - 1] + v[n - i + 1] - (x[n - i + 2] - x[n - i + 1]);
	smx2[i] = max(sm2[i], smx2[i - 1]);
  }

  FOR(i, 1, n + 1) {
	ans = max(ans, sm1[i]);
	ans = max(ans, sm2[i]);
	ans = max(ans, sm1[i] + smx2[n - i] - x[i]);
	ans = max(ans, sm2[i] + smx1[n - i] - (c - x[n - i + 1]));
  }
  cout << ans << endl;

  return 0;
}

