    // 最大スコアの算出
    for(ll i=0; i<n; i++){
        // 一方向に地点iまで進んで脱出する場合
        chmax(ans, max(lsMax[i], rsMax[i]));
        // 地点iまで進んで逆方向に進む
        if(i != n-1){
            chmax(ans, lss[i]+rsMax[n-i-2]);
            chmax(ans, rss[i]+lsMax[n-i-2]);
        }
    }

    cout << ans << endl;
    return 0;
}

