struct data_t {
    long long int dist;
    int cost;
};

vector<data_t> data_array;
long long int C;
long long int calc(int fi, int bi, long long int c);

int main(void) {

	int N;
	cin >> N >> C;

	for(int i=0; i<N; i++) {
		data_t d;
		cin >> d.dist >> d.cost;
		data_array.push_back(d);
	}

	cout << calc(0, N-1, 0);

	return 0;
}

long long int calc(int fi, int bi, long long int c) {

	long long int d1, d2;
	if(data_array[fi].dist < c) {
		d1 = abs(C - c) + data_array[fi].dist;
	} else {
		d1 = abs(data_array[fi].dist - c);
	}
	if(data_array[bi].dist > c) {
		d2 = abs(C - data_array[bi].dist) + c;
	} else {
		d2 = abs(data_array[bi].dist - c);
	}
	if(fi == bi) {
		return max((long long int)0, data_array[fi].cost - min(d1, d2));
	} else {
		long long int costFi = data_array[fi].cost - d1;
		long long int costBi = data_array[bi].cost - d2;
		long long int calcFi = calc(fi+1, bi, data_array[fi].dist);
		long long int calcBi = calc(fi, bi-1, data_array[bi].dist);

		return max(max(costFi, costBi), max(costFi + calcFi, costBi + calcBi));
	}
}

