ll calc(vector<ll> &x, vector<ll> &v) {
  x[n + 1] = c;
  vector<ll> v_sum(n + 1);
  for (int i = 1; i <= n; ++i) {
    v_sum[i] = v_sum[i - 1] + v[i];
  }
  vector<ll> f(n + 1), g(n + 1);
  for (int i = 1; i <= n; ++i) {
    f[i] = v_sum[i] - x[i];
    g[i] = max(g[i - 1], f[i]);
  }
  ll res = 0;
  for (int i = n + 1; i >= 1; --i) {
    ll oa = g[i - 1];
    ll ob = v_sum[n] - v_sum[i - 1] - 2 * (c - x[i]);
    res = max(res, oa + ob);
  }
  return res;
}

