        right[i+1]=right[i]+(v[i]-x[i]);
        if(i!=0) right[i+1] += x[i-1];
        cerr<<right[i]<<" ";
    }
    cerr<<endl;
    for(int i=0;i<=n;i++){
        left[i+1]=left[i]+(v[n-i-1]-(c-x[n-i-1]));
        if(i!=0) left[i+1] += (c-x[n-i]);
        cerr<<left[i]<<" ";
    }
    cerr<<endl;
    ll ans = 0;
    for(int i=0;i<=n;i++){
        for(int l=0;l<=i;l++){
            // r = i-l; たべる
            ll t = left[l]+right[i-l];
            // 左右どちらかは往復するので距離分を余計に引く必要がある
            if(l!=0 && l!=i){
                t = t-min(x[i-l-1], c-x[n-l-1]);
            }
            ans = max(ans, t);
        }
    }
    cout<<ans<<endl;
}

