    for (long long  i = 0; i < N; i++) {
        cin >> x[i] >> v[i];
    }

    // 動的計画法で考える.
    vector<vector<long long> > dp(N+1,vector<long long>(C+1) );
    // ここでのdpは, 摂取カロリーのことである.

    for (long long i = 0; i <= N; i++) {
        for (long long j = 0; j <= C; j++) {
            dp[i][j] = 0;
        }
    }
    // iはi番目, jは直近でどこで食べたか.
    dp[0][0]    = 0;
    int xx = ((C - x[0]) >= (x[0])) ? x[0] : (C - x[0]);
    dp[0][x[0]] = v[0] - xx;
    long long sub = 0;
    long long subsub = 0;
    for (long long i = 0; i < (N - 1); i++) {
        for (long long j = 0; j <= C; j++) {

            // 食べる時. 前の位置jと後の位置x[i+1]について
            if ((x[i+1] - j) <= (C - x[i+1] + j)) {
              sub = x[i+1] - j;
            }
            else {
              sub = C - x[i+1] + j;  
            }

            subsub = dp[i+1][x[i+1]] - (dp[i][j] + v[i+1] - sub);
            if (subsub >= 0 ) {                
            }
            else {
              dp[i+1][x[i+1]] = dp[i][j] + v[i+1] - sub;  
            }

            // 何も食べない時.
            dp[i+1][j] = max(dp[i+1][j], dp[i][j]); 
        }
    }
    long long max = -1;
    for (long long i = 0; i <= C; i++) {
        // cout << dp[N-1][i] << endl;
        if (max < 0 || max <= dp[N-1][i]) {
            max = dp[N-1][i];
        }
    }
    cout << max << endl;
}

