    ct.push_back(Pl(x, v));
  }
  ct.push_back(Pl(0, 0));

  FOR(i, 1, N + 1) {
    ls[i] = ls[i - 1] + ct[i].second;
    rs[i] = rs[i - 1] + ct[N - i + 1].second;
  }

  ll max_cal = 0;
  rep(i, N + 1) {
    ll l = ls[i];
    ll l_dist = ct[i].first;

    rep(j, N - i + 1) {
      ll r = rs[j];
      ll r_dist = C - ct[N - j + 1].first;
      if (r_dist == C) r_dist = 0;

      ll cal = l + r;
      ll dist = min(2 * l_dist + r_dist, 2 * r_dist + l_dist);
      max_cal = max(max_cal, cal - dist);
    }
  }
