int main() {
  ios::sync_with_stdio(false); cin.tie(nullptr); //入出力高速化
  ll N,C; cin >> N >> C;
  vector<ll> x(N),v(N);
  for (int i = 0; i < N; i++) cin >> x[i] >> v[i];
  ll l,r,ls,rs,lM,rM,lsM,rsM;
  l = r = ls = rs = lM = rM = lsM = rsM = 0;
  vector<ll> lmax(N), rmax(N), lsmax(N), rsmax(N);

  rep(i,N) {
    if (i == 0) {
      l = (v[i] - x[i]);
      ls = l - x[i];
      r = (v[N-1-i] - (C - x[N-1-i]));
      rs = r - (C - x[N-1-i]);
    }
    else {
      l += (v[i] - (x[i] - x[i-1]));
      ls = l - x[i];
      r += (v[N-1-i] - (x[N-i] - x[N-1-i]));
      rs = r - (C - x[N-1-i]);
    }
    chmax(lM,l);
    chmax(rM,r);
    chmax(lsM,ls);
    chmax(rsM,rs);
    lmax[i] = lM;
    rmax[i] = rM;
    lsmax[i] = lsM;
    rsmax[i] = rsM;
  }

  ll ansl, ansr;
  ansl = ansr = 0;
  rep(i,N) {
    if (i == N-1) {
      chmax(ansl,lmax[i]);
      chmax(ansr,rmax[i]);
    } else {
      chmax(ansl,lmax[i] + rsmax[N-2-i]);
      chmax(ansr,rmax[i] + lsmax[N-2-i]);
    }
  }

  cout << max(ansl,ansr) << endl;
}

