void solve() {
  int midPos = lower_bound(x, x+n, c / 2) - x;

  ll sum = 0;
  ll tmp = 0;
  ll dist = 0;
  for (int i=0;i<midPos;i++) {
    tmp += v[i];
    if (sum < tmp - x[i]) {
      sum = tmp - x[i];
      dist = x[i];
    }
  }
  ll revSum = 0;
  ll revDist = 0;
  tmp = 0;
  for (int i=n-1;i>=midPos;i--) {
    tmp += v[i];
    if (revSum < tmp - (c - x[i])) {
      revSum = tmp - (c - x[i]);
      revDist = (c - x[i]);
    }
  }
  cout << (sum + revSum - min(dist, revDist)) << endl;
}

