		RValue[a] = make_pair(x, v);
		LValue[a] = make_pair(C - x, v);

	}

	sort(RValue.begin(), RValue.end());
	sort(LValue.begin(), LValue.end());

	R = 0;
	L = 0;
	RX = 0;
	LX = 0;

	for (int a = 0; a < N; ++a)
	{
		R += RValue[a].second;
		L += LValue[a].second;

		RX = RValue[a].first;
		LX = LValue[a].first;

		Ans = max(max(R - RX, L - LX), Ans);

	}

	HR = 0;
	HL = 0;

	HRN = 0;
	HLN = 0;
	QRN = 0;
	QLN = 0;

	R = 0;
	L = 0;

	for (ll a = 0; a < N; a++)
	{
		if (RValue[a].first > C / 2) break;

		R += RValue[a].second;

		if (HR < R - RValue[a].first)
		{
			HR = R - RValue[a].first;
			HRN = RValue[a].first;
		}

	}

	for (ll a = 0; a < N; a++)
	{
		if (LValue[a].first > C / 2) break;

		L += LValue[a].second;

		if (HL < L - LValue[a].first)
		{
			HL = L - LValue[a].first;
			HLN = LValue[a].first;
		}

	}


	R = 0;
	L = 0;
	QR = 0;
	QL = 0;

	for (ll a = 0; a < N; a++)
	{
		if (RValue[a].first > C / 4) break;

		R += RValue[a].second;


		if (QR < R - RValue[a].first * 2)
		{
			QR = R - RValue[a].first * 2;
			QRN = RValue[a].first;
		}


	}

	for (ll a = 0; a < N; a++)
	{
		if (LValue[a].first > C / 4) break;

		L += LValue[a].second;

		if (QL < L - LValue[a].first * 2)
		{
			QL = L - LValue[a].first * 2;
			QLN = LValue[a].first;
		}

	}

	Ans = max(Ans, max(max(QR + HL + max(QRN, HLN), QL + HR + max(QLN, HRN)), QR + QL + max(QRN, QLN)));

	OUT << Ans << endl;

	return 0;
}

