vector<pair<ll, ll>> dny(vector<pair<ll, ll>> vec, int N) {
	ll mxd = 0, mxe = 0;
	for (int i = 0;i < N;i++) {
		if (vec[i].first <= mxe) {
			vec[i].first = mxe;
			vec[i].second = mxd;
		}
		else {
			mxe = vec[i].first;
			mxd = vec[i].second;
		}
	}
	return vec;
}

