int n,c;
const int maxn=1e5+100;
int x[maxn],v[maxn];
int sa[maxn],sb[maxn];
int maxv=0;
priority_queue < int > q;
void solve(){
	memset(sa,0,sizeof(sa));
	memset(sb,0,sizeof(sb));
	for (int i=1;i<=n;i++){
		sa[i]=sa[i-1]+v[i]-(x[i]-x[i-1]);
	}
	x[n+1]=c;
	for (int i=n;i>=1;i--){
		sb[i]=sb[i+1]+v[i]-((c-x[i])-(c-x[i+1]));
	}
//	for (int i=1;i<=n;i++) cout << sa[i] << ' ';
//	cout << endl;
	for (int i=1;i<=n;i++){
		maxv=max(maxv,sa[i]);
	}
//	cout << "maxv=" << maxv << endl;
	while (!q.empty()) q.pop();
	q.push(0);
	for (int i=n;i>=1;i--){
		int u=q.top();
//		cout << "u=" << u << endl;
		maxv=max(maxv,u+sa[i]-x[i]);
//		cout << "max=" << maxv << endl; 
		q.push(sb[i]);
	}
}
