	for (int i=1;i<=n;i++) x[i]=c-x[i];
	for (int i=1;i<=n/2;i++){
		swap(x[i],x[n-i+1]);
		swap(v[i],v[n-i+1]);
	}
	solve();
	cout << maxv << endl;
	return 0;
}

