#include <cstdio>
#include <iostream>
#include <vector>
struct rl_vec{
  std::vector<int> r;
  std::vector<int> l;
};
struct rl_num{
  int r;
  int l;
};

int CalcCal(std::vector<int> cal, std::vector<int> dis, int max)
{
  int sum = 0;
  for(int i = 0; i < max+1; i++){
    sum += cal[i];
  }
  return sum-dis[max];
}

int CalcMaxCal(rl_num cal, int disr,int disl){
  int sum_cal = cal.r+cal.l;
  if(disr > disl) return sum_cal-disl;
  else return sum_cal-disr;
}

int main(int argc, char **argv){
  int counter;
  int total_num;
  scanf("%d %d",&total_num,&counter);
  int half_cou = counter/2;

  rl_vec dis;
  rl_vec cal;
  rl_num num;
  num.r = num.l = 0;

  //INPUT DATA
  for(int i = 0; i < total_num; i++){
    int buf_cal,buf_dis;
    scanf("%d %d",&buf_dis,&buf_cal);
    if(buf_dis > half_cou){
      num.l = total_num - i;
      dis.l.assign(num.l,0);
      cal.l.assign(num.l,0);
      buf_dis = counter - buf_dis;
      dis.l[num.l-1]=buf_dis;
      cal.l[num.l-1]=buf_cal;
      break;
    }
    num.r++;
    dis.r.push_back(buf_dis);
    cal.r.push_back(buf_cal);
  }

  for(int i = 0; i < num.l-1; i++){
    if(num.l==1) break;
    int buf_cal,buf_dis;
    scanf("%d %d",&buf_dis,&buf_cal);
    buf_dis = counter - buf_dis;
    dis.l[num.l-i-2]=buf_dis;
    cal.l[num.l-i-2]=buf_cal;
  }

  rl_num rl_cal;
  int buf_max_cal = 0;
  int old_max_cal = 0;
  bool r_m_flag = false;
  bool l_m_flag = false;
  for(int i = 0; i < num.r; i++){
    rl_cal.r = CalcCal(cal.r,dis.r,i);
    if(rl_cal.r <= 0) r_m_flag = true;
    for(int j = 0; j < num.l; j++){
      rl_cal.l = CalcCal(cal.l,dis.l,j);
      if(rl_cal.l <= 0) l_m_flag = true;
      if(r_m_flag && l_m_flag) continue;
      else if(!r_m_flag && !l_m_flag) buf_max_cal = CalcMaxCal(rl_cal,dis.r[i],dis.l[j]);
      else{
        if (r_m_flag) buf_max_cal = rl_cal.l;
        else buf_max_cal = rl_cal.r;
      }
      if(buf_max_cal > old_max_cal) old_max_cal = buf_max_cal;
    }
  }
  printf("%d\n",old_max_cal);

  return 0;
}

