  }
  ll ans = max(r[n - 1], 0LL);
  ans = max(ans, l[0]);
  rep(i, n - 1) ans = max(ans, revr[i] + l[i + 1]);
  for (int i = n - 1; i > 0; i--) ans = max(ans, revl[i] + r[i - 1]);
  cout << ans << endl;
  return 0;
}

