template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }
template<typename A, size_t N, typename T> void Fill(A (&array)[N], const T &val) { fill( (T*)array, (T*)(array+N), val ); }

int N;
ll C;
ll x[100010], v[100010];
ll y[100010];
ll A[100010], B[100010], D[100010];

ll solve() {
    // 時計回りの価値の累積和
    A[0] = v[0];
    REP(i, 1, N) A[i] = A[i-1] + v[i];

    // 反時計回りの価値の累積和
    B[N-1] = v[N-1];
    RREPS(i, N-2, 0) B[i] = B[i+1] + v[i];

    // y[0]は右から0番目を反時計回りで歩いた時に消費するカロリー
    // y[N-1]からiが少なくなるほど、反時計周りした時に消費するカロリーは減る
    rep(i, N) y[i] = C - x[i];

    D[N-1] = B[N-1] - y[N-1];
    RREPS(i, N-2, 0) {
        // i番目までの寿司を食べる時のカロリー差の最大値
        D[i] = B[i] - y[i];
        //　N-1番目からi番目までの寿司を食べられる時のカロリー差の最大値
        chmax(D[i], D[i+1]);
    }

    ll ans = 0;
    rep(i, N) {
        ll sm = 0;
        sm -= x[i];
        sm += A[i];
        chmax(ans, sm);
        sm -= x[i];

        if (i < N - 1) sm += D[i+1];
        chmax(ans, sm);
    }
    return ans;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> C;
    rep(i, N) cin >> x[i] >> v[i];

    ll ans = 0;
    chmax(ans, solve());

    reverse(v, v + N);
    rep(i, N) x[i] = C - x[i];
    reverse(x, x + N);
    chmax(ans, solve());
    cout << ans << endl;
    return 0;
}

