    sumL[i] = sumL[i+1] + v[i]-(x[i+1]-x[i]);
    maxL[i] = max(maxL[i+1], sumL[i]);
  }
  ll ans = 0;
  for (int i=n+1; i>=0; i--) {
    ll cal = sumL[i] - (c-x[i]);
    cal += maxR[i-1];
    chmax(ans, cal);
  }
  rep(i, n+1) {
    ll cal = sumR[i] - x[i];
    cal += maxL[i+1];
    chmax(ans, cal);
  } 
  printf("%lld\n", ans);
  return 0;
}

