	{
		sum=sum-(x[i+1]-x[i])+v[i];
		ans=max(ans,sum);
	}
	for(register int i=1;i<=n;i++)
	{
		k[1][i]=k[1][i-1]+v[i]+2*x[i-1]-2*x[i];
		k[2][i]=k[2][i-1]+v[i]+x[i-1]-x[i];
	}
	for(register int i=n;i>=1;i--)
	{
		k[3][i]=k[3][i+1]+v[i]+2*(c-x[i+1])-2*(c-x[i]);
		k[4][i]=k[4][i+1]+v[i]+(c-x[i+1])-(c-x[i]);
	}
