    r[n-i]={c-x,v};
  }
  l[n+1]={c,0};
  r[n+1]={c,0};
  l[0]={0,0};
  r[0]={0,0};
  vector<ll>suml(n+3),sumr(n+3);
  rep(i,n+2)
  {
    suml[i+1]=suml[i]+l[i].c;
    sumr[i+1]=sumr[i]+r[i].c;
  }
  SegmentTree<ll> stl(n+3,[](ll a,ll b){return max(a,b);},0),stl2(n+3,[](ll a,ll b){return max(a,b);},0);
  rep(i,n+2)
  {
    stl.update(i,suml[i+1]-l[i].x);
    stl2.update(i,suml[i+1]-2*l[i].x);
  }
  rep(i,n+1);//cout<<stl2.query(i,i+1)<<" ";
  //cout<<endl;

  ll res=0;
  rep(i,n+1)
  {
    ll tr=r[i].x;
    ll id=lower_bound(all(l),(sushi){tr,0},[&](sushi a,sushi b){return a.x<b.x;})-l.begin();
    ll tres=sumr[i+1];
    if(id<=n-i)
    {
      tres+=max(stl2.query(0,id)-tr,stl.query(id,n-i+1)-2*tr);
    }
    else
    {
      tres+=stl2.query(0,n-i+1)-tr;
    }
    chmax(res,tres);
    //cout<<i<<" "<<id<<endl;
