int main() {
	long long N, C;

	scanf("%lld %lld", &N,&C);

	std::vector<std::pair<long long, long long>> sushi;

	long long tmp,tmp2;
	for (int i = 0; i < N; i++) {
		scanf("%lld %lld", &tmp, &tmp2);
		sushi.push_back(std::make_pair(tmp,tmp2));
	}
	std::sort(sushi.begin(), sushi.end());

	long long ans = 0;
	long long ans2 = 0;
	long long ans3 = 0;
	long long ans4 = 0;

	long long ir = -1;
	long long jl = N;



	//1.Go R
	std::vector<std::pair<long long, long long>> ir_max;;
	long long max = 0;
	long long dist = 0;
	long long sum = 0;
	for (long long i = 0; i < N; i++) {
		dist = sushi[i].first;
		sum += sushi[i].second;
		if (sum - dist >= max) {
			max = sum - dist;
			ans = max;
			ir = i;
		}
		ir_max.push_back(std::make_pair(ir,max));
	}

//	printf("%lld\n", ans);

	std::vector<std::pair<long long, long long>> jl_max;;
	//2.Go L
	sum = 0; max = 0;
	for (long long j = N-1; j >= 0; j--) {
		dist = C - sushi[j].first;
		sum += sushi[j].second;
		if (sum - dist >= max) {
			max = sum - dist;
			ans2 = max;
			jl = j;
		}
		jl_max.push_back(std::make_pair(jl, max));
	}
//	printf("%lld\n", ans2);

	//3.Go L then R
	long long i;
	sum = 0;
	max = 0;
	for (long long j = N - 1; j > 0; j--) {
		i = ir_max[j-1].first;
		sum += sushi[j].second;
		if (i != -1) {
			dist = 2 * (C - sushi[j].first);
			if (max <= sum + ir_max[j-1].second - dist) {
				max = sum + ir_max[j-1].second - dist;
				ans3 = max;
			}
		}
	}

	//4.Go R then L

	long long j;
	sum = 0;
	max = 0;
	for (long long i = 0; i < N-1; i++) {
		j = jl_max[N-2-i].first;
		sum += sushi[i].second;
		if (j != N) {
			dist = 2 * sushi[i].first;
			if (max <= sum + jl_max[N-2-i].second - dist) {
				max = sum + jl_max[N-2-i].second - dist;
				ans4 = max;
			}
		}
	}




	printf("%lld", std::max(std::max(ans,ans2), std::max(ans3, ans4)));




	return 0;
}

