			min1 = min(abs(head->next->x - flag), min(abs(c - flag + (head->next->x)), abs(c + flag - (head->next->x))));
			min2 = min(abs(last->x - flag), min(abs(c + (last->x) - flag), abs(c - (last->x) + flag)));
		if (sum > max) max = sum;
	}
	cout << max << endl;
	return 0;
}

