// 0: clockwise
// 1: counter - clockwise

void maximize(long long &a, long long b) {
	if (a < b) a = b;
}

void minimize(long long &a, long long b) {
	if (a > b) a = b;
}

int main() {
	freopen("1.inp", "r", stdin); freopen("1.out", "w", stdout);
	scanf("%d %lld", &n, &c);
	for (int i = 1; i <= n; i++) scanf("%lld %lld", &x[i], &v[i]);
	long long ans = -INF;
	long long temp = 0;
	for (int i = 1; i <= n; i++) {
		temp += v[i];
		temp -= (x[i] - x[i - 1]);
		maximize(ans, temp);
	}
	temp = 0;
	x[n + 1] = c;
	for (int i = n; i >= 1; i--) {
		temp += v[i];
		temp -= (x[i + 1] - x[i]);
		maximize(ans, temp);
	}
	// cout << ans << endl;
	temp = 0;
	dp[n + 1][1] = -INF;
	for (int i = n; i >= 1; i--) {
		temp += v[i];
		temp -= (x[i + 1] - x[i]);
		maximize(dp[i][1], dp[i + 1][1]);
		maximize(dp[i][1], temp);
	}
	temp = 0;
	dp[0][0] = -INF;
	for (int i = 1; i <= n; i++) {
		temp += v[i];
		temp -= (x[i] - x[i - 1]);
		maximize(dp[i][0], dp[i - 1][0]);
		maximize(dp[i][0], temp);
