	// for (int i = n; i >= 1; i--) cout << dp[i][1] << " "; cout << endl;
	for (int i = 1; i <= n; i++) {
		maximize(ans, dp[i][0] + dp[i + 1][1] - x[i]);
	}
	for (int i = n; i >= 1; i--) {
		maximize(ans, dp[i][1] + dp[i - 1][0] - (c - x[i]));
	}
	maximize(ans, 0);
	printf("%lld", ans);
	return 0;
}

