#define reps(i,s,n) for(int (i) = (s); (i) < (n); (i)++)
#define rep(i,n) reps(i,0,n)

int main(){
    int n;
    ll c;
    cin >> n >> c;

    vector<ll> x(n),v(n);
    vector<ll> left(n),right(n);
    vector<ll> g_left(n),g_right(n);
    ll ans = 0;

    rep(i,n){
        cin >> x[i] >> v[i];
    }
    right[0] = v[0];
    reps(i,1,n){
        right[i] += (v[i] + right[i-1]);
    }
    left[n-1] = v[n-1];
    for(int j = n-2; j >= 0; j--){
        left[j] += (v[j]  + left[j+1]);
    }

    g_right[0] = max(g_right[0],v[0] - x[0]);
    reps(i,1,n){
        g_right[i] = max(g_right[i-1], right[i] - x[i]);
    }

    if(v[n-1] - (c-x[n-1]) > 0) g_left[n-1] = v[n-1] - (c- x[n-1]);
    for(int j = n-2; j >= 0; j--){
        g_left[j] = max(g_left[j+1] , left[j] - (c- x[j]) );
    }

    rep(i,n){
        ans = max(ans,g_right[i]);
        ans = max(ans,g_left[i]);
    }

    rep(i,n-1){
        if(ans < right[i] + g_left[i+1] - 2* x[i]){
            ans = max(ans,right[i] + g_left[i+1] - 2* x[i]);
        }
    }

    for(int j = n-1; j > 0; j--){
        if(ans < max(ans,left[j] + g_right[j-1] - 2*(c- x[j]) )){
            ans = max(ans,left[j] + g_right[j-1] - 2*(c- x[j]) );
        }
    }
    cout << ans << endl;
}

