int main() {
  long long N,C;
  cin >> N >> C;
  vector<long long> x(N+2,0),v(N+2,0);
  for(int i=1;i<=N;i++){
    cin >> x[i] >> v[i];
  }
  x[N+1]=C;
  long long ans=0;
  long long a=0,k=0,b=0,l=0;
  for(long long i=1;i<=N;i++){
    k +=v[i]-x[i]+x[i-1];//v[1]-x[1],v[1]+v[2]-x[2]+x[1]-x[1],...
    a=max(a,k);
    //時計回り
  }
  //cout << a << endl;
  for(long long i=N;i>=0;i--){
    l +=v[i]-x[i+1]+x[i];//v[N]-x[N+1]+x[N],v[N]+v[N-1]-x[N+1]+x[N-1],...
    b=max(b,l);
    //反時計回り
  }
  //cout << b << endl;
  long long c=0,d=0,e=0,f=0,g=0,h=0,p=0,q=0,m=0;
  while(x[m]<=C/2){
    m++;
  }
  //cout << m-1 << endl;
  //x[m-1]までがC/2以下

  for(long long i=1;i<m;i++){
    e +=v[i]-2*x[i]+2*x[i-1];
    c=max(c,e);
  }
  //cout << c << endl;
  //原点まで戻ってくる
  for(long long i=N;i>=m;i--){
    f +=v[i]-x[i+1]+x[i];
    d=max(d,f);
  }
  //cout << d << endl;
  //戻ってきた後の移動
    for(long long i=1;i<m;i++){
    p +=v[i]-x[i]+x[i-1];
    g=max(g,p);
  }
  //cout << g << endl;
  //戻ってきた後の移動
  for(long long i=N;i>=m;i--){
    q +=v[i]-2*x[i+1]+2*x[i];
    h=max(h,q);
  }
  //cout << h << endl;
  //原点まで戻ってくる
  //cout << c+d << endl;
  //cout << g+h << endl;
  ans=max(max(a,b),max(c+d,g+h));
  cout << ans << endl;
}

