#include <bits/stdc++.h>
#define inf 1e17
using namespace std;

long long n, c, ans = 0;
vector<long long> v, x, memo;

void solve();
void calc();

int main() {
  cin >> n >> c;
  v.assign(n, 0);
  x.assign(n, 0);
  memo.assign(n, 0);
  for(int i = 0; i < n; ++i) cin >> x[i] >> v[i];
  calc();
  solve();
  reverse(x.begin(), x.end());
  reverse(v.begin(), v.end());
  for(int i = 0; i < n; ++i) x[i] = c - x[i];
  calc();
  solve();
  cout << ans << endl;
  return 0;
}

void solve() {
  long long sum = 0;
  ans = max(ans, memo[n - 1]);
  for(int i = 0; i < n - 1; ++i) {
    long long now = 0;
    now = memo[n - 2 - i];
    sum += v[n - 1 - i];
    now += sum;
    now -= 2 * (c - x[n - 1 - i]);
    ans = max(ans, now);
  }
}

void calc() {
  long long sum = v[0] - x[0];
  for(int i = 0; i < n; ++i) {
    if(i == 0) {
      memo[i] = max(0LL, sum);
      continue;
    }
    sum += v[i] - x[i] + x[i - 1];
    memo[i] = max(memo[i - 1], sum);
  }
}

