    //cy[i]:=反時計回りにi+1個寿司をとったときのエネルギーの差し引き
    ll cx[N], cy[N];
    cx[0] = v[0]-x[0];
    cy[0] = v[N-1]-y[N-1];
    rep2(i, 1, N-1){
        cx[i] = cx[i-1]+v[i]-(x[i]-x[i-1]);
        cy[i] = cy[i-1]+v[N-1-i]-(y[N-1-i]-y[N-i]);
    }
    //mx[i]:=cx[0]からcx[i]までの最大値
    ll mx[N], my[N];
    mx[0] = cx[0], my[0] = cy[0];
    rep2(i, 1, N-1){
        mx[i] = max(mx[i-1], cx[i]);
        my[i] = max(my[i-1], cy[i]);
    }
    ll ans = 0;
    //最初時計回りにi+1個回収してからから折り返す場合
    rep(i, N-1){
        ll tmp = cx[i]-x[i]+my[N-2-i];
        ans = max(ans, tmp);
    }
    //最初反時計回りにi+1個回収してから折り返す場合
    rep(i, N-1){
        ll tmp = cy[i]-y[N-1-i]+mx[N-2-i];
        ans = max(ans, tmp);
    }
    //折り返さない場合
    ans = max(ans, mx[N-1]);
    ans = max(ans, my[N-1]);
    cout << ans << endl;
}

