LL n, c, x[101010], v[101010], s1[101010], ans =- LINF;

LL solve() {
	REP(i, n + 1)s1[i] = -LINF;
	LL g = 0, ret = 0;
	for (int i = 1; i <= n; i++) {
		g += v[i];
		s1[i] = max(s1[i - 1], g - x[i]);
	}
	ret = max(ret,s1[n]);
	LL z = 0;
	for (int i = n; i >= 1; i--) {
		z += v[i];
		ret = max(ret, s1[i - 1] + (z - (c - x[i]) * 2));
	}
	return ret;
}

