using namespace std;


#define SIZE 100005


ll N,C;
ll loc[SIZE],value[SIZE];
ll CLOCK[SIZE],rev[SIZE];
ll max_CLOCK[SIZE],max_rev[SIZE];


int main(){

	scanf("%lld %lld",&N,&C);

	for(ll i = 1; i <= N; i++){

		scanf("%lld %lld",&loc[i],&value[i]);
	}
	loc[0] = 0;
	loc[N+1] = 0;

	//時計回りを計算(片道)
	ll add = 0;

	CLOCK[0] = 0;
	max_CLOCK[0] = 0;

	for(ll i = 1; i <= N; i++){

		add += value[i];
		ll tmp = add-loc[i];

		CLOCK[i] = tmp;
		max_CLOCK[i] = max(CLOCK[i],max_CLOCK[i-1]); //それまでで最大の差分を取得
		//printf("時計[%lld]:%lld\n",i,max_CLOCK[i]);
	}

	//半時計周りを計算(片道)
	add = 0;

	rev[0] = 0;
	max_rev[0] = 0;

	for(ll i = 1; i <= N; i++){

		add += value[(N+1)-i];
		ll tmp = add-(C-loc[(N+1)-i]);

		rev[i] = tmp;
		max_rev[i] = max(rev[i],max_rev[i-1]);
		//printf("半時計[%lld]:%lld\n",i,max_rev[i]);
	}

	ll maximum = 0;

	//時計回りを全探索(引き返す)
	for(ll i = 0; i <= N; i++){

		ll tmp = CLOCK[i];
		tmp -= loc[i];

		//printf("i:%lld CLOCK:%lld loc:%lld tmp:%lld\n",i,CLOCK[i],loc[i],tmp);

		tmp += max_rev[N-i];
		//printf("max_rev[%lld]:%lld\n",N-i,max_rev[N-i]);

		maximum = max(maximum,tmp);
	}

	//半時計周りを全探索(引き返す)
	for(ll i = 0; i <= N; i++){

		ll tmp = rev[i];
		tmp -= (C-loc[(N+1)-i]);

		tmp += max_CLOCK[N-i];

		maximum = max(maximum,tmp);
	}

	printf("%lld\n",maximum);

	return 0;
}

