int main(void){
  long long int N,C,ans=0,work;
  scanf("%lld%lld",&N,&C);
  long long int x[N],v[N],value[N],dist[N];
  scanf("%lld%lld",&x[0],&v[0]);
  value[0] = 0;
  dist[0] = 0;
  if(v[0]-x[0] > 0){
    value[0] = v[0]-x[0];
    dist[0] = x[0];
  }
  work = v[0];
  for(int i=1;i<N;i++){
    scanf("%lld%lld",&x[i],&v[i]);
    work += v[i];
    if(work-x[i] > value[i-1]){
      value[i] = work-x[i];
      dist[i] = x[i];
    }
    else{
      value[i] = value[i-1];
      dist[i] = dist[i-1];
    }
  }
  ans = value[N-1];
  work = 0;
  for(int i=N-1;i>-1;i--){
    work += v[i];
    long long int temp = work-(C-x[i]);
    if (C-x[i] < dist[i-1])
      temp = temp+value[i-1]-(C-x[i]);
    else
      temp = temp+value[i-1]-dist[i-1];

    if(ans < temp)
      ans = temp;
  }

  printf("%lld\n",ans);
  return 0;

}

