int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    ll c;
    cin >> n >> c;
    VL x(n), v(n);
    REP(i, n) cin >> x[i] >> v[i];
    VL xx(n);
    REP(i, n) xx[i] = c - x[n - i - 1];
    VL intake_clock(n);
    intake_clock[0] = v[0];
    FOR(i, 1, n - 1) intake_clock[i] = v[i] + intake_clock[i - 1];
    VL intake_unclock(n);
    intake_unclock[0] = v[n - 1];
    FOR(i, 1, n - 1) intake_unclock[i] = v[n - i - 1] + intake_unclock[i - 1];

    ll only_clock = intake_clock[0] - x[0];
    int only_clock_index = 0;
    vector<pair<ll, int>> opt_clock(n);
    REP(i, n) {
        if(only_clock < intake_clock[i] - x[i]) {
            only_clock = intake_clock[i] - x[i];
            only_clock_index = i;
        }
        opt_clock[i].first = only_clock;
        opt_clock[i].second = only_clock_index;
    }
    ll only_unclock = intake_unclock[0] - xx[0];
    int only_unclock_index = 0;
    vector<pair<ll, int>> opt_unclock(n);
    REP(i, n) {
        if(only_unclock < intake_unclock[i] - xx[i]) {
            only_unclock = intake_unclock[i] - xx[i];
            only_unclock_index = i;
        }
        opt_unclock[i].first = only_unclock;
        opt_unclock[i].second = only_unclock_index;
    }
    ll fold = 0;
    FOR(i, 0, n - 2) {
        fold = max(fold, opt_clock[i].first 
                         - x[opt_clock[i].second] 
                         + opt_unclock[n - i - 2].first);
        fold = max(fold, opt_unclock[i].first 
                         - xx[opt_unclock[i].second] 
                         + opt_clock[n - i - 2].first);
    }

    fold = max(fold, only_clock);
    fold = max(fold, only_unclock);
    cout << fold << endl;

    return 0;
}

