	for (int i = 1; i <= N; i++) {
		table[i] = table[i-1] + input[i].v;
	}

	long long int max = 0;
	for (int a = 0; a <= N; a++) {
		for (int b = 0; b <= N; b++) {
			long long int p1, p2, p;

			if (b == 0) {
				p1 = table[a] - (2 * input[a].x);
				p2 = table[a] - input[a].x;
			} else if (a < b) {
				p1 = table[a] + table[N] - table[b-1] - (2 * input[a].x + (C - input[b].x));
				p2 = table[N] - table[b-1] + table[a] - (2 * (C - input[b].x) + input[a].x);
			} else {
				p1 = table[a] - (2 * input[a].x + (input[a].x - input[b].x));
				p2 = table[a] - (2 * (input[a].x - input[b].x) + input[a].x);
			}

			if (p1 > p2) {
				p = p1;
			} else {
				p = p2;
			}

			if (max < p) {
				max = p;
			}
		}
	}

