void go2() {
  ll x = c;
  ll tot = 0;

  for (int i=n; i>=1; i--) {
    ll y = a[i].first; ll gain = a[i].second;
    tot += gain - (x-y);
    acc2[i] = tot;
    x = y;
  }
  for (int i=n; i>=1; i--) {
    if (acc2[i] > dp2[i+1]) {
      dp2[i] = acc2[i];
      ind2[i] = a[i].first;
    } else {
      dp2[i] = dp2[i+1];
