  vector<int64_t> cc_max(N,0);
  cc_max[N-1]=cc[N-1];
  for(int i=N-2;i>=0;--i) cc_max[i]=max(cc_max[i+1],cc[i]);

  ans=max(ans,max(c_max[N-1],cc_max[0]));
  //時計-反時計
  for(int i=0;i<N-1;++i){
    ans=max(ans,c[i]-x[i]+cc_max[i+1]);
  }
  //反時計-時計
  for(int i=N-1;i>0;--i){
    ans=max(ans,cc[i]-(C-x[i])+c_max[i-1]);
  }

  cout<<ans<<endl;
}

