int N;
ll C;
ll x[101010], v[101010];
ll y[101010];
ll A[101010], B[101010], D[101010];

ll solve() {
  A[0] = v[0];
  //時計回りの累積和
  srep(i, 1, N) A[i] = A[i - 1] + v[i];

  rep(i, N) y[i] = C - x[i];
  B[N - 1] = v[N - 1];
  //半時計回りの累積和
  drep(i, N - 1) B[i] = B[i + 1] + v[i];

  D[N - 1] = B[N - 1] - y[N - 1];
  //D[i]:=左にi個までのお寿司を食べたときの、カロリーの最大値
  drep(i, N - 1) {
    D[i] = B[i] - y[i];
    maxs(D[i], D[i + 1]);
  }

  ll ans = 0;
  rep(i, N) {
    ll sm = 0;
    sm -= x[i];  // →移動
    sm += A[i];  // →カロリー
    maxs(ans, sm);
    sm -= x[i];  // 原点に戻る
    if (i < N - 1) sm += D[i + 1];
    maxs(ans, sm);
  }

  return ans;
}
int main() {
  cin >> N >> C;
  rep(i, N) cin >> x[i] >> v[i];

  ll ans = 0;
  maxs(ans, solve());

  reverse(v, v + N);
  rep(i, N) x[i] = C - x[i];
  reverse(x, x + N);

  maxs(ans, solve());
  cout << ans << endl;
}

