    for (int i = 0; i < n; i++) {
        if (i == 0) {
            if ((vec[first].v-vec[first].x) >= (vec[end].v-c+vec[end].v)) {
                ans += vec[first].v;
                ans -= vec[first].x;
                a[i] = ans;
