                first++;
            }      
            else {
                ans += vec[end].v;
                ans -= c-vec[end].x;
                a[i] = ans;
                ans += c-vec[end].x;
                X = vec[end].x;
                end--;
                count = 1;
            }      
        }
        else {
            if (count == 0) {
                if ((vec[first].v - vec[first].x + X) >= (vec[end].v - c + vec[end].x - X)) {
