                        a[i] = ans;
                        ans += min_x(vec[first].x,c-vec[end+1].x);
                        X = vec[first].x;
                        first++;
                    }
                }
                else {
                    ans += vec[end].v;
                    ans -= min_x(vec[first-1].x,c-vec[end].x);
                    a[i] = ans;
                    ans += min_x(vec[first-1].x,c-vec[end].x);
                    X = vec[end].x;
                    end--;
                    count = 1;
                    pass = 1;
                }
            }
            else if (count == 1) {
                if ((vec[first].v - c + X - vec[first].x) >= (vec[end].v - X + vec[end].x)) {
                    ans += vec[first].v;
                    ans -= min_x(vec[first].x,c-vec[end+1].x);
                    a[i] = ans;
                    ans += min_x(vec[first].x,c-vec[end+1].x);
                    X = vec[first].x;
                    first++;
                    count = 0;
                    pass = 1;
                }
                else {
                    if (pass == 0) {
                        ans += vec[end].v;
                        ans -= c - vec[end].v;
                        a[i] = ans;
                        ans += c - vec[end].v;
                        X = vec[end].v;
