                        a[i] = ans;
                        ans += min_x(vec[first-1].x,c-vec[end].x);
                        X = vec[end].v;
                        end--;
                    }
                }
            }
        }
    }

    int max = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] > max) {
            max = a[i];
        }
    }

    cout  << max << endl;

    return 0;
}

