int main()
{
    int64_t N, C;
    std::cin >> N >> C;

    struct S {
        int64_t x;
        int64_t v;
    };

    std::vector<S> sr;
    for (size_t i = 0; i < N; ++i) {
        S s;
        std::cin >> s.x >> s.v;
        sr.push_back(s);
    }


    std::sort(std::begin(sr), std::end(sr),
              [](const auto& a, const auto& b) {
                  return a.x < b.x;
              });

    auto sl = sr;
    std::reverse(std::begin(sl), std::end(sl));

    // 時計回り、反時計回りにi個食べた中でのベストエネルギ
    std::vector<int64_t> rmax, lmax;
    rmax.push_back(0);
    lmax.push_back(0);
    {
        int64_t rm, lm, re, le, rpos, lpos;
        rm = lm = re = le = rpos = 0;
        lpos = C;

        for (size_t i = 0; i < N; ++i) {
            re = re + sr[i].v - (sr[i].x - rpos);
            rm = std::max(rm, re);
            rmax.push_back(rm);
            rpos = sr[i].x;

            le = le + sl[i].v - (lpos - sl[i].x);
            lm = std::max(lm, le);
            lmax.push_back(lm);
            lpos = sl[i].x;
        }
    }

    int64_t rlmax, lrmax;
    {
        int64_t re, le, rpos, lpos;
        rlmax = lrmax = re = le = rpos = 0;
        lpos = C;

        for (size_t i = 0; i < N; ++i) {
            // i+1個目食べるかどうか判定

            // 時計回りに進んだパターン
            re = re + sr[i].v - (sr[i].x - rpos);
            // {もう食べない, いまの食べる, 今の食べて反時計回りに最大N-(i+1)個食べる}の中のベスト
            rlmax = std::max({rlmax, re, re + lmax[N-i-1] - sr[i].x});
            rpos = sr[i].x;

            // 反時計回りに進んだパターン
            le = le + sl[i].v - (lpos - sl[i].x);
            // {もう食べない, いまの食べる, 今の食べて時計回りに最大N-(i+1)個食べる}の中のベスト
            lrmax = std::max({lrmax, le, le + rmax[N-i-1] - (C - sl[i].x)});
            lpos = sl[i].x;
        }
    }

    std::cout << std::max(lrmax, rlmax) << std::endl;

    return 0;
}

