	for(int i=N-1;i>=1;i--) {
		right_back[i] = (right_score[i] - (C - x[i]));
		// [0,i-1]までのleftの最大値
		right_back[i] += left_max[i-1];
		right_back_ans = max(right_back_ans, right_back[i]);
	}

	cout << max({left_ans, right_ans, left_back_ans, right_back_ans}) << endl;
}

