template<class T1, class T2> inline std::ostream & operator<< (std::ostream & os, const std::pair<T1, T2> & p) { return os << p.first << ' ' << p.second; }

void solve(void)
{
  ll N, C; cin >> N >> C;
  using Pair = pair<ll, ll>;
  vector<Pair> X(N + 1);
  X[0] = {0, 0};
  for(size_t i = 1; i < X.size(); ++i)
    cin >> X[i].first >> X[i].second;

  vector<ll> v_sumr(X.size());
  for(size_t i = 0; i < v_sumr.size(); ++i){
    v_sumr[i] = X[i].second;
    if(i){
      v_sumr[i] += v_sumr[i - 1];
    }
  }
  vector<Pair> r_max(X.size());
  for(size_t i = 0; i < r_max.size(); ++i){
    r_max[i].second = v_sumr[i] - X[i].first;
    r_max[i].first = X[i].first;
    if(i){
      if(r_max[i].second < r_max[i - 1].second){
        r_max[i] = r_max[i - 1];
      }
    }
  }
  vector<Pair> r_max2(X.size());
  for(size_t i = 0; i < r_max2.size(); ++i){
    r_max2[i].second = v_sumr[i] - X[i].first * 2;
    r_max2[i].first = X[i].first * 2;
    if(i){
      if(r_max2[i].second < r_max[i - 1].second){
        r_max2[i] = r_max2[i - 1];
      }
    }
  }

  vector<ll> v_suml(X.size());
  for(auto l_it = v_suml.rbegin(); l_it != v_suml.rend(); ++l_it){
    auto r_index = (v_suml.size() - 1) - std::distance(v_suml.rbegin(), l_it);
    *l_it = X[r_index].second;
    if(l_it != v_suml.rbegin()){
      *l_it += *std::prev(l_it);
    }
  }

  // cout << "X :" << X << CRLF;
  // cout << "v_sumr :" << v_sumr << CRLF;
  // cout << "r_max :" << r_max << CRLF;
  // cout << "v_suml :" << v_suml << CRLF;
  ll ans{};
  for(size_t i = 1; i < X.size(); ++i){
    auto l_dis = C - X[i].first;
    auto l_val = v_suml[i];

    auto res0 = l_val - l_dis + r_max2[i - 1].second;
    auto res1 = l_val - l_dis - l_dis + r_max[i - 1].second;
    auto res = std::max(res0, res1);
    chmax(ans, res);
  }
  chmax(ans, r_max.back().second);

  cout << ans << CRLF;

  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

