		}
		else {
			cal_cw[0] = v[0] - x[0];
		}
		ans = max(ans, cal_cw[i]);
	}

	// 反時計回り
	for (int i = N - 1; i >= 0; --i) {
		if (i < (N - 1)) {
			cal_ccw[i] = cal_ccw[i + 1] + v[i] - (x[i + 1] - x[i]);
		}
		else {
			cal_ccw[N - 1] = v[N - 1] - (C - x[N - 1]);
		}
		ans = max(ans, cal_ccw[i]);
	}

