	scanf("%lld%lld", &N, &C);
	X = (long long *)malloc(sizeof(long long) * N);
	V = (long long *)malloc(sizeof(long long) * N);
	A = (long long *)malloc(sizeof(long long) * N);
	B = (long long *)malloc(sizeof(long long) * N);
	Am = (long long *)malloc(sizeof(long long) * N);
	Bm = (long long *)malloc(sizeof(long long) * N);

	for (long long i = 0; i < N; i++) {
		scanf("%lld%lld", &X[i], &V[i]);
	}
	A[0] = V[0] - X[0];
	Am[0] = A[0] > 0 ? A[0] : 0;
	for (long long i = 1; i < N; i++) {
		A[i] = A[i - 1] - (X[i] - X[i - 1]) + (V[i]);
		Am[i] = Am[i - 1] > A[i] ? Am[i - 1] : A[i];
	}


	B[0] = V[N - 1] - (C - X[N - 1]);
	Bm[0] = B[0] > 0 ? B[0] : 0;
	for (long long i = 1; i < N; i++) {
		B[i] = B[i - 1] - (X[N - i] - X[N - i - 1]) + (V[N - i - 1]);
		Bm[i] = Bm[i - 1] > B[i] ? Bm[i - 1] : B[i];
	}


	for (long long i = 0; i < N; i++) {
		long long a = A[i];
		if (ans < a) {
			ans = a;
		}
		if (i != N - 1) {
			for (long long j = 0; j < N; j++) {
				if (Bm[N - i - 2] == Bm[j]) {
					a += Bm[j] - X[i];
					break;
				}
			}
		}
		if (ans < a) {
			ans = a;
		}
	}

	printf("%lld\n", ans);

	return 0;
}

