        vv[i] = bkv;
    }

    vsum = 0;
    bkx = 0;
    bkv = 0;

    ll ans = 0;

    for (int i = N - 1; 0 <= i; i--)
    {
        vsum += xv[i].second;

        ll Bx = C - xv[i].first;
        ll Bv = vsum - Bx;

        ll Ax = 0;
        ll Av = 0;

        if (bkv < Bv)
        {
            if (i != 0)
            {
                Ax = vx[i - 1];
                Av = vv[i - 1];
            }

            bkx = Bx;
            bkv = Bv;
        }

        // O B O A
        ans = max(ans, Av + bkv - bkx);
        // O A O B
        ans = max(ans, bkv + Av - Ax);
    }

    // O A
    ans = max(ans, vv[N - 1]);

    // O B
    ans = max(ans, bkv);

    cout << ans << endl;
    return 0;
}

