	for(int i = 0; i < n; i++){
		scanf("%lld %d",&x[i],&v[i]);
	}
	for(int i = 0; i < n; i++) dp[0][i] = dp[1][i] = -inf;
	long long sum = 0;
	for(int i = 0; i < n; i++){
		sum += v[i];
		dp[0][i] = max(dp[0][i - 1], sum - x[i]);
		m[0][i] = sum - 2 * x[i];
	}
	sum = 0;
	for(int i = n - 1; i >= 0; i--){
		sum += v[i];
		dp[1][i] = max(dp[1][i + 1], sum - (c - x[i]));
		m[1][i] = sum - 2 * (c - x[i]);
	}
	ans = max(dp[0][n-1], dp[1][0]);
	for(int i = 0; i < n; i++){
		ans = max(ans, m[0][i] + dp[1][i + 1]);
		ans = max(ans, m[1][n - i] + dp[0][n - i - 1]);
	}
	if(ans != 0)
		printf("%lld\n",ans);
	else
		printf("0\n");
return 0;
