using namespace std;

signed main(){
	int n,c;
	cin>>n>>c;
	int x[n+1],v[n+1];
	rep(i,n)cin>>x[i+1]>>v[i+1];
	x[0]=v[0]=0;
	int l[n+1],r[n+1],f[n+1],lw[n+1],rw[n+1],fw[n+1];
	rep(i,n+1){
		if(i==0){
			l[i]=f[i]=lw[i]=fw[i]=0;
		}else{
			l[i]=l[i-1]+x[i-1]+v[i]-x[i];
			lw[i]=lw[i-1]+2*x[i-1]+v[i]-x[i]*2;
			f[i]=max(f[i-1],l[i]);
			fw[i]=max(fw[i-1],lw[i]);
		}
	}
	for(int i=n;i>0;i--){
		if(i==n){
			r[i]=v[i]-(c-x[i]);
			rw[i]=v[i]-2*(c-x[i]);
		}else{
			r[i]=r[i+1]+(c-x[i+1])+v[i]-(c-x[i]);
			rw[i]=rw[i+1]+2*(c-x[i+1])+v[i]-2*(c-x[i]);
		}
	}
	r[0]=rw[0]=0;
	int ans=0;
	rep(b,n+1){
		int res=(b-1+n+1)%(n+1);
		ans=max(ans,max(r[b]+fw[res],rw[b]+f[res]));
	}
	cout<<ans<<endl;
	return 0;
}

