}x[MaxN + 5];

bool cmp(struct xxx a1,struct xxx b1)
{
	return a1.f < b1.f;
}

struct yyy
{
	long long sum;
	long long mAx;
	long long hf;
}a[MaxN + 5],b[MaxN + 5];

int main()
{
	long long c,n,ans,piu,biu;
	while(~scanf("%lld %lld",&n,&c))
	{
		memset(x,0,sizeof(x));
		memset(a,0,sizeof(a));
		memset(b,0,sizeof(b));
		ans = 0;
		for(long long i = 1;i <= n;i++)
		{
			scanf("%lld %lld",&x[i].z,&x[i].v);
			a[i].sum = a[i - 1].sum + x[i].v - x[i].z + x[i - 1].z;
			ans = max(ans,a[i].sum);
			if(a[i - 1].mAx < a[i].sum)
			{
				a[i].hf = x[i].z;
				a[i].mAx = a[i].sum;
			}
			else
			{
				a[i].hf = a[i - 1].hf;
				a[i].mAx = a[i - 1].mAx;
			}
			x[i].f = c - x[i].z;
		}
		sort(x + 1, x + 1 + n,cmp);
		for(long long i = 1;i <= n;i++)
		{
			b[i].sum = b[i - 1].sum + x[i].v - x[i].f + x[i - 1].f;
			ans = max(ans,b[i].sum);
			if(b[i - 1].mAx < b[i].sum)
			{
				b[i].hf = x[i].f;
				b[i].mAx = b[i].sum;
			}
			else
			{
				b[i].hf = b[i - 1].hf;
				b[i].mAx = b[i - 1].mAx;
			}
		}
		piu = 0;
		for(long long i = 1;i < n;i++)
		{
			piu = a[i].mAx - a[i].hf + b[n - i].mAx;
			ans = max(ans,piu);
			piu += a[i].hf - b[n - i].hf;
			ans = max(ans,piu);
		}
		printf("%lld\n",ans);
	}
	return 0;
}

