int main(void){
    ll N,C; cin >> N >> C;
    vector<ll> x(N), v(N), rx(N); REP(i,N) cin >> x[i] >> v[i];
    vector<ll> val(N), rval(N);
    REP(i,N){
        val[i] = v[i]-x[i];
        rval[N-i-1] = v[i]-(C-x[i]);
        rx[i] = C-x[N-i-1];
    }

    VI nxt_plus(N), rnxt_plus(N);
    int next = -1;
    REP(i,N){
        if(val[i] > 0){nxt_plus[i] = next; next = i;}
        else nxt_plus[i] = next;
    }
    next = -1;
    REP(i,N){
        if(rval[i] > 0){rnxt_plus[i] = next; next = i;}
        else rnxt_plus[i] = next;
    }

    vector<ll> sum_ene(N,0), rsum_ene(N,0);
    sum_ene[0] = v[0]; rsum_ene[0] = v[N-1];
    REP(i,N-1) sum_ene[i+1] = sum_ene[i] + v[i+1];
    REP(i,N-1) rsum_ene[i+1] = rsum_ene[i] + v[N-i-2];

    ll ene = 0, cal = 0, ans = 0;
    REP(i,N-1){
        if(val[i] <= 0) continue;
        ene = sum_ene[i];
        cal = 2*x[i];
        ll add_ene=0, add_cal=0;
        if(rval[N-i-2] > 0){
            add_ene = rsum_ene[N-i-2];
            add_cal = C - x[N-i-2];
        }
        else{
            if(rnxt_plus[N-i-2] != -1){
                add_ene = rsum_ene[rnxt_plus[N-i-2]];
                add_cal = rx[rnxt_plus[N-i-2]];
            }
        }
        ene += add_ene;
        cal += add_cal;
        chmax(ans, ene-cal);
    }

    REP(i,N-1){
        if(rval[i] <= 0) continue;
        ene = rsum_ene[i];
        cal = 2*rx[i];
        ll add_ene=0, add_cal=0;
        if(val[N-i-2] > 0){
            add_ene = sum_ene[N-i-2];
            add_cal = x[N-i-2];
        }
        else{
            if(nxt_plus[N-i-2] != -1){
                add_ene = sum_ene[nxt_plus[N-i-2]];
                add_cal = x[nxt_plus[N-i-2]];
            }
        }
        ene += add_ene;
        cal += add_cal;
        chmax(ans, ene-cal);
    }

    if(val[N-1] > 0) chmax(ans, sum_ene[N-1]-x[N-1]);
    else{
        if(nxt_plus[N-1] != -1){
            chmax(ans, sum_ene[nxt_plus[N-1]]-x[nxt_plus[N-1]]);
        }
    }
    if(rval[N-1] > 0) chmax(ans, rsum_ene[N-1]-(C-x[0]));
    else{
        if(rnxt_plus[N-1] != -1){
            chmax(ans, rsum_ene[rnxt_plus[N-1]]-rx[rnxt_plus[N-1]]);
        }
    }

    cout << ans << endl;
    return 0;
}

