    for (int i = 0; i < n; i++) cin >> x[i] >> v[i];
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            l1[i] = v[i] - x[i];
        } else {
            l1[i] = l1[i - 1] + v[i] - (x[i] - x[i - 1]);
        }
        l2[i] = l1[i] - x[i];
    }
    for (int i = n - 1; i >= 0; i--) {
        if (i == n - 1) {
            r1[i] = v[i] - (c - x[i]);
        } else {
            r1[i] = r1[i + 1] + v[i] - (x[i + 1] - x[i]);
        }
        r2[i] = r1[i] - (c - x[i]);
    }
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            l1[i] = (0 > l1[i] ? 0 : l1[i]);
            l2[i] = (0 > l2[i] ? 0 : l2[i]);
        } else {
            l1[i] = max(l1[i], l1[i - 1]);
            l2[i] = max(l2[i], l2[i - 1]);
        }
    }
    for (int i = 0; i <= n; i++) {
        if (i == 0) {
            res1 = r1[0];
            res2 = r2[0];
        } else if (i == n) {
            res1 = max(res1, l2[i - 1]);
            res2 = max(res2, l1[i - 1]);
        } else {
            res1 = max(res1, r1[i] + l2[i - 1]);
            res2 = max(res2, r2[i] + l1[i - 1]);
        }
    }
    cout << max(res1, res2) << endl;
}

