  }

  ll ma = 0;
  REP(i, N + 1) {
    if (ma < X[i].second - X[i].first)
      ma = X[i].second - X[i].first;
    A[i] = ma;
  }
  ma = 0;
  for (ll i = N; i > 0; i--) {
    if (ma < X[N].second - X[i - 1].second - (C - X[i].first))
      ma = X[N].second - X[i - 1].second - (C - X[i].first);
    B[i] = ma;
  }

  ll ans = 0;
  FOR(i, 1, N + 1) {
    ans = max(ans, X[i].second - X[i].first);
    ans = max(ans, X[i].second - (2 * X[i].first) + B[i + 1]);
  }
  for (ll i = N; i > 0; i--) {
    ans = max(ans, X[N].second - X[i - 1].second - (C - X[i].first));
    ans = max(ans, A[i - 1] + X[N].second - X[i - 1].second -
                       (2 * (C - X[i].first)));
  }

  cout << ans << endl;
  return 0;
}

