using namespace std;
typedef long long ll;
typedef vector<int> vi;
typedef vector<long long> vl;

int main() {
    ll N, C;
    cin >> N >> C;
    vl X(N), V(N);
    rep(i, N) {
        cin >> X[i] >> V[i];
    }

    // 先頭からみる用のvector
    vl AX(N + 1), AV(N + 1);
    rep(i, N) { AX[i + 1] = X[i]; AV[i + 1] = V[i]; }
    rep(i, N) { AV[i + 1] += AV[i]; }

    // 後ろからみる用のvecotr
    vl BX(N + 1), BV(N + 1);
    rep(i, N) { BX[i + 1] = C - X[N - i - 1]; BV[i + 1] = V[N - i - 1]; }
    rep(i, N) { BV[i + 1] += BV[i]; }

    // AとBの組み合わせを全探索したのではO(N^2)なので間に合わない
    // Aの要素を固定した時の最大のBを事前に計算しておく(s2 - d2)
    vl BM(N + 1);
    ll tmpbmax = 0;
    for (int i = 0; i < N + 1; i++) {
        ll b = BV[i] - BX[i];
        if (b > tmpbmax) {
            tmpbmax = b;
        }
        BM[i] = tmpbmax;
    }

    // Bの要素を固定した時の最大のAを事前に計算しておく(s1 - d1)
    vl AM(N + 1);
    ll tmpamax = 0;
    for (int i = 0; i < N + 1; i++) {
        ll a = AV[i] - AX[i];
        if (a > tmpamax) {
            tmpamax = a;
        }
        AM[i] = tmpamax;
    }

    ll ans = 0;
    // (s1 - 2 * d1) + (s2 - d2)のパターン
    for (int i = 0; i < N + 1; i++) {
        ll d1 = AX[i];
        ll s1 = AV[i];
        ans = max(ans, (s1 - 2 * d1 + BM[N - i]));
    }

    // (s2 - 2 * d2) + (s1 - d1)のパターン
    for (int i = 0; i < N + 1; i++) {
        ll d2 = BX[i];
        ll s2 = BV[i];
        ans = max(ans, (s2 - 2 * d2 + AM[N - i]));
    }

    cout << ans << endl;
}

