int dx[] = {1, -1, 0, 0};

ll N, C;

ll solve(vector<ll> x, vector<ll> v) {
    vector<ll> S(N+1, 0);
    REP(i, N) S[i+1] = S[i] + v[i];
    REP(i, N) S[i+1] -= 2 * x[i];

    vector<ll> rev(N+1, 0);
    RREP(i, N-1) rev[i] = rev[i+1] + v[i];
    RREP(i, N-1) rev[i] -= (C - x[i]);

    ll max_rev = 0;
    RREP(i, N) rev[i] = max_rev = max(max_rev, rev[i]);

    ll res = -inf;
    REP(i, N+1) {
        ll val = 0;

        val += S[i];
        val += rev[i+1];

        res = max(res, val);
    }
    return res;
}

