	vector<ll> right, left;
	ll sum = 0;
	for (int i = 1;i <= n;i++) {
		sum -= x[i] - x[i - 1];
		sum += v[i];
		right.push_back(sum);
		ans = max(ans, sum);
	}
	sum = 0;
	for (int i = n;i >= 1;i--) {
		sum -= x[i + 1] - x[i];
		sum += v[i];
		left.push_back(sum);
		ans = max(ans, sum);
	}

	vector<ll> right_max, left_max;
