int main_D() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, C; cin >> N >> C;
    vl X(N + 2, 0), V(N + 2, 0);
    FOR(i, 1, N + 1) cin >> X[i] >> V[i];
    X[N + 1] = C;

    // clockwise
    vl dpR(N + 2, 0);
    // dpR[i] := max cal to get from [0,i] 
    ll sum = 0;
    FOR(i, 1, N + 1) {
        sum += V[i];
        sum -= (X[i] - X[i - 1]);
        dpR[i] = max(dpR[i - 1], sum);
    }

    // counter clockwise
    // dpL[i] := max cal to get from [N,i] 
    vl dpL(N + 2, 0);
    sum = 0;
    for (int i = N; i >= 1; i--) {
        sum += V[i];
        sum -= (X[i] - X[i + 1]);
        dpL[i] = max(dpL[i + 1], sum);
    }

    ll ans = 0;
    FOR(i, 0, N + 1) {
        ans = max(ans, dpR[i] - X[i] + dpL[i + 1]);
        ans = max(ans, dpL[i + 1] - (C - X[i + 1]) + dpR[i]);
    }

    return 0;
}

