void dfs(long long pre,long long bef)
{
	long long i;
	ans=max(ans,pre);
	for(i=0;i<n;i++)
	{
		if(!book[i])
		{
			if(abs(x[i]-bef)>v[i]&&abs(c+bef-x[i])>v[i])
			{
				continue;
			}
			book[i]=true;
			if(abs(x[i]-bef)>abs(c+bef-x[i]))
			{
				dfs(pre+v[i]-abs(c+bef-x[i]),x[i]);
			}
			else
			{
				dfs(pre+v[i]-abs(x[i]-bef),x[i]);
			}
			book[i]=false;
		}
	}
}
