  vector < int64_t > pref(n + 2, 0), suff(n + 2, 0), max_suff(n + 2, 0);
  for (int i = 1; i <= n; ++i) {
    sum += v[i];
    pref[i] = sum - x[i];
    res = max(res, pref[i]);
  }
  sum = 0;
  for (int i = n; i; --i) {
    sum += v[i];
    suff[i] = sum - (c - x[i]);
    max_suff[i] = max(max_suff[i + 1], suff[i]);
    res = max(res, pref[i] + max_suff[i + 1] - x[i]);
  }
  return res;
}

