  int64_t ans = max(int64_t(0), solve());
  reverse(x + 1, x + n + 1);
  reverse(v + 1, v + n + 1);
  for (int i = 1; i <= n; ++i)
    x[i] = c - x[i];
  cout << (ans = max(ans, solve())) << '\n';
}

