	vector<ll> vbmin( N + 1 );
	vb[0] = vbmax[0] = vbmin[0] = 0;
	rep( i, N )
	{
		vb[i + 1] = vb[i] + v[N - 1 - i].S;
	}
	rep( i, N )
	{
		vb[i + 1] = vb[i + 1] - ( C - v[N - 1 - i].F );
	}
	rep( i, N )
	{
		vbmax[i + 1] = max( vbmax[i], vb[i + 1] );
		vbmin[i + 1] = ( C - v[N - 1 - i].F );
	}

	ll max = 0;
	rep( i, N )
	{
		chmax( max, vamax[N - 1 - i] + vbmax[i] - min( vamin[N - 1 - i], vbmin[i] ) );
	}

	cout << max << endl;

	return ( 0 );
}

