ll res = 0;

ll mymax(ll a, ll b)
{
  if (a > b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

ll mymin(ll a, ll b)
{
  if (a < b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

int main()
{
  cin >> N >> C;
  v = vector<ll>(N);
  x = vector<ll>(N);
  l = vector<ll>(N);
  r = vector<ll>(N);
  rmax = vector<ll>(N);
  lmax = vector<ll>(N);

  for (int i = 0; i < N; i++)
  {
    cin >> x[i] >> v[i];
  }
  for (int i = 0; i < N; i++)
  {
    r[i] = (i == 0 ? 0 : r[i - 1]) + v[i] - (x[i] - (i == 0 ? 0 : x[i - 1]));
  }
  for (int i = N - 1; i >= 0; i--)
  {
    if (i == N - 1)
    {
      l[i] = v[i] - (C - x[i]);
    }
    else
    {
      l[i] = v[i] + l[i + 1] - (x[i + 1] - x[i]);
    }
    if (i == N - 1)
    {
      lmax[i] = i;
      continue;
    }
    if (l[lmax[i + 1]] <= l[i])
    {
      lmax[i] = i;
    }
    else
