    if (i != N - 1)
    {
      res = mymax(res, l[lmax[i + 1]]);
      temp += l[lmax[i + 1]];
      res = mymax(res, temp - mymin(x[i], (C - x[lmax[i + 1]])));
    }
    else
    {
      res = mymax(res, l[0]);
    }
  }

  cout << res << endl;
  return 0;
}

