template<class T>bool chmax(T &a, const T &b) { if (b > a) { a = b; return true; } return false; }
template<class T>bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

constexpr int dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
constexpr int INF = 1e9;
constexpr long long LINF = 1e18;
#pragma endregion

void solve(){
    int N;
    ll C;
    cin >> N >> C;
    vector<pair<ll, ll>> sushi(N);
    for (int i=0; i<N; i++) {
        cin >> sushi.at(i).first >> sushi.at(i).second;
    }
    vector<ll> forw(N+1), rev(N+1), disForw(N+1), disRev(N+1);
    for (int i=1; i<N+1; i++) {
        forw.at(i) = sushi.at(i-1).second;
        rev.at(i) = sushi.at(N-i).second;
        disForw.at(i) = sushi.at(i-1).first;
        disRev.at(i) = C - sushi.at(N-i).first;
    }
    for (int i=1; i<N+1; i++) {
        forw.at(i) += forw.at(i-1);
        rev.at(i) += rev.at(i-1);
    }
    for (int i=1; i<N+1; i++) {
        forw.at(i) -= disForw.at(i);
        rev.at(i) -= disRev.at(i);
    }
    for (int i=1; i<N+1; i++) {
        if (chmax(forw.at(i), forw.at(i-1))) disForw.at(i) = disForw.at(i-1);
        if (chmax(rev.at(i), rev.at(i-1))) disRev.at(i) = disRev.at(i-1);
    }
    ll ans = -LINF;
    for (int i=0; i<N+1; i++) {
        if (i == N) {
            chmax(ans, forw.at(i));
        } else if (i == 0) {
            chmax(ans, rev.at(N));
        } else {
            chmax(ans, forw.at(i) + rev.at(N-i) - min(disForw.at(i), disRev.at(N-i)));
        }
    }

    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

