    LL benefit_back = acum_ccw[i] - 2 * (C - sushi[i].first);
    if (i == N - 1) {
      best = benefit;
      best_back = benefit_back;
      best_ccw[i] = best_ccw_back[i] = i;
      continue;
    }
    best_ccw[i] = best_ccw[i + 1];
    best_ccw_back[i] = best_ccw_back[i + 1];

    if (benefit > best) {
      best = benefit;
      best_ccw[i] = i;
    }

    if (benefit_back > best_back) {
      best_back = benefit_back;
      best_ccw_back[i] = i;
    }
  }

  best = 0;
  for (int i = 0; i < N-1; ++i) {
    LL walk_cw = sushi[i].first;
    LL benefit_cw = acum_cw[i];
    LL benefit_one_dir = benefit_cw - walk_cw;
    best = max(best, benefit_one_dir);


    LL pos_ccw = best_ccw[i + 1];
    LL walk_ccw = C - sushi[pos_ccw].first;
    LL benefit_ccw = acum_ccw[pos_ccw];
