    LL pos_ccw_back = best_ccw_back[i + 1];
    LL walk_ccw_back = C - sushi[pos_ccw_back].first;
    LL benefit_ccw_back = acum_ccw[pos_ccw_back];
    LL benefit_two_dir_back = benefit_one_dir + benefit_ccw_back - 2*walk_ccw_back;
    best = max(best, benefit_two_dir_back);
  }

