int main(){
  int N;
  ll C;
  cin >> N >> C;
  vector<ll> X(N+1, 0), V(N+1, 0);
  for(int i=0; i<N; i++)
    cin >> X[i+1] >> V[i+1];

  // 累積和
  vector<ll> sum(N+1, 0);
  sum[0] = 0;
  for(int i=1; i<N+1; i++)
    sum[i] = sum[i-1] + V[i];

  // f(a) := v0 + v1 + ... + va - xa
  vector<ll> F(N+1, 0);
  F[0] = 0;
  for(int i=1; i<N+1; i++)
    F[i] = sum[i] - X[i];

  // g(a) := max(f(0), f(1), ... , f(a))
  vector<ll> G(N+1, 0);
  vector<ll> Gpos(N+1, 0);
  G[0] = 0;
  Gpos[0] = 0;
  for(int i=1; i<N+1; i++)
    if(G[i-1] < F[i]){
      G[i] = F[i];
      Gpos[i] = X[i];
    } else {
      G[i] = G[i-1];
      Gpos[i] = Gpos[i-1];
    }

  ll ans = max(G[N], 0LL); // xb = 0

  // xa = 0
  for(int i=1; i<N; i++)
    if(ans < sum[N] - sum[i-1] - (C - X[i]))
      ans = sum[N] - sum[i-1] - (C - X[i]);

  for(int i=1; i<N+1; i++){
    ll fb = sum[N] - sum[i-1] - (C - X[i]);
    ll tmp = fb + G[i-1] - min(C - X[i], Gpos[i-1]);
    if(tmp > ans){
      ans = tmp;
    }
  }

  cout << ans << endl;
  return 0;
}

