/*
题目大意： 一个圈上有寿司，走的路程长度为消耗的能量，吃的的寿司为得到的能量，问最多获得能量是多少。

分析：

人走的方式有四种方式；

1、顺时针走，得到最大值

2、逆时针走，得到最大值

3、先顺时针，再返回起点，再逆时针

4、先逆时针，再返回起点，再顺时针

人为了得到最大能量，最多返回一次

首先计算出顺时针走到每个点的值a[i], 再计算出逆时针的每个点最终的能量值b[i]。 

若有返回，如顺时针则为a[i] - x[i] (回到起点消耗下x[i]) , 然后加上逆时针走到b[i + 1]的值。即a[i] - x[i] + b[i + 1];

然后四种情况进行一次比较*/

// https://atcoder.jp/contests/abc095/tasks/arc096_b
#include <bits/stdc++.h>
using namespace std;
#define int long long
#define REP(i, n) FOR(i, 0, n)
#define REPR(i, n) for (int i = n - 1; i >= 0; i--)
#define FOR(i, s, n) for (int i = (s), i##_len = (n); i < i##_len; ++i)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()
#define DIV(a, b) ((a - 1) / b + 1)

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, C;
    cin >> N >> C;
    vector<pair<int, int>> v;
    REP(i, N) {
        int a, b;
        cin >> a >> b;
        v.emplace_back(a, b);
    }
    sort(ALL(v));
    // 累積和
    vector<int> s(2 * N + 1);
    int ans = 0;
    REP(i, 2 * N) { s[i + 1] = s[i] + v[i % N].second; }
    REP(i, N) {
        FOR(j, i, i + N) {
            int t = s[j + 1] - s[i] - v[j % N].first - (j >= N ? C : 0);
            ans = max(ans, t);
        }
    }
    cout << ans << endl;

    return 0;
}

