using Sushi = vector<long long>;
bool chmax(long long& a, long long b) { if (a < b) { a = b; return 1; } return 0; }

long long solve(int n, Sushi sl, Sushi sr, Sushi x) {
    vector<long long> max_s(n+1, 0);
    for (int i = 1; i <= n; i++) max_s[i] = max(max_s[i-1], sr[i]);

    long long ret = 0;
    for (int i = 0; i <= n; i++) {
        long long eat = sl[i];
        long long nxt = max_s[n-i] - x[i];
        if (nxt > 0) eat += nxt;
        chmax(ret, eat);
    }

    return ret;
}

int main() {
    int n;
    long long c;
    cin >> n >> c;
    Sushi x(n+2, 0), v(n+2, 0); x[n+1] = c;
    for (int i = 1; i <= n; i++) cin >> x[i] >> v[i];

    vector<long long> sl(n+1, 0), sr(n+1, 0);
    for (int _ = 0; _ < 2; _++) {
        if (_ == 0) {
            for (int i = 1; i <= n; i++) sl[i] = sl[i-1] + v[i];
            for (int i = 1; i <= n; i++) sl[i] -= x[i];
        } else {
            for (int i = 1; i <= n; i++) sr[i] = sr[i-1] + v[i];
            for (int i = 1; i <= n; i++) sr[i] -= abs(c - x[i]);
        }
        reverse(v.begin(), v.end());
        reverse(x.begin(), x.end());
    }

    long long ans = max(solve(n, sl, sr, x), solve(n, sr, sl, x));
    cout << ans << endl;
    return 0;
}

