int main() {
    fastio();

    cin >> n >> c;
    forn1(i, n) cin >> x[i] >> v[i];

    ll total = 0;
    forn1(i, n) {
        total += v[i];
        r[i] = max(r[i - 1], total - x[i]);
    }

    total = 0;
    for (int i = n; i >= 1; i--) {
        total += v[i];
        l[i] = max(l[i + 1], total - (c - x[i]));
    }

    ll ans = 0;

    total = 0;
    forn1(i, n) {
        total += v[i];
        ll temp = total - x[i];
        chmax(ans, max(temp, temp - x[i] + l[i + 1]));
    }

    total = 0;
    for (int i = n; i >= 1; i--) {
        total += v[i];
        ll temp = total - (c - x[i]);
        chmax(ans, max(temp, temp - (c - x[i]) + r[i - 1]));
    }

    cout << ans << endl;

    return 0;
}

