using namespace std;

int main() {
	long long int n,c;
	cin >> n >> c;
	long long int x[n],v[n];
	for(int i = 0; i < n; i++) {
		cin >> x[i] >> v[i];
	}
	long long int ans = 0;
	// cw-0
	long long int now = 0;
	long long int tmp = 0;
	for(int i = 0; i < n; i++) {
		ans = max(ans,tmp);
		tmp = tmp + v[i] - (x[i] - now);
		now = x[i];
	}
	ans = max(ans,tmp);


	// cw-1
	now = 0;
	tmp = 0;
	for(int i = 0; i < n; i++) {
		tmp = tmp + v[i] - (x[i] - now);
		long long int ccTmp = tmp;

		tmp = tmp - x[i];
		now = c;

		for(int j = n-1; j > i; j--) {
			ans = max(ans,tmp);
			tmp = tmp + v[j] - (now - x[j]);
			now = x[j];
			ans = max(ans,tmp);
		}
		tmp = ccTmp;
		now = x[i];
	}


	// ccw-0

	now = c;
	tmp = 0;

	for(int i = n-1; i >= 0; i--) {
		ans = max(ans,tmp);
		tmp = tmp + v[i] - (now - x[i]);
		now = x[i];
	}
	ans = max(ans,tmp);



	// ccw-1

	now = c;
	tmp = 0;
	for(int i = n-1; i >= 0; i--) {
		tmp = tmp + v[i] - (now - x[i]);
		long long int ccTmp = tmp;

		tmp = tmp - (c - x[i]);
		now = 0;

		for(int j = 0; j < i; j++) {
			ans = max(ans,tmp);
			tmp = tmp + v[j] - (x[j] - now);
			now = x[j];
			ans = max(ans,tmp);
		}


		tmp = ccTmp;
		now = x[i];
	}



	cout << ans << endl;



}

