	for (int i = 1; i <= n; ++i) {
		ll minus = i - 2 >= 0 ? a[i - 2].x : 0;
		pref1[i] = pref1[i - 1] + a[i - 1].v - (a[i - 1].x - minus);
		max_pref1[i] = max(max_pref1[i - 1], pref1[i]);
	}
	vector<Sushi> b(n);
	for (int i = 0; i < n; ++i) {
		b[i].x = C - a[i].x;
		b[i].v = a[i].v;
	}
	reverse(b.begin(), b.end());
	for (int i = 1; i <= n; ++i) {
		ll minus = i - 2 >= 0 ? b[i - 2].x : 0;
		pref2[i] = pref2[i - 1] + b[i - 1].v - (b[i - 1].x - minus);
		max_pref2[i] = max(max_pref2[i - 1], pref2[i]);
	}

	//~ debug(pref1, pref2);
	//~ for (int i = 0; i < n; ++i) {
		//~ cout << a[i].x << ' ';
	//~ }
	//~ cout << '\n';
	//~ for (int i = 0; i < n; ++i) {
		//~ cout << b[i].x << ' ';
	//~ }
	//~ cout << '\n';
	ll answer = 0;
	for (int cnt1 = 0; cnt1 <= n; ++cnt1) {
		ll minus = cnt1 == 0 ? 0 : a[cnt1 - 1].x;
		ll cur = pref1[cnt1];
		cur += max_pref2[n - cnt1];
		answer = max(answer, cur - minus);
	}
	for (int cnt1 = 0; cnt1 <= n; ++cnt1) {
		ll minus = cnt1 == 0 ? 0 : b[cnt1 - 1].x;
		ll cur = pref2[cnt1];
		cur += max_pref1[n - cnt1];
		answer = max(answer, cur - minus);
	}
	cout << answer << '\n';
 	return 0;
}

