void dfs_pos2(ll cal, ll now, ll pre, ll turn, ll eat)
{
    cal += data[now].second;
    if (turn == 1)
    {
        cal -= llabs(data[now].first + (c - data[pre].first));
    }
    else
    {
        cal -= llabs(data[now].first - data[pre].first);
    }
    eat++;
    chmax(ans, cal);
    if (eat == n)
    {
        return;
    }
    dfs_pos2(cal, now + 1, now, turn + 1, eat);
}
void dfs_neg(ll cal, ll now, ll pre, ll turn, ll eat)
{
    cal += data[now].second;
    if (eat == 0)
    {
        cal -= c - data[now].first;
    }
    else
    {
        if (turn == 1)
        {
            cal -= llabs(data[pre].first + (c - data[now].first));
        }
        else
        {
            cal -= llabs((c - data[now].first) - (c - data[pre].first));
        }
    }

    eat++;
    chmax(ans, cal);
    if (eat == n)
    {
        return;
    }
    if (turn == 0)
    {
        dfs_pos2(cal, 0, now, turn + 1, eat);
        dfs_neg(cal, now - 1, now, turn, eat);
    }
    else
    {
        dfs_neg(cal, now - 1, now, turn + 1, eat);
    }
}
void dfs_pos1(ll cal, ll now, ll pre, ll turn, ll eat)
{
    cal += data[now].second;
    if (eat == 0)
    {
        cal -= data[now].first;
    }
    else
    {
        cal -= llabs(data[now].first - data[pre].first);
    }
    eat++;
    chmax(ans, cal);
    if (eat == n)
    {
        return;
    }
    if (turn == 0)
    {
        dfs_neg(cal, n - 1, now, turn + 1, eat);
        dfs_pos1(cal, now + 1, now, turn, eat);
    }
    else
    {
        dfs_pos1(cal, now + 1, now, turn + 1, eat);
    }
}
