struct dist_cal {ll dist, cal;};

ll n, c;
vector<dist_cal> xv;
vector<dist_cal> xv_rev;

ll ans;

ll solve(vector<dist_cal> dsv) {
  /****************************************************/
  ll score_a[MAX_N];
  ll score_b[MAX_N];
  ll score_g[MAX_N];

  ll tmp_a = 0;
  for (int i = 0; i < dsv.size(); ++i) {
    tmp_a += dsv[i].cal;
    score_a[i] = tmp_a - dsv[i].dist;
  }

  ll tmp_b = 0;
  for (int i = n - 1; i >= 0; --i) {
    tmp_b += dsv[i].cal;
    score_b[i] = tmp_b - (c - dsv[i].dist);
  }

  score_g[0] = 0;
  for (int i = 1; i < dsv.size(); ++i) {
    score_g[i] = max(score_g[i - 1], score_a[i - 1]);
  }

  // ll last_max = score_g[n - 1];
  for (int i = n - 1; i >= 0; --i) {
    ll cur_score = score_b[i] - (c - dsv[i].dist) + score_g[i];
    last_max = max(last_max, cur_score);
  }
  /****************************************************/

  return last_max;
}

int main(void) {
  // Here your code !
	scanf("%lld %lld", &n, &c);
	for (ll i = 0; i < n; ++i) {
    ll x, v;
    scanf("%lld %lld", &x, &v);
    dist_cal tmp;
    tmp.dist = x;
    tmp.cal = v;
    xv.push_back(tmp);
  }

  for (int i = 0; i < xv.size(); ++i) {
    dist_cal tmp;
    tmp.dist = c - xv[i].dist;
    tmp.cal = xv[i].cal;
    xv_rev.push_back(tmp);
  }

  sort(xv.begin(), xv.end(), [](dist_cal a, dist_cal b) { return a.dist < b.dist; });
  sort(xv_rev.begin(), xv_rev.end(), [](dist_cal a, dist_cal b) { return a.dist < b.dist; });

  ans = max(solve(xv), solve(xv_rev));
  ans = max(ans, (ll)0);

  printf("%lld\n", ans);

	return 0;
}

