ll N,C;

ll func(vector<ll>&vec_x, vector<ll>&vec_v){
  vector<ll>max_values;
  ll max_value = 0;
  ll sum_v = 0;

  for(int i = 0 ; i < N ; i++){
    sum_v += vec_v[i];
    max_values.push_back(max_value);
    max_value = max(max_value,sum_v - (vec_x[i]) * 2);
  }
  max_values.push_back(max_value);

  sum_v = 0;
  ll ret = 0;
  for(int i = N-1 ; i >= 0 ; i--){
    sum_v += vec_v[i];
    ret = max(ret, sum_v - (C - vec_x[i]) + max_values[max(0,i-1)]);
  }

  return ret;
}

int main(){
  cin >> N >> C;
  vector<ll>vec_x,vec_v;
  for(int i = 0 ; i < N ; i++){
    ll x,v;
    cin >> x >> v;
    vec_x.push_back(x);
    vec_v.push_back(v);
  }
  ll res = 0;
  res = func(vec_x, vec_v);
  reverse(vec_x.begin(), vec_x.end());
  for(int i = 0 ; i < vec_x.size() ; i++){
    vec_x[i] = (C - vec_x[i]);
  }
  reverse(vec_v.begin(), vec_v.end());
  res = max(res,func(vec_x, vec_v));
  cout << res << endl;
  return 0;
}

