  for (uint32_t n = 0; n < N; ++n) {
    uint64_t x;
    uint32_t v;
    cin >> x >> v;
    X.push_back(x);
    V.push_back(v);
  }

  X.push_back(C);
  V.push_back(0);

  cout << exec() << endl;

  return 0;
}

