int solve(int N, int C, const std::vector<int>& x, const std::vector<int>& v) {
	int res = 0;
	int tmp = 0;
	int pos = 0;
	std::map<int, int>m;
	for (int i = 0; i < N; ++i) {
		tmp += v[i];
		tmp -= x[i] - pos;
		pos = x[i];
		MAX(res, tmp);
		m.insert({ pos,res });
