ll solve(dist_cal *dsv) {
  /****************************************************/
  ll score_a[MAX_N];
  ll score_b[MAX_N];
  ll score_g[MAX_N];

  ll tmp_a = 0;
  score_a[0] = 0;
  for (ll i = 1; i <= n; ++i) {
    tmp_a += dsv[i].cal;
    score_a[i] = tmp_a - dsv[i].dist;
  }

  ll tmp_b = 0;
  score_b[0] = 0;
  for (ll i = n; i >= 1; --i) {
    tmp_b += dsv[i].cal;
    score_b[i] = tmp_b - (c - dsv[i].dist);
  }

  score_g[0] = score_a[0];
  for (ll i = 1; i <= n; ++i) {
    score_g[i] = max(score_g[i - 1], score_a[i]);
  }

  ll last_max = score_g[n];
  for (ll i = n; i >= 1; --i) {
    ll cur_score = score_b[i] - (c - dsv[i].dist) + score_g[i - 1];
    last_max = max(last_max, cur_score);
  }
  /****************************************************/

  return last_max;
}

