ll c;
ll fun(vi &x,vi &v)
{
    ll n=sz(x);
    vi clock(n,0);
    for(ll i=0;i<n;i++)
    {
        clock[i]=v[i]-x[i];
        if(i)
        {
            clock[i]+=x[i-1];
            clock[i]+=clock[i-1];
        }
    }
    vi clock_max(clock);
    for(ll i=1;i<n;i++)
    {
        clock_max[i]=max(clock[i],clock_max[i-1]);
    }
    vi aclock(n,0);
    for(ll i=0;i<n;i++)
    {
        aclock[i]=v[n-i-1]+x[n-i-1]-c;
        if(i)
        {
            aclock[i]+=c-x[n-i];
            aclock[i]+=aclock[i-1];
        }
    }

    ll ans=0;
    for(ll n1=0;n1<=n;n1++)
    {
        //n1 number of anticlockwise numbers taken
        ll curr=0;
        ll pos=0;
        if(n1)
        {
            curr=aclock[n1-1];
            pos=x[n-n1];
        }

        ll ind=n-1-n1;
        if(ind==-1)
            ans=max(ans,curr);
        else
            ans=max(ans,max(curr,curr+clock_max[ind]-(c-pos)%c));
    }
    return ans;
}
