class DStaticSushi {
public:
	void solve(std::istream& in, std::ostream& out)
	{
        int n;
        ll c;
        in >> n >> c;
        vector<ll> x(n), v(n);
        for(int i=0; i<n; i++){
            in >> x[i] >> v[i];
        }
        vector<pair<ll, ll>> l, r;
        for(int i=0; i<n; i++){
            l.push_back(make_pair(x[i], v[i]));
            r.push_back(make_pair(c-x[i], v[i]));
        }

        sort(l.begin(), l.end());
        sort(r.begin(), r.end());

        vector<ll> lc(n+1), rc(n+1);
        lc[0] = rc[0] = 0;
        for(int i=0; i<n; i++){
            lc[i+1] = lc[i] + (l[i].second - l[i].first);
            rc[i+1] = rc[i] + (r[i].second - r[i].first);
            if(i-1 >= 0){
                lc[i+1] += l[i-1].first;
                rc[i+1] += r[i-1].first;
            }
        }

        vector<ll> lmx(n+1), rmx(n+1);
        lmx[0] = rmx[0] = 0;
        for(int i=0; i<n; i++){
            lmx[i+1] = max(lmx[i], lc[i+1]);
            rmx[i+1] = max(rmx[i], rc[i+1]);
        }

        ll res = -inf;
        for(int i=0; i<n; i++){
            chmax(res, lc[i]);
            chmax(res, rc[i]);
        }

        for(int i=0; i<=n; i++){
            ll cost = rc[i] - (i>0 ? r[i-1].first : 0) + lmx[n-i];
            chmax(res, cost);
        }

        for(int i=0; i<=n; i++){
            ll cost = lc[i] - (i>0 ? l[i-1].first : 0) + rmx[n-i];
            chmax(res, cost);
        }

        out << res << endl;
	}
};


