template<typename W, typename T> vi finds(const W &a, const T &key) {    int n = sz(a);    vi rpos(n, n);    rer(i, n - 1) {        if (i < n - 1) { rpos[i] = rpos[i + 1]; }        if (a[i] == key)rpos[i] = i;    }    return rpos;}
template<typename W, typename T> vi rfinds(const W &a, const T &key) {    int n = sz(a);    vi lpos(n, -1);    rep(i, n) {        if (i > 0) { lpos[i] = lpos[i - 1]; }        if (a[i] == key)lpos[i] = i;    }    return lpos;}
