void step(long &cal, bool tokei) {
    long pos = tokei ? 0 : c;
    for (int i = 0; i < n; i++) {
        int a = tokei ? i : n - 1 - a;
        long d = x[a] - pos;
        long t = v[i] - d;
        if (t > 0) {
            cal += t;
        } else {
            break;
        }
    }

    int r = tokei ? n - 1 : 0;
    long rd = tokei ? pos + (c - x[r]) : (c - pos) + x[r];
    if ((v[r] - rd) > 0) {
        cal -= tokei ? pos : c - pos;
        step(cal, !tokei);
    }
}

