const ll mod = 1000000007;
const ll INF = 1e16;
const ll MAX_N = 100010;

int main() {
    ll n, c;
    cin >> n >> c;

    vl x(n), v(n);
    rep(i, n) {
        cin >> x[i] >> v[i];
    }

    ll ans = 0;  // 1貫も食べないとき0

    // 時計回りにのみ進んで方向を変えないとき
    rep(i, n) {  // 寿司0から寿司iを食べるとする
        ll now = 0;
        exrep(j, 0, i) {
            now += v[j];
        }
        now -= x[i];
        chmax(ans, now);
    }

    // 反時計回りにのみ進んで方向を変えないとき
    for(ll i = n-1; i >= 0; i--) {  // 寿司n-1から寿司iを食べるとする
        ll now = 0;
        for(ll j = n-1; j >= i; j--) {
            now += v[j];
        }
        now -= (c - x[i]);
        chmax(ans, now);
    }

    // 先に時計回りに進んでから方向を変えて反時計回りに進むとき
    exrep(i, 0, n-2) {  // まず寿司0から寿司iを食べるとする
        for(ll j = n-1; j >= i+1; j--) {  // 次に寿司n-1から寿司jを食べるとする
            ll now = 0;
            exrep(k, 0, i) {
                now += v[k];
            }
            now -= 2*x[i];
            for(ll k = n-1; k >= j; k--) {
                now += v[k];
            }
            now -= (c - x[j]);
            chmax(ans, now);
        }
    }

    // 先に反時計回りに進んでから方向を変えて時計回りに進むとき
    for(ll i = n-1; i >= 1; i--) {  // まず寿司n-1から寿司iを食べるとする
        exrep(j, 0, i-1) {  // 次に寿司0から寿司jを食べるとする
            ll now = 0;
            for(ll k = n-1; k >= i; k--) {
                now += v[k];
            }
            now -= 2*(c - x[i]);
            exrep(k, 0, j) {
                now += v[k];
            }
            now -= x[j];
            chmax(ans, now);
        }
    }

    out(ans);
    re0;
}

