using namespace std;

typedef long long ll;

ll N, C;
vector<ll> v, x;
vector<ll> l, r;
vector<ll> rmax, lmax;
ll res = 0;

ll mymax(ll a, ll b)
{
  if (a > b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

ll mymin(ll a, ll b)
{
  if (a < b)
  {
    return a;
  }
  else
  {
    return b;
  }
}

int main()
{
  cin >> N >> C;
  v = vector<ll>(N);
  x = vector<ll>(N);
  l = vector<ll>(N);
  r = vector<ll>(N);
  rmax = vector<ll>(N);
  lmax = vector<ll>(N);

  for (int i = 0; i < N; i++)
  {
    cin >> x[i] >> v[i];
  }
  for (int i = 0; i < N; i++)
  {
    r[i] = (i == 0 ? 0 : r[i - 1]) + v[i] - (x[i] - (i == 0 ? 0 : x[i - 1]));
  }
  for (int i = N - 1; i >= 0; i--)
  {
    l[i] = (i == N - 1 ? 0 : l[i + 1]) + v[i] - ((i == N - 1 ? C : x[i + 1]) - x[i]);
    if (i == N - 1)
    {
      lmax[i] = i;
      continue;
    }
    if (l[lmax[i + 1]] < l[i])
    {
      lmax[i] = i;
    }
    else
    {
      lmax[i] = lmax[i + 1];
    }
  }

  //iで方向転換
  for (int i = 0; i < N; i++)
  {
    ll temp = 0;
    temp += r[i];
    res = mymax(res, temp);
    if (i != N - 1)
    {
      res = mymax(res, l[lmax[i + 1]]);
      temp += l[lmax[i + 1]];
      res = mymax(res, temp - mymin(x[i], (C - x[lmax[i + 1]])));
    }
  }

  cout << res << endl;
  return 0;
}

