using namespace std;

int main()
{
    int64_t N, C;
    std::cin >> N >> C;

    struct S {
        int64_t x;
        int64_t v;
    };

    std::deque<S> sv;
    for (size_t i = 0; i < N; ++i) {
        S s;
        std::cin >> s.x >> s.v;
        sv.push_back(s);
    }

    auto svr = sv;

    std::sort(std::begin(sv), std::end(sv),
              [](const auto& a, const auto& b) {
                  return a.x < b.x;
              });

    int64_t emax = 0;
    auto f = [&emax, &sv, C](auto F, int64_t pos, int64_t sum) -> void {
        //cerr << pos << " " << sum << endl;
        emax = std::max(emax, sum);
        if (!sv.empty()) {
            // 時計回りに食べる
            auto s = sv.front();
            //cerr << "r: "<< s.x << " " <<s.v << endl;
            sv.pop_front();
            int64_t dist;
            if (s.x > pos) {
                dist = s.x - pos;
            }
            else {
                dist = C - pos + s.x;
            }
            F(F, s.x, sum+s.v - dist);
            sv.push_front(s);

            // 反時計回りに食べる
            s = sv.back();
            //cerr << "l: "<< s.x << " " <<s.v << endl;
            sv.pop_back();
            if (s.x > pos) {
                dist = C - s.x + pos;
            }
            else {
                dist = pos - s.x;
            }

            F(F, s.x, sum+s.v - dist);
            sv.push_back(s);
        }
    };

    f(f, 0, 0);


    std::cout << emax << std::endl;

    return 0;
}

