  cin >> N >> C;
  vll x(N), v(N);
  rep(i, N) cin >> x[i] >> v[i];

  vll A(N), B(N);
  ll before_a = 0, before_b = 0;
  rep(i, N) {
    A[i] = v[i] - (x[i] - before_a);
    before_a = x[i];

    ll index = N - 1 - i;
    B[i] = v[index] - (C - x[index] - before_b);
    before_b = C - x[index];
  }

  vll Am(N), Bm(N);
  ll ma = 0, mb = 0;
  ll ca = 0, cb = 0;
  rep(i, N) {
    ca += A[i];
    cb += B[i];
    chmax(ma, ca);
    chmax(mb, cb);
    Am[i] = ma;
    Bm[i] = mb;
  }

  ll ans = 0;
  ll current_a = 0, current_b = 0;
  rep(i, N) {
    current_a += A[i];
    chmax(ans, current_a);
    ll score_a = current_a - x[i];
    score_a += Bm[N - i - 2];
    chmax(ans, score_a);

    current_b += B[i];
    chmax(ans, current_b);
    ll score_b = current_b - (C - x[N - 1 - i]);
    score_b += Am[N - i - 2];
    chmax(ans, score_b);
  }

  ANS;
  return 0;
}

