	long long dist = 0;
	long long sum = 0;
	for (long long i = 0; i < N; i++) {
		dist = sushi[i].first;
		sum += sushi[i].second;
		if (sum - dist >= max) {
			max = sum - dist;
			ans = max;
		}
	}

