vector<ll> seg1((1<<20)*2,-INF);
vector<ll> seg2((1<<20)*2,-INF);
void add1(ll ind,ll v){
  ind+=(1<<20);
  seg1[ind]=v;
  while(ind!=0){
    ind/=2;
    seg1[ind]=max(seg1[ind*2],seg1[ind*2+1]);
  }
}

ll get1(ll l,ll r){
  l+=(1<<20);
  r+=(1<<20);
  ll ans=-INF;
  while(l<r){
    if(l%2==1){
      chmax(ans,seg1[l]);
      l++;
    }
    l/=2;
    if(r%2==1){
      chmax(ans,seg1[r-1]);
      r--;
    }
    r/=2;
  }
  return ans;
}

void add2(ll ind,ll v){
  ind+=(1<<20);
  seg2[ind]=v;
  while(ind!=0){
    ind/=2;
    seg2[ind]=max(seg2[ind*2],seg2[ind*2+1]);
  }
}

ll get2(ll l,ll r){
  l+=(1<<20);
  r+=(1<<20);
  ll ans=-INF;
  while(l<r){
    if(l%2==1){
      chmax(ans,seg2[l]);
      l++;
    }
    l/=2;
    if(r%2==1){
      chmax(ans,seg2[r-1]);
      r--;
    }
    r/=2;
  }
  return ans;
}
/* 累積和 */
vector<ll> acc_sum(vector<ll> v){
  vector<ll> ans(v.size()+1,0);
  rep(i,v.size()) ans[i+1]=ans[i]+v[i];
  return ans;
}
