int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    ll n, c;

    cin >> n >> c;
    vector<ll> x(n + 2), v(n + 2);
    for (int i = 1; i <= n; ++i) cin >> x[i] >> v[i];

    ll max_c = 0;

    // 時計回り
    vector<ll> plus(n + 2, -c);
    for (ll i = 1, sum = 0; i <= n; ++i) {
        sum += v[i];
        plus[i] = max(plus[i - 1], sum - x[i]);
        max_c = max(max_c, plus[i]);
    }

    // 半時計回り
    vector<ll> neg(n + 2, -c);
    for (ll i = n, sum = 0; 1 <= i; --i) {
        sum += v[i];
        neg[i] = max(neg[i + 1], sum - (c - x[i]));
        max_c = max(max_c, neg[i]);
    }

    // 時計回り -> 半時計回り
    for (ll i = 1, sum = 0; i < n; ++i) {
        sum += v[i];
        max_c = max(max_c, (sum - 2 * x[i]) + neg[i + 1]);
    }

    // 半時計回り -> 時計回り
    for (ll i = n, sum = 0; 1 < i; --i) {
        sum += v[i];
        max_c = max(max_c, (sum - 2 * (c - x[i])) + plus[i - 1]);
    }

    cout << max_c << endl;

    return 0;
}

