int main() {

    long long N, C;
    cin >> N >> C;
    vector<LLP> sushi(N);
    rep(i,N) cin >> sushi[i].first >> sushi[i].second;

    sort(sushi.begin(), sushi.end());

    vector<long long> clock(N, 0), antiClock(N, 0);
    vector<long long> clockMax(N, 0), antiClockMax(N, 0);

    clock[0] = sushi[0].second - sushi[0].first;
    clockMax[0] = max((long long)0, clock[0]);

    for (int i = 1; i < N; i++) {
        clock[i] = clock[i - 1] + sushi[i].second - (sushi[i].first - sushi[i - 1].first);
        clockMax[i] = max(clockMax[i - 1], clock[i]);
    }

    antiClock[N - 1] = sushi[N - 1].second - (C - sushi[N - 1].first);
    antiClockMax[N - 1] = max((long long)0, antiClock[N - 1]);
    for (int i = N - 2; i >= 0; i--) {
        antiClock[i] = antiClock[i + 1] + sushi[i].second - (sushi[i + 1].first - sushi[i].first);
        antiClockMax[i] = max(antiClockMax[i + 1], antiClock[i]);
    }

    long long ans = 0;
    for (int i = 0; i <= N - 2; i++) {
        ans = max(ans, clock[i] - sushi[i].first + antiClockMax[i + 1]);
    }
    ans = max(ans, clockMax[N - 1]);
    for (int i = N - 1; i > 0; i--) {
        ans = max(ans, antiClock[i] - (C - sushi[i].first) + clockMax[i - 1]);
    }
    ans = max(ans, antiClockMax[0]);

    cout << ans << endl;

    return 0;
}

