#include <algorithm>
#include <string>

int main(){
	int n;
	long long c;
	std::cin >> n >> c;
	long long walk = 0;
	long long val = 0;
	long long loc = 0;
	for(int i = 0; i < n; i++){
		long long x, v;
		std::cin >> x >> v;
		std::cout << "x: " << x << "     " << "v: " << v << std::endl;
		if(x >= v){
			continue;
		}
		if(x > loc){
			if(abs(x - loc) < abs(loc+20 - x)){
				walk += abs(x-loc);
				loc = x;
				val += v;
			}else if(abs(x - loc) > abs(loc+20 - x)){
				walk += abs(loc+20 - x);
				loc = x;
				val += v;
			}
		}else if(x < loc){
			if(abs(x+20 - loc) < abs(loc-x)){
				walk += abs(x+20 - loc);
				loc = x;
				val += v;
			}else if(abs(x - loc) > abs(loc-x)){
				walk += abs(loc-x);
				loc = x;
				val += v;
			}
		}else{
			val += v;
		}
		std::cout << "walk : " << walk << std::endl;
	}
	std::cout << val - walk;
}

