int data1[maxn<<2];
int data3[maxn<<2];

void pushup1(int o)
{
	data1[o]=max(data1[o<<1],data1[o<<1|1]);
}

void build1(int o,int l,int r)
{
	if(l==r)
	{
		data1[o]=v[l][1];
		return;
	}
	build1(o<<1,l,mid);
	build1(o<<1|1,mid+1,r);
	pushup1(o);
}

int query1(int o,int l,int r,int ql,int qr)
{
	if(ql>qr) return 0;
	if(l==r) return data1[o];
	if(ql<=l && r<=qr) return data1[o];
	int res=0;
	if(ql<=mid) res=max(res,query1(o<<1,l,mid,ql,qr));
	if(mid+1<=qr) res=max(res,query1(o<<1|1,mid+1,r,ql,qr));
	return res;
}

void pushup3(int o)
{
	data3[o]=max(data3[o<<1],data3[o<<1|1]);
}

void build3(int o,int l,int r)
{
	if(l==r)
	{
		data3[o]=v[l][3];
		return;
	}
	build3(o<<1,l,mid);
	build3(o<<1|1,mid+1,r);
	pushup3(o);
}

int query3(int o,int l,int r,int ql,int qr)
{
	if(ql>qr) return 0;
	if(l==r) return data3[o];
	if(ql<=l && r<=qr) return data3[o];
	int res=0;
	if(ql<=mid) res=max(res,query3(o<<1,l,mid,ql,qr));
	if(mid+1<=qr) res=max(res,query3(o<<1|1,mid+1,r,ql,qr));
	return res;
}

