#include<bits/stdc++.h>
using namespace std ;
const int N = 1e5+5 ;

int n ;
long long c ,x[N] ,add[N] ;
long long ansR[N] ,ansL[N] ,ans ,bestL[N] ,bestR[N] ;
long long solve(long long cur,int ii,int jj){
    if(ii>jj) return 0;
    long long ret = 0 ;
    ret = max(ret ,solve(x[ii],ii+1,jj) - (x[ii]-cur+c)%c + add[ii]) ;
    ret = max(ret ,solve(x[jj],ii,jj-1) - (cur-x[jj]+c)%c + add[jj]) ;
    return ret;
}
int main(){
    scanf("%d%lld",&n,&c);
    for(int i=0;i<n;++i) scanf("%lld%lld",x+i,add+i);
    long long cur = 0 ;
    for(int i=0;i<n;++i){
        if(i) ansL[i] = ansL[i-1] ,bestL[i] = bestL[i-1] ;
        ansL[i] += add[i] - (x[i]-cur+c)%c ;
        ans = max(ans ,ansL[i]);
        bestL[i] = max(bestL[i] ,ansL[i]);
        cur = x[i] ;
    }
    cur = 0 ;
    for(int i=n-1;i>=0;--i){
        ansR[i] = ansR[i+1] ,bestR[i] = bestR[i+1];

        ansR[i] += add[i] - (cur-x[i]+c)%c ;
        ans = max(ans,ansR[i]);
        bestR[i] = max(bestR[i] ,ansR[i]);
        cur = x[i] ;
    }

    for(int i=0;i<n;++i){
        long long xx = ansL[i] - x[i] + bestR[i+1] ;
        ans = max(ans,xx);
    }
    for(int i=n-1;i>=0;--i){
        long long xx= ansR[i] - (c-x[i]) + bestL[i-1] ;
        ans = max(ans,xx);
    }
    cout << ans ;
    return 0;
}

