	for(int i=0;i<n;i++){
		cin >> s[i][0] >> s[i][1];
	}


	for(int i = 0;i<n;i++){
		int mmm = 0;
		p = s[i][0];
		for(int j =0 ;j<n;j++){
			if(p >= s[j][0]){
				mmm += s[j][1];
			}
		}
		mmm -= p;
		if(max <= mmm)max =mmm;
	}
	for(int i = 0;i<n;i++){
		int mmm = 0;
		p = s[i][0];
		for(int j =0 ;j<n;j++){
			if(p <= s[j][0]){
				mmm += s[j][1];
			}
		}
		mmm -= (c-p);
		if(max <= mmm)max =mmm;
	}

	for(int i=1;i<n;i++){

		for(int j=0;j<i;j++){
			int mm = 0;
			if(s[i][0] <= c/2 && s[j][0] <= c/2)continue;
			if(s[i][0] >= c/2 && s[j][0] >= c/2)continue;
			if(s[i][0] <= s[j][0]){
				l = s[i][0];
				r = s[j][0];
			}else{
				l = s[j][0];
				r = s[i][0];
			}
			for(int k = 0;k<n;k++){
				if(s[k][0] <= l){
					mm += s[k][1];
				}
				if(s[k][0] >= r){
					mm += s[k][1];
				}
			}
