//ここから編集する
class Solve {
public:
    int N;
    ll C;
    vector<ll> X, V;

    void input() {
        cin >> N >> C;
        rep(i, 0, N) {
            ll x, v;
            cin >> x >> v;
            X.push_back(x);
            V.push_back(v);
        }


    }

    ll calc(int wL, int wR) {
        vector<ll> ruiXL(N + 2);
        vector<ll> ruiXR(N + 2);
        vector<ll> ruiVL(N + 2);
        vector<ll> ruiVR(N + 2);

        for (int i = 0; i < N; ++i) {
//            ruiXL[i + 1] = ruiXL[i] + X[i];
            ruiXL[i + 1] = X[i];
            ruiVL[i + 1] = ruiVL[i] + V[i];
        }
        for (int i = N; i > 0; --i) {
//            ruiXR[i] = ruiXR[i + 1] + X[i];
            ruiXR[i] = C - X[i - 1];
            ruiVR[i] = ruiVR[i + 1] + V[i - 1];
        }

        vector<ll> beneL(N + 2);
        vector<ll> beneR(N + 2);

        for (int i = 0; i <= N + 1; ++i) {
            beneL[i] = ruiVL[i] - wL * ruiXL[i];
            beneR[i] = ruiVR[i] - wR * ruiXR[i];
        }

        for (int i = 0; i <= N; ++i) {
            beneL[i + 1] = max(beneL[i], beneL[i + 1]);
        }
        for (int i = N + 1; i > 0; --i) {
            beneR[i - 1] = max(beneR[i], beneR[i - 1]);
        }

        ll ret = 0ll;
        for (int i = 0; i <= N; ++i) {
            chmax(ret, beneL[i] + beneR[i + 1]);
        }

        return ret;
    }

    void solve() {
        input();

        ll ans = max(calc(1, 2), calc(2, 1));
        cout << ans << endl;

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    Solve().solve();


    return 0;
}

