int main(){
  int n;
  ll c;
  cin >> n >> c;

  ll cl[n+1], f[n+1], fb[n+1], v[n+1], sum[n+1], unsum[n+1];
  pair<ll, int> g[n+1];

  cl[0] = f[0] = v[0] = fb[0] = sum[0] = unsum[0] = 0;
  g[0] = {0, 0};

  for(int i=1; i<=n; i++) {
    cin >> cl[i] >> v[i];
    sum[i] = sum[i-1] + v[i];
    f[i] = sum[i] - cl[i];
    g[i] = max(g[i-1], {f[i], -i});
  }

  for(int i=n; i>=1; i--){
    unsum[i] = v[i] + unsum[(i+1)%(n+1)];
  }

  ll ans = g[n].first;
  for(int i=1; i<=n; i++){
    int a = -g[i-1].second;
    ll dis = min(cl[a], c-cl[i]);

    ans = max(unsum[i]-(c-cl[i])+g[i-1].first-dis, ans);
  }

  assert(ans >= 0);
  cout << ans << endl;

  return 0;
}

