  }

  for(int i = N - 1; i >= 0; i--) {
    ll tmp = dp2[i];
    if(i >= 1 && dp1[i - 1] - (C - x[i]) > 0) {
      tmp += dp1[i - 1] - (C - x[i]);
    }
