	rep(i,n) cin>>x[i]>>v[i];
	vll rsum(n+1),lsum(n+1);
	rep(i,n) rsum[i+1]=rsum[i]+v[i];
	rep(i,n) rsum[i+1]-=x[i];
	rep(i,n) lsum[i+1]=lsum[i]+v[n-1-i];
	rep(i,n) lsum[i+1]-=c-x[n-1-i];
	SegmentTree<ll> segR(rsum, [](ll x,ll y){return max(x,y);}, 0ll);
	SegmentTree<ll> segL(lsum, [](ll x,ll y){return max(x,y);}, 0ll);
	ll ans=0;
	//L -> R
	FOR(i,0,n){
		ll sum=0;
		sum += lsum[i];
		if (i>0) sum -= c-x[n-i];
		sum += segR.query(0,n-i+1);
		chmax(ans,sum);
	}
	//R -> L
	FOR(i,0,n){
		ll sum=0;
		sum += rsum[i];
		if (i>0) sum -= x[i-1];
		sum += segL.query(0,n-i+1);
