     x1: 0000 0001 0010 0101 0110 0111 0111
     x2: xxxx 0001 0011 0100 0101 1000 0110
x1 & x2: 0000 0001 0010 0100 0100 0000 0110

      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S & (1 << i) -> if true, i in S
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}
__builtin_popcountl(i) -> the number of 1 in binary

#Conditional Operator
condition ? true : false;

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
str s, t, u;
ll n, m, h, w, k, Q;
ll a, b, c, d, idx, cnt;
vl as, bs, cs, ds;
vb2 block;
Graph graph;

void solve(){
    in2(n, c);
    // dist, val
    as = bs = vl(n);
    rep(i, n) in2(as[i], bs[i]);

    vl2 ls(2, vl(n + 1, 0)), rs(2, vl(n + 1, 0));
    rep(i, n){
        ls[0][i + 1] = as[i];
        ls[1][i + 1] = ls[1][i] + bs[i];
        rs[0][i + 1] = c - as[n - 1 - i];
        rs[1][i + 1] = rs[1][i] + bs[n - 1 - i];
    }

    vl2 memo(2, vl(n + 1, 0));
    rep(r, n + 1){
        memo[0][r] = rs[1][r] - rs[0][r];
        memo[1][r] = rs[1][r] - 2 * rs[0][r];
        if (r != 0){
            chmax(memo[0][r], memo[0][r - 1]);
            chmax(memo[1][r], memo[1][r - 1]);
        }
    }

    rep(l, n + 1){
        ll val0, val1;
        val0 = ls[1][l] - ls[0][l];
        val1 = ls[1][l] - 2 * ls[0][l];
        val0 += memo[1][n - l];
        val1 += memo[0][n - l];
        chmax(answer, max(val0, val1));
    }

    prl(answer);
}

