int main() {
    ll n, c;
    cin >> n >> c;

    vl x(n), v(n);
    rep(i, n) {
        cin >> x[i] >> v[i];
    }

    // 時計回りに進むとき
    ll ans = 0;  // 1貫も食べないとき0
    rep(i, n) {  // 寿司0から寿司iを食べるとする
        ll now = 0;
        exrep(j, 0, i) {
            now += v[j];
        }
        now -= x[i];
        chmax(ans, now);
    }

    // 反時計回りに進むとき
    for(ll i = n-1; i >= 0; i--) {  // 寿司n-1から寿司iを食べるとする
        ll now = 0;
        for(ll j = n-1; j >= i; j--) {
            now += v[j];
        }
        now -= c - x[i];
        chmax(ans, now);
    }

    out(ans);
    re0;
}

