    vector<ll> x(n), v(n);
    rep(i, 0, n) cin >> x[i] >> v[i];
    vector<ll> acc(n+1, 0), left_max(n+1, 0), left_pos(n+1, 0);
    rep(i, 0, n) acc[i+1] = acc[i] + v[i];
//    rep(i, 0, n+1) cerr << acc[i] << endl;
    rep(i, 0, n){
        if(left_max[i] - left_pos[i] > acc[n] - acc[n-1-i] - (c - x[n-1-i])){
            left_max[i+1] = left_max[i];
            left_pos[i+1] = left_pos[i];
        }else{
            left_max[i+1] = acc[n] - acc[n-1-i];
            left_pos[i+1] = c - x[n-i-1];
        }
    }
//    rep(i, 0, n+1) cerr << left_max[i] << " " << left_pos[i] << endl;
    ll ans = 0;
    rep(i, 0, n+1){
        ll dist = (i == 0 ? 0 : x[i-1]);
        ll m1 = left_max[n-i] - 2 * left_pos[n-i] + acc[i] - dist;
        ll m2 = left_max[n-i] - left_pos[n-i] + acc[i] - 2 * dist;
//        cerr << i << ": " << m1 << " " << m2 << endl;
        ans = max({ans, m1, m2}); 
    }
    cout << ans << endl;
    return 0;
}

