  vector<int> x(N), v(N);
  REP(i, N) cin >> x[i] >> v[i];

  SegmentTree<int> R(N, [](int a, int b) { return max(a, b); }, -INF);
  SegmentTree<int> L(N, [](int a, int b) { return max(a, b); }, -INF);
  int sum = 0;
  REP(i, N){
    sum += v[i];
    R.set(i, sum-x[i]);
  }
  sum = 0;
  RREP(i, N){
    sum += v[i];
    L.set(i, sum-(C-x[i]));
  }
  R.build(); L.build();

  int ans = max(R.query(0, N+1), L.query(0, N+1)); 
  REP(i, N){
    chmax(ans, R.query(0, i+1)-x[i]+L.query(i+1, N+1));
    chmax(ans, L.query(i, N+1)-(C-x[i])+R.query(0, i));
  }

  cout << ans << endl;

  return 0;
}

