void solve(long long N, long long C, vector<long long> x, vector<long long> v){
	vector<ll> d(N+1), r(N+1), md(N+1), mr(N+1);
	repn(i, N) {
		d[i] = d[i-1] + v[i-1] - (x[i]-x[i-1]);
		md[i] = max(md[i-1], d[i]);
	}
	repn(i, N) {
		r[i] = r[i-1] + v[N-i] - ((C-x[N-i+1])-(C-x[N-i+2]));
		// cout << i << ": " << r[i] << " " << C-x[N-i+1] << " " << (C-x[N-i+2]) << endl;
		mr[i] = max(mr[i-1], r[i]);
	}

	ll res = 0;
	repn(i, N) {
		ll now = 0;
		now = d[i]+max(mr[N-i]-x[i], 0LL);
		// cout << i << ": " << d[i] << " " << N-i << ": " << max(mr[N-i]-x[i], 0LL) << endl;
		res = max(res, now);
	}
	repn(i, N) {
		ll now = 0;
		now = r[i]+max(md[N-i]-(C-x[N-i+1]), 0LL);
		// cout << "rev " << i << ": " << r[i] << " " << N-i << ": " << max(md[N-i]-(C-x[N-i]), 0LL) << endl;
		res = max(res, now);
	}
	cout << res << endl;
}

