void dfs(long long pos,long long walk,long long cls)
{
	ans=max(ans,cls-walk);
	if(!x.size())
		return ;
	int pnt=lower_bound(x.begin(),x.end(),pos)-x.begin();
	vector<long long> tmp=x,tcp=c;
	long long to=x[pnt%x.size()],cl=c[pnt%x.size()];
	x.erase(x.begin()+pnt%x.size());
