	to=x[pnt%x.size()],cl=c[pnt%x.size()];
	x.erase(x.begin()+pnt%x.size());
	c.erase(c.begin()+pnt%c.size());
	dfs(to,walk+(pos-to+C)%C,cl+cls);
	x=tmp;
	c=tcp;
	return ;
}
