const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};


void solve(long long N, long long C, std::vector<long long> x, std::vector<long long> v){
    vector<pair<LL, int> > rightCost, leftCost;

    LL temp = 0;
    REP(i, N) {
        temp += v[i];
        if(temp - x[i] * 2 <= 0) continue;
        leftCost.PB(MP(temp - x[i] * 2, i));
    }

    temp = 0;
    RREP(i, N-1) {
        temp += v[i];
        if(temp - (C - x[i]) * 2 <= 0) continue;
        rightCost.PB(MP(temp - (C - x[i]) * 2, i));
    }

    sort(ALL(leftCost), greater<pair<LL, int> >());
    sort(ALL(rightCost), greater<pair<LL, int> >());

    LL ans = 0;
    int nextIdx = 0;
    temp = 0;
    REP(i, N) {
        temp += v[i];
        LL nowCost = temp - x[i];

        REP2(j, nextIdx, rightCost.size()) {
            if(rightCost[j].second <= i) {
                nextIdx++;
                continue;
            }

            nowCost += rightCost[j].first;
            break;
        }

        ans = max(ans, nowCost);
    }

    nextIdx = 0;
    temp = 0;
    RREP(i, N-1) {
        temp += v[i];
        LL nowCost = temp - (C - x[i]);

        REP2(j, nextIdx, leftCost.size()) {
            if(i <= leftCost[j].second) {
                nextIdx++;
                continue;
            }

            nowCost += leftCost[j].first;
            break;
        }

        ans = max(ans, nowCost);
    }

    cout << ans << endl;
}

