      dp[i] = P(cal[i] - 2 * x[i-1], x[i-1]);
    } else {
      dp[i] = dp[i-1];
    }
    if (revDp[i-1].first < revCal[i] - 2 * (c - x[n - i])) {
      revDp[i] = P(revCal[i] - 2 * (c - x[n - i]), c - x[n - i]);
    } else {
      revDp[i] = revDp[i - 1];
    }
  }

  ll ans = max(dp[n].first + dp[n].second, revDp[n].first + revDp[n].second);
  for (int i=1;i<n;i++) {
    ans = max(ans, dp[i].first + revDp[n - i].first + max(dp[i].second, revDp[n-i].second));
  }

  cout << ans << endl;
}

int main() {
  cin >> n >> c;
  for (int i=0;i<n;i++) {
    cin >> x[i] >> v[i];
  }
  solve();
}

