lint N, C, x, v;
lint X[100001], V[100001];
lint points[2][100002];

lint solve() {
	lint maxv = 0;
	REP(i, N) {
		points[0][i + 1] = V[i];
		points[1][N - i] = V[i];
	}
	REP(i, N) {
		points[0][i + 1] += points[0][i];
		points[1][i + 1] += points[1][i];
	}
	REP(i, N) {
		points[0][i + 1] -= X[i];
		points[1][N - i] -= (C - X[i]);
	}
	lint index = 0, curr = 0;
	REP(i, N) {
		if (curr < points[0][i]) {
			curr = points[0][i];
			index = i;
		}
		lint pls = (index == 0 ? 0 : X[index - 1]);
		if (maxv < points[1][N - i] + points[0][index] - pls) {
			maxv = points[1][N - i] + points[0][index] - pls;
		}
	}
	return maxv;
}

