ll dp2[200005];
int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll N,C;
    cin >> N >> C;
    if(N>100)return 0;
    vector<ll> x(2*N+1),v(2*N+1);
    rep(i,N){
        cin >> x[i] >> v[i];
        x[i+N] = C - x[i];
        v[i+N] = v[i];
    }
    //0からスタートして右に行くか
    //Nからスタートして左に行くかの2通り試す
    ll ans = 0;
    //0からスタートして右に行く場合
    rep(i,N){
        if(i==0)dp[1] = v[0] - x[0];
        else{
            dp[i+1] = dp[i] + v[i] - (x[i]-x[i-1]);
        }
        ans = max(ans,dp[i+1]);
    }
    //Nからスタートして左に行く
    //dp2[2*N-i] := 左にi個取った場合の最大値
    for(int i=2*N-1;i>=N;i--){
        if(i==(2*N)-1){
            dp2[2*N - i] = v[i] - x[i];
        }else{
            dp2[2*N-i] = dp2[2*N-i-1] + v[i] - (x[i]-x[i+1]);
        }
        ans = max(ans,dp2[i]);
    }
    for(int i=0;i<=N;i++){
        for(int j=0;j+i<=N;j++){
            ll t = dp[i] + dp2[j];
            ll dis;
            if(i==0||j==0)dis = 0;
            else {
                dis = min(x[i-1],x[2*N-j]);
            }
            ans = max(ans,t-dis);
        }
    }
    cout << ans << endl;
}

