using Sushi = vector<long long>;

long long solve(int n, Sushi s1, Sushi s2, Sushi x) {
    Sushi max_s(n+1, 0);
    for (int i = 1; i <= n; i++) max_s[i] = max(max_s[i-1], s2[i]);

    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        long long res = s1[i] + max(0LL, max_s[n-i] - x[i]);
        if (ans < res) ans = res;
    }

    return ans;
}

