inline int pd(ll w,int l,int r)
{
	int mid,ret=0;
	while (l<r)
	{
		mid=l+r+1>>1;
		if (t[mid]==w) return mid;
		if (t[mid]>w) l=mid,ret=mid;
		else r=mid-1;
	}
	if (ret==0) return mid;
	else return ret;
}

inline int lowbit(int x){return x&(-x);}

void add(int x,ll k)
{
	while (x<=n) 
	{
		f[x]=l[x]-t[x];
		for (int i=1;i<lowbit(x);i<<=1) f[x]=max(f[x],f[x-1]);
		x+=lowbit(x);
	}
}

ll query(int x,int y)
{
	ll ret=0;
	while(y>=x)
	{
		ret=max(ret,l[y]-t[y]),--y;
		for (;y-lowbit(y)>=x;y-=lowbit(y)) ret=max(f[y],ret);
	}
	return ret;
}

void add2(int x,ll k)
{
	while (x<=n) 
	{
		g[x]=l[x];
		for (int i=1;i<lowbit(x);i<<=1) g[x]=max(g[x],g[x-1]);
		x+=lowbit(x);
	}
}

ll query2(int x,int y)
{
	ll ret=0;
	while(y>=x)
	{
		ret=max(ret,l[y]),--y;
		for (;y-lowbit(y)>=x;y-=lowbit(y)) ret=max(g[y],ret);
	}
	return ret;
}

inline ll read()
{
	ll x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if (ch=='-') f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
	return x*f;
}

inline void writ(ll x)
{
	if(x<0) putchar('-'),x=-x;
	if(x>9) writ(x/10);
	putchar(x%10+'0');
}
inline void write(ll x){writ(x);putchar('\n');}

int main()
{
	ll ans=0;
	n=read(),c=read();
	for (int i=1;i<=n;++i) d[i]=read(),t[i]=c-d[i],v[i]=read();
	for (int i=1;i<=n;++i) ww+=v[i],s[i]=ww-d[i],ans=max(ans,s[i]);ww=0;
	for (int i=n;i>=1;--i) ww+=v[i],l[i]=ww-t[i],ans=max(ans,l[i]);
	for (int i=1;i<=n;++i) add(i,l[i]-t[i]),add2(i,l[i]);
	for (int i=1;i<n;++i)
	{
		if (d[i]<=t[n]) ans=max(ans,s[i]-d[i]+query2(i+1,n));
		else if (d[i]>=t[i+1]) ans=max(ans,s[i]+query(i+1,n));
		else
		{
			int x=pd(d[i],i+1,n);
			ans=max(ans,max(s[i]-d[i]+query2(i+1,x),s[i]+query(x+1,n)));
		}
	}
