	VL rdp(N,0), ldp(N,0);
	ll score = 0,scoresum = 0,scoremax = 0;
	REP(i,N){
		scoresum += v[i];
		score = scoresum - x[i];
		scoremax = max(scoremax, score);
		rdp[i] = scoremax;
	}
