	REP(i, N) ans = max(ans, ldp[i]);
	REP(i ,N - 1) ans = max(ans, rdp[i] + ldp[i + 1] - x[i]);
	REP(i, N - 1) ans = max(ans, ldp[N - 1 - i] + rdp[N - 2 - i] - (C - x[N - 1 - i]));
	cout << ans << endl;

