#include <bits/stdc++.h>
#define LOGN 31
#define MAXN 200001
using namespace std;
void build(long long *A, long long ST[LOGN][MAXN], int n) {

    int h = floor(log2(n));

    // base case
    for (int j = 0; j < n; j++) ST[0][j] = A[j];

    // iterative dynamic programming approach
    for (int i = 1; i <= h; i++) 
        for (int j = 0; j + (1<<i) <= n; j++)
            ST[i][j] = max(ST[i-1][j], ST[i-1][j + (1<<(i-1))]);
}
int query(int l, int r, long long ST[LOGN][MAXN]) {        // query in range [l,r)
    int p = 31 - __builtin_clz(r-l);
    return max(ST[p][l], ST[p][r-(1<<p)]);
}
int main() {
  long long N,C;
  cin >> N >> C;
  long long x[N], v[N], sum = 0, answer = 0, y[N];
  for (int i = 0; i < N; i++) {
    cin >> x[i] >> v[i];
  }
  for (int i = N-1; i+1; i--) {
    sum += v[i];
    y[i] = sum-2*(C-x[i]);
    answer = max(answer,sum-C+x[i]);
  }
  long long sparse_table[LOGN][MAXN];
  build(y,sparse_table,N);
  sum = 0;
  for (int i = 0; i < N-1; i++) {
    sum += v[i];
    answer = max(answer,sum-x[i]+query(i+1,N,sparse_table));
  }
  sum = 0;
  for (int i = 0; i < N; i++) {
    sum += v[i];
    y[i] = sum-2*x[i];
    answer = max(answer,sum-x[i]);
  }
  build(y,sparse_table,N);
  sum = 0;
  for (int i = N-1; i; i--) {
    sum += v[i];
    answer = max(answer,sum-C+x[i]+query(0,i,sparse_table));
  }
  cout << answer;
}

