struct S{
  ll x;
  ll v;
};


const int MAX_N = 112345;
struct RMQStatic {
  ll *a;
  ll dp_max[20][MAX_N];

  int log2(int b) {return 31 - __builtin_clz(b);}

  // O(NlogN)
  void build(ll* a, int N) {
    this->a = a;
    int M = log2(N) + 1;
    REP(i, N) dp_max[0][i] = i;
    for (int i = 1, len = 1; i < M; i++, len <<= 1) {
      for (int j = 0; j + len < N; j++) {
        {
          ll s = dp_max[i - 1][j];
          ll t = dp_max[i - 1][j + len];
          dp_max[i][j] = a[s] >= a[t] ? s : t;
        }
      }
    }
  }

  ll get_max(int from, int to) {
    int k = log2(to - from + 1);
    ll s = dp_max[k][from];
    ll t = dp_max[k][to - (1 << k) + 1];
    return a[s] >= a[t] ? s : t;
  }

};


ll A[MAX_N];
ll B[MAX_N];
RMQStatic rmqA, rmqB;

ll solve(vector<S> ss, ll C) {
  const int N = ss.size();

  {
    A[0] = 0;
    ll got = 0;
    REP(i, N) {
      got += ss[i].v;
      A[i+1] = got - ss[i].x;
    }
  }
  {
    B[N] = 0;
    ll got = 0;
    for (int i = N - 1; i >= 0; i--) {
      got += ss[i].v;
      B[i] = got - 2LL*(C - ss[i].x);
    }
  }

  rmqA.build(A, N+1);
  rmqB.build(B, N+1);

  ll ans = 0;
  for (int i = 0; i <= N; i++) {
    ll p = A[ rmqA.get_max(0, i) ];
    ll q = B[ rmqB.get_max(i, N) ];
    chmax(ans, p + q);
  }
  return ans;
}

int main2() {
  int N = nextInt();
  ll C = nextLong();
  vector<S> ss(N);
  REP(i, N) {
    ss[i].x = nextLong();
    ss[i].v = nextLong();
  }
  ll ans1 = solve(ss, C);
  REP(i, N) ss[i].x = C - ss[i].x;
  sort(ALL(ss), [](const S&a, const S&b) -> bool {
    return a.x < b.x;
  });
  ll ans2 = solve(ss, C);
  ll ans = 0;
  chmax(ans, ans1);
  chmax(ans, ans2);
  cout << ans << endl;
  return 0;
}

