  ll maxcal=std::max(posmax, negmax);
  ll bufcos=0;
  ll revmax=0;
  //p>>0>>n
  for(int i = 0; i < N; i++){
    bufcos=posco[N-2-i]-posx[N-2-i];
    revmax=std::max(revmax, negco[i]);
    maxcal=std::max(maxcal, revmax+bufcos);
  }
  revmax=0;
  //n>>0>>p
  for(int i = 0; i < N; i++){
    bufcos=negco[N-2-i]-negx[N-2-i];
    revmax=std::max(revmax, posco[i]);
    maxcal=std::max(maxcal, revmax+bufcos);
  }

  std::cout << maxcal << std::endl;

  return 0;
}

