ll calc() {
  for (int i = 0; i < N; i++) {
    if (i == 0) cumv[i] = v[i];
    else cumv[i] = cumv[i-1] + v[i];
  }
  ll res = 0;
  for (int i = 0; i < N; i++) {
    res = max(res, cumv[i] - x[i]);
  }
  priority_queue<ll> que;
  que.emplace(0);
  ll cumv2 = 0;
  for (int i = N-1; i >= 0; i--) {
