using namespace std;
typedef pair<llong, llong> ipair;
llong modulo(llong left, llong right) { return (left % right + right) % right; }

llong N, C;
ipair sushi[MAX_N + 2];
llong cw_oneway[MAX_N + 2], cw_round[MAX_N + 2];
llong ccw_oneway[MAX_N + 2], ccw_round[MAX_N + 2];

llong solve() {
    llong v_sum = 0;
    cw_oneway[0] = cw_round[0] = 0;
    for(int i = 1; i <= N; ++i) {
        v_sum += sushi[i].second;
        cw_oneway[i] = max(cw_oneway[i - 1], v_sum - sushi[i].first);
        cw_round[i] = max(cw_round[i - 1], v_sum - sushi[i].first * 2);
    }

    v_sum = 0;
    ccw_oneway[N + 1] = ccw_round[N + 1] = 0;
    for(int i = N; i >= 1; --i) {
        v_sum += sushi[i].second;
        ccw_oneway[i] = max(ccw_oneway[i + 1], v_sum - (C - sushi[i].first));
        ccw_round[i] = max(ccw_round[i + 1], v_sum - (C - sushi[i].first) * 2);
    }

    llong res = 0;
    for(int i = 0; i <= N; ++i)
        res = max(res, cw_round[i] + ccw_oneway[i + 1]);
    for(int i = 0; i <= N; ++i)
        res = max(res, cw_oneway[i] + ccw_round[i + 1]);

    return res;
}

