        v = b;
    }
};

int main(void) {
    int n;
    int64_t c;
    cin >> n >> c;
    std::vector<Sushi> s;
    s.push_back(Sushi(0, 0));
    for (int i = 0; i < n; i++) {
        int64_t m1, m2;
        cin >> m1 >> m2;
        s.push_back(Sushi(m1, m2));
    }

    int64_t cum_clock[100010] = {}, cum_anti[100010] = {};
    // cout << "cum_clock" << endl;
    for (int i = 1; i <= n; i++) {
        cum_clock[i] = cum_clock[i - 1] + s[i].v - (s[i].x - s[i - 1].x);
        // cout << cum_clock[i] << endl;
    }
    cum_anti[n] = s[n].v - (c - s[n].x);
    // cout << "cum_anti" << endl << cum_anti[n] << endl;
    for (int i = n - 1; i >= 0; i--) {
        cum_anti[i] = cum_anti[i + 1] + s[i].v - (s[i + 1].x - s[i].x);
        // cout << cum_anti[i] << endl;
    }

    int64_t antimax[100010] = {};
    antimax[n]              = std::max((int64_t)0, cum_anti[n]);
    // cout << "antimax" << endl << antimax[n] << endl;
    for (int i = n - 1; i >= 0; i--) {
        antimax[i] = std::max(antimax[i + 1], cum_anti[i]);
        // cout << antimax[i] << endl;
    }
    int64_t clockmax[100010] = {};
    // cout << "clockmax" << endl;
    for (int i = 1; i <= n; i++) {
        clockmax[i] = std::max(clockmax[i - 1], cum_clock[i]);
        // cout << clockmax[i] << endl;
    }
    // clock->anticlock
    int64_t res = clockmax[n];
    for (int turn = 1; turn <= n - 1; turn++) {
        int64_t temp = cum_clock[turn] - s[turn].x + antimax[turn + 1];
        if (temp > res)
            res = temp;
    }

    // anticlock->clock
    res = std::max(res, antimax[1]);

    for (int turn = n; turn >= 2; turn--) {
        int64_t temp = cum_anti[turn] - (c - s[turn].x) + clockmax[turn - 1];
        if (temp > res)
            res = temp;
    }

    cout << res << endl;

    return 0;
}

