int main(int argc, char *argv[]) {
  LL N, C;
  cin >> N >> C;
  N+=2;
  vector<PLL> sushi(N);
  sushi[0].first = sushi[0].second = 0;
  sushi[1].first = C;
  sushi[1].second = 0;
  for (int i = 2; i < N; ++i) {
    cin >> sushi[i].first >> sushi[i].second;
  }
  sort(sushi.begin(), sushi.end());

  vector<LL> acum_cw(N);
  vector<LL> best_cw(N);
  LL acum = 0;
  LL best = 0;
  for (int i = 0; i < N; ++i) {
    acum += sushi[i].second;
    acum_cw[i] = acum;

    LL benefit = acum_cw[i] - sushi[i].second;
    if (i == 0) {
      best = benefit;
      best_cw[i] = 0;
    } else if (benefit > best) {
      best = benefit;
      best_cw[i] = i;
    } else {
      best_cw[i] = best_cw[i - 1];
    }
  }

  vector<LL> acum_ccw(N);
  vector<LL> best_ccw(N);
  acum = 0;
  best = 0;
  for (int i = N - 1; i >= 0; i--) {
    acum += sushi[i].second;
    acum_ccw[i] = acum;

    LL benefit = acum_ccw[i] - (C - sushi[i].second);
    if (i == N - 1) {
      best = benefit;
      best_ccw[i] = 0;
    } else if (benefit > best) {
      best = benefit;
      best_ccw[i] = i;
    } else {
      best_ccw[i] = best_ccw[i + 1];
    }
  }

  best = 0;
  for (int i = 0; i < N; ++i) {
    LL walk_cw = sushi[i].first;
    LL benefit_cw = acum_cw[i];
    for (int j = N - 1; j > i; j--) {
      LL walk_ccw = C - sushi[j].first;
      LL benefit_ccw = acum_ccw[j];
      LL benefit = benefit_cw + benefit_ccw - walk_cw - walk_ccw - min(walk_cw, walk_ccw);
      best = max(best, benefit);
    }
  }

  cout << best << endl;
  return EXIT_SUCCESS;
}

