            if (max_rf < sum_lf - sushi_seq[i].dist) {
                max_rf = sum_lf - sushi_seq[i].dist;
            }
        }
        sum_right[i] = max_rf;
    }

    sum_left[0] = 0;
    sum_lf = 0;

    for (int i = 1; i <= N; i++) {
        sum_lf += sushi_seq[N + 1 - i].energy;
        sum_left[i] = sum_lf;
    }

    for (int i = 0; i <= N; i++) {
        if (i == 0) {
            max_lf = max(max_lf, sum_left[i] + sum_right[N]);   
