    //順回り
    LL sum = 0;
    int prev = 0;
    for (int i = 0; i < n; i++) {
        sum += v[i] - x[i] + prev;
        prev = x[i];
        if (sum > ans) ans = sum;
    }

    //逆回り
    sum = 0;
    for (int i = n-1; i >= 0; i--) {
        sum += v[i] + x[i] - prev - c;
        prev = x[i];
        if (sum > ans) ans = sum;
    }
}

