typedef long long ll;
#define rep(i,s,n)for(ll i=s;i<n;i++)
#define repe(i,s,n)for(ll i=s;i<=n;i++)
#define rep_r(i,s,n)for(ll i=n;i>s;i--)
#define repe_r(i,s,n)for(ll i=n;i>=s;i--)
static const ll MOD = 1e9 + 7;
static const ll MAX_L = (ll)1 << 62;

ll x[100001] = {};
ll v[100001] = {};
ll r[100001] = {};
ll r_max[100001] = {};
ll l[100001] = {};
ll l_max[100001] = {};
int main() {
	ll n, c; cin >> n >> c;
	repe(i, 1, n)cin >> x[i] >> v[i];

	ll maxE = 0;
	ll sumX = 0;
	repe(i, 1, n) {
		sumX = x[i] - x[i - 1];
		r[i] += v[i] + r[i - 1] - sumX;
		r_max[i] = max(r[i], r_max[i - 1]);
		maxE = max(maxE, r_max[i]);
	}

	repe_r(i, 1, n) {
		sumX = (c - x[i]) - ((i != n) ? (c - x[i + 1]) : 0);
		l[i] += v[i] + l[i + 1] - sumX;
		l_max[i] = max(l[i], l_max[i + 1]);
		maxE = max(maxE, l_max[i]);
	}

	rep(i, 1, n) {
		ll v = r[i] - x[i] + l_max[i + 1];
		maxE = max(maxE, v);
	}

	rep_r(i, 1, n) {
		ll v = l[i] - (c - x[i]) + r_max[i - 1];
		maxE = max(maxE, v);
	}

	cout << maxE << endl;

	return 0;
}

