typedef long long ll;

ll re_MAX(vector<ll> vt, int size){
    sort(vt.begin(), vt.begin()+size, greater<ll>());
    return vt[0];
}

int main()
{
    ll N,C;
    cin >> N >> C;
    vector < vector <ll> > conditions(N, vector<ll>(2));
    for(int i=0; i<N; i++){
        cin >> conditions[i][0] >> conditions[i][1];//[0]がx0からの距離[1]が価値
    }
    vector<ll> gain_clock(N), gain_counter(N);
    gain_clock[0]=conditions[0][1]-conditions[0][0];
    gain_counter[0]=conditions[N-1][1]-(C-conditions[N-1][0]);
    ll ans=max(gain_clock[0], gain_counter[0]);
    ans=max(ans, (ll)0);
    for(int i=1; i<N; i++){
        gain_clock[i]=gain_clock[i-1]+conditions[i][1]-(conditions[i][0]-conditions[i-1][0]);
        ans=max(gain_clock[i], ans);
        gain_counter[i]=gain_counter[i-1]+conditions[N-i-1][1]-(conditions[N-i][0]-conditions[N-i-1][0]);
        ans=max(gain_counter[i], ans);
    }
    for(int i=0; i<N-1; i++){
        ll tmp=gain_clock[i];
        /*vector<ll> copied(N-i-1);
        copy(gain_counter.begin(), gain_counter.begin()+N-i-1, copied.begin());
        sort(copied.begin(), copied.end(), greater<ll>());*/

        ll a0=re_MAX(gain_counter, N-i-1);

        ans=max(ans, tmp-conditions[i][0]+a0);//copied[0]

        tmp=gain_counter[i];
        /*copy(gain_clock.begin(), gain_clock.begin()+N-i-1, copied.begin());
        sort(copied.begin(), copied.end(), greater<ll>());*/

        a0=re_MAX(gain_clock, N-i-1);

        ans=max(ans, tmp-(C-conditions[N-i-1][0])+a0);
    }

    cout << ans << endl;

    return 0;
}

