long long int getcal_r(int last_sushi_num)
{
	long long int sum_cal = 0;
	for (int i = 1; i <= last_sushi_num; ++i) {
		sum_cal += v[i];
	}
	sum_cal -= x[last_sushi_num];
	return sum_cal;
}
long long int getcal_l(int last_sushi_num)
{
	long long int sum_cal = 0;
	for (int i = n; i >= last_sushi_num; --i) {
		sum_cal += v[i];
	}
	sum_cal -= (c - x[last_sushi_num]);
	return sum_cal;
}
long long int getcal_b(int first_sushi_num, int last_sushi_num)
{
	long long int sum_cal = 0;
	for (int i = 1; i <= first_sushi_num; ++i) {
		sum_cal += v[i];
	}
	sum_cal -= x[first_sushi_num];
	for (int i = n; i >= last_sushi_num; --i) {
		sum_cal += v[i];
	}
	sum_cal -= (c - v[last_sushi_num]);
	if (x[first_sushi_num] > (c - x[last_sushi_num])) {
		sum_cal -= (c - x[last_sushi_num]);
	}
	else if (x[first_sushi_num] <= (c - x[last_sushi_num])) {
		sum_cal -= x[first_sushi_num];
	}
	return sum_cal;
}

