int main() {
  int N; ll C; cin >>N >>C;
  vector<ll> x(N),v(N); rep(i, N) cin >>x[i] >>v[i];
  ll res = 0;
  priority_queue<ll> left1,left2;
  // どちらも差し引き得られるカロリーを入れていく
  // left1 : 原点から左に何個か寿司を取る
  // left2 : 原点から左に何個か寿司を取ってきて原点に帰ってくる

  // 原点から時計回りにn個～0個寿司を取るとして、各々について最適なやつを選ぶ
  ll right1 = 0, right2 = 0;
  rep(i, N){ right1 += v[i]; right2 += v[i];}
  right1 -= x[N-1]; right2 -= 2*x[N-1];
  // どちらも差し引き得られるカロリーを入れていく
  // right1 : 原点から右に何個か寿司を取る
  // right2 : 原点から右に何個か寿司を取ってきて原点に帰ってくる

  // left1, right2 と left2, right1 がセットになるイメージ
  // 右回りにn, n-1, ..., 2, 1, 0 個取るときを考える
  ll leftxsum = 0;
  ll leftvsum = 0;
  for (int i=N; i>=0; i--){
    if (i < N){
      right1 -= v[i] - x[i];   if (i != 0) right1 -= x[i-1];
      right2 -= v[i] - 2*x[i]; if (i != 0) right2 -= 2*x[i-1];
    }
    if (i < N){
      leftvsum += v[i];
      leftxsum = C - x[i];
    }
    left1.push(leftvsum - leftxsum);
    left2.push(leftvsum - 2*leftxsum);

    // 右に行って帰ってきて左に行くパターン
    chmax(res, right2 + left1.top());

    // 左に行って帰ってきて右に行くパターン
    chmax(res, left2.top() + right1);
  }

  cout <<res <<endl;
}

