constexpr ll nlim = 1e5, clim = 1e14;

ll n, c;
ll x[nlim+1], v[nlim+1];
ll cum[nlim+1];

ll solve(){
  ll f[n+2], g[n+2];
  memset(f, 0, sizeof(f));
  memset(g, 0, sizeof(g));
  for(int i=1; i<=n+1; i++){
    f[i] = cum[i] - x[i];
    g[i] = max(g[i-1], f[i]);
  }

  ll res = 0;
  for(int b=1; b<=n+1; b++){
    res = max(res, g[b-1] + (cum[n] - cum[b-1]) - 2*(c-x[b]));
    //cout << res << " " << g[b-1] << " " << (cum[n] - cum[b-1]) - 2*(c-x[b]) << endl;
  }

  //cout << res << endl;
  return res;
}

