  cin >> n >> c;
  for(int i=1; i<=n; i++){
    cin >> x[i] >> v[i];
  }
  x[n+1] = c; v[n+1] = 0;

  memset(cum, 0, sizeof(cum));
  for(int i=1; i<=n+1; i++){
    cum[i] = cum[i-1] + v[i];
  }

  ll ans = 0;

  ans = max(ans, solve());

  reverse(x, x+n+2);
  reverse(v, v+n+2);
  memset(cum, 0, sizeof(cum));
  for(int i=1; i<=n+1; i++){
    cum[i] = cum[i-1] + v[i];
    x[i] = c - x[i];
  }

  ans = max(ans, solve());

  cout << ans << endl;

  return 0;
}

