  for(int i=1; i<=N; i++) {
    con_l[i] = max(con_l[i-1], sum_l[i]);
    con_r[i] = max(con_r[i-1], sum_r[i]);
  }


  int ans = 0;
  for(int i=1; i<=N; i++) {
    ans = max(ans, max(sum_r[i], sum_r[i]-x[i]+con_r[N-i]));
    ans = max(ans, max(sum_l[i], sum_l[i]-(C-x[N-i+1])+con_r[N-i]));
  }

  cout << ans << endl;
}

