  REP(i, N){
    if(i==0){
      sum[i+1] = sum[i]+v[i]-x[i];
    }
    else{
      sum[i+1] = sum[i] + v[i] -(x[i]-x[i-1]);
    }
    msum[i+1] = max(msum[i], sum[i+1]);
  }
