using P=pair<ll,ll>;
void solve(){
  ll n,c;
  cin>>n>>c;
  vector<P>v(n);
  rep(i,n)cin>>v[i].first>>v[i].second;
  priority_queue<P>pq,pq2;
  ll sum=0;
  for(int i=n-1;i>=0;--i){
    sum+=v[i].second;
    pq.emplace(sum-(c-v[i].first),v[i].first);
  }
  sum=0;
  rep(i,n){
    sum+=v[i].second;
    pq2.emplace(sum-v[i].first,v[i].first);
  }
  ll ans=0;
  ll res=0;
  rep(i,n){
    res+=v[i].second;
    chmax(ans,res-v[i].first);
    ll res2=res-v[i].first;
    res2-=v[i].first;
    while(!pq.empty()){
      auto x=pq.top();
      if(x.second>v[i].first){
        res2+=x.first;
        break;
      }
      else pq.pop();
    }
    chmax(ans,res2);
  }
  res=0;
  reverse(v.begin(),v.end());
  rep(i,n){
    res+=v[i].second;
    chmax(ans,res-(c-v[i].first));
    ll res2=res-(c-v[i].first);
    res2-=(c-v[i].first);
    while(!pq2.empty()){
      auto x=pq2.top();
      if(x.second<v[i].first){
        res2+=x.first;
        break;
      }
      else pq2.pop();
    }
    chmax(ans,res2);
  }
  cout<<ans<<endl;
}

int main(){
	ios::sync_with_stdio(false);
  cin.tie(0);
	cout<<fixed<<setprecision(15);
	solve();
	return 0;
}

