void solveSingleCase(int caseNo)
{
    int N;
    lint C;
    cin >> N >> C;

    VEC(lint) X(N), V(N);
    VEC(lint) S(N + 1, 0LL);

    FOR(i, 0, N) {
        cin >> X[i] >> V[i];
        S[i + 1] = S[i] + V[i];
    }

    lint ret = 0;
    FOR(i, 1, N + 1) {
        // go clockwise.
        lint dist = X[i - 1], eat = S[i];
        ret = max(ret, eat - dist);

        // go counter-clockwise.
        dist = C - X[i - 1];
        eat = S[N] - S[i - 1];
        ret = max(ret, eat - dist);
    }

    VEC(lint) eb(N + 1), ef(N + 1);
    eb[0] = ef[0] = 0;
    FOR(i, 1, N + 1) {
        ef[i] = max(ef[i - 1], S[i] - X[i - 1]);
        eb[i] = max(eb[i - 1], S[N] - S[N - i] - (C - X[N - i]));
    }

    FOR(i, 1, N) {
        ret = max(ret, ef[i] - X[i - 1] + eb[N - i]);
        ret = max(ret, eb[i] - (C - X[N - i]) + ef[N - i]);
    }

    cout << ret << endl;
};

