        clockwise.pb(tot - V[i].first);
        mx = max(mx, clockwise[i]);
        mxClock.pb(mx);
    }
    mx = 0, tot = 0;
    FORD(i, N - 1, 0) {
        tot += V[i].second;
        counter.pb(tot - (C - V[i].first));
        mx = max(mx, counter[N - 1 - i]);
        mxCounter.pb(mx);
    }
    // debug(clockwise);
    // debug(counter);
    // debug(mxClock);
    // debug(mxCounter);

    ll ans = 0, acc = 0;
    REP(i, N) {
        ll sum = clockwise[i];
        // debug(sum);
        if (i < N - 1) {
            auto it = lower_bound(mxCounter.begin(), mxCounter.end() - i - 2, mxCounter[N - i - 2]);
            if (*it - V[i].first > 0) {
                sum += *it - V[i].first;
            }

        }
        // debug(sum);
        ans = max(ans, sum);
    }
    REP(i, N) {
        ll sum = counter[i];
        if (i < N - 1) {
            auto it = lower_bound(mxClock.begin(), mxClock.end() - i - 2, mxClock[N - i - 2]);
            if (*it - (C - V[N - 1 - i].first) > 0) {
                sum += *it - (C - V[N - 1 - i].first);
            }
        }
        // debug(sum);
        ans = max(ans, sum);
    }
    cout << ans << endl;
}

