struct Sara {
	LL v;
	LL d1;
	LL d2;
	LL kati;
	bool used = false;
};

int main() {

	LL N, C;
	cin >> N >> C;
	vector<Sara> saras(N);
	LL maxkati = 0;
	int maxkatiindex = 0;
	REP(i, N) {
		LL x,v;
		cin >> x>>v;
		saras[i].d1 =x;//原点からの距離
		saras[i].d2 = C-x;
		saras[i].v = v;
		saras[i].kati = v - min(C - x, x);
		if (saras[i].kati > maxkati) {
			maxkatiindex = i;
			maxkati = saras[i].kati;
		}
	}

	//bool reached = false;
	if (maxkati <= 0) { cout << 0 << endl; return 0; }

	LL a = saras[maxkatiindex].v;
	int lastindex = maxkatiindex;
	LL sum = a;
	//右方向に移動
	vector<bool> reached(N);
	REP(i, SZ(reached)) { reached[i] = false; }
	vector<LL> rightroop(N), leftroop(N);
	int mi=-1;
	REP(i, N) {
		int migi = (lastindex + 1) % N;
		if (migi == maxkatiindex) { break; }
		if (migi < lastindex) { reached[i] = true;   sum += saras[migi].v - (saras[migi].d1 + saras[lastindex].d2); }
		else {
			if (i > 1) {
				reached[i] = reached[i - 1];
			}
			sum+=saras[migi].v-(saras[migi].d1 - saras[lastindex].d1);
		}
		rightroop[i] = sum;
		if (reached[i] == false) {
			rightroop[i] -= min(min(saras[maxkatiindex].d1, saras[maxkatiindex].d2), min(saras[migi].d1, saras[migi].d2));
		}
		else if (reached[i] == true&&lastindex!=N-1) {
			rightroop[i] -= min(saras[lastindex].d1,saras[migi].d2);
		}
		lastindex = migi;
	}
	rightroop[SZ(rightroop)-1]=(saras[maxkatiindex].v - min(saras[maxkatiindex].d1, saras[maxkatiindex].d2));

	lastindex = maxkatiindex;

	sum = a;
	REP(i, SZ(reached)) { reached[i] = false; }

	REP(i, N) {
		int hidari = (lastindex - 1+N) % N;
		if (hidari == maxkatiindex) { break; }

		if (hidari > lastindex) { reached[i] = true;   sum += saras[hidari].v - (saras[hidari].d2 + saras[lastindex].d1); }
		else {
			if (i > 1) {
				reached[i] = reached[i - 1];
			}
			sum += saras[hidari].v - abs(saras[hidari].d1 - saras[lastindex].d1);
		}
		leftroop[i] = sum;
		if (reached[i] == false) {
			leftroop[i] -= min(min(saras[maxkatiindex].d1, saras[maxkatiindex].d2), min(saras[hidari].d1, saras[hidari].d2));
		}
		else if (reached[i] == true && lastindex != 0) {
			leftroop[i] -= min(saras[lastindex].d2, saras[hidari].d1);
		}
		lastindex = hidari;

	}
	sort(ALL(rightroop), greater<LL>());
	sort(ALL(leftroop), greater<LL>());
	LL ans = max(rightroop[0], leftroop[0]);
	if (ans < 0) { ans = 0; }
	cout << ans << endl;

}

