const long long int MOD = 1000000007;

long long int N, M, K, H, W;

class Segment_Tree {
	vector<long long int>v;
	vector<int>l;
	vector<int>r;
	int num;
	long long int ret;
	bool is_min;
	long long int Update(int place) {
		if (place >= v.size() / 2) {
			return v[place];
		}
		if (is_min) {
			v[place] = min(Update(place * 2), Update(place * 2 + 1));
			return v[place];
		}
		v[place] = max(Update(place * 2), Update(place * 2 + 1));
		return v[place];
	}
	void RMQ(int a, int b, int place) {
		if (l[place] >= a && r[place] <= b) {
			if (is_min)ret = min(ret, v[place]);
			else ret = max(ret, v[place]);
			return;
		}
		if (l[place]>b || r[place]<a) return;
		RMQ(a, b, place * 2);
		RMQ(a, b, place * 2 + 1);
		return;
	}
public:
	void Left(int place) {
		if (place >= v.size() / 2) {
			l[place] = place - v.size() / 2;
			return;
		}
		Left(place * 2);
		Left(place * 2 + 1);
		l[place] = l[place * 2];
		return;
	}
	void Right(int place) {
		if (place >= v.size() / 2) {
			r[place] = place - v.size() / 2;
			return;
		}
		Right(place * 2);
		Right(place * 2 + 1);
		r[place] = r[place * 2 + 1];
		return;
	}
	Segment_Tree(int n, bool min) {
		n++;
		num = 1;
		while (num < n * 2) {
			num *= 2;
		}
		l.resize(num);
		r.resize(num);
		is_min = min;
		if (min) {
			v.resize(num, MOD*MOD);
		}
		else v.resize(num, -MOD * MOD);
		Left(1);
		Right(1);
	}
	void Insert(int place, long long int num, bool update) {
		place += v.size() / 2;
		v[place] = num;
		if (!update)return;
		place /= 2;
		while (place) {
			if (is_min)v[place] = min(v[place * 2], v[place * 2 + 1]);
			else v[place] = max(v[place * 2], v[place * 2 + 1]);
			place /= 2;
		}
	}
	void TopDown() {
		Update(1);
	}
	long long int RMQ(int a, int b) {
		if (is_min)ret = LLONG_MAX;
		else ret = LLONG_MIN;
		RMQ(a, b, 1);
		return ret;
	}
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> K;
	vector<pair<long long int, long long int>>v(N + 2);
	for (int i = 1; i <= N; i++) {
		cin >> v[i].first >> v[i].second;
	}
	v[N + 1].first = K;
	vector<long long int>cww(N + 2);
	vector<long long int>rcww(N + 2);
	Segment_Tree sg(N + 2, false);
	for (int i = 1; i <= N; i++) {
		cww[i] = cww[i - 1];
		cww[i] -= v[i].first - v[i - 1].first;
		cww[i] += v[i].second;
		rcww[i] = cww[i] - v[i].first;
	}
	long long int ans = 0;
	long long int sum = 0;
	for (int i = N + 1; i >= 0; i--) {
		sum += v[i].second;
		sg.Insert(i, sum - K + v[i].first, false);
	}
	sg.TopDown();
	for (int i = 0; i <= N; i++) {
		ans = max(ans, rcww[i] + sg.RMQ(i + 1, N + 1));
	}
	for (int i = 0; i <= N+1; i++) {
		sg.Insert(i, sg.RMQ(i, i) - K + v[i].first, false);
	}
	sg.TopDown();
	for (int i = 0; i <= N; i++) {
		ans = max(ans, cww[i] + sg.RMQ(i + 1, N + 1));
	}
	cout << ans << endl;
	return 0;
}

