    for (int j = N - 1; j > i; j--)
    {
      res = mymax(res, temp + l[j]);
    }
  }
  for (int i = N - 1; i >= 0; i--)
  {
    ll temp = 0;
    temp += l[i];
    res = mymax(res, temp);
    temp -= (C - x[i]);
    for (int j = 0; j < i; j++)
    {
      res = mymax(res, temp + r[j]);
    }
  }

  cout << res << endl;
  return 0;
}

