typedef struct{
    long long x;
    long long v;
    long long cw;
    long long ccw;
}Sushi;

int main(void){
    int n;
    long long c;
    cin >> n >> c;

    Sushi s[100002] = {{0}};
    int i;
    for(i = 1; i <= n; i++){
        cin >> s[i].x >> s[i].v;
        s[i].cw = s[i - 1].cw + s[i].v;
    }
    s[n + 1].x = c;
    for(i = n; i >= 1; i--){
        s[i].ccw = s[i + 1].ccw + s[i].v;
    }

    long long dist;
    long long cal;
    long long max = 0;
    int ret, end;
    // clockwise
    for(ret = n + 1; ret >= 1; ret--){
        for(end = 1; end <= n; end++){
            dist = (c - s[ret].x) * 2 + s[end].x;
            if(dist >= c){
                break;
            }
            cal = s[ret].ccw + s[end].cw - dist;
            if(cal > max){
                max = cal;
            }
        }
    }

    // counterclockwise
    for(ret = 0; ret <= n; ret++){
        for(end = n; end >= 1; end--){
            dist = s[ret].x * 2 + (c - s[end].x);
            if(dist >= c){
                break;
            }
            cal = s[ret].cw + s[end].ccw - dist;
            if(cal > max){
                max = cal;
            }
        }
    }

    cout << max << endl;

    return 0;
}

