  }
  ll r_max=0, l_max=0;
  for (int i=0;i<=N;++i){
    r_max=max(r_max, l_single[i]+r_double[i]);
    l_max=max(l_max, r_single[i]+l_double[i]);
  }
  ll ans=max(r_max, l_max);
  cout << ans << endl;
  return 0;
}

