typedef struct{
    ll x;
    ll value;
    bool eaten;
}sushi;

ll eat_sushi(int n, ll x, int index, int N, vector<sushi> data, ll C){
    cout << n << ' ' << index << endl;

    if(n == N){
        return 0;
    }

    int indexR = -1, indexL = -1;
    if(index == -1){
        indexR = 0;
        indexL = N - 1;
    }else{
        INC(i, 1, N){
            if(data[(i + index) % N].eaten == false){
                indexR = (i + index) % N;
                break;
            }
        }

        DEC(i, N - 1, 0){
            if(data[(i + index) % N].eaten == false){
                indexL = (i + index) % N;
                break;
            }
        }
    }

    ll enegyR, enegyL;
    if(indexR != - 1){
        data[indexR].eaten = true;
        ull deltaX;
        if(index < indexR){
            deltaX = data[indexR].x - x;
        }else{
            deltaX = C - (x - data[indexR].x);
        }

        enegyR = eat_sushi(n + 1, data[indexR].x, indexR, N, data, C) + data[indexR].value - deltaX;
        data[indexR].eaten = false;
    }else{
        enegyR = -10;
    }
    if(indexL != - 1){
        data[indexL].eaten = true;
        ull deltaX;
        if(index > indexL){
            deltaX = x - data[indexL].x;
        }else{
            deltaX = C - (data[indexL].x - x);
        }

        enegyL = eat_sushi(n + 1, data[indexL].x, indexL, N, data, C) + data[indexL].value - deltaX;
        data[indexL].eaten = false;
    }else{
        enegyL = -10;
    }

    ll enegyGOHome = eat_sushi(n + 1, x, index, N, data, C);

    return max(max(enegyL, enegyR), enegyGOHome);
}

