    pcal[1][n - 1] = v[n - 1] - (c - x[n - 1]);
    psum[1][n - 1] = max(0LL, pcal[1][n - 1]);
    for (int i = n - 2; i >= 0; --i) {
        pcal[1][i] = pcal[1][i + 1] + v[i] - (x[i + 1] - x[i]);
        psum[1][i] = max(psum[1][i + 1], pcal[1][i]);
    }
    ll ret = 0;
    for (int i = 0; i < n; ++i) {
        chmax(ret, pcal[0][i]);
        chmax(ret, pcal[1][i]);
        if (i != n - 1) {
            chmax(ret, pcal[0][i] + psum[1][i + 1] - x[i]);
            chmax(ret, psum[0][i] + pcal[1][i + 1] - (c - x[i + 1]));
        }
    }
    cout << ret << "\n";
    return 0;
}

