  vector<LL> acum_cw(N);
  LL acum = 0;
  for (int i = 0; i < N; ++i) {
    acum += sushi[i].second;
    acum_cw[i] = acum;
  }
  vector<LL> acum_ccw(N);
  acum = 0;
  for (int i = N - 1; i >= 0; i--) {
    acum += sushi[i].second;
    acum_ccw[i] = acum;
