  }

  ll ans = 0;
  rep(i, N){ // x[i]までとりに行く
    ll cand = S[i+1];
    cand = max(cand,
               cand-x[i] + Rmax[i+1]); // 一度原点に戻って、xi+1まで取りに行くときの最大地
    ans = max(ans, cand);
  }
  rrep(i, N){ // xiまでとりに行く
    ll cand = R[i];
    cand = max(cand,
               cand-(C-x[i]) + Smax[i]); // 一度原点に戻って、xi-1まで取りに行くときの最大地
    ans = max(ans, cand);
  }

  cout << ans << endl;

  return 0;
}

