        now += v[i];
        now -= (i == N-1 ? C - x[i] : x[i+1] - x[i]);
        ans = max(ans, now);
    }

    // right
    now = 0;
    RREP(i, N-1){
        now += v[i];
        now -= (i == N-1 ? x[i] : x[i+1] - x[i]);
        ans = max(ans, now);
    }

    cout << ans << endl;
}

