using namespace std;

#define ll long long

int N;
ll C;
vector<ll> x;
vector<ll> v;
ll maxc = 0, c = 0;
vector<ll> cr, cl;
ll maxcr=0, maxcl=0;

int input(){
  cin >> N >> C;
  x.resize(N+2);
  v.resize(N+2);
  cr.resize(N+2);
  cl.resize(N+2);
  x[0]=0;v[0]=0;cr[0]=0;cl[0]=0;
  x[N+1]=0;v[N+1]=0;cr[N+1]=0;cl[N+1]=0;
  for( int i = 1; i <= N; i++ ){
    cin >> x[i] >> v[i];
  }
  return 0;
}

int run(){
  c = 0;
  for( int i = 1; i <= N; i++ ){
    c += v[i];
    cr[i] = c-x[i];
    if( c-x[i] > maxcr ){ maxcr = c-x[i]; }
    cr[i] = maxcr;
  }
  c = 0;
  for( int i = N; i >= 1; i-- ){
    c += v[i];
    cl[i] = c-(C-x[i]);
    if( c-(C-x[i]) > maxcl ){ maxcl = c-(C-x[i]); }
    cl[i] = maxcl;
  }
  maxc = (maxcr>maxcl ? maxcr : maxcl);
  c = 0;
  for( int i = 1; i <= N; i++ ){
    // cout << "i:" << i << endl;
    c = cr[i]+cl[i+1]-x[i];
    // cout << c << endl;
    if( c > maxc ){ maxc = c; }
    c = cl[i]+cr[i-1]-(C-x[i]);
    if( c > maxc ){ maxc = c; }
    // cout << c << endl;
  }
  cout << maxc << endl;
  return 0;
}

int main(){
  input();
  run();
  return 0;
}

