/* main */
int main(){
    int N; ll C;
    cin >> N >> C;
    vector<vector<ll> > vX(2, vector<ll>(N + 1)), vV(2, vector<ll>(N + 1));
    for (int i = 1; i <= N; i++) { scanf("%ld %ld", &vX[0][i], &vV[0][i]); }
    // vX[0] = [0, C - x0, ..., C - x(N-1)]
    // vX[1] = [C - x0, ..., C - x(N-1), 0]
    for (int i = 1; i <= N; i++) {
        vX[1][i - 1] = C - vX[0][i];
        vV[1][i - 1] = vV[0][i];
    }
    // Vについて累積和
    // vV[0] = [0, v0, v0 + v1, ...]
    // vV[1] = [..., v(N-2) + v(N-1), v(N-1), 0]
    for (int i = 0; i < N; i++) {
        vV[0][i + 1] += vV[0][i];
        vV[1][N - (i + 1)] += vV[1][N - i];
    }
    // vMax[i][j] j番目までの最大ゲイン
    // vMax[0] : 0 ~ j
    // vMax[1] : N-1 - j ~ N-1
    vector<vector<ll> > vMax(2, vector<ll>(N + 1));
    for (int i = 1; i <= N; i++) {
        vMax[0][i] = max(vMax[0][i - 1], vV[0][i] - vX[0][i]);
        vMax[1][N - i] = max(vMax[1][N - (i - 1)], vV[1][N - i] - vX[1][N - i]);
    }

    ll ans = -LINF;
    // min(時計周り -> 反時計回り or 反時計周り -> 時計回り)
    for (int i = 0; i <= N; i++) {
        ans = max(ans, vV[0][i] - vX[0][i] * 2 + vMax[1][i]);
        ans = max(ans, vV[1][i] - vX[1][i] * 2 + vMax[0][i]);
    }
    cout << ans << '\n';
}

