typedef long long ll;

int main(){
    int N;cin>>N;
    ll C;cin>>C;
    vector<ll> x(100010),y(100010),v(100010),L(100010),R(100010),lmax(100010),rmax(100010); 
    //L[i] 時計回りで寿司iまで食べた時のエネルギー
    //lmax[i] 時計回りで寿司iまで食べた時の最大値
    L[0]=x[0]=lmax[0]=0;
    for(int i=1;i<=N;i++){
        cin>>x[i]>>v[i];
        L[i]=L[i-1]+v[i]-(x[i]-x[i-1]);
        lmax[i]=max(L[i],lmax[i-1]);
    }
    R[0]=y[0]=rmax[0]=0;
    for(int i=1;i<=N;i++){
        y[i]=C-x[N+1-i];
        R[i]=R[i-1]+v[N+1-i]-(y[i]-y[i-1]);
        rmax[i]=max(R[i],rmax[i-1]);
    }
    //右側で折り返し
    int i=1;
    ll r_turn=0;
    while(2*y[i]<=C){
        r_turn=max(r_turn,R[i]-y[i]+lmax[N-i]);
        i++;
        if(i==N+1)break;
    }
    //左側で折り返し
    int j=1;
    ll l_turn=0;
    while(2*x[j]<=C){
        l_turn=max(l_turn,L[j]-x[j]+rmax[N-j]);
        j++;
        if(j==N+1)break;
    }

    ll ans=max(max(lmax[N],rmax[N]),max(l_turn,r_turn));
    cout<<ans<<endl;
    return 0;
}

