long long int search(vector<pair<long long int, long long int>> &sushi, long long int &C)
{
    long long int ans = 0;
    for (size_t B = 0; B <= sushi.size(); B++)
    {
        for (size_t A = B + 1; A <= sushi.size() + 1; A++)
        {
            long long int sum = 0;
            for (size_t i = A; i - 1 < sushi.size(); i++)
            {
                sum += sushi[i - 1].second;
            }
            if (A <= sushi.size())
                sum -= (C - sushi[A - 1].first) * 2;
            for (size_t i = 1; i <= B; i++)
            {
                sum += sushi[i - 1].second;
            }
            if (B != 0)
                sum -= sushi[B - 1].first;
            if (ans < sum)
            {
                ans = sum;
            }
        }
    }
    return ans;
}

int main(int argc, char const *argv[])
{
    int N;
    long long int C;
    scanf("%d %lld\n", &N, &C);
    vector<pair<long long int, long long int>> sushi(N), sushiReversed(N);
    for (size_t i = 0; i < N; i++)
    {
        scanf("%lld %lld\n", &(sushi[i].first), &(sushi[i].second));
        sushiReversed[N - i - 1].first = C - sushi[i].first;
        sushiReversed[N - i - 1].second = sushi[i].second;
    }
    long long int leftStart, rightStart;
    leftStart = search(sushi, C);
    rightStart = search(sushiReversed, C);
    cout << max(leftStart, rightStart) << endl;
    return 0;
}

