using namespace std;
using ll = long long;
int mod = 1000000007;

int main(void){
    int N; ll C; cin >> N >> C;
    pair<ll, ll> sushi[N];
    rep(i, N){
        cin >> sushi[i].first >> sushi[i].second;
    }
    ll watch_val[N]; //watch_val[i]: 時計回りで,sushi[i]まで到達した時の価値の最大
    ll anti_watch_val[N];

    // watch_valの用意
    ll acc = sushi[0].second - sushi[0].first;
    watch_val[0] = max(0ll, acc);
    for(int i = 1; i < N; i++){
        acc += sushi[i].second - (sushi[i].first - sushi[i-1].first);
        watch_val[i] = max(watch_val[i-1], acc);
    }

    acc = sushi[N-1].second - (C - sushi[N-1].first);
    anti_watch_val[N-1] = max(0ll, acc);
    for(int i = N-2; i >= 0; i--){
        acc += sushi[i].second - (sushi[i+1].first - sushi[i].first);
        anti_watch_val[i] = max(anti_watch_val[i+1], acc);
    }
    //rep(i, N) cout << watch_val[i] << " "; cout << endl;
    //rep(i, N) cout << anti_watch_val[i] << " "; cout << endl;
    vector<ll> choice;
    choice.push_back(watch_val[N-1]);
    choice.push_back(anti_watch_val[0]);

    //時計回り -> 反時計回り
    for(int i = 0; i < N-1; i++){
        //iまで時計回りで行く
        choice.push_back(watch_val[i] - sushi[i].first + anti_watch_val[i+1]);
    }
    //反時計回り -> 時計回り
    for(int i = N-1; i > 0; i--){
        choice.push_back(anti_watch_val[i] - (C - sushi[i].first) + watch_val[i-1]);
    }

    //choiceの中で最大の値を出力
    ll ans = 0ll;
    rep(i, choice.size()) ans = max(ans, choice[i]);
    cout << ans << endl; 
    return 0;
}

