  // Backward -> Forward
  for (it = v_cost.begin(); it != v_cost.end(); it++) {    
    for (it2 = v_cost2.begin(); it2 != v_cost2.end(); it2++) {
      if (it->first + it2->first > N) { continue; }
      ll step = it->first == 0 || it2->first == 0 ? 0 : vp2[it2 - v_cost2.begin()-1].first;      
      ll all_cal = it2->second + it->second - step;
