using P=pair<ll,ll>;
void solve(){
  ll n,c;
  cin>>n>>c;
  vector<P>v(n);
  rep(i,n)cin>>v[i].first>>v[i].second;
  vector<ll>cal(n+1),cal2(n+1);
  ll sum=0;
  for(int i=n-1;i>=0;--i){
    sum+=v[i].second;
    cal[i+1]=max(cal[i],sum-(c-v[i].first));
  }
  sum=0;
  rep(i,n){
    sum+=v[i].second;
    cal2[i+1]=max(cal2[i],sum-v[i].first);
  }
  ll ans=0;
  ll res=0;
  //時計回り
  rep(i,n){
    res+=v[i].second;
    chmax(ans,res-v[i].first);//戻らないとき
    ll res2=res-v[i].first;//戻るとき
    res2-=v[i].first;
    res2+=cal[i+1];
    chmax(ans,res2);
  }
  res=0;
  reverse(v.begin(),v.end());
  //反時計回り
  rep(i,n){
    res+=v[i].second;
    chmax(ans,res-(c-v[i].first));//戻らないとき
    ll res2=res-(c-v[i].first);//戻るとき
    res2-=(c-v[i].first);
    res2+=cal2[n-i];
    chmax(ans,res2);
  }
  cout<<ans<<endl;
}

int main(){
	ios::sync_with_stdio(false);
  cin.tie(0);
	cout<<fixed<<setprecision(15);
	solve();
	return 0;
}

