int cam3(eat x,eat y)
{
	return x.f<y.f;
}
int main()
{
	int n;
	long long r;
	cin>>n>>r;
	for(int i=0;i<n;i++)cin>>p[i].l>>p[i].e;
	int s=n;
    long long tem=0;
