	while(s--)
	{
		for(int i=0;i<=s;i++)
		{
			if(abs(p[i].l-tem)*2>r)
			{
				if(tem<p[i].l)p[i].h=p[i].e-abs(r-(p[i].l-tem));
				else p[i].h=p[i].e-abs(r-(tem-p[i].l));
				p[i].f=abs(r-abs(p[i].l-tem));
			}
