  vector<ll> x(N), v(N);
  vector<ll> effect_max_right(N), effect_max_left(N);
  ll v_sum=0;
  rep(i, 0, N){
    cin >> x[i] >> v[i];
    if(i==0){
      effect_max_right[i] = max(v[i] - x[i], (ll)0);
    }else{
      effect_max_right[i] = max(v[i] + v_sum - x[i], effect_max_right[i-1]);
    }
    v_sum += v[i];
  }
  v_sum = 0;
  rep(i, 0, N){
    if(i==0){
      effect_max_left[i] = max(v[N-1-i] - (C-x[N-1-i]), (ll)0);
    }else{
      effect_max_left[i] = max(v[N-1-i] + v_sum - (C-x[N-1-i]), effect_max_left[i-1]);
    }
    v_sum += v[N-1-i];
  }

  ll ans = max(effect_max_right[N-1], effect_max_left[N-1]);
  cout << effect_max_right[N-1] << " " << effect_max_left[N-1] << endl;
  rep(i, 0, N-1){
