	}

	vector<ll> s1(n + 1);
	s1[0] = 0;
	ll now = 0;

	REP(i, n) {
		s1[i + 1] = s1[i] + (p[i].second - p[i].first + now);
		now = p[i].first;
	}

	vector<ll> s2(n + 1);
	s2[0] = 0;
	now = c;

	REP(i, n) {
		s2[i + 1] = s2[i] + (p[n - 1 - i].second + p[n - 1 - i].first - now);
		now = p[n - i - 1].first;
	}

	ll ans = 0;
	ll sum = 0;
	pair<ll, ll> z;

	priority_queue<pair<ll, ll>> q;
	q.push(make_pair(-INF, n + 1));

	REP(i, n) {
		q.push(make_pair(s2[i + 1], n - i));
	}

	ans = max(ans, q.top().first);

	REP(i, n) {
		sum = s1[i + 1];
		while (i + 1 >= q.top().second) {
			q.pop();
		}
		z = q.top();
		if (z.first > p[i].first) {
			sum += z.first - p[i].first;
		}
		ans = max(ans, sum);
	}

	priority_queue<pair<ll, ll>> q2;
	q2.push(make_pair(-INF, 0));

	REP(i, n) {
		q2.push(make_pair(s1[i + 1], i + 1));
	}

	ans = max(ans, q2.top().first);

	REP(i, n) {
