    for(int i = 0; i < n; ++i){
        cin >> x[i] >> v[i];
        rev[i] = c - x[i];
    }

    vector<SegmentTree<ll>> clockwise(2, SegmentTree<ll>(n + 1, [](ll a, ll b){return max(a, b);}, 0ll));
    ll val = 0;
    for(int i = 0; i < n; ++i){
        val += v[i];
        clockwise[0].update(i + 1, val - x[i]);
        clockwise[1].update(i + 1, val - x[i] * 2);
    }

    vector<SegmentTree<ll>> counter_clockwise(2, SegmentTree<ll>(n + 1, [](ll a, ll b){return max(a, b);}, 0ll));
    val = 0;
    for(int i = n - 1; i >= 0; --i){
        val += v[i];
        counter_clockwise[0].update(i, val - rev[i]);
        counter_clockwise[1].update(i, val - rev[i] * 2);
    }

    // for(int i = 0; i <= n; ++i) cerr << clockwise[0][i] << " ";
