struct Sushi
{
    int64_t pos;
    int64_t value;
};

int main()
{
    int64_t n, circumference;
    cin >> n >> circumference;

    vector<Sushi> sushi(n);
    for (auto &s : sushi) {
        cin >> s.pos >> s.value;
    }

    vector<int64_t> balance_clock(n);
    vector<int64_t> balance_counter(n);

    int64_t balance = 0;
    for (int64_t i = 0; i < n; i += 1) {
        balance -= sushi[i].pos - (i == 0 ? 0 : sushi[i - 1].pos);
        balance += sushi[i].value;
        balance_clock[i] = balance;
        if (i > 0) {
            balance_clock[i] = max(balance_clock[i], balance_clock[i - 1]);
        }
    }

    balance = 0;
    for (int64_t i = n - 1; i >= 0; i -= 1) {
        balance -= (i == n - 1 ? circumference : sushi[i + 1].pos) - sushi[i].pos;
        balance += sushi[i].value;
        balance_counter[i] = balance;
        if (i < n - 1) {
            balance_counter[i] = max(balance_counter[i], balance_counter[i + 1]);
        }
    }

    int64_t res = 0;
    for (int64_t i = 0; i < n; i += 1) {
        int64_t value = balance_clock[i];
        res = max(res, value);

        value += (i + 1 < n ? balance_counter[i + 1] : 0) - sushi[i].pos;
        res = max(res, value);
    }

    for (int64_t i = n - 1; i >= 0; i -= 1) {
        int64_t value = balance_counter[i];
        res = max(res, value);

        value += sushi[i].pos - circumference + (i > 0 ? balance_clock[i - 1] : 0);
        res = max(res, value);
    }

    cout << res << "\n";
    return 0;
}

