inline int pd(ll w,int l,int r)
{
	int mid,ret=0;
	while (l<r)
	{
		mid=l+r+1>>1;
		if (t[mid]==w) return mid;
		if (t[mid]>w) l=mid,ret=mid;
		else r=mid-1;
	}
	if (ret==0) return mid;
	else return ret;
}

inline int lowbit(int x){return x&(-x);}

void add(int x,ll k)
{
	while (x<=n) 
	{
		f[x]=l[x]-t[x];
		for (int i=1;i<lowbit(x);i<<=1) f[x]=max(f[x],f[x-1]);
		x+=lowbit(x);
	}
}

ll query(int x,int y)
{
	ll ret=0;
	while(y>=x)
	{
		ret=max(ret,l[y]-t[y]),--y;
		for (;y-lowbit(y)>=x;y-=lowbit(y)) ret=max(f[y],ret);
	}
	return ret;
}

void add2(int x,ll k)
{
	while (x<=n) 
	{
		g[x]=l[x];
		for (int i=1;i<lowbit(x);i<<=1) g[x]=max(g[x],g[x-1]);
		x+=lowbit(x);
	}
}

ll query2(int x,int y)
{
	ll ret=0;
	while(y>=x)
	{
		ret=max(ret,l[y]),--y;
		for (;y-lowbit(y)>=x;y-=lowbit(y)) ret=max(g[y],ret);
	}
