	return x*f;
}

inline void writ(ll x)
{
	if(x<0) putchar('-'),x=-x;
	if(x>9) writ(x/10);
	putchar(x%10+'0');
}
inline void write(ll x){writ(x);putchar('\n');}

int main()
{
	ll ans=0;
	n=read(),c=read();
	for (int i=1;i<=n;++i) d[i]=read(),t[i]=c-d[i],v[i]=read();
	for (int i=1;i<=n;++i) ww+=v[i],s[i]=ww-d[i],ans=max(ans,s[i]);ww=0;
	for (int i=n;i>=1;--i) ww+=v[i],l[i]=ww-t[i],ans=max(ans,l[i]);
	for (int i=1;i<=n;++i) add(i,l[i]-t[i]),add2(i,l[i]);
	for (int i=1;i<n;++i)
	{
		if (d[i]<=t[n]) ans=max(ans,s[i]-d[i]+query2(i+1,n));
		else if (d[i]>=t[i+1]) ans=max(ans,s[i]+query(i+1,n));
