	map<int, pair<long long, long long>> bm;
	for (size_t i = 0; i < N; i++)
	{
		fs += vl[i] - (xl[i] - fp);
		if (fs > maxfs) {
			maxfs = fs;
			maxfsi = xl[i];
		}
		else if(i > 0){
			maxfs = fm[i - 1].first;
			maxfsi = fm[i - 1].second;
		}
		fm[i] = pair<long long,long long>(maxfs,maxfsi);
		fp = xl[i];
	}
	for (int i = N - 1; i >= 0; i--)
	{
		bs += vl[i] - (bp - xl[i]);
		if (bs > maxbs) {
			maxbs = bs;
			maxbsi = xl[i];
		}
		else if(i < (N - 1)){
			maxbs = bm[i + 1].first;
			maxbsi = bm[i + 1].second;
