			long long p2 = fm[i].first - (C - bm[i].second) + bm[i + 1].first;
			maxv = max(maxv, max(p1, max(p2, max(fm[i].first, bm[i + 1].first))));
		}
		else {
			maxv = max(maxv, max(fm[i].first,bm[0].first));
		}
	}
