  int dp[2][N];
  fill(dp[0],dp[0]+N,0);
  int cal = 0;
  for(int i = 0; i < n; i++){
    //それまでの最大カロリーを記録
    cal += v[i+1] - (x[i+1] - x[i]);
    dp[0][i+1] = max(dp[0][i],cal);
  }
  cal = 0;
  for(int i = n; i > 0; i--){
    cal += v[i] - (x[i+1] - x[i]);
    dp[1][i] = max(dp[1][i+1],cal);
  }

  int ans = 0;
  for(int i = 0; i <= n; i++){
    //時計周り
    ans = max(ans,dp[0][i] - x[i] + dp[1][i+1]);
    //反時計周り
    ans = max(ans,dp[1][i+1] - (c-x[i+1]) + dp[0][i]);
  }
  cout << ans << endl;

  return 0;
}

