ll x[100010], v[100010];

// 初期位置からi番目の寿司を食べるまでに得るカロリー
ll cal_cw[100010]; // 時計回り(clockwise)
ll cal_ccw[100010]; // 反時計回り(counter-clockwise)
ll a_ix_best[100010];

int main() {
	ll N, C;
	cin >> N >> C;

	REP(i, N) {
		cin >> x[i] >> v[i];
	}

	// 時計回り
	REP(i, N) {
		if (i > 0) {
			cal_cw[i] = cal_cw[i - 1] + v[i] - (x[i] - x[i - 1]);
		}
		else {
			cal_cw[0] = v[0] - x[0];
		}
	}

	// 反時計回り
	for (int i = N - 1; i >= 0; --i) {
		if (i < (N - 1)) {
			cal_ccw[i] = cal_ccw[i + 1] + v[i] - (x[i + 1] - x[i]);
		}
		else {
			cal_ccw[N - 1] = v[N - 1] - (C - x[N - 1]);
		}
	}

	// Bの位置(b_ix)を固定したときの最適なA:[O,b_ix)の位置(a_ix_best)を求める
	a_ix_best[1] = 0; // b_ix = 1のときは強制的に決まる。b_ix = 0のときは定義されない。
	REPS(b_ix, 2, N) {

		if (cal_cw[b_ix - 1] > cal_cw[a_ix_best[b_ix - 1]]) {
			a_ix_best[b_ix] = b_ix - 1; // 更新
		}
		else {
			a_ix_best[b_ix] = a_ix_best[b_ix - 1]; // 引継ぎ
		}
		//cout << a_ix_best[b_ix] << " ";
	}
	//cout << endl;

	ll ans = 0;

	REPS(b_ix, 1, N) {
		ll ans_oaob = 0, ans_oboa = 0, ans_oab = 0, ans_oba;

		//cout << "b_ix: " << b_ix << endl;

		// O→B→O→Aの場合の取得カロリー
		ans_oboa += cal_ccw[b_ix];
		ans_oboa -= (C - x[b_ix]);
		ans_oboa += cal_cw[a_ix_best[b_ix]];
		//cout << ans_oboa<<endl;

		// O→A→O→Bの場合の取得カロリー
		ans_oaob += cal_cw[a_ix_best[b_ix]];
		ans_oaob -= x[a_ix_best[b_ix]];
		ans_oaob += cal_ccw[b_ix]; // O→B
		//cout << ans_oaob << endl;

		// O→A→Bの場合の取得カロリー
		ans_oab = cal_cw[b_ix];

		// O→B→Aの場合の取得カロリー
		ans_oba = cal_ccw[a_ix_best[b_ix]];

		ans = max(ans, max(max(ans_oab,ans_oba), max(ans_oboa, ans_oaob)));
		//cout << ans << endl;
	}

	cout << ans;
	system("pause");
	return 0;
}

