  long long C;
  cin >> N >> C;

  vector<long long> x(N);
  vector<long long> v(N);
  for (int i = 0; i < N; ++i) {
    cin >> x[i] >> v[i];
  }

  long long ans = 0;

  {
    long long sum_r = 0;  // clock wise
    for (int i = 0; i < N; ++i) {
      sum_r += v[i];
      long long sum_l = 0;
      for (int j = N - i - 1; j > i; --j) {
        sum_l += v[j];
        const auto total = sum_l + sum_r - (x[i] + x[i] + (C - x[j]));
        ans = max(ans, total);
      }
      ans = max(ans, sum_r - x[i]);
    }
  }
  {
    long long sum_l = 0;  // anti clock wise
    for (int i = N - 1; i >= 0; --i) {
      sum_l += v[i];
      long long sum_r = 0;
      for (int j = 0; j < i; ++j) {
        sum_r += v[j];
        const auto total = sum_l + sum_r - (x[j] + 2 * (C - x[i]));
        ans = max(ans, total);
      }
      ans = max(ans, sum_l - (C - x[i]));
    }
  }

  cout << ans << endl;
  return 0;
}

