#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
#define REP(i, n) for(int i=0; i<n; i++)

ll X[100100];
ll V[100100];
ll RS[100100];
ll LS[100100];
ll MRS[100100];
ll MLS[100100];
int main(){
    ll N, C;
    cin >> N >> C;
    REP(i, N){
        ll x, v;
        cin >> x >> v;
        X[i] = x;
        V[i] = v;
    }

    RS[0] = V[0] - X[0];
    MRS[0] = RS[0];
    for(int i = 1; i < N; i++){
        RS[i] = RS[i-1] + V[i] - (X[i] - X[i-1]);
        MRS[i] = max(MRS[i-1], RS[i]);
    }

    LS[N-1] = V[N-1] - (C-X[N-1]);
    MLS[N-1] = LS[N-1];
    for(int i = N-2; i >= 0; i--){
        LS[i] = LS[i+1] + V[i] + (X[i] - X[i+1]);
        MLS[i] = max(MLS[i+1], LS[i]);
    }

    ll ans = 0;
    for(int i = 0; i < N; i++){
        ll num = 0;
        num += MRS[i];
        if(i != N-1){
            num -= X[i];
            num += MLS[i+1];
        }
        ans = max(ans, num);
    }

    for(int i = N-1; i >= 0; i--){
        ll num = 0;
        num += MLS[i];
        if(i != 0){
            num -= C - X[i];
            num += MRS[i-1];
        }
        ans = max(ans, num);
    }


    cout << ans << endl;
    return 0;
}

