	sort(a+1,a+1+n,my);a[n+1].x=c;
	for(int i=1;i<=n;i++) fl[i]=fl[i-1]+a[i].v+a[i-1].x-a[i].x,ml[i]=max(ml[i-1],fl[i]);
	for(int i=n;i>=1;i--) fr[n-i+1]=fr[n-i]+a[i].v+a[i].x-a[i+1].x,mr[i]=max(mr[n-i],fr[n-i+1]);
	ans=max(ml[n],mr[n]);
