int main() {
    Int n, c;
    cin >> n >> c;
    vector<Int> x(n), v(n);
    for (Int i = 0; i < n; i++) cin >> x[i] >> v[i];
    vector<Int> a(n + 1, 0), b(n + 1, 0);
    for (Int i = 0; i < n; i++) a[i + 1] += a[i] + v[i];
    for (Int i = 0; i < n; i++) b[i + 1] += b[i] + v[i];
    for (Int i = 1; i <= n; i++) a[i] -= x[i - 1];
    for (Int i = 0; i < n; i++) a[i + 1] = max(a[i + 1], a[i]);
    Int res = 0;
    for (Int i = 0; i < n; i++) {
        // B が x[i] のときの最大を O(1) で求めたい
        Int ma = b[n] - b[i] - 2LL * (c - x[i]) + a[i];
        if (a[i] == 0) ma += c - x[i];
        res = max(res, ma);
    }
    vector<Int> xr(n), vr(n);
    for (Int i = 0; i < n; i++) {
        xr[i] = c - x[n - 1 - i];
        vr[i] = v[n - 1 - i];
    }
    vector<Int> ar(n + 1, 0), br(n + 1, 0);
    for (Int i = 0; i < n; i++) ar[i + 1] += ar[i] + vr[i];
    for (Int i = 0; i < n; i++) br[i + 1] += br[i] + vr[i];
    for (Int i = 1; i <= n; i++) ar[i] -= xr[i - 1];
    for (Int i = 0; i < n; i++) ar[i + 1] = max(ar[i + 1], ar[i]);
    for (Int i = 0; i < n; i++) {
        Int ma = br[n] - br[i] - 2LL * (c - xr[i]) + ar[i];
        if (ar[i] == 0) ma += c - xr[i];
        res = max(res, ma);
    }
    dump(res);
    return 0;
}

