typedef pair<li, li> PI;

li v[100100];
li x[100100];
li n, c;

PI dp1[100100];
PI dp2[100100];

int main(void)
{
    cin >> n >> c;
    rin{
        cin >> x[i] >> v[i];
    }
    li res = 0;

    li tsum = v[0];
    if (v[0] < x[0]) {
        dp1[0] = {0, 0};
    } else {
        dp1[0] = {v[0] - x[0], x[0]};
    }
    res = max(res, dp1[0].F);
    repp(i, 1, n) {
        // clockwise
        tsum += v[i];
        if (tsum - x[i] > dp1[i - 1].F) {
            dp1[i] = {tsum - x[i], x[i]};
        } else {
            dp1[i] = dp1[i - 1];
        }

        res = max(res, dp1[i].F);
    }
    tsum = v[n - 1];
    if (v[n - 1] > (c - x[n - 1])) {
        dp2[n - 1] = {v[n - 1] - (c - x[n - 1]), c - x[n - 1]};
    } else {
        dp2[n - 1] = {0, 0};
    }
    res = max(res, dp2[n - 1].F);
    for (li i = n - 2; i >= 0; --i) {
        // counter-clockwise
        tsum += v[i];
        if (tsum - (c - x[i]) > dp2[i + 1].F) {
            dp2[i] = {tsum - (c - x[i]), c - x[i]};
        } else {
            dp2[i] = dp2[i + 1];
        }
        res = max(res, dp2[i].F);
    }

    rin{
        if (i < n - 1) {
            res = max(res, dp1[i].F + dp2[i + 1].F - dp1[i].S);
        }
        if (i > 0) {
            res = max(res, dp2[i].F + dp1[i - 1].F - dp2[i].S);
        }
    }
    cout << res << endl;

    return 0;
}

