#define ll long long
#define loop(__x, __start, __end) for(int __x = __start; __x < __end; __x++)

struct P { ll x, v; };

int main() {
  ll n, c; in(n),in(c);
  vector<P> A(n);
  loop(i,0,n) in(A[i].x),in(A[i].v);
  vector<ll> acc(n+1);
  acc[0] = 0;
  loop(i,0,n) acc[i+1] = acc[i] + A[i].v;
  ll ans = 0;
  loop(i,1,n+1) { // i個取る
    ans = max(ans, acc[i] - A[i-1].x); // 右にi個とる時の最大価値
  }
  loop(i,1,n+1) {
    ans = max(ans, acc[n] - acc[n-i] - (c - A[n-i].x)); // 左にi個とる時の最大価値.
  }

  // 3) 右にi個とり、Oに戻って最大でn-i個とる時の最大値 O(N^2)
  loop(i,1,n) { // 1個からn-1まで. 0個の場合は左からしか取らない、nの場合は右からしか取らないので.
    ll right = acc[i] - 2 * A[i-1].x; // 往復コスト
    loop(j,1,n) {
      if (i+j>n) break;
      ll left = acc[n] - acc[n-j] - (c - A[n-j].x);
      ans = max(ans, right+left);
    }
  }

  // 4) 左にi個とり、Oに戻って最大でn-i個とる時の最大値O(N^2)
  loop(i,1,n) {
    ll left = acc[n] - acc[n-i] - 2 * (c - A[n-i].x); // 往復コスト
    loop(j,1,n) {
      if (i+j>n) break;
      ll right = acc[j] - A[j-1].x;
      ans = max(ans, left+right);
    }
  }
  print(ans);
  return 0;
}

