  x[0] = 0;
  v[0] = 0;
  for (int i = 1; i <= N; i++) {
    cin >> x[i] >> v[i];
  }

  long long f[N], g[N], gx[N];
  f[0] = 0;
  g[0] = 0;
  gx[N] = 0;
  for (int i = 1; i <= N; i++) {
    f[i] = f[i - 1] + v[i] + x[i - 1] - x[i];
    g[i] = max(g[i - 1], f[i]);
    if (g[i] == f[i]) gx[i] = x[i];
    else gx[i] = gx[i - 1];
  }

  long long ans = g[N];
  long long rf = v[N] - (C - x[N]);
  ans = max(ans, rf + g[N - 1] - min(C - x[N], gx[N - 1]));
  for (int i = N - 1; i >= 2; i--) {
    rf = rf + v[i] + (C - x[i + 1]) - (C - x[i]);
    ans = max(ans, rf + g[i - 1] - min(C - x[i], gx[i - 1]));
  }
  cout << ans << endl;
}

