	for (auto i = 0; i < N; ++i)
	{
		long long x, v;
		cin >> x >> v;
		list.push_back(make_pair(x, v));
	}

	auto result = 0ll;
	vector<long long> sumListA;
	vector<long long> maxListA;
	auto tempSumA = 0ll;
	auto tempMaxA = 0ll;
	vector<long long> sumListB;
	vector<long long> maxListB;
	auto tempSumB = 0ll;
	auto tempMaxB = 0ll;
	for (auto i = 0; i < N; ++i)
	{
		tempSumA += list[i].second;
		tempMaxA = max(tempSumA - list[i].first, tempMaxA);
		sumListA.push_back(tempSumA);
		maxListA.push_back(tempMaxA);

		auto j = N - i - 1;
		tempSumB += list[j].second;
		tempMaxB = max(tempSumB - (C - list[j].first), tempMaxB);
		sumListB.push_back(tempSumB);
		maxListB.push_back(tempMaxB);
	}

	for (auto i = 0; i < N; ++i)
	{
		auto sumA = sumListA[i];
		auto sumB = sumListB[i];
		sumA -= list[i].first;
		sumB -= C - list[N - i - 1].first;
		if (i < N - 1)
		{
			auto b = maxListB[N - (i + 1) - 1];
			auto cost = list[i].first;
			if (b > cost)
			{
				sumA -= cost;
				sumA += b;
			}

			auto a = maxListA[N - i - 2];
			cost = C - list[N - i - 1].first;
			if (a > cost)
			{
				sumB -= cost;
				sumB += a;
			}
		}
		result = max(result, sumA);
		result = max(result, sumB);
	}

	cout << result << endl;

	return 0;
}

