using namespace std;

int N;
long long C;

// f(a) = v[0] + v[1] + ... + v[a-1] - x[a-1]
long long Soa[100000] = {0};
long long Sob[100000] = {0};
// g(a) = max(f(0), f(1), ..., f(a))
long long Moa[100000] = {0};
long long Mob[100000] = {0};

// OA + 2OB
long long solve_oa_2ob(const vector<long long>& x) {
  long long ans = Moa[N - 1];
  for (int i = N - 1; i > 0; --i) {
    const auto w_2ob = Sob[i] - (C - x[i]);
    const auto w_oa = Moa[i - 1];
    ans = max(ans, w_oa + w_2ob);
  }
  return ans;
}

// 2OA + OB
long long solve_2oa_ob(const vector<long long>& x) {
  long long ans = Mob[0];
  for (int i = 0; i < N - 1; ++i) {
    const auto w_2oa = Soa[i] - x[i];
    const auto w_ob = Mob[i + 1];
    ans = max(ans, w_2oa + w_ob);
  }
  return ans;
}

int main() {
  cin >> N >> C;

  vector<long long> x(N);
  vector<long long> v(N);

  long long sum = 0;
  for (int i = 0; i < N; ++i) {
    cin >> x[i] >> v[i];

    sum += v[i];
    Soa[i] = sum - x[i];
  }

  sum = 0;
  for (int i = N - 1; i >= 0; --i) {
    sum += v[i];
    Sob[i] = sum - (C - x[i]);
  }

  Moa[0] = Soa[0];
  for (int i = 1; i < N; ++i) {
    Moa[i] = max(Moa[i - 1], Soa[i]);
  }

  Mob[N - 1] = Sob[N - 1];
  for (int i = N - 2; i >= 0; --i) {
    Mob[i] = max(Mob[i + 1], Sob[i]);
  }

  const long long ans = max({0LL, solve_oa_2ob(x), solve_2oa_ob(x)});
  cout << ans << endl;

  return 0;
}

