int solve(vector<int> const& x,vector<int> const& v,int n,int c){
    int res=0;
    vector<int> max(n,0);
    int sum=v[n-1]-c+x[n-1];
    max[n-1]=chmax(0,sum);
    for(int i=n-2;i>=0;i--){
        sum+=v[i];
        sum+=c-x[i+1];
        sum-=c-x[i];
        max[i]=chmax(max[i+1],sum);
    }
    int buf=v[0]-x[0]*2+max[1];
    res=chmax(res,buf);
    rep1(i,n-2){
        buf+=v[i];
        buf+=x[i-1]*2;
        buf-=x[i]*2;
        buf+=max[i+1];
        buf-=max[i];
        res=chmax(res,buf);
    }
    res=chmax(res,max[0]);
    return res;
}
