signed main(void)
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, c;
  cin >> n >> c;
  VI x(n), v(n);
  REP(i, n) cin >> x[i] >> v[i];

  VI dp1(n);
  dp1[0] = v[0] - x[0];
  FOR(i, 1, n) dp1[i] = dp1[i-1] + v[i] - (x[i] - x[i-1]);
  FOR(i, 1, n) chmax(dp1[i], dp1[i-1]);

  VI dp2(n);
  dp2[n-1] = v[n-1] - (c - x[n-1]);
  for(int i=n-2; i>=0; --i) {
    dp2[i] = dp2[i+1] + v[i] - (x[i+1] - x[i]);
  }
  for(int i=n-2; i>=0; --i) {
    dp2[i] = max(dp2[i], dp2[i+1]);
  }

  int ans = max(0LL, dp2[0]);
  REP(i, n) {
    // i番目まで時計回りで取る
    int tmp = dp1[i];
    // [i+1, n-1] の最大
    if(i+1<n && dp2[i+1] - x[i] > 0) tmp += dp2[i+1] - x[i];
    chmax(ans, tmp);
  }
  for(int i=n-1; i>=0; --i) {
    int tmp = dp2[i];
    if(i >= 1 && dp1[i-1] - (c - x[i]) > 0 ) tmp += dp1[i-1] - (c - x[i]);
    chmax(ans, tmp);
  }
  cout << ans << endl;

  return 0;
}

