	}

	sort(sushi_forward.begin(), sushi_forward.end(),
		[](const auto& item1, const auto& item2) {return item1.pos < item2.pos; });
	sort(sushi_backward.begin(), sushi_backward.end(),
		[](const auto& item1, const auto& item2) {return item1.pos < item2.pos; });

	{
		long long int sum_cal = 0;
		long long int best_cal = 0;
		for (auto& sushi : sushi_forward) {
			sum_cal += sushi.cal;
			best_cal = max(best_cal, sum_cal - sushi.pos);
			sushi.best_cal = best_cal;
