	{
		up_com[i + 1] = up_com[i] + data[i].second;
		down_com[i + 1] = down_com[i] + data[N - 1 - i].second;
		up_dis[i + 1] = data[i].first;
		down_dis[i + 1] = C - data[N - 1 - i].first;
	}

	for (int i = 0; i < N; i++)
	{
		up_max[i + 1] = max(up_max[i], up_com[i + 1] - up_dis[i + 1]);
		up_back_max[i + 1] = max(up_back_max[i], up_com[i + 1] - up_dis[i + 1] * 2);
