};

struct union_find {
  vi data;
  union_find(int size) : data(size, -1) { }
  bool union_set(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool find_set(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

vi cum(vi V) {
  vi U(sz(V));
  partial_sum(ALL(V), begin(U));
  return U;
}

void solve() {
  int n, c;
  int ans = 0;

  cin >> n >> c;
  vi xr(n), xl(n), vr(n), vl(n), r(n), l(n);
  REP(i, n) {
    cin >> xr[i] >> vr[i];
    xl[i] = c - xr[i];
    vl[i] = vr[i];
  }
  REV(xl);
  REV(vl);
  r[0] = vr[0] - xr[0];
  l[0] = vl[0] - xl[0];
  FOR(i, 1, n) {
    r[i] = vr[i] - (xr[i] - xr[i - 1]);
    l[i] = vl[i] - (xl[i] - xl[i - 1]);
  }
  vi cr = cum(r);
  vi cl = cum(l);
  vi r_max(n), l_max(n);
  r_max[0] = max(0ll, cr[0]);
  l_max[0] = max(0ll, cl[0]);
  FOR(i, 1, n) {
    r_max[i] = max(cr[i], r_max[i - 1]);
    l_max[i] = max(cl[i], l_max[i - 1]);
  }
  ans = max(0ll, max(r_max[n - 1], l_max[n - 1]));
  REP(i, n - 1) {
    int tmp = cr[i] - xr[i] + l_max[n - i - 2];
    ans = max(tmp, ans);
    tmp = cl[i] - xl[i] + r_max[n - i - 2];
    ans = max(tmp, ans);
  }

  cout << ans << endl;
  // REP(i, n) {
  //   cout << a[i];
  // }
}

signed main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
