	{
		q.push(x);
	}
	pa Top()
	{
		while (!q.empty()&&flag[q.top().second]) q.pop();
		if (q.empty()) return mp(-INF,0);
		return q.top();
	}
	void Del(int pos)
	{
		flag[pos]=1;
	}
}Q1,Q2;
