    for (int i = 1; i <= N; i++){
        if(f[i] > now){
            now = f[i];
            nownum = i;
        }
        fmax[i] = nownum;
    }

    ll ans = 0;
    rep(i, N+1){
        ll now = f[fmax[N-i]];
