void Solve() {

	li(N, C);
	vlc(N, x, v);
	vvvll dp = ven(2, 2, N + 1, -INF);
	vvvll dps = ven(2, 2, N + 1, -INF);
	dp[0][0][0] = 0;
	dp[0][1][0] = 0;
	dp[1][0][N] = 0;
	dp[1][1][N] = 0;
	dps[0][0][0] = 0;
	dps[0][1][0] = 0;
	dps[1][0][N] = 0;
	dps[1][1][N] = 0;
	REP1(i, N) {
		REP(j, 2) {
			dp[0][j][i] = dp[0][j][i - 1] + v[i - 1] - (x[i - 1] - (i == 1 ? 0 : x[i - 2]))*(j + 1);
			dp[1][j][N - i] = dp[1][j][N - i + 1] + v[N - i] - ((i == 1 ? C : x[N - i + 1]) - x[N - i])*(j + 1);
			dps[0][j][i] = max(dps[0][j][i - 1], dp[0][j][i]);
			dps[1][j][N - i] = max(dps[1][j][N - i + 1], dp[1][j][N - i]);
		}
	}
