template <typename T>
class SegTree {
   private:
    int n;
    T ID_ELEM;
    vector<T> dat;
    T op(const T &a, const T &b) { return max(a, b); }

   public:
    SegTree(int n, T ID_ELEM) : ID_ELEM(ID_ELEM) {
        this->n = 1;
        while (this->n < n) {
            this->n *= 2;
        }
        dat.resize(2 * this->n - 1, ID_ELEM);
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1) r = n;
        if (a >= r || b <= l) {
            return ID_ELEM;
        } else if (a <= l && r <= b) {
            return dat[k];
        }
        int mid = (l + r) / 2;
        return op(query(a, b, k * 2 + 1, l, mid), query(a, b, k * 2 + 2, mid, r));
    }

    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(int k) {
        k += n - 1;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    T &at(int k) { return dat[k + n - 1]; }
};

