typedef long long ll;
typedef vector<int> VI;
typedef vector<ll> VL;


int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    ll c;
    cin >> n >> c;
    VL x(n), v(n);
    REP(i, n) cin >> x[i] >> v[i];
    VL xx(n);
    REP(i, n) xx[i] = c - x[n - i - 1];
    VL intake_clock(n);
    intake_clock[0] = v[0];
    FOR(i, 1, n - 1) intake_clock[i] = v[i] + intake_clock[i - 1];
    VL intake_unclock(n);
    intake_unclock[0] = v[n - 1];
    FOR(i, 1, n - 1) intake_unclock[i] = v[n - i - 1] + intake_unclock[i - 1];

    ll only_clock = intake_clock[0] - x[0];
    VL opt_clock(n);
    REP(i, n) {
        only_clock = max(only_clock, intake_clock[i] - x[i]);
        opt_clock[i] = only_clock;
    }
    ll only_unclock = intake_unclock[0] - xx[0];
    VL opt_unclock(n);
    REP(i, n) {
        only_unclock = max(only_unclock, intake_unclock[i] - xx[i]);
        opt_unclock[i] = only_unclock;
    }
    ll fold = 0;
    REP(i, n) {
        fold = max(fold, opt_clock[i] - x[i] + opt_unclock[n - i - 2]);
        fold = max(fold, opt_unclock[i] - xx[i] + opt_clock[n - i - 2]);
    }

    fold = max(fold, only_clock);
    fold = max(fold, only_unclock);
    cout << fold << endl;

    return 0;
}

