            score = g[N];
        }
        else
        {
            score = ff[N - b + 1] - (C - x[b - 1]) + g[b - 1];
        }

        chmax(ans, score);
    }

    for (int a = 0; a <= N; ++a)
    {
        ll score = 0;
        if (a == 0)
        {
            score = gg[0];
        }
        else
        {
            score = f[a] - x[a - 1] + gg[N - a];
        }
        chmax(ans, score);
    }

    cout << ans << endl;
}

