int const N_MAX = 100000;

int N;
ll C;
ll xs[N_MAX + 1], vs[N_MAX + 1];
ll ls[N_MAX + 1], rs[N_MAX + 1];
ll gls[N_MAX + 1], grs[N_MAX + 1];

int main() {
  scanf("%d %lld", &N, &C);
  xs[0] = 0;
  vs[0] = 0;
  FOR(i, 1, N + 1) {
    scanf("%lld %lld", &xs[i], &vs[i]);
  }

  FOR(i, 1, N + 1) {
    ls[i] = ls[i - 1] + vs[i];
    rs[i] = rs[i - 1] + vs[N - i + 1];
  }

  FOR(i, 1, N + 1) {
    ll dist = C - xs[N - i + 1];
    ll cal = rs[i] - dist;
    gls[i] = max(gls[i - 1], cal);
    grs[i] = max(grs[i - 1], cal - dist);
  }

  ll max_cal = 0;
  rep(i, N + 1) {
    ll l = ls[i];
    ll l_dist = xs[i];
    ll l_cal = l - l_dist;

    int j = N - i;
    ll rl_cal = gls[j];
    ll cal = l_cal + rl_cal - l_dist;
    max_cal = max(max_cal, cal);

    ll rr_cal = grs[j];
    cal = l_cal + rr_cal;
    max_cal = max(max_cal, cal);

  }
  printf("%lld\n", max_cal);
}

