	std::vector<Data> sushiDataL(sushiNum);
	for(int i = 0; i < sushiNum; i++){
		std::cin >> sushiDataR[i].x >> sushiDataR[i].cal;
		sushiDataL[i].x = len - sushiDataR[i].x;
	}

	long long sumCal = 0;
	long long pos = 0;

	std::sort(sushiDataR.begin(), sushiDataR.end(), [](const Data a, const Data b){return (a.x < b.x); });
	std::sort(sushiDataL.begin(), sushiDataL.end(), [](const Data a, const Data b){return (a.x < b.x); });

	int rElem, lElem;
	rElem = lElem = 0;
	for(int i = 0; i < sushiNum; i++){

		while(sushiDataR[rElem].cal - (sushiDataR[rElem].x - pos) < 0 && rElem < (sushiNum - lElem)){
			rElem++;
		}

		while(sushiDataL[lElem].cal - (sushiDataR[lElem].x + pos) < 0 && lElem < (sushiNum - rElem)){
			lElem++;
		}

		if(rElem >= (sushiNum - lElem) || lElem >= (sushiNum - rElem)){
			break;
		}

