lli process() {
	lli sum=0, res=0;
	for(int i=0;i<n;i++) {
		sum+=v[i];
		res=max(res,sum-x[i]);
	}
	set<ip> s;
	sum=0;
	for(int i=n-1;i>=0;i--) {
		sum+=v[i];
		if(sum-(c-x[i])<=0) continue;
		if(s.empty() || sum-(c-x[i])>(*s.begin()).second)
			s.insert(ip(i,sum-(c-x[i])));
	}
	sum=0;
	for(int i=0;i<n;i++) {
		sum+=v[i];
		lli val=sum-2*x[i];
		set<ip>::iterator it=s.lower_bound(ip(i+1,-1));
		if(it!=s.end()) val+=it->second;
		res=max(res,val);
	}
	return res;
}

