ll gcd(ll a, ll b)
{
  while (b > 0) {
    a = a % b;
    std::swap(a, b);
  }
  return a;
}

ll lcm(ll a, ll b) {
  ll gcd_val = gcd(a, b);
  return a / gcd_val * b;   // over flow 防止のため、割り算を先にする
}

ll extgcd(ll a, ll b, ll& x, ll& y)
{
  ll d = a;
  if (b != 0) {
    ll x_dash;
    ll y_dash;
    d = extgcd(b, a % b, x_dash, y_dash);
    x = y_dash;
    y = x_dash - (a / b) * y_dash;
  } else {
    x = 1;
    y = 0;
  }
  return d;
}

