  vector<ll> x(n), v(n);
  for(int i = 0; i < n; i++) cin >> x.at(i) >> v.at(i);

  ll ans = 0, keep = 0;
  // 時計回りのみ
  for(int i = 0; i < n; i++){
    keep += v.at(i);
    ans = max(ans, keep - x.at(i));
  }
  // 反時計回りのみ
  keep = 0;
  for(int i = n - 1; i >= 0; i--){
    keep += v.at(i);
    ans = max(ans, keep - (c - x.at(i)));
  }

  // 反時計->時計
  vector<ll> benefit(n);
  benefit.at(0) = v.at(0) - x.at(0);
  for(int i = 1; i < n; i++){
    benefit.at(i) = benefit.at(i - 1) + v.at(i) - (x.at(i) - x.at(i - 1));
  }
  for(int i = 1; i < n; i++){
    benefit.at(i) = max(benefit.at(i), benefit.at(i - 1));
  }
  keep = 0;
  for(int i = n - 1; i > 0; i--){
    keep += v.at(i);
    ans = max(ans, keep - (c - x.at(i)) * 2 + benefit.at(i - 1));
  }

  // 時計->反時計
  vector<ll> benefit2(n);
  benefit2.at(n - 1) = v.at(n - 1) - (c - x.at(n - 1));
  for(int i = n - 2; i >= 0; i--){
