#define LL long long
const int maxn = 100000 + 100;
struct Node {
    LL pos;
    LL num;
};

bool operator<(const Node &a, const Node &b) {
    return a.pos < b.pos;
}

int n;
LL c;
Node node[maxn];
LL Max[maxn];
int mn[maxn];
LL num[maxn], sum[maxn];

void Init() {
    Max[0] = 0;
    for(int i = 1; i <= n; ++i) {
        Max[i] = max(Max[i - 1], num[i]);
    }
}

void Reverse() {
    for(int i = 1; i <= n / 2; ++i) {
        swap(node[i], node[n - i + 1]);
        node[i].pos = c - node[i].pos;
        node[n - i + 1].pos = c - node[n - i + 1].pos;
    }
    if(n % 2 == 1) {
        node[n / 2 + 1].pos = c - node[n / 2 + 1].pos;
    }
}

LL solve() {
    LL ret = 0;
    sum[0] = 0;
    for(int i = 1; i <= n; ++i) {
        sum[i] = sum[i - 1] + node[i].num;
        num[i] = sum[i] - 2 * node[i].pos;
        ret = max(ret, num[i]);
    }
    Init();
    for(int i = n; i >= 1; --i) {
        ret = max(ret, Max[i - 1] + sum[n] - sum[i - 1] - (c - node[i].pos));
    }
    return ret;
}

