    for( int i = N-2; i > 0; --i )
        maxEneCCW[i] = max( maxEneCCW[i+1], vSumCCW[i]-(C-x[i]) );

    long long ansCW = 0, ansCCW = 0;
    // 始め時計回りに回る場合
    for( int i = 0; i < N; ++i ){
        if( maxEneCCW[i+1] < x[i] or i == N-1 ) ansCW = max( ansCW, vSumCW[i] - x[i] );
