		if (i == 0){
			B[i] = sum - v[i].first;//消費したカロリーを引く
		}else{
			B[i] = max(B[i - 1], sum - v[i].first);//消費したカロリーを引く
		}
	} 
	sum = 0;
	for (int i = n - 1; i >= 0; i--){//反時計回り
		sum += v[i].second;//寿司のカロリーを足す
		if (i == n - 1){
			A[i] = sum - (c - v[i].first);//消費したカロリーを引く
		}else{
			A[i] = max(A[i + 1], sum - (c - v[i].first));//消費したカロリーを引く          
		}
	} 
	for (int i = 0; i<n; i++){
		res = max(res, B[i]);//時計回りの最大カロリーの値を調べる
