int main() {
  cin >> N >> C;

  // clock wise
  vector<long long> x_r(N, 0);
  vector<long long> v_r(N, 0);
  vector<long long> f_r(N, 0);
  vector<long long> g_r(N, 0);
  // anti clock-wise
  vector<long long> x_l(N, 0);
  vector<long long> v_l(N, 0);
  vector<long long> f_l(N, 0);
  vector<long long> g_l(N, 0);

  for (int i = 0; i < N; ++i) {
    cin >> x_r[i] >> v_r[i];

    x_l[N - 1 - i] = C - x_r[i];
    v_l[N - 1 - i] = v_r[i];
  }

  auto calc_fg = [](const vector<long long>& x, const vector<long long>& v,
                    vector<long long>& f, vector<long long>& g) {
    long long sum = v[0];
    f[0] = v[0] - x[0];
    g[0] = f[0];
    for (int i = 1; i < N; ++i) {
      sum += v[i];
      f[i] = sum - x[i];
      g[i] = max(g[i - 1], f[i]);
    }
  };

  calc_fg(x_r, v_r, f_r, g_r);
  calc_fg(x_l, v_l, f_l, g_l);

  auto solve = [](const vector<long long>& x, const vector<long long>& f,
                  const vector<long long>& g) {
    long long ans = g[N - 1];
    for (int i = 0; i < N - 1; ++i) {
      const auto w2 = f[i] - x[i];
      const auto k = N - 1 - i;
      ans = max(ans, g[k - 1] + w2);
    }
    return ans;
  };

  // Bを動かす, Aを動かす
  const auto ans = max({0LL, solve(x_l, f_l, g_r), solve(x_r, f_r, g_l)});
  cout << ans << endl;

  return 0;
}

