        }
        ans=max(ans,suml[i+1]-(c-x[n-1-i].first));
    }
    //cout << ans << "\n";
    //cout << iter_rmax << "\n";
    if(iter_rmax!=-1){
        for(int i=0;i<n-iter_rmax-1;i++){
            ans=max(ans,backsumr+suml[i+1]-(c-x[n-1-i].first));
        }
    }
    //cout << ans << "\n";
    //cout << iter_lmax << "\n";
    if(iter_lmax!=-1){
        for(int i=0;i<iter_lmax;i++){
