long long cwise() {
	cwisev.resize(N + 1);
	cwisev[0] = 0;
	VV.resize(N + 1,0);
	long long vsum = 0;
	long long ans = 0;
	for (int n = 1; n <= N; n++) {
		vsum += sushis[n].v;
		cwisev[n] = vsum - sushis[n].x;
		ans = max(ans, cwisev[n]);
		VV[n] = vsum;
	}
	return ans;
}

long long uncwise() {
	uncwisev.resize(N + 1);
	long long vsum = 0;
	long long ans = 0;
	for (int n = N; n >= 1; n--) {
		vsum += sushis[n].v;
		uncwisev[n] = vsum - (C - sushis[n].x);
		ans = max(ans, uncwisev[n]);
	}
	return ans;
}

long long cwiseuncwise() {
	long long ans = 0;
	long long mun = 0;
	for (int t = N-1; t > 0; t--) {
		long long tempans = VV[t] - 2 * sushis[t].x;
		mun = max(mun, uncwisev[t + 1]);
		tempans += mun;
		ans = max(ans, tempans);
	}
	return ans;
}

long long uncwisecwise() {
	long long ans = 0;
	long long mun = 0;
	for (int t = 1; t < N; t++) {
		long long tempans = VV[N] - VV[t - 1] - 2 * (C - sushis[t].x);
		mun = max(mun, cwisev[t - 1]);
		tempans += mun;
		ans = max(ans, tempans);
	}
	return ans;
}

