		clockwise_sum_return_max[i] = max(clockwise_sum_return_max[i - 1], clockwise_sum[i] - x[i] * 2);
	}

	long long all_sum = clockwise_sum[N - 1];
	counter_sum_max[N - 1] = max((long long)0, v[N - 1] - (C - x[N - 1]));
	counter_sum_return_max[N - 1] = max((long long)0, v[N - 1] - (C - x[N - 1]) * 2);
	for (int i = N - 2; i >= 1; i--)
	{
		counter_sum_max[i] = max(counter_sum_max[i + 1], all_sum - clockwise_sum[i - 1] - (C - x[i]));
		counter_sum_return_max[i] = max(counter_sum_return_max[i + 1], (all_sum - clockwise_sum[i - 1]) - (C - x[i]) * 2);
	}
	counter_sum_max[0] = max(counter_sum_max[1], all_sum - (C - x[0]));
	counter_sum_return_max[0] = max(counter_sum_return_max[1], all_sum - (C - x[0]) * 2);

	long long result = max(clockwise_sum_max[N - 1], (long long)0);
	// cout << "start "<<result <<"\n";
	for (int i = 0; i < N - 1; i++)
	{
		long long i_max = max(clockwise_sum_max[i] + counter_sum_return_max[i + 1], clockwise_sum_return_max[i] + counter_sum_max[i + 1]);
