			// cout << i << ":" << clockwise_sum_max[i] << " " << counter_sum_return_max[i + 1] << " or " << clockwise_sum_return_max[i] << " " << counter_sum_max[i + 1] << "\n";
			result = i_max;
		}
	}

	cout << result;

	return 0;
}

