  {
    std::vector<std::pair<long long,long long>> vec2 = vec;
    long long cpos2 = uind->first;
    // printf ("cpos: %lld\n", cpos);
    long long cmax2 = cmax + uind->second - std::min(std::abs(cpos2 - cpos), C - std::abs(cpos2 - cpos));
