long long MAX1(vector<long long> v, int a) {
  long long max;
  max = v[0];
  for (int i = 0; i <= a; i++) {
    if (max < v[i]) max = v[i];
  }
  return max;
}

long long MAX2(vector<long long> v, int a, int N) {
  long long max;
  max = v[N];
  for (int i = N; i >= a; i--) {
    if (max < v[i]) max = v[i];
  }
  return max;
}

