vector< pair<ll, ll> > xv;

vector<ll> va;
vector<ll> vb;

int main()
{
    ll N, C;
    cin >> N >> C;

    xv.resize(N);

    va.resize(N);
    vb.resize(N);

    ll vsum = 0;
    ll bkv = 0;

    REP(i, N)
    {
        ll x, v;
        cin >> x >> v;

        xv[i] = make_pair(x, v);
        vsum += v;

        if (bkv < vsum - x) bkv = vsum - x;

        va[i] = bkv;
    }

    vsum = 0;
    bkv = 0;

    for (int i = N - 1; 0 <= i; i--)
    {
        vsum += xv[i].second;

        ll Bv = vsum - (C - xv[i].first);
        if (bkv < Bv) bkv = Bv;

        vb[i] = bkv;
    }

    ll ans = 0;
    for (int i = N - 1; 0 <= i; i--)
    {
        ll Ax = 0;
        ll Av = 0;

        if (i != 0)
        {
            Ax = xv[i - 1].first;
            Av = va[i - 1];
        }

        ll Bx = C - xv[i].first;
        ll Bv = vb[i];

        // ここで Ax または Bx は
        // 引きすぎているように見えるが
        // 各地点ごとに処理している為
        // しかるべき地点で max 更新しており問題無い
        // O B O A
        ans = max(ans, Av + Bv - Bx);
        // O A O B
        ans = max(ans, Bv + Av - Ax);
    }

    // O A
    ans = max(ans, va[N - 1]);

    // O B
    ans = max(ans, vb[0]);

    cout << ans << endl;
    return 0;
}

