using namespace std;
using ll = long long;

struct sushi {
    ll x, c;
    bool exist = true;
};

ll solve() {
    ll n, c;
    cin >> n >> c;
    vector<sushi> sushis(n);
    forin(i, 0, n) {
        cin >> sushis[i].x >> sushis[i].c;
    }
    ll costSum = 0;
    auto &left = sushis[n - 1];
    auto leftC = left.c - (c - left.x);
    auto &right = sushis[0];
    auto rightC = right.c - right.x;
    auto i = leftC > rightC ? n - 1 : 0;
    while (max(leftC, rightC) > 0) {
        if (leftC > rightC) {
            left.exist = false;
            costSum += leftC;
        } else {
            right.exist = false;
            costSum += rightC;
        }
        if (leftC > rightC) {
            leftC = 0;
            for (auto j = (i + n - 1) % n; j != i; j = (j + n - 1) % n) {
                if (!sushis[j].exist) continue;
                auto cCost = sushis[j].c - (left.x - sushis[j].x);
                if (cCost > 0)  {
                    rightC -= left.x - sushis[j].x;
                    left = sushis[j];
                    leftC = cCost;
                    i = j;
                    break;
                }
            }
        } else {
            rightC = 0;
            for (auto j = (i + 1) % n; j != i; j = (j + 1) % n) {
                if (!sushis[j].exist) continue;
                auto cCost = sushis[j].c - (sushis[j].x - right.x);
                if (cCost > 0)  {
                    leftC -= sushis[j].x - right.x;
                    right = sushis[j];
                    rightC = cCost;
                    i = j;
                    break;
                }
            }
        }
    }


    return costSum;
}

int main() {
    cout << solve() << endl;
}

