	for (int i = 1; i <= n; i++){
		cin >> lx[i] >> lv[i];
		rx[n+1-i] = c - lx[i];
		rv[n+1-i] = lv[i];
	}
	vector<ll> slv(n+1), srv(n+1);
	slv[0] = 0, srv[0] = 0;

