vector< pair<ll, ll> > xv;

vector<ll> vx;
vector<ll> vv;

int main()
{
    ll N, C;
    cin >> N >> C;

    xv.resize(N);

    vx.resize(N);
    vv.resize(N);

    ll vsum = 0;
    ll bkx = 0;
    ll bkv = 0;

    REP(i, N)
    {
        ll x, v;
        cin >> x >> v;

        xv[i] = make_pair(x, v);
        vsum += v;

        if (bkv < vsum - x)
        {
            bkx = x;
            bkv = vsum - bkx;
        }

        vx[i] = bkx;
        vv[i] = bkv;
    }

    vsum = 0;
    bkv = 0;

    ll ans = 0;

    for (int i = N - 1; 0 <= i; i--)
    {
        ll Ax = 0;
        ll Av = 0;

        if (i != 0)
        {
            Ax = vx[i - 1];
            Av = vv[i - 1];
        }

        vsum += xv[i].second;

        ll Bx = C - xv[i].first;
        ll Bv = vsum - Bx;

        if (bkv < Bv) bkv = Bv;

        // O B O A ただし O B O が負なら ゼロ
        ans = max(ans, Av + max((ll)0, Bv - Bx));
        // O A O B ただし O A O が負なら ゼロ
        ans = max(ans, Bv + max((ll)0, Av - Ax));
    }

    // O A
    ans = max(ans, vv[N - 1]);

    // O B
    ans = max(ans, bkv);

    cout << ans << endl;
    return 0;
}

