#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// const int INF = 2147483647;
// const ll INF = 9223372036854775807;
// const ll MOD = 1e9 + 7;

ll x[100001];
ll d[100001];
ll r_d[100001];

ll v[100001];
ll r_v[100001];

ll cum_v[100001];
ll r_cum_v[100001];

ll max_cal[100001];
ll r_max_cal[100001];

int main() {
	ll N, C;
	cin >> N >> C;

	for (int i=0; i<N; i++) {
		cin >> x[i] >> v[i];
		r_v[i] = v[i];
	}
	reverse(r_v, r_v+N);

	for (int i=0; i<N; i++) {
		d[i+1] = x[i];
		r_d[i+1] = C - x[N-1-i];
	}

	for (int i=0; i<N; i++) {
		cum_v[i+1] = cum_v[i] + v[i];
		r_cum_v[i+1] = r_cum_v[i] + r_v[i];
	}

	ll tmp_max_cal = 0;
	for (int i=1; i<=N; i++) {
		ll cal = cum_v[i] - d[i];
		tmp_max_cal = max(tmp_max_cal, cal);
		max_cal[i] = tmp_max_cal;
	}

	tmp_max_cal = 0;
	for (int i=1; i<=N; i++) {
		ll cal = r_cum_v[i] - r_d[i];
		tmp_max_cal = max(tmp_max_cal, cal);
		r_max_cal[i] = tmp_max_cal;
	}

	ll ans = 0;

	// 時計回りのみ
	for (int i=0; i<=N; i++) {
		ll cal = cum_v[i] - d[i];
		ans = max(ans, cal);
	}

	// 反時計回りのみ
	for (int i=0; i<=N; i++) {
		ll cal = r_cum_v[i] - r_d[i];
		ans = max(ans, cal);
	}

	// 反時計回り→時計回り
	for (int i=0; i<N; i++) {
		ll cal = r_cum_v[i] - r_d[i]; // 反時計回り
		cal -= r_d[i]; // 原点に戻る
		cal += max_cal[N-i]; // 時計回り
		ans = max(ans, cal);
	}

	// 時計回り→反時計回り
	for (int i=0; i<N; i++) {
		ll cal = cum_v[i] - d[i];// 時計回り
		cal -= d[i]; // 原点に戻る
		cal += r_max_cal[N-i]; // 反時計回り
		ans = max(ans, cal);
	}

	cout << ans << endl;

	return 0;
}

