	for (int z = 0; z < 2; z++) {
		assert(is_sorted(X, X + N));

		cw[0] = 0;
		ll s = 0;
		for (int i = 0; i < N; i++) {
			s += V[i];
			cw[i+1] = max(cw[i], s - 2 * X[i]);
		}

		s = 0;
		ccw[0] = 0;
		for (int i = N-1; i >= 0; i--) {
			s += V[i];
			ccw[N-i] = max(ccw[N-i-1], s - (C - X[i]));
		}

		for (int i = 0; i <= N; i++) {
			ans = max(ans, cw[i] + ccw[N-i]);
		}

		for (int i = 0; i < N; i++) {
			X[i] = C - X[i];
		}
