const int INF = 1e18;

struct CumulativeSum{
    vector<int> data;
    CumulativeSum(int sz) : data(sz, 0) {};
    void add(int k, int x){
        data[k] += x;
    }
    void build(){
        for(int i = 1; i < data.size(); i++){
            data[i] += data[i - 1];
        }
    }
    int query(int k){
        if(k < 0) return 0;
        return (data[min(k, (int)data.size() - 1)]);
    }
    int query(int l, int r){
        return query(r - 1) - query(l - 1);
    }
};

int n, c;

int solve(vector<int> x, vector<int> v){
    CumulativeSum cs(n), csr(n);
    rep(i, 0, n){
        int tmp = x[i] - (i == 0 ? 0 : x[i - 1]);
        cs.add(i, v[i] - tmp);
    }
    cs.build();
    for(int i = n - 1; i >= 0; i--){
        int tmp = (i == n - 1 ? c : x[i + 1]) - x[i];
        csr.add(n - 1 - i, v[i] - 2 * tmp);
    }
    csr.build();
    vector<int> csrm(n);
    int MAX = 0;
    for(int i = 0; i < n; i++){
        MAX = max(MAX, csr.query(0, i + 1));
        csrm[i] = MAX;
    }
    int ans = 0;
    for(int i = 0; i < n; i++){
        int tmp = cs.query(0, i + 1);
        // cout << i << ' ' << tmp << ' ' << csrm[n - 2 - i] << endl;
        if(i != n - 1 && csrm[n - 2 - i] > 0) tmp += csrm[n - 2 - i];
        ans = max(ans, tmp);
    }
    return ans;
}

