class DStaticSushi {
public:
	void solve(std::istream& in, std::ostream& out)
	{
        int n;
        ll c;
        in >> n >> c;
        vector<ll> x(n), v(n);
        for(int i=0; i<n; i++){
            in >> x[i] >> v[i];
        }
        vector<pair<ll, ll>> l, r;
        for(int i=0; i<n; i++){
            l.push_back(make_pair(x[i], v[i]));
            r.push_back(make_pair(c-x[i], v[i]));
        }

        sort(l.begin(), l.end());
        sort(r.begin(), r.end());

        vector<ll> lc(n+1), rc(n+1);
        lc[0] = rc[0] = 0;
        for(int i=0; i<n; i++){
            lc[i+1] = lc[i] + (l[i].second - l[i].first);
            rc[i+1] = rc[i] + (r[i].second - r[i].first);
            if(i-1 >= 0){
                lc[i+1] += l[i-1].first;
                rc[i+1] += r[i-1].first;
            }
        }

//        debug.vd(lc);
//        debug.vd(rc);

        ll res = -inf;
        for(int i=0; i<n; i++){
            chmax(res, max(lc[i], rc[i]));
        }

        ll posr = 0, posl = 0;
        ll cost = 0;
        while(posl + posr < n) {
            ll costr, costl;
            if(l[posl].first < (posr>0 ? r[posr-1].first : 0))
                costl = lc[posl+1] + rc[posr] - l[posl].first;
            else
                costl = lc[posl+1] + rc[posr] - (posr>0 ? r[posr-1].first : 0);

            if(r[posr].first < (posl>0 ? l[posl-1].first : 0))
                costr = lc[posl] + rc[posr+1] - r[posr].first;
            else
                costr = lc[posl] + rc[posr+1] - (posl>0 ? l[posl-1].first : 0);

            //cout << costl sp costr << endl;
            if(costl > costr) {
                cost = costl;
                posl++;
            }else{
                cost = costr;
                posr++;
            }
            chmax(res, cost);
        }

        out << res << endl;
	}
};


int main() {
	DStaticSushi solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

