    rep(i, n) {
        cin >> x[i] >> v[i];
    }

    vl rui1(n+1);  // rui1[i+1] : 時計回りに進んで寿司0から寿司iを食べるときのカロリーの合計
    vl rui2(n+1);  // rui2[i+1] : 反時計回りに進んで寿司n-1から寿司(n-1) - iを食べるときのカロリーの合計
    rep(i, n) {
        rui1[i+1] = rui1[i] + v[i];
    }
    rep(i, n) {
        rui2[i+1] = rui2[i] + v[(n-1) - i];
    }

    ll ans = 0;  // 1貫も食べないとき0

    // 時計回りにのみ進んで方向を変えないとき
    rep(i, n) {  // 寿司0から寿司iを食べるとする
        ll now = rui1[i+1] - x[i];
        chmax(ans, now);
    }

    // 反時計回りにのみ進んで方向を変えないとき
    for(ll i = n-1; i >= 0; i--) {  // 寿司n-1から寿司iを食べるとする
        ll now = rui2[n - i] - (c - x[i]);
        chmax(ans, now);
    }

    // 先に時計回りに進んでから方向を変えて反時計回りに進むとき
    exrep(i, 0, n-2) {  // まず寿司0から寿司iを食べるとする
        for(ll j = n-1; j >= i+1; j--) {  // 次に寿司n-1から寿司jを食べるとする
            ll now = rui1[i+1] - 2*x[i];
            now += rui2[n - j] - (c - x[j]);
            chmax(ans, now);
        }
    }

    // 先に反時計回りに進んでから方向を変えて時計回りに進むとき
    for(ll i = n-1; i >= 1; i--) {  // まず寿司n-1から寿司iを食べるとする
        exrep(j, 0, i-1) {  // 次に寿司0から寿司jを食べるとする
            ll now = rui2[n - i] - 2*(c - x[i]);
            now += rui1[j+1] - x[j];
            chmax(ans, now);
        }
    }

    out(ans);
    re0;
}

