  int ans = max(max(ri.query(0, N), le.query(0, N)), 0ll);
  REP(i, N){
    chmax(ans, ri.query(0, i+1)-x[i]+le.query(i+1, N));
    chmax(ans, le.query(i, N)-(C-x[i])+ri.query(0, i));
  }

