  for(int i=0;i<num;i++){
    cin >> x[i] >> v[i];
    sushi.push_back(make_pair(x[i],v[i]-x[i]));
  }

  //clockwise
  sort(sushi.begin(),sushi.end());
  int benefit[100000], max_ben=0, arg=0;
  benefit[0] = sushi[0].second;
  cout << 0 << ":" << benefit[0] << endl;
  for(int i=1;i<num;i++){
    benefit[i] = benefit[i-1] + sushi[i].second + sushi[i-1].first;
    if(max_ben < benefit[i]) {max_ben = benefit[i]; arg = i;}
  }

  result = max_ben;
  // cout << "counter" << result << endl;
