using namespace std;
typedef long long int ll;
typedef pair<int, int> P;
template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

ll n, c;

ll solve(vector<ll> &x, vector<ll> &v){
    vector<ll> maxR(n);
    maxR[0] = max(v[0] - x[0] * 2, 0LL);
    ll sum = v[0];
    for(int i = 1; i < n; ++i){
        sum += v[i];
        maxR[i] = max(maxR[i-1], sum - 2 * x[i]);
    }
    ll res = 0, sumL = 0;
    for(int i = n-1; i > 0; --i){
        sumL += v[i];
        chmax(res, sumL - (c - x[i]) + maxR[i-1]);
    }
    sumL += v[0];
    chmax(res, sum - x[n-1]);
    chmax(res, sum - c + x[0]);
    return res;
}

