    ll ans = solve(x, v);
    reverse(x.begin(), x.end());
    rep(i,n) x[i] = c - x[i];
    reverse(v.begin(), v.end());
    chmax(ans, solve(x, v));
    cout << ans << endl;
    return 0;
}

