long long C;

long long int getMax(std::vector<std::pair<long long,long long>> vec, long long cpos, int uind, int lind, long long int cmax)
{
  if (vec.empty()) {
    return cmax;
  }
  long long ans[2];
  // printf("%lld %ld\n", cmax, vec.size());
  {
    std::vector<std::pair<long long,long long>> vec2 = vec;
    long long cpos2 = vec2.at(lind).first;
    long long cmax2 = cmax + vec2[lind].second - std::min(std::abs(cpos2 - cpos), C - std::abs(- cpos2 + cpos));
    // printf ("cmax2: %lld %lld %lld %lld %lld\n", cmax2, cmax, vec2[lind].second,  C - std::abs(cpos2 - cpos), std::abs(cpos2 - cpos));
    vec2.erase(vec2.begin() + lind);
    int lind2;
    if (lind == 0) {
      lind2 = vec2.size() - 1;
    } else {
      lind2 = lind - 1;
    }
    ans[0] = std::max(cmax, getMax(vec2, cpos2, (uind >= lind) ? uind-1 : uind , lind2, cmax2));
    // printf("cmax: %lld %lld\n", cmax, cmax2);
  }
  {
    std::vector<std::pair<long long,long long>> vec2 = vec;
    long long cpos2 = vec2[uind].first;
    // printf ("cpos: %lld\n", cpos);
    long long cmax2 = cmax + vec2.at(uind).second - std::min(std::abs(cpos2 - cpos), C - std::abs(cpos2 - cpos));
    // printf ("cmax2: %lld %lld %lld %lld %lld\n", cmax2, cmax, vec2[uind].second,  C - std::abs(cpos2 - cpos), std::abs(cpos2 - cpos));
    vec2.erase(vec2.begin() + uind);
    int uind2;
    uind2 = uind + 1;
    if (uind2 >= vec2.size()) {
      uind2 = 0;
    }
    ans[1] = std::max(cmax, getMax(vec2, cpos2, 0, vec2.size() - 1,  cmax2));
    // printf("%lld\n", cmax);
  }
  return std::max(ans[0], ans[1]);
}

