ll rightmap[MAXN];
ll leftmap[MAXN];
ll war[MAXN];
ll wal[MAXN];
ll maxr[MAXN];
ll maxl[MAXN];


int main() {
	ll N, C;
	cin >> N >> C;
	vector<bool> exist;
	vector<pair<ll, ll>> sushis,revSushis;
	for (ll i = 0; i < N; i++) {
		ll tx, tv;
		cin >> tx >> tv;
		pair<ll, ll> p = make_pair(tx, tv);
		sushis.push_back(p);
	}
	sort(sushis.begin(), sushis.end());
	revSushis = sushis;
	reverse(revSushis.begin(), revSushis.end());
	for (int i = 0; i < N; i++) {
		revSushis[i].first = C - revSushis[i].first;
	}
	sushis.insert(sushis.begin(), make_pair(0, 0));
	revSushis.insert(revSushis.begin(), make_pair(0, 0));
	N++;
	war[0] = 0;
	wal[0] = 0;
	//累積和を計算
	for (int i = 1; i < N; i++) {
		war[i] = sushis[i].second - sushis[i].first + sushis[i-1].first  + war[i-1];
		wal[i] = revSushis[i].second - (revSushis[i].first)+ (revSushis[i-1].first) + wal[i - 1];
	}
	//累積最大値を計算
	ll nowr = war[0], nowl = wal[0];
	maxr[0] = war[0];
	maxl[0] = wal[0];
	for (ll i = 1; i < N; i++) {
		if (nowr < war[i]) nowr = war[i];
		if (nowl < wal[i]) nowl = wal[i];
		ll calcr = war[i - 1] + rightmap[i] - 1;
		ll calcl = wal[i - 1] + leftmap[i] - 1;
		maxr[i] = max(calcr, nowr);
		maxl[i] = max(calcl, nowl);
	}
	ll ans = 0;
	for (int i = 0; i < N; i++) {
		ll mini = min(sushis[i].first,revSushis[N-i-1].first);
		ll calc = maxr[i] + maxl[N - i - 1] - mini;
		if (calc > ans) ans = calc;
	}
	if (ans < 0) return -1;
	cout << ans << "\n";
	return 0;
}

