  for(int i = 0; i < N; i++){
    std::cin >> posx[i] >> v[i];
    negx[N-1-i]=C-posx[i];
  }

  posco[0]=v[0]-posx[0];
  negco[0]=v[N-1]-negx[0];

  ll posmax=(posco[0]>0)?posco[0]:0;
  ll negmax=(negco[0]>0)?negco[0]:0;

  for(int i = 1; i < N; i++){
    posco[i]+=posco[i-1]+v[i]-posx[i]+posx[i-1];
    negco[i]+=negco[i-1]+v[N-1-i]-negx[i]+negx[i-1];
    posmax=std::max(posmax,posco[i]);
    negmax=std::max(negmax,negco[i]);
  }
  //ここまでok

  ll maxcal=std::max(posmax, negmax);
  for(int i = 0; i < N; i++){
    if(posco[i]-posx[i]<0) continue;
    for(int j = 0; j < N-1-i; j++){
      if(negco[j]-negx[j]<0) continue;
      ll bufsum=posco[i]+negco[j];
      ll bufmax=bufsum-std::min(posx[i],negx[j]);
      maxcal=std::max(maxcal, bufmax);
    }
  }

