        g2[i] = max(g2[i - 1], v_sum_right[i - 1] - 2 * x[i - 1]);
    }

    // 探査
    ans = v_sum_left[0] - C + x[0];
    for (i = 1; i < N; i++) {
        ans = max(ans, v_sum_left[i] + g[i] - 2 * (C +- x[i]));
        ans = max(ans, v_sum_left[i] - C + x[i] + g2[i]);
    }
    ans = max(ans, g[N]);


    // ofstream cout("output.txt");
    cout << ans << endl;

    return 0;
}

