using namespace std;

#define LL long long int
const LL INF = (LL)(1e18)+1;
const int INF_INT = 2147483647-1e6-1;
const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL N,C;
LL x[100001],v[100001];

LL ans = 0;

void solve(){
	//1~i番目までのカロリーの合計をdish_accum_clockwise[i]とおく
	vector<LL> dish_accum_clockwise(N+1,0);
	for(int i=1;i<=N;i++){
		dish_accum_clockwise[i] = dish_accum_clockwise[i-1] + v[i];
	}

	LL mx0 = 0;//まず反時計回りに行って、それから時計回りに引き返す用
	LL mx1 = 0;//まず時計回りに行って、それから反時計回りに引き返す用
	//地点0から見た、i番目の寿司について注目していく
	for(int i=N;i>=1;i--){
		//dish_accum_clockwise[i] = 1~i-1番目までのカロリーの合計
		//↑時計回りに1番目,2番目,...,i-1番目とi-1個分見ていくイメージ

		//dish_accum_clockwise[i]-x[i]+mx0
		//まず反時計回りにとある寿司をとりに行き、そこから時計回りに引き返して(ここまでがmx0)
		//寿司iをとりに行った時の総カロリー

		//dish_accum_clockwise[i]-2*x[i]+mx1
		//まず時計回りにとある寿司をとりに行き、そこから反時計回りに引き返して(ここまでがmx1)
		//寿司iをとりに行った時の総カロリー

		//このうち大きい方をansとする
		ans = max(ans,dish_accum_clockwise[i]-x[i]+mx0);//i=Nの時は必ずこれが選ばれる
		ans = max(ans,dish_accum_clockwise[i]-2*x[i]+mx1);

		//dish_accum_clockwise[N]-dish_accum_clockwise[i-1]
		// = i-1~N-1番目までのカロリーの合計
		//↑反時計回りにN-1番目,N-2番目,...,i-1番目とN-i+1個分見ていくイメージ
		//C-x[i] = 寿司iに、地点0から反時計回りに向かった時の距離
		//dish_accum_clockwise[N]-dish_accum_clockwise[i-1]

		//dish_accum_clockwise[N]-dish_accum_clockwise[i-1]-(C-x[i])
		//は、寿司iに、地点0から反時計回りに向かった時に得られる総カロリー

		//mx0には、地点0からj(0<=j<=i-1)番目の寿司をとりに行き、地点0に戻る時のカロリー摂取量
		//が入っている(ただしjは(0<=j<=i-1)のうち、max0が最大になるようなもの)
		mx0 = max(mx0,dish_accum_clockwise[N]-dish_accum_clockwise[i-1]-2*(C-x[i]));
		//mx1には、地点0からj(0<=j<=i-1)番目の寿司をとりに行くのカロリー摂取量
		//が入っている(ただしjは(0<=j<=i-1)のうち、mx1が最大になるようなもの)
		mx1 = max(mx1,dish_accum_clockwise[N]-dish_accum_clockwise[i-1]-(C-x[i]));
	}
	ans = max(ans,mx1);
}

int main(){
    cin >> N >> C;
    for(int i=1;i<=N;i++){
    	cin >> x[i] >> v[i];
    }

    solve();

    cout << ans << endl;
    return 0;
}

