  for(int i = 0; i < N; i++){
    std::cin >> posx[i] >> v[i];
    negx[N-1-i]=C-posx[i];
  }

  posco[0]=v[0]-posx[0];
  negco[0]=v[N-1]-negx[0];

  std::vector<int> maxvec(3,0),posmax(2,0),negmax(2,0);
  maxvec[0]=posco[0];
  maxvec[1]=negco[0];

  //single direction
  for(int i = 1; i < N; i++){
    posco[i]+=posco[i-1]+v[i]-posx[i]+posx[i-1];
    negco[i]+=negco[i-1]+v[N-1-i]-negx[i]+negx[i-1];
    maxvec[0]=std::max(maxvec[0],posco[i]);
    maxvec[1]=std::max(maxvec[1],negco[i]);
  }

  //rev
  for(int i = 0; i < N-1; i++){
    for(int j = 0; j < N-1-i; j++){
      int bufsum=posco[i]+negco[j];
      int bufmax=bufsum-std::min(posx[i],negx[i]);
      maxvec[2]=std::max(maxvec[2], bufmax);
    }
  }

