template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
typedef long long ll;
typedef std::pair<ll,ll> P;

ll gcd ( ll a, ll b ) { if ( b == 0 ) return a; else return gcd ( b, a%b ); }
ll lcm ( ll a, ll b ) { return a * b / gcd(a, b); }

ll C;

ll sol(const std::vector<P> &s) {
  ll ans = 0, D = 0;
  int N = sz(s);

  // cyclic only
  std::vector<ll> Lr(N);
  D = 0;
  rep(i,N) {
    if ( i != 0 ) D += s[i].second-(s[i].first - s[i-1].first);
    else D += (s[i].second - s[i].first);
    chmax(ans, D);
    Lr[i] = D;
  }

  // mae keisann
  std::vector<ll> Ll(N);
  ll tmp = 0;
  D = 0;
  for(int k=N-1; k>=0; k--) {
    if ( k != N-1 ) D += s[k].second - (s[k+1].first - s[k].first);
    else D += (s[k].second - (C-s[k].first));
    chmax(tmp, D);
    Ll[k] = tmp;
  }

  // cyclic i, un-cyc j
  rep(i,N-1) {
    D = Lr[i];
    D -= s[i].first;
    D += Ll[i+1];
    chmax(ans, D);
  }

  return ans;
}

int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  ll N; std::cin >> N >> C;
  std::vector<P> s(N); rep(i,N) std::cin >> s[i].first >> s[i].second;
  std::vector<P> t(N); rep(i,N) t[i] = { C-s[N-i-1].first, s[N-i-1].second };

  std::cout << std::max( sol(s), sol(t) ) << std::endl;
  return 0;
}

