int main () {
  ll n, c;
  cin >> n >> c;
  ll x[n + 1], v[n + 1];
  ll sum1[n + 1], sum2[n + 1];
  x[0] = 0;
  sum1[0] = 0;
  sum2[0] = 0;
  v[0] = 0;
  for (ll i = 1; i <= n; i++) {
    cin >> x[i] >> v[i];
    sum1[i] = sum1[i - 1] + v[i];  
  }  
  for (ll i = 1; i <= n; i++) {
    sum2[i] = sum2[i - 1] + v[n - i + 1];  
  }
  pair<ll, ll> dp1[n + 1], dp2[n + 1];
  dp1[0] = make_pair(0, 0);
  dp2[0] = make_pair(0, 0);
  for (ll i = 1; i <= n; i++) {
    ll now;
    if ((sum1[i] - x[i]) > dp1[i - 1].first) {
      now = i;
      dp1[i] = make_pair(sum1[i] - x[now], now);  
    }  
    else {
      dp1[i] = dp1[i - 1];  
    }
    ll j = n - i + 1;
    if ((sum2[i] - (c - x[j]))> dp2[i - 1].first) {
      now = j;
      dp2[i] = make_pair(sum2[i] - (c - x[now]), now);  
    }
    else {
      dp2[i] = dp2[i - 1];  
    }
  }
  ll max = -1;
  for (ll i = 0; i <= n; i++) {
    ll left = x[dp1[i].second];
    ll sum = dp1[i].first;
    ll right = x[dp2[n - dp1[i].second].second];
    if (right == 0) {
      right = c;  
    }
    sum = sum + dp2[n - dp1[i].second].first;
    if (left < (c - right)) {
      sum -= left;  
    } 
    else {
      sum -= c - right;  
    }
    if (max < sum) {
      max = sum;  
    }
  }
  cout << max << endl;
}

