bool check(Sushi *sushi){
  for(int i=0;i<N;i++) if(sushi[i].eated==false) return false;
  return true;
}

int nakabashi(Sushi *sushi,int np){
  if(check(sushi)){
    int n;
    n=takecal-usecal;
    ans=(n>ans)?n:ans;
    return 0;
  }
  else{
    for(int i=0;i<N;i++){
      if(sushi[i].eated==false){
        sushi[i].eated=true;
        usecal+=(abs(np-sushi[i].dist)<abs(C-np+sushi[i].dist))?abs(np-sushi[i].dist):abs(C-np+sushi[i].dist);
        takecal+=sushi[i].cal;
        nakabashi(sushi,sushi[i].dist);
        takecal-=sushi[i].cal;
        usecal-=(abs(np-sushi[i].dist)<abs(C-np+sushi[i].dist))?abs(np-sushi[i].dist):abs(C-np+sushi[i].dist);
        sushi[i].eated=false;
      }
    }
  }
}

