    vector<P> right1(N+1, {0,0}), left1(N+1, {0,0}), right2(N+1, {0,0}), left2(N+1, {0,0});
    rep(i, N){
        right[i+1] = right[i] + v[i+1] - (x[i+1] - x[i]);
