#define D_SUSHI_MAX		100000									// 最大寿司数

// 内部構造体 - 寿司情報
typedef struct Sushi {
	long long mlLen;											// 距離
	long long mlCal;											// カロリー
	long long mlCSum;											// カロリー累計
} Sushi;

// 内部変数
static Sushi sz1SushiR[D_SUSHI_MAX];							// 寿司リスト(右側方向累計)
static Sushi sz1SushiL[D_SUSHI_MAX];							// 寿司リスト(左側方向累計)
static int siSCnt;												// 寿司リスト数
static long long slLen;											// 外周長さ
static long long slMax;											// 最大カロリー累計

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpT, *szpFpA;
#endif

// 寿司リスト - 累計セット・片側移動の最大値更新
int
fUpMaxSgl(
	Sushi *pzpSushi				// <I> 寿司リスト
)
{
	int i;

	// １つ目
	long long llLSum = pzpSushi[0].mlLen;
	long long llCSum = pzpSushi[0].mlCal - pzpSushi[0].mlLen;
	pzpSushi[0].mlCSum = llCSum;

	// 最大値更新
	if (slMax < llCSum) {
		slMax = llCSum;
	}

	// ２つ目以降
	for (i = 1; i < siSCnt; i++) {
		llLSum += pzpSushi[i].mlLen;
		llCSum += pzpSushi[i].mlCal - pzpSushi[i].mlLen + pzpSushi[i - 1].mlLen;
		if (llCSum < pzpSushi[i - 1].mlCSum) {										// 前回の寿司時点の方が高カロリーの場合
			pzpSushi[i].mlCSum = pzpSushi[i - 1].mlCSum;
		}
		else {																		// 今回の寿司が高カロリー
			pzpSushi[i].mlCSum = llCSum;

			// 最大値更新
			if (slMax < llCSum) {
				slMax = llCSum;
			}
		}
	}

	return 0;
}

// 寿司リスト - 両側移動の最大値更新
int
fUpMaxDbl(
	Sushi *pzpSushi1			// <I> 寿司リスト１
	, Sushi *pzpSushi2			// <I> 寿司リスト２
)
{
	int i;

	for (i = 0; i < siSCnt - 1; i++) {

		// リスト１方向へ
		long long llCSum = pzpSushi1[i].mlCSum;

		// 初期位置へ
		llCSum -= pzpSushi1[i].mlLen;

		// リスト２方向へ
		llCSum += pzpSushi2[siSCnt - i - 2].mlCSum;

		// 最大値更新
		if (slMax < llCSum) {
			slMax = llCSum;
		}
	}

	return 0;
}

