    int v[C],x;
    for(i=0;i<C;i++)v[i] = 0;
    for(i=0;i<N;i++){
        scanf("%d",&x);
        scanf("%d",&v[x]);
    }
    int xT=0,cT=0;
    /*
    for(i=0;i<C;i++){
        printf("%d\n",v[i]);
    }
    */
    int maxV,maxX,vR,vL,walk;
    while(1){
        maxV=0;
        maxX=0;

        for(i=0;i<C;i++){
            if(maxV < v[i] - Min(abs(x-xT),C/2-abs(x-xT))){
                maxV = v[i] - Min(abs(x-xT),C/2-abs(x-xT));
                maxX = i;
            }
        }
        if(maxV <= 0)break;
        vR = 0 ; vL = 0 ; walk = 0 ;
        for(i=xT;i!=maxX;i++){
            if(i==C)i=0;
            vR += v[i];
            v[i] = 0;
            walk ++;
        }
        vR -= walk;

        walk = 0;
        for(i=xT;i!=maxX;i--){
            if(i==0)i=C;
            vL += v[i];
            v[i] = 0;
            walk ++;
        }
        vL -= walk;

        //walk = 0;

        xT = maxX;
        cT += Max(vR,vL);

    //    printf("%d\n",cT);
    }
