main(int argc, char *argv[])
{
  int n; ll c;
  scanf("%d %lld", &n, &c);
  ll x[100000], v[100000];
  REP(i, n) scanf("%lld %lld", &x[i], &v[i]);

  ll vl[100000], sum = 0;
  REP(i, n){
    sum += v[i];
    vl[i] = sum - x[i];
  }

  ll vlmax[100000]; vlmax[0] = vl[0];
  for(int i = 1; i < n; i++){
    vlmax[i] = Max(vlmax[i - 1], vl[i]);
  }

  ll vr[100000]; sum = 0;
  REP(i, n){
    sum += v[n - 1 - i];
    vr[n - 1 - i] = sum - (c - x[n - 1 - i]);
  }

  ll vrmax[100000]; vrmax[n - 1] = vr[n - 1];
  for(int i = n - 2; i >= 0; i--){
    vrmax[i] = Max(vrmax[i + 1], vr[i]);
  }

  //右回りから始める
  ll ans = Max(0, vlmax[n - 1]);
  for(int i = n - 1; i >= 0; i--){
    if(i - 1 >= 0){
      ans = Max(vr[i] - (c - x[i]) + vlmax[i - 1], ans);
    }
  }

  //左回りから始める
  ans = Max(ans, vrmax[0]);
  for(int i = 0; i < n; i++){
    if(i + 1 < n){
      ans = Max(vl[i] - x[i] + vrmax[i + 1], ans);
    }
  }

  printf("%lld\n", ans);

  return 0;
}

