static llong int heap[100010];
int sz=-1;

void push(llong int x){
	//自分のノード番号
	int i;
	sz++;
	i=sz;

	while(i>0){
		//親のノード番号
		int p=(i-1)/2;
		//もう逆転していないなら抜ける
		if(heap[p]>=x) break;
		//親のノードの数字を下ろして、自分は上に
		heap[i]=heap[p];
		i=p;
	}
	heap[i]=x;
}

llong int pop(){
	llong int ret;
	int a,b;
	llong int x;
	int i;
	//最小値
	ret=heap[0];
	//根に持ってくる値
	x=heap[sz];
	sz=sz-1;
	//根からおろしていく
	i=0;
	while(i*2+1<=sz){
		a=i*2+1;
		b=i*2+2;
		if(b<sz&&heap[b]>heap[a]) a=b;
		//もう逆転していないなら終わり
		if(heap[a]<=x) break;
		//子の数字を持ち上げる
		heap[i]=heap[a];
		i=a;
	}
	heap[i]=x;

	return ret;
}



