#define MAX (1 << 18) /* 262144 */
#define INF INT64_C(11111111111111111)

int64_t ki[MAX * 2 - 1];
int64_t* ki_data = ki + (MAX - 1);

void ki_init(void) {
	int i;
	for (i = (MAX - 1) - 1; i >= 0; i--) {
		int64_t c1 = ki[i * 2 + 1], c2 = ki[i * 2 + 2];
		ki[i] = c1 >= c2 ? c1 : c2;
	}
}

int64_t ki_get_i(int idx, int qmin, int qmax, int smin, int smax) {
	if (qmax <= smin || smax <= qmin) { /* クエリがセグメントから完全に外れている */
		return -INF;
	} else if (qmin <= smin && smax <= qmax) { /* セグメントがクエリに完全に含まれる */
		return ki[idx];
	} else {
		int smid = smin + (smax - smin) / 2;
		int64_t left, right;
		left = ki_get_i(idx * 2 + 1, qmin, qmax, smin, smid);
		right = ki_get_i(idx * 2 + 2, qmin, qmax, smid, smax);
		return left >= right ? left : right;
	}
}

int64_t ki_get(int min, int max) {
	return ki_get_i(0, min, max, 0, MAX);
}

int N;
int64_t C;
int64_t x[114514];
int64_t v[114514];

int64_t solve(void) {
	int64_t answer = 0; /* 何もせず帰れば0キロカロリーを得られる */
	int i;
	ki_data[0] = 0;
	for (i = 1; i < N * 2; i++) {
		ki_data[i] = ki_data[i - 1] + v[i % N] - ((x[i % N] + C - x[(i - 1) % N])) % C;
	}
	ki_init();
	for (i = 0; i <= N; i++) {
		int64_t candidate = -(C - x[i]);
		candidate += ki_get(i, i + N) - ki_data[i];
		candidate += v[i];
		if (candidate > answer) answer = candidate;
	}
	return answer;
}

int main(void) {
	int i;
	int64_t a1, a2;
	if (scanf("%d%" SCNd64, &N, &C) != 2) return 1;
	x[0] = 0;
	v[0] = 0;
	N++;
	for (i = 1; i < N; i++) {
		if (scanf("%" SCNd64 "%" SCNd64, &x[i], &v[i]) != 2) return 1;
	}
	x[N] = C;
	v[N] = 0;
	/* 反時計回りに移動→そこの寿司を食べる→時計回りに移動して食べる */
	a1 = solve();
	/* 反対まわりにして解く */
	for (i = 1; i < N; i++) x[i] = C - x[i];
	for (i = 1; i < N - i; i++) {
		int64_t t = x[i];
		x[i] = x[N - i];
		x[N - i] = t;
		t = v[i];
		v[i] = v[N - i];
		v[N - i] = t;
	}
	a2 = solve();
	/* いい方を出力する */
	printf("%" PRId64 "\n", a1 >= a2 ? a1 : a2);
	return 0;
}

