#define MAX 100001
#define MOD 1000000007


int main(void) {
	long long int n, c;
	scanf("%lld %lld", &n, &c);
	long long int x[MAX], v[MAX];
	x[0] = 0; v[0] = 0;
	for ( int i = 1; i <= n; i++ )  
		scanf("%lld %lld", &x[i], &v[i]);

	// 時計回りの位置をA,反時計回りの位置をB
	// va[a]: v(1) + v(2)     + ... + v(a)
	// vb[b]: v(n) + v(n - 1) + ... + v(b)
	long long int va[MAX], vb[MAX];
	va[0] = 0; vb[0] = 0; 
	for ( int i = 0; i < n; i++ )
		va[i + 1] = va[i] + v[i + 1];
	vb[n] = v[n];
	for ( int i = n; i > 1; i-- )
		vb[i - 1] = vb[i] + v[i - 1];



	// geta(a): v(1) + v(2)   + ... + v(a) - x(a)
	// getb(b): v(n) + v(n-1) + ... + v(b) - (c - x(b))
	long long int geta[MAX], getb[MAX];
	geta[0] = 0; getb[0] = 0;
	for ( int i = 1; i <= n; i++ ) {
		geta[i] = va[i] - x[i];
		getb[i] = vb[i] - ( c - x[i] );
	}

	// maxa(a): max{ geta(0), geta(1), ..., get(a) }
	// maxb(b): max{ getb(n), getb(n-1), ..., getb(b) }
	long long int maxa[MAX], maxb[MAX];
	maxa[0] = 0; maxb[n] = getb[n];
	for ( int i = 0; i < n; i++ ) {
		maxa[i + 1] = max(maxa[i], geta[i + 1]);
		maxb[n - i - 1] = max(maxb[n - i], getb[n - i - 1]);
	}
	maxb[0] = 0;

	long long int ans = 0;
	// 最終地点がA側(Bを固定)
	for ( int i = 0; i <= n; i++ )
		ans = max(ans, maxa[i] + getb[i] - (c - x[i]));
	// 最終地点がB側(Aを固定)
	for ( int i = 0; i <= n; i++ )
		ans = max(ans, maxb[i] + geta[i] - x[i]);

	printf("%lld\n", ans);
  return 0;
}

