int main(void){
    int N;
    long long int C;

    scanf("%d%lld", &N, &C);

    int i;

    long long int *x = (long long int *) malloc(sizeof(long long int) * N);
    int *v = (int *) malloc(sizeof(int) * N);

    for(i = 0; i < N; i ++){
        scanf("%lld%d", x + i, v + i);
    }
    // 右回り
    long long int c = v[0] - x[0];
    long long int c2 = v[0] - 2 * x[0];
    long long int c_max = 0;
    long long int c2_max = 0;
    long long int *c_forward = (long long int *) malloc(sizeof(long long int) * N);
    long long int *c2_forward = (long long int *) malloc(sizeof(long long int) * N);

    if(c > c_max){
        c_max = c;
    }
    if(c2 > c2_max){
        c2_max = c2;
    }
    c_forward[0] = c_max;
    c2_forward[0] = c2_max;

    for(i = 1; i < N; i ++){
        c += v[i] - (x[i] - x[i - 1]);
        c2 += v[i] - 2 * (x[i] - x[i - 1]);

        if(c > c_max){
            c_max = c;
        }
        if(c2 > c2_max){
            c2_max = c2;
        }
        c_forward[i] = c_max;
        c2_forward[i] = c2_max;
    }
    // 左回り
    c = v[N - 1] - (C - x[N - 1]);
    c2 = v[N - 1] - 2 * (C - x[N - 1]);
    c_max = 0;
    c2_max = 0;

    long long int *c_back = (long long int *) malloc(sizeof(long long int) * N);
    long long int *c2_back = (long long int *) malloc(sizeof(long long int) * N);

    if(c > c_max){
        c_max = c;
    }
    if(c2 > c2_max){
        c2_max = c2;
    }
    c_back[N - 1] = c_max;
    c2_back[N - 1] = c2_max;

    for(i = N - 2; i >= 0; i --){
        c += v[i] - (x[i + 1] - x[i]);
        c2 += v[i] - 2 * (x[i + 1] - x[i]);

        if(c > c_max){
            c_max = c;
        }
        if(c2 > c2_max){
            c2_max = c2;
        }
        c_back[i] = c_max;
        c2_back[i] = c2_max;
    }
    // cの最大値を求める
    long long int c_max_all = 0;

    for(i = 0; i < N - 1; i ++){
        c_max = c_forward[i] + c2_back[i + 1];

        if(c_max > c_max_all){
            c_max_all = c_max;
        }
    }
    if(c_forward[N - 1] > c_max_all){
        c_max_all = c_forward[N - 1];
    }
    for(i = N - 1; i > 0; i --){
        c_max = c2_forward[i - 1] + c_back[i];

        if(c_max > c_max_all){
            c_max_all = c_max;
        }
    }
    if(c_back[0] > c_max_all){
        c_max_all = c_back[0];
    }
    printf("%lld\n", c_max_all);

    return 0;
}

