int main(void) {
  int N;
  long long C;
  long long *x;
  int *v;
  long long *ck, *ack;
  long long max = 0;
  scanf("%d%lld", &N, &C);
  x = (long long*)malloc(sizeof(long long) * (N+2));
  v = (int*)malloc(sizeof(int) * (N+1));
  ck = (long long*)malloc(sizeof(long long) * (N+1));
  ack = (long long*)malloc(sizeof(long long) * (N+1));
  x[0] = v[0] = 0;
  x[N+1] = C;
  for (int i = 1; i <= N; i++) scanf("%lld%d", &x[i], &v[i]);

  ck[0] = ack[0] = 0;
  for (int i = 1; i <= N; i++) {
    ck[i] += ck[i-1] + v[i];
    ack[i] += ack[i-1] + v[N+1-i];
  }

  for (int j = 0; j <= N; j++) {
    for (int i = 0; i <= N-j; i++) {
      long long sum = ack[j] + ck[i];
      sum -= ((x[i] < C-x[N+1-j]) ? 2*x[i] + (C-x[N+1-j]) : x[i] + 2*(C-x[N+1-j]));
      if (sum > max) max = sum;
    }
  }
  printf("%lld\n", max);

  return 0;
}

