#include <stdio.h>
#define MAX(x,y) x>y?x:y
typedef long long int ll;

ll N,C,x[100002],v[100002];

ll Solve(){
	ll lg=0,tem=0;
        ll max[100001];
        max[0]=0;
	for(ll i=0;i<N;i++)
	{
		lg+=v[i+1]+x[i]-x[i+1];
		max[i+1]=MAX(max[i],lg);
	}
	ll ans=max[N];
	for(ll i=N;i>1;i--)
	{
		tem+=v[i]+x[i]-x[i+1];
		ans=MAX(tem+x[i]-C+max[i-1],ans);
	}
	return ans;
}

void swap(ll* v1,ll* v2){
        ll sw = *v1;
        *v1=*v2;
        *v2=sw;
}

int main(){
	scanf("%lld %lld",&N,&C);
	for(ll i=0;i<N;i++) scanf("%lld %lld",&x[i+1],&v[i+1]);
	x[N+1]=C;
        x[0]=0;
	ll Ans1=Solve();
        for(ll i=1;i<=N/2;i++) {
            x[i]=C-x[i];
            x[N+1-i]=C-x[N+1-i];
            swap(&x[i],&x[N+1-i]);
            swap(&v[i],&v[N+1-i]);
        }
	ll Ans2=Solve();
	printf("%lld",MAX(Ans1,Ans2));
	return 0;
}

