import java.util.*

fun main(args: Array<String>) {
    val (N, C) = readLine()!!.split(" ").map{it.toLong()}

    val cal = TreeMap<Long, Long>()
    val rcal = TreeMap<Long, Long>()

    for (i in 1..N) {
        val (x, v) = readLine()!!.split(" ").map{it.toLong()}
        val e = cal.lowerEntry(x)
        cal[x] = v + (e?.value ?: 0L) - (x - (e?.key ?: 0L))
        rcal[C - x] = v
    }

    for (k in rcal.keys) {
        val e = rcal.lowerEntry(k)
        rcal[k] = rcal[k]!! + (e?.value ?: 0L) - (k - (e?.key ?: 0L))
    }

    fun func(cal: TreeMap<Long, Long>) {
        for (k in cal.keys) {
            cal[k] = Math.max(cal[k]!!, cal.lowerEntry(k)?.value ?: 0L)
        }
    }

    func(cal)
    func(rcal)

    fun calc(mp: TreeMap<Long, Long>, rmp: TreeMap<Long, Long>): Long {
        var r = 0L

        for (e in mp.entries) {
            r = Math.max(r, e.value)

            val t = rmp.lowerEntry(C - e.key)?.value ?: 0L
            r = Math.max(r, e.value + t - e.key)
        }

        return r
    }

    println(Math.max(calc(cal, rcal), calc(rcal, cal)))
}

fun main(args: Array<String>) {
    val (n, C) = readLine()!!.split(" ").map { it.toLong() }
    val N = n.toInt()
    val x = LongArray(N)
    val v = LongArray(N)
    (0 until N).forEach {
        val (a, b) = readLine()!!.split(" ").map { it.toLong() }
        x[it] = a
        v[it] = b
    }

    var max = 0L
    var cal = 0L
    var position = 0L
    // Start to right
    val r = LongArray(N)
    for (i in 0 until N) {
        val move = x[i] - position
        cal = cal + v[i] - move
        position = x[i]
        max = Math.max(max, cal)
        r[i] = max
    }

    val l = LongArray(N)
    max = 0L
    cal = 0L
    position = C
    for (i in N - 1 downTo  0) {
        val move = position - x[i]
        cal = cal + v[i] - move
        position = x[i]
        max = Math.max(max, cal)
        l[i] = max
    }

    var answer = Math.max(r[N - 1], l[0])
    // Start to left
    for (i in 0 until N - 1) {
        answer = Math.max(answer, r[i] + l[i + 1] - x[i])
    }
    for (i in N - 1 downTo  1) {
        answer = Math.max(answer, l[i] + r[i-1] - (C - x[i]))
    }

    println(answer)
}

import java.lang.Math

fun main(args: Array<String>) {
    val (N, C) = readInputLine().split(" ").let { Pair(it[0].toInt(), it[1].toLong()) }

    val sushi = Array(N + 2) {
        if (it == 0 || it == N + 1) Pair(0L, 0L)
        else readInputLine().split(" ").let {
            Pair(it[0].toLong(), it[1].toLong())
        }
    }

    // 最大摂取カロリーとそこまでの距離のペア
    val clockwiseMax = Array(N + 2) { Pair(0L, 0L) }

    var currentDist = 0L
    var currentCal = 0L
    for (i in 1..N) {
        currentDist = sushi[i].first
        currentCal += sushi[i].second
        if (clockwiseMax[i - 1].first < currentCal - currentDist) {
            clockwiseMax[i] = Pair(currentCal - currentDist, currentDist)
        } else {
            clockwiseMax[i] = clockwiseMax[i - 1]
        }
    }

    currentDist = 0L
    currentCal = 0L

    val unclockwiseMax = Array(N + 2) { Pair(0L, 0L) }
    for (i in N downTo 1) {
        currentDist = C - sushi[i].first
        currentCal += sushi[i].second
        if (unclockwiseMax[i].first < currentCal - currentDist) {
            unclockwiseMax[i] = Pair(currentCal - currentDist, currentDist)
        } else {
            unclockwiseMax[i] = unclockwiseMax[i + 1]
        }
    }

    var ans = 0L
    for (i in 1..N) {
        ans = Math.max(ans, clockwiseMax[i].first + unclockwiseMax[i + 1].first - unclockwiseMax[i + 1].second)
        ans = Math.max(ans, clockwiseMax[i].first + unclockwiseMax[i + 1].first - clockwiseMax[i].second)
    }

    println(ans)
}

