    }

    cal = 0L
    position = C
    var answer = maxDp[N - 1]
    // Start to left
    for (i in N - 1 downTo  0) {
        val move = position - x[i]
        cal = cal + v[i] - move
        position = x[i]
        if (i -1 >= 0) {
            answer = Math.max(answer, cal - (C - position) + maxDp[i - 1])
        } else {
            answer = Math.max(answer, cal)
        }
    }

    println(answer)
}

