const val MOD = 1000000007L
const val INF = 9223372036854775807L

// Main
fun main(args: Array<String>) {
    solve()
    pw.flush()
}


fun solve() {
    val n = nextLong()
    val c = nextLong()
    val sushi = longAry2(n, 2)  // x,v
    for (i in 0 until n) {
        sushi[i][0] = nextLong()
        sushi[i][1] = nextLong()
    }

    val right = longAry(n)
    val left = longAry(n)
    var nowcal = 0L
    for (i in 0 until n) {
        val dis = sushi[i][0]
        nowcal += sushi[i][1]
        right[i] = if(i == 0L) nowcal - dis else max(nowcal - dis, right[i - 1])
    }
    nowcal = 0L
    for (i in n - 1 downTo 0) {
        val dis = c - sushi[i][0]
        nowcal += sushi[i][1]
        left[i] = if(i == n - 1) nowcal - dis else max(nowcal - dis, left[i + 1])
    }

    var ans = max(right[n - 1], left[0], 0L)
    for (i in 0 until n - 1) {
        val rightcal = right[i]
        val leftcal = left[i + 1] - sushi[i][0]
        ans = max(ans, rightcal + leftcal)
    }
    for (i in n - 1 downTo 1) {
        val leftcal = left[i]
        val rightcal = right[i - 1] - (c - sushi[i][0])
        ans = max(ans, leftcal + rightcal)
    }

    println(ans)

}



