var n = 0
var c = 0L

fun main(args: Array<String>) = IO().exec {
    n = int()
    c = long()
    val x = LongArray(n)
    val v = LongArray(n)
    for (i in 0 until n) {
        x[i] = long()
        v[i] = long()
    }
    var ret = calc(x, v)
    x.reverse()
    for (i in 0 until n) x[i] = c - x[i]
    v.reverse()
    ret = Math.max(ret, calc(x, v))
    println(ret)
}

fun calc(x: LongArray, v: LongArray): Long {
    val cumv = Cum(v)
    val g = LongArray(n+1)
    for (i in 0 until n)
        g[i+1] = Math.max(g[i], cumv[0..i] - x[i])
    var ret = g[n]
    for (i in 0 until n) {
        ret = Math.max(ret, g[i] + cumv[i until n] - (c - x[i]) * 2)
    }
    return ret
}

class Cum(val a: LongArray) {
    val s = LongArray(a.size + 1)
    init {
        for (i in 0 until a.size) {
            s[i+1] = s[i] + a[i]
        }
    }
    operator fun get(range: IntRange): Long = s[range.last+1] - s[range.first]
}

class IO {
    val printable = 33..126
    val buffer = ByteArray(1024)
    var ptr = 0
    var buflen = 0
    val out = PrintWriter(System.out)
    fun hasNextByte(): Boolean = if (ptr < buflen) true else {
        ptr = 0
        buflen = System.`in`.read(buffer)
        buflen > 0
    }
    fun readByte(): Byte = if (hasNextByte()) buffer[ptr++] else -1
    fun hasNext(): Boolean {
        while (hasNextByte() && buffer[ptr] !in printable) ptr++
        return hasNextByte()
    }
    fun string(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (b in printable) {
            sb.appendCodePoint(b.toInt())
            b = readByte()
        }
        return sb.toString()
    }
    fun long(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var minus = false
        var b = readByte()
        if (b == '-'.toByte()) {
            minus = true
            b = readByte()
        }
        if (b !in '0'.toByte()..'9'.toByte()) {
            throw NumberFormatException()
        }
        while (true) {
            if (b in '0'.toByte()..'9'.toByte()) {
                n *= 10
                n += b - '0'.toByte()
            } else if (b == (-1).toByte() || b !in printable) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }
    fun int(): Int {
        val nl = long()
        if (nl !in Integer.MIN_VALUE..Integer.MAX_VALUE) throw NumberFormatException()
        return nl.toInt()
    }
    fun double(): Double = string().toDouble()
    fun print(obj: Any) = out.print(obj)
    fun print(i: Int) = out.print(i)
    fun print(l: Long) = out.print(l)
    fun println(obj: Any) = out.println(obj)
    fun println(i: Int) = out.println(i)
    fun println(l: Long) = out.println(l)
    inline fun exec(block: IO.() -> Unit) {
        block()
        out.flush()
    }
}

import java.lang.Math;
import java.util.Scanner;
import java.util.Arrays;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt() + 1;
        long C = sc.nextLong();

        long costs[] = new long[N];   // x_i
        int values[] = new int[N];  // v_i
        costs[0] = 0;  // 初期位置
        values[0] = 0;

        for (int i = 1; i < N; i++) {
            costs[i] = sc.nextLong();
            values[i] = sc.nextInt();
        }

        // O(N^2) 解
        long value_accum[] = new long[N];
        long value_accum_rev[] = new long[N];
        value_accum[0] = 0;  // 初期位置
        value_accum_rev[0] = 0;
        for (int i = 1; i < N; i++) {
            value_accum[i] = value_accum[i-1] + values[i];
            value_accum_rev[i] = value_accum_rev[i-1] + values[N-i];
        }
        // System.out.println(Arrays.toString(values));
        // System.out.println(Arrays.toString(value_accum));
        // System.out.println(Arrays.toString(value_accum_rev));

        // 全探索
        long score_max = 0;
        for (int i = 0; i < N+1; i++) {
            for (int j = 0; j < N-i; j++) {
                // System.out.println(i + ", " + j);

                // 時計回り側の価値・コスト
                long cw_value = value_accum[i];
                long cw_cost = costs[i];

                // 反時計周り
                long acw_value = value_accum_rev[j];
                long acw_cost = (j == 0) ? j : (C - costs[N-j]);
                // System.out.println("acw_value: " + acw_value);
                // System.out.println("acw_cost: " + acw_cost);

                // 時計回りに先に行く場合
                long score_cw = (cw_value - cw_cost * 2) + (acw_value - acw_cost);
                // System.out.println("score_cw: " + score_cw);

                // 反時計周り
                long score_acw = (cw_value - cw_cost) + (acw_value - acw_cost * 2);
                // System.out.println("score_acw: " + score_acw);

                if (score_cw >= score_max) { score_max = score_cw; }
                if (score_acw >= score_max) { score_max = score_acw; }
            }
        }

        System.out.println(score_max);
    }
}

import java.util.Scanner;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		long c = sc.nextLong();

		long[] poss = new long[n];
		long[] cals = new long[n];

		for(int i = 0; i < n; i++) {
			poss[i] = sc.nextLong();
			cals[i] = sc.nextLong();
		}

		long max = 0;
		long sum = 0;
		long cal;
		for(int i = 0; i < n; i++) {
			sum = cals[i];
			cal = sum;
			if(poss[i] < c - poss[i]) {
				cal -= poss[i];
			} else {
				cal -= (c - poss[i]);
			}
			max = Math.max(max, cal);
			int j = 0;
			while(j < n-1) {
				int idx;
				if(i+j+1 < n) {
					idx = i + j + 1;
				} else {
					idx = i + j - n + 1;
				}
				sum += cals[idx];
				cal = sum;
				if(i < idx) {
					cal -= Math.abs(poss[i] - poss[idx]);
					if(poss[i] < c - poss[idx]) {
						cal -= poss[i];
					} else {
						cal -= (c - poss[idx]);
					}
				} else {
					cal -= (c - poss[i]) + poss[idx];
					if(poss[idx] < c - poss[i]) {
						cal -= poss[idx];
					} else {
						cal -= (c - poss[i]);
					}
				}
				max = Math.max(max, cal);
				j++;
			}
		}
		System.out.println(max);

	}
}

