    public static void main(String args[]) {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        c = sc.nextLong();
        xs = new long[n + 2];
        vs = new long[n + 2];
        xs[0] = 0;
        xs[n + 1] = c;
        vs[0] = 0;
        vs[n + 1] = 0;
        for (int i = 1; i <= n; i++) {
            xs[i] = sc.nextLong();
            vs[i] = sc.nextLong();
        }

        System.out.println(rec(1, n, true));
        /*
        // counterclockwise
        long counterClockSum = 0;
        long[] counterClockDP = new long[n + 1];
        for (int i = 0; i < n; i++) {
            counterClockDP[i + 1] = Math.max(counterClockDP[i + 1],
                    counterClockDP[i] + vs[i] - xs[i] + xs[i - 1]);
        }
        for (int i = n - 1; i > 0; i--) {
            if (vs[i] > xs[i] - xs[i - 1]) {
                counterClockSum += vs[i] - xs[i] + xs[i - 1];
            }
        }
        */
    }

    static long rec(int next, int prev, boolean forward) {
        if (next > prev) return 0;
        long nextDistance = xs[next] - xs[next - 1];
        long prevDistance = xs[next - 1] + c - xs[prev];
        if (!forward) {
            nextDistance = xs[next] + c - xs[prev + 1];
            prevDistance = xs[prev + 1] - xs[prev];
        }
        long ans = Math.max(0, Math.max(
                rec(next + 1, prev, true) + vs[next] - nextDistance,
                rec(next, prev - 1, false) + vs[prev] - prevDistance));
        return ans;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Scanner;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long N = sc.nextLong();
		long C = sc.nextLong();
		long x[] = new long[(int)N+1];
		long v[] = new long[(int)N+1];
		for(int i =1;i <=N;i++) {
			x[i]= sc.nextLong();
			v[i]= sc.nextLong();
		}

		boolean iscon =true;
		long nowx =0;
		long now =0;
		boolean right =true;
		long best =-1;
		long kal=0;
		while(iscon) {
			long max =0;
			long len =0;
			for(int i =1;i <=N;i++) {
				if(Math.abs(nowx-x[i])<Math.abs(C-nowx+x[i])) {
					right= true;
					len =nowx-x[i];
				}else {
					right=false;
					len =C-nowx+x[i];
				}
				//long len = Math.min(Math.abs(now-x[i]),Math.abs(C-now+x[i]));
				if(max<v[i]-len) {
					max = v[i]-len;
					best = i;
					nowx = x[i];
				}
			}
			if(max<0) {
				iscon =false;
				break;
			}
			if(right) {
				long i = now +1;
				while(i !=best) {
					kal+=max;
					i++;
				}
				now = best;
			}else {
				long i = now -1;
				if(i==-1) {
					i = N;
				}
				while(i!=best) {
					kal+=max;
					i--;
					if(i==-1) {
						i =N;
					}
				now = best;
				}
			}
			System.out.println(kal);
		}
		sc.close();
	}
}

