public class Main {
	public static int N;
	public static long C;
	public static long[] positions, values, prefixes, suffixes;
	public static boolean[][][] visited = new boolean[102][102][2];

	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(f.readLine());
		N = Integer.parseInt(st.nextToken());
		C = Long.parseLong(st.nextToken());
		positions = new long[N + 1];
		values = new long[N + 1];
		prefixes = new long[N + 1];
		suffixes = new long[N + 1];
		positions[0] = 0;
		values[0] = 0;
		for (int i = 0; i < N; i++) {
			st = new StringTokenizer(f.readLine());
			long x = Long.parseLong(st.nextToken());
			long v = Long.parseLong(st.nextToken());
			positions[i + 1] = x;
			values[i + 1] = v;
		}
		for (int i = 1; i <= N; i++) {
			prefixes[i] = prefixes[i - 1] + values[i];
		}
		for (int i = N - 1; i >= 0; i--) {
			suffixes[i] = suffixes[i + 1] + values[i + 1];
		}
		long res = 0;
		for (int i = 0; i <= N; i++) {
			res = Math.max(res, prefixes[i] - positions[i]);
			res = Math.max(res, suffixes[i] - (C - positions[i]));
			for (int j = i + 1; j <= N; j++) {
				res = Math.max(res, prefixes[i] + suffixes[j - 1] - positions[i] - positions[i] - (C - positions[j]));
				res = Math.max(res, prefixes[i] + suffixes[j - 1] - 2 * (C - positions[j]) - positions[i]);
			}
		}
		System.out.println(res);
	}
}

import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        long C = sc.nextLong();
        long[] x = new long[N];
        int[] v = new int[N];
        for (int i = 0; i < N; ++i) {
            x[i] = sc.nextLong();
            v[i] = sc.nextInt();
        }

        System.out.println(solve(x, v, C));

        sc.close();
    }

    static long solve(long[] x, int[] v, long C) {
        return Math.max(solveFirstClockwise(x, v, C),
                solveFirstClockwise(Arrays.stream(x).map(xi -> C - xi).sorted().toArray(), v, C));
    }

    static long solveFirstClockwise(long[] x, int[] v, long C) {
        int N = x.length;

        PriorityQueue<Element> pq = new PriorityQueue<>((e1, e2) -> -Long.compare(e1.gain, e2.gain));
        long counterClockwiseEnergySum = 0;
        for (int i = N - 1; i >= 0; --i) {
            counterClockwiseEnergySum += v[i];
            long gain = counterClockwiseEnergySum - (C - x[i]);

            pq.offer(new Element(x[i], gain));
        }

        long result = Math.max(0, pq.peek().gain);
        long clockwiseEnergySum = 0;
        for (int i = 0; i < N; ++i) {
            clockwiseEnergySum += v[i];
            long balance = clockwiseEnergySum - x[i];

            while (!pq.isEmpty() && pq.peek().clockwiseDistance <= x[i]) {
                pq.poll();
            }
            if (!pq.isEmpty()) {
                balance += Math.max(0, pq.peek().gain - x[i]);
            }

            result = Math.max(result, balance);
        }

        return result;
    }
}

class Element {
    long clockwiseDistance;
    long gain;

    Element(long clockwiseDistance, long gain) {
        this.clockwiseDistance = clockwiseDistance;
        this.gain = gain;
    }
}

