    long[] dp1 = new long[n + 1];
    long[] dp2 = new long[n + 1];
    for(int i = 1; i < n + 1; i++) {
      x[i] = sc.nextLong();
      v[i] = sc.nextLong();
      sum[i] = sum[i - 1] + v[i];
      dp1[i] = Math.max(dp1[i - 1], sum[i] - x[i]);
    }
    dp2[n] = Math.max(0, sum[n] - sum[n - 1] - (c - x[n])); 
    for(int i = n - 1; i >= 1; i--) {
      dp2[i] = Math.max(dp2[i + 1], sum[n] - sum[i - 1] - (c - x[i]));
    }
    long ans = Math.max(dp1[n], dp2[1]);
    for(int i = 1; i < n + 1; i++) {
      if(i < n) ans = Math.max(ans, sum[i] - 2 * x[i] + dp2[i + 1]);
      if(i > 1) ans = Math.max(ans, sum[n] - sum[i - 1] - 2 * (c - x[i]) + dp1[i - 1]);
    }
    System.out.println(ans);
  }
}

import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;

class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long c = Long.parseLong(input[1]);
        long forwardMax[] = new long[n+1];
        long backwardMax[] = new long[n+1];

        long positions[] = new long[n+1];
        long values[] = new long[n+1];

        positions[0] = 0;
        values[0] = 0;
        for(int i = 1; i <= n; i++){
            input = br.readLine().split(" ");
            positions[i] = Long.parseLong(input[0]);
            values[i] = Long.parseLong(input[1]);
        }

        long max = 0;
        long sum = 0;
        for(int i = 0; i <= n; i++){
            sum += values[i];
            max = Math.max(max, sum - positions[i]);
            forwardMax[i] = max;
        }

        max = 0;
        sum = 0;
        for(int i = n; i >= 0; i--){
            sum += values[i];
            max = Math.max(max, sum - (c - positions[i]) );
            backwardMax[i] = max;
        }

        long res = 0;

        for(int i = 0; i <= n; i++){
            // forward OA + OA + OB
            res = Math.max(res, forwardMax[i]);
            if(i != n)
                res = Math.max(res, forwardMax[i] - (positions[i]) + backwardMax[i+1]);

            // backward OA + OB + OB        
            res = Math.max(res , backwardMax[i]);
            if(i != 0) 
                res = Math.max(res , backwardMax[i] - (c - positions[i]) + forwardMax[i-1]);
        }

        System.out.println(res);
    }
}

import java.util.*;
public class Main {
    static long[] reverse(long a[]) { 
        final int n = a.length;
        long[] b = new long[n]; 
        int j = n; 
        for (int i = 0; i < n; i++) {
            b[j - 1] = a[i]; 
            j = j - 1; 
        }
        return b;
    } 
    static void shift(long a[], long val) { 
        final int n = a.length;
        for (int i = 1; i < n; i++) {
            a[i - 1] = a[i]; 
        }
        a[n-1] = val;
    } 
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long C = sc.nextLong();
        long[] X = new long[N+2]; X[0] = 0;
        long[] V = new long[N+1]; V[0] = 0;

        for (int n = 1; n <= N; n++) {
            X[n] = sc.nextLong(); 
            V[n] = sc.nextLong();
        }
        X[N+1] = C;
//時計回り
        long[] L = new long[N+1]; L[0] = 0;
        for (int n = 1; n <= N; n++) {
            L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
        }
        long[] R = new long[N+1]; R[0] = 0;
        for (int n = N-1; n >= 0; n--) {
            R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
        }
        long ans = Long.MAX_VALUE;
        for (int n = 0; n <= N; n++) {
            ans = Math.max(ans, L[n]);
            for (int m = n; m < N; m++) {
                long s = L[n] - X[n] + R[m];
                ans = Math.max(ans, s);
            }
        }
//反時計回り
        for (int n = 0; n < X.length; n++) {
            X[n] = C - X[n];
        }
        X = reverse(X);
        shift(V, 0); 
        V = reverse(V);
        L[0] = 0;
        for (int n = 1; n <= N; n++) {
            L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
        }
        R[N] = 0;
        for (int n = N-1; n >= 0; n--) {
            R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
        }
        for (int n = 0; n <= N; n++) {
            ans = Math.max(ans, L[n]);
            for (int m = n; m < N; m++) {
                long s = L[n] - X[n] + R[m];
                ans = Math.max(ans, s);
            }
        }
        System.out.println(ans);
        sc.close();
        }
}

