        ArrayList<Sushi> sushi = new ArrayList<Sushi>();
        for(int i = 0 ; i < n; i++){
            long d = sc.nextLong();
            long c = sc.nextLong();
            Sushi s = new Sushi(d,c);
            sushi.add(s);
        }
        long now = 0;
        long ans = 0;
        for(int i = 0; i < n; i++){
            Sushi s = sushi.get(i);
            now += s.cal;
            long tmp = now;
            for(int j = n-1; j > i; j--){
                Sushi s2 = sushi.get(j);
                tmp += s2.cal;
                ans = Math.max(ans,tmp-(circle - s2.dist)-s.dist*2);
            }
            ans = Math.max(ans,now-s.dist);
