/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author silviase
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DStaticSushi solver = new DStaticSushi();
        solver.solve(1, in, out);
        out.close();
    }

    static class DStaticSushi {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int n = in.nextInt();
            long c = in.nextLong();
            long[] x = new long[n];
            long[] v = new long[n];
            long[] f = new long[n];
            long[] fm = new long[n];
            long[] g = new long[n];
            long[] gm = new long[n];

            long max = 0;

            for (int i = 0; i < n; i++) {
                x[i] = in.nextLong();
                v[i] = in.nextLong();
            }

            for (int i = 0; i < n; i++) {
                if (i == 0) {
                    f[i] = v[i] - x[i];
                    fm[i] = f[i];
                } else {
                    f[i] = f[i - 1] + v[i] - x[i] + x[i - 1];
                    fm[i] = Math.max(fm[i - 1], f[i]);
                }
            }

            for (int i = n - 1; i >= 0; i--) {
                if (i == n - 1) {
                    g[i] = v[i] - c + x[i];
                    gm[i] = g[i];
                } else {
                    g[i] = g[i + 1] + v[i] - (x[i + 1] - x[i]);
                    gm[i] = Math.max(gm[i + 1], g[i]);
                }
            }

            max = Math.max(max, gm[0]);
            max = Math.max(max, fm[n - 1]);
            for (int i = 0; i < n - 1; i++) {
                long cmp = f[i] - x[i] + gm[i + 1];
                max = Math.max(max, cmp);
            }

            for (int i = 1; i < n; i++) {
                long cmp = g[i] - (c - x[i]) + fm[i - 1];
                max = Math.max(max, cmp);
            }

            out.println(max);


        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    int n;
    long c;
    long[] xs, vs;

    public static void main(String args[]) {
        new Main().run();
    }

    void run() {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        c = sc.nextLong();
        xs = new long[n + 2];
        vs = new long[n + 2];
        for (int i = 1; i <= n; i++) {
            xs[i] = sc.nextLong();
            vs[i] = sc.nextLong();
        }
        xs[n + 1] = c;
        solve();
    }

    void solve() {
        long[] vSumToI = new long[n + 1];
        long[] vSumToJ = new long[n + 2];
        long[] maxVSumForJ = new long[n + 1];
        int[] maxVSumForJIndex = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            vSumToI[i] = vSumToI[i - 1] + xs[i - 1] + vs[i] - xs[i];
        }
        vSumToJ[n] = vs[n] - c + xs[n];
        for (int i = n - 1; i >= 1; i--) {
            vSumToJ[i] = vSumToJ[i + 1] - xs[i + 1] + vs[i] + xs[i];
        }
        maxVSumForJ[0] = 0;
        int maxIndex = 0;
        for (int i = 1; i <= n; i++) {
            if (maxVSumForJ[i - 1] > vSumToI[i]) {
                maxVSumForJ[i] = maxVSumForJ[i - 1];
            } else {
                maxVSumForJ[i] = vSumToI[i];
                maxIndex = i;
            }
            maxVSumForJIndex[i] = maxIndex;
        }
        long maxCal = 0;
        for (int i = 1; i <= n + 1; i++) {
            long tempMaxCal = maxVSumForJ[i - 1] + vSumToJ[i];
            if (c - xs[i] < xs[maxVSumForJIndex[i - 1]]) {
                tempMaxCal -= c - xs[i];
            } else {
                tempMaxCal -= xs[maxVSumForJIndex[i - 1]];
            }
            maxCal = Math.max(maxCal, tempMaxCal);
        }
        System.out.println(maxCal);
    }

    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

