public class Main {
    static MyReader in = new MyReader();

    public static void main(String[] args){
        int n = in.i();
        long c = in.l();
        long[] x = new long[n + 2];
        int[] v = new int[n + 2];
        for (int i = 1; i <= n; i++) {
            x[i] = in.l();
            v[i] = in.i();
        }
        x[n + 1] = c;

        long f = 0;
        long[] g = new long[n + 1];
        long[] l = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            f += v[i] - (x[i] - x[i - 1]);
            if (g[i - 1] < f) {
                l[i] = x[i];
                g[i] = f;
            } else {
                l[i] = l[i - 1];
                g[i] = g[i - 1];
            }
        }
        long ans = 0;
        long t = 0;
        for (int i = n + 1; i > 0; i--) {
            long r = c - x[i];
            t += v[i];
            ans = Math.max(ans, t - r * 2 + g[i - 1]);
            ans = Math.max(ans, t - r - l[i - 1] + g[i - 1]);            
        }

        out.println(ans);
    }
