//                tmp_inv_cal += v[j];
                tmp_inv_cal = sumVInvClock[j];
                totalCal = tmp_clock_cal + tmp_inv_cal;
                totalCal -= ( x[i] + (C - x[j]));
                long tmp = x[i] < (C - x[j]) ? x[i] : (C - x[j]);
                totalCal -= tmp;
                if(totalCal > totalCalMax){
                    totalCalMax = totalCal;
                }
            }
        }
        System.out.println(totalCalMax);
