import java.util.*;
public class Main {
    static long[] reverse(long a[]) { 
        final int n = a.length;
        long[] b = new long[n]; 
        int j = n; 
        for (int i = 0; i < n; i++) {
            b[j - 1] = a[i]; 
            j = j - 1; 
        }
        return b;
    } 
    static void shift(long a[], long val) { 
        final int n = a.length;
        for (int i = 1; i < n; i++) {
            a[i - 1] = a[i]; 
        }
        a[n-1] = val;
    } 
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), C = sc.nextInt();
        long[] X = new long[N+2]; X[0] = 0;
        long[] V = new long[N+1]; V[0] = 0;

        for (int n = 1; n <= N; n++) {
            X[n] = sc.nextInt(); 
            V[n] = sc.nextInt();
        }
        X[N+1] = C;
//時計回り
        long[] L = new long[N+1]; L[0] = 0;
        for (int n = 1; n <= N; n++) {
            L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
        }
        long[] R = new long[N+1]; R[0] = 0;
        for (int n = N-1; n >= 0; n--) {
            R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
        }
        long ans = Long.MAX_VALUE;
        for (int n = 0; n <= N; n++) {
            ans = Math.max(ans, L[n]);
            for (int m = n; m < N; m++) {
                long s = L[n] - X[n] + R[m];
                ans = Math.max(ans, s);
            }
        }
//反時計回り
        for (int n = 0; n < X.length; n++) {
            X[n] = C - X[n];
        }
        X = reverse(X);
        shift(V, 0); 
        V = reverse(V);
        L[0] = 0;
        for (int n = 1; n <= N; n++) {
            L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
        }
        R[N] = 0;
        for (int n = N-1; n >= 0; n--) {
            R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
        }
        for (int n = 0; n <= N; n++) {
            ans = Math.max(ans, L[n]);
            for (int m = n; m < N; m++) {
                long s = L[n] - X[n] + R[m];
                ans = Math.max(ans, s);
            }
        }
        System.out.println(ans);
        sc.close();
        }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int n = ir.nextInt();
		long c = ir.nextLong();
		long[][] a = new long[n][];
		long[][] im = new long[n + 1][2];
		for (int i = 0; i < n; i++)
			a[i] = ir.nextLongArray(2);
		long ma = 0, tot = 0;
		for (int i = 0; i < n; i++) {
			tot += a[i][1];
			ma = Math.max(ma, tot - a[i][0]);
			im[i + 1][0] = Math.max(im[i][0], tot - a[i][0]);
		}
		tot = 0;
		for (int i = n - 1; i >= 0; i--) {
			tot += a[i][1];
			ma = Math.max(ma, tot - (c - a[i][0]));
			im[n - i][1] = Math.max(im[n - i - 1][1], tot - (c - a[i][0]));
		}
		for (int i = 0; i < n; i++) {
			ma = Math.max(ma, im[i + 1][0] - a[i][0] + im[n - i - 1][1]);
			ma = Math.max(ma, im[i + 1][1] - (c - a[n - 1 - i][0]) + im[n - i - 1][0]);
		}
		out.println(ma);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		if (debug)
			out.println(Arrays.deepToString(o));
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		long c = scanner.nextLong();
		long xs[] = new long[n+1];
		xs[0]=0;
		long vSum1[] = new long[n+1];
		long vSum2[] = new long[n+1];	//逆周り
		vSum1[0]=0;
		vSum2[0]=0;
		long e1[] = new long[n+1];
		long e2[] = new long[n+1];

		ArrayList<long[]> max1 = new ArrayList<>();
		ArrayList<long[]> max2 = new ArrayList<>();


		for (int i=1; i<=n; i++) {
			xs[i] = scanner.nextLong();
			vSum1[i] = scanner.nextInt() + vSum1[i-1];
			e1[i] = vSum1[i] - xs[i];
			if (max1.isEmpty() || e1[i] >= max1.get(max1.size()-1)[1]) {
				long[] tmp = {xs[i], e1[i]};
				max1.add(tmp);
			}
		}
		for (int i=n; i>=1; i--) {
			vSum2[i] = vSum1[n] - vSum1[i-1];
			e2[i] = vSum2[i] - (c-xs[i]);
			if (max2.isEmpty() || e2[i] >= max2.get(max2.size()-1)[1]) {
				long[] tmp = {xs[i], e2[i]};
				max2.add(tmp);
			}
		}


		long max = 0;
		int ind = max2.size()-1;
		big1:for (long[] data: max1) {
			while (max2.get(ind)[0] <= data[0]) {
				if (ind==0) {
					break big1;
				}
				ind--;
			}
			if (data[0] >= max2.get(ind)[1]) {
				max = Math.max(max, data[1]);
			}else {
				max = Math.max(max, data[1]-data[0]+max2.get(ind)[1]);
			}
		}
		ind = max1.size()-1;
		big2:for (long[] data: max2) {
			while (max1.get(ind)[0] >= data[0]) {
				if (ind==0) {
					break big2;
				}
				ind--;
			}
			if (c-data[0] >= max1.get(ind)[1]) {
				max = Math.max(max, data[1]);
			}else {
				max = Math.max(max, data[1]-(c-data[0])+max1.get(ind)[1]);
			}
		}

		System.out.println(max);
	}

}

import java.lang.Math;
import java.util.Scanner;
import java.util.Arrays;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt() + 1;
        long C = sc.nextLong();

        long costs[] = new long[N];   // x_i
        int values[] = new int[N];  // v_i
        costs[0] = 0;  // 初期位置
        values[0] = 0;

        for (int i = 1; i < N; i++) {
            costs[i] = sc.nextLong();
            values[i] = sc.nextInt();
        }

        long value_accum[] = new long[N];
        long value_accum_rev[] = new long[N];
        value_accum[0] = 0;  // 初期位置
        value_accum_rev[0] = 0;
        for (int i = 1; i < N; i++) {
            value_accum[i] = value_accum[i-1] + values[i];
            value_accum_rev[i] = value_accum_rev[i-1] + values[N-i];
        }
        // System.out.println(Arrays.toString(values));
        // System.out.println(Arrays.toString(value_accum));
        // System.out.println(Arrays.toString(value_accum_rev));

        // 時計回り側のコスパ
        long cw_cospa[] = new long[N];
        for (int i = 0; i < N; i++) {
            long cw_value = value_accum[i];
            long cw_cost = costs[i];
            cw_cospa[i] = cw_value - cw_cost;
        }

        // cw_cospa_bestpos[N] = 時計回り側の N までのコスパのなかで一番いいやつの位置
        int cw_cospa_bestpos[] = new int[N];
        cw_cospa_bestpos[0] = 0;
        for (int i = 1; i < N; i++) {
            if (cw_cospa[i] > cw_cospa[cw_cospa_bestpos[i-1]]) {
                cw_cospa_bestpos[i] = i;
            }
            else {
                cw_cospa_bestpos[i] = cw_cospa_bestpos[i-1];
            }
        }
        // System.out.println(Arrays.toString(cw_cospa_bestpos));

        long score_max = 0;
        for (int i = 0; i < N; i++) {
            // System.out.println("cw, ccw = " + (N-1-i) + ", " + i);

            // 反時計回り側のコスパ
            long ccw_value = value_accum_rev[i];
            long ccw_cost = (i == 0) ? i : (C - costs[N-i]);

            long score_cw  = cw_cospa[cw_cospa_bestpos[N-1-i]] - costs[cw_cospa_bestpos[N-1-i]] + ccw_value - ccw_cost;
            // System.out.println("score_cw = " + score_cw);
            long score_ccw = cw_cospa[cw_cospa_bestpos[N-1-i]] + (ccw_value - ccw_cost * 2);
            // System.out.println("score_ccw = " + score_ccw);
            score_max = Math.max(score_max, score_cw);
            score_max = Math.max(score_max, score_ccw);
        }

        System.out.println(score_max);
    }
}

