int num;
long c;
long x[][];
long dp[][][];
boolean visited[][][];

long cal(int i, int j, int k) {
	i = (i + num) % num;
	j = (j + num) % num;
	if(i == j || visited[i][j][k]) return dp[i][j][k];
	visited[i][j][k] = true;
	if(k == 0) {
		if(i != 0 && i < j) return - INF;
		dp[i][j][k] = max(dp[i][j][k], cal(i + 1, j, k));
		if(j > 0) dp[i][j][k] = max(dp[i][j][k], cal(i, j - 1, k) - dist(j - 1, j, k) + x[j - 1][1]);
		if(j > 0) dp[i][j][k] = max(dp[i][j][k], cal(j - 1, i, k ^ 1) - dist(i, j, k) + x[j - 1][1]);
	}else {
		if(i != 0 && i > j) return - INF;
		dp[i][j][k] = max(dp[i][j][k], cal(i - 1, j, k));
		if(j > 0) dp[i][j][k] = max(dp[i][j][k], cal(i, j + 1, k) - dist(j + 1, j, k) + x[j - 1][1]);
		if(j > 0) dp[i][j][k] = max(dp[i][j][k], cal(j + 1, i, k ^ 1) - dist(i, j, k) + x[j - 1][1]);
	}
	return dp[i][j][k];
}

long dist(int i, int j, int k) {
	i = (i + num) % num;
	j = (j + num) % num;
	long di = i == 0 ? 0 : x[i - 1][0];
	long dj = j == 0 ? 0 : x[j - 1][0];
	return k == 0 ? (dj - di + c) % c : (di - dj + c) % c;
}


