    long asum = 0;
    for (int i = 1; i <= n; i++) {
      asum += v[i];
      a[i] = Math.max(a[i - 1], asum - x[i]);
      aa[i] = Math.max(aa[i - 1], asum - x[i] * 2);
    }
    long[] b = new long[n + 1];
    long[] bb = new long[n + 1];
