      bb[i] = Math.max(bb[i - 1], bsum - (c - x[i]) * 2);
    }
    long res = 0;
    for (int i = n; i > 0; i--) {
      res = Math.max(res, Math.max(a[i - 1] + bb[i], aa[i - 1] + b[i]));
