import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static int N;
	public static long C;
	public static long[] positions, values;
	public static boolean[][][] visited = new boolean[102][102][2];

	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(f.readLine());
		N = Integer.parseInt(st.nextToken());
		C = Long.parseLong(st.nextToken());
		positions = new long[N + 1];
		values = new long[N + 1];
		positions[0] = 0;
		values[0] = 0;
		for (int i = 0; i < N; i++) {
			st = new StringTokenizer(f.readLine());
			long x = Long.parseLong(st.nextToken());
			long v = Long.parseLong(st.nextToken());
			positions[i + 1] = x;
			values[i + 1] = v;
		}
		long res = Math.max(dfs(N, 0, 1, distance(N, 0), 0) - distance(N, 0),
				dfs(0, 1, 0, distance(0, 1), 0) - distance(0, 1));
		res = Math.max(res, 0);
		System.out.println(res);
	}

	public static long dfs(int left, int right, int isLeft, long lastDistance, int depth) {
		// System.out.println(left + " " + right + " " + isLeft + " " + depth);
		if (left == -1) {
			return dfs(N, right, isLeft, lastDistance, depth);
		}
		if (right == N + 1) {
			return dfs(left, 0, isLeft, lastDistance, depth);
		}
		if (left == right) {
			return lastDistance;
		}
		if (visited[left][right][isLeft]) {
			return 0;
		}
		visited[left][right][isLeft] = true;
		if (isLeft == 1) {
			return values[left] + Math.max(0,
					Math.max(dfs(left - 1, right, 1, distance(left - 1, left), depth + 1) - distance(left - 1, left),
							dfs(left, right + 1, 0, distance(right + 1, left), depth + 1) - distance(right + 1, left)));
		} else {
			return values[right] + Math.max(0,
					Math.max(
							dfs(left, right + 1, 0, distance(right + 1, right), depth + 1) - distance(right + 1, right),
							dfs(left - 1, right, 1, distance(left - 1, right), depth + 1) - distance(left - 1, right)));
		}
	}

	public static long distance(int i, int j) {
		if (i == -1) {
			i = N;
		}
		if (j == -1) {
			j = N;
		}
		if (i == N + 1) {
			i = 0;
		}
		if (j == N + 1) {
			j = 0;
		}
		long max = Math.max(positions[i], positions[j]);
		long min = Math.min(positions[i], positions[j]);
		return Math.min(max - min, C - max + min);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    private static final BufferedReader input = new BufferedReader(new InputStreamReader(System.in));

    public static void main(String[] args) {
        String str = readLineStandardInput();
        String[] mem = str.split(" ");
        int N = Integer.parseInt(mem[0]);
        long C = Long.parseLong(mem[1]);
        String[] strs = readLinesStandardInput(N);
        long[] x = new long[N];
        int[] v = new int[N];
        boolean[] isSetSushi = new boolean[N];
        for(int i = 0; i < x.length; i++){
            String[] mems = strs[i].split(" ");
            x[i] = Long.parseLong(mems[0]);
            v[i] = Integer.parseInt(mems[1]);
            isSetSushi[i] = true;
        }

        long totalCalTmp = 0;
        long clockMax = 0;
        long invClockMax = 0;
        long[] clockVList = new long[N];
        long[] clockVRTList = new long[N];
        long[] invClockVList = new long[N];
        long[] invClockVRTList = new long[N];
        /* calc clock max */
        for(int i = 0; i < x.length; i++){
            totalCalTmp += v[i];
            long totalCal = totalCalTmp - x[i];
            clockVList[i] = totalCal;
            if(totalCal > clockMax){
                clockMax = totalCal;
            }
            long tmp = totalCal - x[i];
            clockVRTList[i] = tmp;
        }
        /* calc inv clock max */
        totalCalTmp = 0;
        for(int i = x.length - 1; i >= 0; i--){
            totalCalTmp += v[i];
            long totalCal = totalCalTmp - C + x[i];
            invClockVList[i] = totalCal;
            if(totalCal > invClockMax) {
                invClockMax = totalCal;
            }
            long tmp = totalCal - (C - x[i]);
            invClockVRTList[i] = tmp;
        }
        /* calc clock and inv clock max */
        long maxValue;
        if(clockMax > invClockMax){
            maxValue = clockMax;
        }
        else{
            maxValue = invClockMax;
        }
        long maxTmp = -1;
        long invMaxTmp = -1;
        for(int i = 0; i < N; i++){
            if(maxTmp > clockVList[i]){
                continue;
            }
            maxTmp = clockVList[i];
            for(int j = i + 1; j < N; j++){
                if(invMaxTmp > invClockVRTList[j]){
                    continue;
                }
                invMaxTmp = invClockVRTList[j];
                long tmp = maxTmp + invMaxTmp;
                if(tmp > maxValue){
                    maxValue = tmp;
                }
            }
        }
        maxTmp = -1; invMaxTmp = -1;
        for(int i = 0; i < N; i++){
            if(maxTmp > clockVRTList[i]){
                continue;
            }
            maxTmp = clockVRTList[i];
            for(int j = i + 1; j < N; j++){
                if(invMaxTmp > invClockVList[j]){
                    continue;
                }
                invMaxTmp = invClockVList[j];
                long tmp = maxTmp + invMaxTmp;
                if(tmp > maxValue){
                    maxValue = tmp;
                }
            }
        }
        System.out.println(maxValue);
    }

    private static String readLineStandardInput() {
        String str;
        try {
            str = input.readLine();
        } catch(IOException e){
            str = null;
            System.out.println(e);
        }
        return str;
    }

    private static String[] readLinesStandardInput(int lineNum) {
        String[] str = new String[lineNum];
        try {
            for(int i = 0; i < lineNum; i++)
                str[i] = input.readLine();
        } catch(IOException e){
            str = null;
            System.out.println(e);
        }
        return str;
    }
}

import java.util.Scanner;

class Main{
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int N=sc.nextInt();
		long C=sc.nextLong();
		long[][] sushi=new long[N][2];
		long[][] migi=new long[N][2];
		long[][] hidari=new long[N][2];

		long max_cal=0;
		for(int i=0; i<N; i++) {
			sushi[i][0]=sc.nextLong();
			sushi[i][1]=sc.nextLong();
		}
		//右回り

		migi[0][0]=sushi[0][0];
		migi[0][1]=sushi[0][1];
		for(int i=1; i<N; i++) {
			migi[i][0]=sushi[i][0];
			migi[i][1]=migi[i-1][1]+sushi[i][1];	//累積和
		}
		//スタート地点よりも左側に行かない時
		for(int i=0; i<N; i++) {
			migi[i][1]-=migi[i][0];		//１回分のキョリを引く
			if(migi[i][1]>=0) {
				max_cal=Math.max(max_cal, migi[i][1]);
			}
		}

		//左のとある地点まで行く場合
		hidari[0][0]=C-sushi[N-1][0];
		hidari[0][1]=sushi[N-1][1];
		for(int i=1; i<N; i++) {
			hidari[i][0]=C-sushi[N-1-i][0];		//逆周りなので一番最初にxN
			hidari[i][1]=hidari[i][1]+sushi[N-1-i][1];
		}

		long[][] gyaku=new long[N][2];		//左のどこまで行くのが最善化をもとめる 0得られるカロリー  1得られる地点(ダブリングを防ぐ為)
		if(hidari[0][1]-hidari[0][0]>0) {
			gyaku[0][0]=hidari[0][1]-hidari[0][0];
			hidari[0][1]=0;
		}
		else {
			gyaku[0][0]=0;
			hidari[0][1]=-1;	//行くな
		}
		for(int i=1; i<N; i++) {
			if(hidari[i][1]-hidari[i][0]>gyaku[i-1][0]) {		//ここがある意味DPテーブルみたいな感じ
				gyaku[i][0]=hidari[i][1]-hidari[i][0];
				gyaku[i][1]=i;
			}
