import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int n = ir.nextInt();
		long c = ir.nextLong();
		long[][] a = new long[n][];
		long[][] im = new long[n + 1][2];
		for (int i = 0; i < n; i++)
			a[i] = ir.nextLongArray(2);
		long ma = 0, tot = 0;
		for (int i = 0; i < n; i++) {
			tot += a[i][1];
			ma = Math.max(ma, tot - a[i][0]);
			im[i + 1][0] = Math.max(im[i][0], tot - a[i][0]);
		}
		tot = 0;
		for (int i = n - 1; i >= 0; i--) {
			tot += a[i][1];
			ma = Math.max(ma, tot - (c - a[i][0]));
			im[n - i][1] = Math.max(im[n - i - 1][1], tot - (c - a[i][0]));
		}
		for (int i = 0; i < n; i++) {
			ma = Math.max(ma, im[i + 1][0] - a[i][0] + im[n - i - 1][1]);
			ma = Math.max(ma, im[i + 1][1] - a[n - 1 - i][0] + im[n - i - 1][0]);
		}
		out.println(ma);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

