    public static void main(String[] args){
        int n = in.i();
        long c = in.l();
        long[] x = new long[n + 2];
        int[] v = new int[n + 2];
        for (int i = 1; i <= n; i++) {
            x[i] = in.l();
            v[i] = in.i();
        }
        x[n + 1] = c;

        long sum = 0;
        long[] f = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            sum += v[i] - (x[i] - x[i - 1]);
            f[i] = max(sum, f[i - 1]);
        }
        sum = 0;
        long[] g = new long[n + 2];
        for (int i = n; i > 0; i--) {
            sum += v[i] - (x[i + 1] - x[i]);
            g[i] = max(sum, g[i + 1]);
        }

        sum = 0;
        long ans = 0;
        for (int i = n + 1; i > 0; i--) {
            long xb = c - x[i];
            sum += v[i];
            ans = max(ans, sum - xb * 2 + f[i - 1]);
        }
        sum = 0;
        for (int i = 0; i <= n; i++) {
            long xa = x[i];
            sum += v[i];
            ans = max(ans, sum - xa * 2 + g[i + 1]);
        }
        out.println(ans);
    }

