class Main{
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int N=sc.nextInt();
		long C=sc.nextLong();
		long[][] sushi=new long[N][2];
		long[][] migi=new long[N][2];
		long[][] hidari=new long[N][2];

		long max_cal=0;
		for(int i=0; i<N; i++) {
			sushi[i][0]=sc.nextLong();
			sushi[i][1]=sc.nextLong();
		}
		//右回り

		migi[0][0]=sushi[0][0];
		migi[0][1]=sushi[0][1];
		for(int i=1; i<N; i++) {
			migi[i][0]=sushi[i][0];
			migi[i][1]=migi[i-1][1]+sushi[i][1];	//累積和
		}
		//スタート地点よりも左側に行かない時
		for(int i=0; i<N; i++) {
			migi[i][1]-=migi[i][0];		//１回分のキョリを引く
			if(migi[i][1]>=0) {
				max_cal=Math.max(max_cal, migi[i][1]);
			}
		}

		//左のとある地点まで行く場合
		hidari[0][0]=C-sushi[N-1][0];
		hidari[0][1]=sushi[N-1][1];
		for(int i=1; i<N; i++) {
			hidari[i][0]=C-sushi[N-1-i][0];		//逆周りなので一番最初にxN
			hidari[i][1]=hidari[i][1]+sushi[N-1-i][1];
		}

		long[][] gyaku=new long[N][2];		//左のどこまで行くのが最善化をもとめる 0得られるカロリー  1得られる地点(ダブリングを防ぐ為)
		if(hidari[0][1]-hidari[0][0]>0) {
			gyaku[0][0]=hidari[0][1]-hidari[0][0];
			hidari[0][1]=0;
		}
		else {
			gyaku[0][0]=0;
			hidari[0][1]=-1;	//行くな
		}
		for(int i=1; i<N; i++) {
			if(hidari[i][1]-hidari[i][0]>gyaku[i-1][0]) {		//ここがある意味DPテーブルみたいな感じ
				gyaku[i][0]=hidari[i][1]-hidari[i][0];
				gyaku[i][1]=i;
			}
			else {
				gyaku[i][0]=gyaku[i-1][0];		//今までよりも先に行った結果損したなら行かないほうが得
				gyaku[i][1]=gyaku[i-1][1];
			}
		}

		for(int i=0; i<N-1; i++) {		//右側の行く地点を固定して、左側に最大利益で行けるとこまで行く。		N-1まで（実質N-2）なのは、N-1まで右回りで行ったら左に向かっていない（向かうと無駄）なので
			migi[i][1]-=migi[i][0];		//右にいく　そして　左へ向かう時の2回目の分を引く
			long tmp=migi[i][1]+gyaku[N-2-i][0];
			max_cal=Math.max(tmp,max_cal);
		}
		//右回り終了

		//左回り
				hidari[0][0]=C-sushi[N-1][0];
				hidari[0][1]=sushi[N-1][1];
				for(int i=1; i<N; i++) {
					hidari[i][0]=C-sushi[N-1-i][0];
					hidari[i][1]=hidari[i-1][1]+sushi[N-1-i][1];	//累積和
				}
				//スタート地点よりも右側に行かない時
				for(int i=0; i<N; i++) {
					hidari[i][1]-=hidari[i][0];		//１回分のキョリを引く
					if(hidari[i][1]>=0) {
						max_cal=Math.max(max_cal, hidari[i][1]);
					}
				}

				//右のとある地点まで行く場合
				migi[0][0]=sushi[0][0];
				migi[0][1]=sushi[0][1];
				for(int i=1; i<N; i++) {
					migi[i][0]=sushi[i][0];		//逆周りなので一番最初にx1
					migi[i][1]=migi[i][1]+sushi[i][1];
				}

				//long[][] gyaku=new long[N][2];		//右のどこまで行くのが最善化をもとめる 0得られるカロリー  1得られる地点(ダブリングを防ぐ為)
				if(migi[0][1]-migi[0][0]>0) {
					gyaku[0][0]=migi[0][1]-migi[0][0];
					migi[0][1]=0;
				}
				else {
					gyaku[0][0]=0;
					migi[0][1]=-1;	//行くな
				}
				for(int i=1; i<N; i++) {
					if(migi[i][1]-migi[i][0]>gyaku[i-1][0]) {		//ここがある意味DPテーブルみたいな感じ
						gyaku[i][0]=migi[i][1]-migi[i][0];
						gyaku[i][1]=i;
					}
					else {
						gyaku[i][0]=gyaku[i-1][0];		//今までよりも先に行った結果損したなら行かないほうが得
						gyaku[i][1]=gyaku[i-1][1];
					}
				}

				for(int i=0; i<N-1; i++) {		//左側の行く地点を固定して、左側に最大利益で行けるとこまで行く。		N-1まで（実質N-2）なのは、N-1まで左回りで行ったら右に向かっていない（向かうと無駄）なので
					hidari[i][1]-=hidari[i][0];		//左にいく　そして　右へ向かう時の2回目の分を引く
					long tmp=hidari[i][1]+gyaku[N-2-i][0];
					max_cal=Math.max(tmp,max_cal);
				}

				//左回り終了

		System.out.println(max_cal);

	}
}

import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        long c=fsc.nextLong();
        long[][] xv=new long[n+1][2];
        for(int i=1;i<=n;i++){
            long x=fsc.nextLong();
            long v=fsc.nextLong();
            xv[i][0]=x;
            xv[i][1]=v;
        }
        fsc.close();
        long[] accumV=new long[n+1];
        for(int i=1;i<=n;i++){
            accumV[i]=accumV[i-1]+xv[i][1];
        }
        long max=Long.MIN_VALUE;
        long[] counterClockMax=new long[n+2];
        long[] clockMax=new long[n+2];
        for(int i=1;i<=n;i++){
            counterClockMax[i]=Math.max(accumV[i]-xv[i][0], counterClockMax[i-1]);
            clockMax[n-i+1]=Math.max((accumV[n]-accumV[n-i])-(c-xv[n-i+1][0]), clockMax[n-i+2]);
            max=Math.max(max, counterClockMax[i]);
            max=Math.max(max, clockMax[n-i+1]);
        }
        long[] rightLeft=new long[n+1];
        long[] leftRight=new long[n+1];
        for(int i=1;i<=n;i++){
            rightLeft[i]=accumV[i]-2*xv[i][0]+clockMax[i+1];
            leftRight[n-i+1]=(accumV[n]-accumV[n-i])-2*(c-xv[n-i+1][0])+counterClockMax[n-i];
            max=Math.max(max, rightLeft[i]);
            max=Math.max(max, leftRight[n-i+1]);
        }

        System.out.println(max);
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;

class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long c = Long.parseLong(input[1]);
        long forwardMax[] = new long[n+1];
        long backwardMax[] = new long[n+1];

        long positions[] = new long[n+1];
        long values[] = new long[n+1];

        positions[0] = 0;
        values[0] = 0;
        for(int i = 1; i <= n; i++){
            input = br.readLine().split(" ");
            positions[i] = Long.parseLong(input[0]);
            values[i] = Long.parseLong(input[1]);
        }

        long max = 0;
        long sum = 0;
        for(int i = 0; i <= n; i++){
            sum += values[i];
            max = Math.max(max, sum - positions[i]);
            forwardMax[i] = max;
        }

        max = 0;
        sum = 0;
        for(int i = n; i >= 0; i--){
            sum += values[i];
            max = Math.max(max, sum - (c - positions[i]) );
            backwardMax[i] = max;
        }

        long res = 0;
        // backward OA + OB + OB
        for(int i = n; i >= 0; i--){
            res = Math.max(res , backwardMax[i]);
            if(i != 0) 
                res = Math.max(res , backwardMax[i] - (c - positions[i]) + forwardMax[i-1]);
        }

        // forward OA + OA + OB
        for(int i = 0; i <= n; i++){
            res = Math.max(res, forwardMax[i]);
            if(i != n)
                res = Math.max(res, forwardMax[i] - (positions[i]) + backwardMax[i+1]);
        }

        System.out.println(res);
    }
}

import java.util.*;
import static java.lang.Math.*;
