public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		// 入力
		int n = sc.nextInt();
		long c = sc.nextLong();
		long[][] xv = new long[n][2];
		for(int i = 0; i < n; i++){
		    xv[i][0] = sc.nextLong();
		    xv[i][1] = sc.nextLong();
		}

		// 計算
		long result = 0;
		long[] cal = new long[n+1];
		for(int i = 0; i < n; i++){
		    if(i > 0){
		        cal[i+1] = cal[i] + xv[i][1] - (xv[i][0] - xv[i-1][0]); 
		    }else{
		        cal[i+1] = cal[i] + xv[i][1] - xv[i][0];
		    }
		}
		long[] rev = new long[n+1];
		for(int i = 0; i < n; i++){
		    if(i > 0){
		        rev[i+1] = rev[i] + xv[n-1-i][1] - (xv[n-i][0] - xv[n-1-i][0]); 
		    }else{
		        rev[i+1] = rev[i] + xv[n-1-i][1] - (c - xv[n-1-i][0]);
		    }
		}
		long[] cal_return = new long[n+1];
		for(int i = 0; i < n; i++){
		    if(i > 0){
		        cal_return[i+1] = cal_return[i] + xv[i][1] - 2*(xv[i][0] - xv[i-1][0]); 
		    }else{
		        cal_return[i+1] = cal_return[i] + xv[i][1] - 2*xv[i][0];
		    }
		}
		long[] rev_return = new long[n+1];
		for(int i = 0; i < n; i++){
		    if(i > 0){
		        rev_return[i+1] = rev_return[i] + xv[n-1-i][1] - 2*(xv[n-i][0] - xv[n-1-i][0]); 
		    }else{
		        rev_return[i+1] = rev_return[i] + xv[n-1-i][1] - 2*(c - xv[n-1-i][0]);
		    }
		}

		for(int i = 0; i < n; i++){
		    long[] array1 = Arrays.copyOf(rev, n+1-i);
		    Arrays.sort(array1);
		    result = max(result, cal_return[i] + max(0, array1[n-i]));
		    long[] array2 = Arrays.copyOf(cal, n+1-i);
		    Arrays.sort(array2);
		    result = max(result, rev_return[i] + max(0, array2[n-i]));
		}

		// 出力
		System.out.println(result);
	}
}

import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long c = Long.parseLong(input[1]);
        long pos[] = new long[n + 1];
        long val[] = new long[n + 1];
        long max[] = new long[n + 1];
        long maxPos[] = new long[n + 1];
        long premax[] = new long[n + 1];

        long befMax = 0;
        int befPos = 0;
        for(int i = 1; i <= n; i++){
            input = br.readLine().split(" ");
            pos[i] = Long.parseLong(input[0]);
            val[i] = Long.parseLong(input[1]);
            premax[i] = premax[i-1] - pos[i] + pos[i-1] + val[i];
            if(befMax < premax[i]){
                max[i] = premax[i];
                befMax = max[i];
                befPos = i;
                maxPos[i] = pos[i];
            }else{
                max[i] = befMax;
                maxPos[i] = pos[befPos];
            }
        }

        long result = max[n];
        long beforeAcc = 0;
        long dist;
        for(int i = n; i >= 1; i--){
            if(i != n){
                dist = (pos[i] - pos[i+1]);
            }else{
                dist = (pos[i] - c);
            }
            beforeAcc += dist + val[i];

            //maxPos[i-1] と c-pos[i]のうち小さいほうをスコアから引く
            result = Math.max(result, beforeAcc + max[i-1] - Math.min(maxPos[i-1], c-pos[i]));
        }

        System.out.println(result);
    }
}

