	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			long c = in.nextLong();
			long[] d1 = new long[n+2];
			long[] d2 = new long[n+2];
			long[] v = new long[n+2];
			long[] sum1 = new long[n+2];
			long[] sum2 = new long[n+2];

			d1[0] = 0; d1[n+1] = c;
			d2[0] = c; d2[n+1] = 0;

			for (int i = 1; i <= n; i++) {
				long tx = in.nextLong();
				long tv = in.nextLong();
				d1[i] = tx;
				d2[i] = c - tx;
				v[i] = tv;
			}

			for (int i = 0; i < n+1; i++) {
				sum1[i+1] = sum1[i] + v[i+1];
			}
			for (int i = n+1; i > 0; i--) {
				sum2[i-1] = sum2[i] + v[i-1];
			}

			long ans = 0;
			for (int x = 0; x < n + 2; x++) {
				for (int y = n + 1; y > x; y--) {
					long tmp = 0;
					tmp += (sum1[x]+sum2[y]-d1[x]-d2[y]);
					tmp -= Math.min(d1[x], d2[y]);
					ans = Math.max(ans, tmp);
				}
			}

			System.out.println(ans);
		}
	}

