//            	prn("3  ans = " + ans + " <-- lmax[" + i + "](" + lmax[i] 
//            			+ ") - X[" + i + "](" + X[i] + ") + rmax[" + (i+1) + "](" + rmax[i+1] + "}");
        		ans = Math.max(ans, rmax[i+1] - (C - X[i+1]) + lmax[i]);
