        max_index[N]=N;
        max_index[N-1]=N-1;
        for (int i=N+1;i<2*N;i++) {
            if (profit[max_index[i-1]]<profit[i]) {
                max_index[i]=i;
            } else {
                max_index[i]=max_index[i-1];
            }
        }
        for (int i=N-2;i>=0;i--) {
            if (profit[max_index[i+1]]<profit[i]) {
                max_index[i]=i;
            } else {
                max_index[i]=max_index[i+1];
            }
        }

        long ans=0L;
        ans = Math.max(ans, profit[2*N-1]);
        ans = Math.max(ans, profit[0]);
        for (int i=N;i<2*N-1;i++) {
            long tmp = profit[i];
            ans = Math.max(ans, tmp);
            ans = Math.max(ans, tmp+profit[max_index[i-N+1]]-(x[i]-C));
        }
        for (int i=N-1;i>0;i--) {
            long tmp = profit[i];
            ans = Math.max(ans, tmp);
            ans = Math.max(ans, tmp+profit[max_index[i+N-1]]-(C-x[i]));
        }
        System.out.println(ans);
    }
}

import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * https://atcoder.jp/contests/abc095/submissions/11235537 を参考に実装
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			long c = scanner.nextLong();
			long[] x = new long[n + 1], v = new long[n + 1];
			x[0] = v[0] = 0L;
			long[] sumV = new long[n + 1];
			sumV[0] = 0L;
			IntStream.rangeClosed(1, n).forEach(i -> {
				x[i] = scanner.nextLong();
				v[i] = scanner.nextLong();
				sumV[i] = sumV[i - 1] + v[i];
			});
			long[] left = new long[n + 1], leftBack = new long[n + 1];
			left[0] = leftBack[0] = 0L;
			IntStream.rangeClosed(1, n).forEach(i -> {
				left[i] = Math.max(left[i - 1], sumV[i] - x[i]);
				leftBack[i] = Math.max(leftBack[i - 1], sumV[i] - x[i] * 2);
			});
			long[] right = new long[n + 1], rightBack = new long[n + 1];
			right[0] = rightBack[0] = 0L;
			IntStream.rangeClosed(1, n).forEach(i -> {
				right[i] = Math.max(right[i - 1], (sumV[n] - sumV[n - i]) - (c - x[n + 1 - i]));
				rightBack[i] = Math.max(rightBack[i - 1], (sumV[n] - sumV[n - i]) - (c - x[n + 1 - i]) * 2);
			});
			System.out.println(IntStream.rangeClosed(0, n)
					.mapToLong(i -> Math.max(left[i] + rightBack[n - i], leftBack[i] + right[n - i])).max()
					.getAsLong());
		}
	}
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {
    static long[] dists;
    static long[] values;
    static long c;
    static Long sum = 0L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        c = sc.nextLong();

        dists = new long[n];
        values = new long[n];

        for (int i = 0; i < n; i++) {
            dists[i] = sc.nextLong();
            values[i] = sc.nextLong();
        }

        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            queue.add(i);
        }

        System.out.print(search(queue, -1, 0L));
    }

    private static long search(LinkedList<Integer> queue, int currentIndex, Long sum) {
        LinkedList<Integer> queue1 = new LinkedList<>(queue);
        LinkedList<Integer> queue2 = new LinkedList<>(queue);

        Integer nextForward = queue1.poll();
        Integer nextBackForward = queue2.pollLast();
        if (nextForward == null || nextBackForward == null) {
            return sum;
        }

        Long currentDist = (currentIndex != -1) ? dists[currentIndex] : 0L;

        Long value1 = values[nextForward] - Math.abs(dists[nextForward] - currentDist);
        Long sum1 = Math.max(search(queue1, nextForward, sum + value1), sum);

        Long value2 = values[nextBackForward] - (currentDist + (c - dists[nextBackForward]));
        Long sum2 = Math.max(search(queue2, nextBackForward, sum + value2), sum);

        return Math.max(sum1, sum2);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static int N;
	public static long C;
	public static long[] positions, values, prefixes, suffixes, maxs1, maxs2;

	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(f.readLine());
		N = Integer.parseInt(st.nextToken());
		C = Long.parseLong(st.nextToken());
		positions = new long[N + 1];
		values = new long[N + 1];
		prefixes = new long[N + 1];
		suffixes = new long[N + 1];
		maxs1 = new long[N + 1];
		maxs2 = new long[N + 1];
		positions[0] = 0;
		values[0] = 0;
		for (int i = 0; i < N; i++) {
			st = new StringTokenizer(f.readLine());
			long x = Long.parseLong(st.nextToken());
			long v = Long.parseLong(st.nextToken());
			positions[i + 1] = x;
			values[i + 1] = v;
		}
		for (int i = 1; i <= N; i++) {
			prefixes[i] = prefixes[i - 1] + values[i];
		}
		suffixes[N] = values[N];
		for (int i = N - 1; i >= 0; i--) {
			suffixes[i] = suffixes[i + 1] + values[i];
		}
		long max = 0;
		for (int i = N; i > 0; i--) {
			max = Math.max(max, suffixes[i] - (C - positions[i]));
			maxs1[i] = max;
		}
		max = 0;
		for (int i = 0; i <= N; i++) {
			max = Math.max(max, prefixes[i] - positions[i]);
			maxs2[i] = max;
		}
		long res = 0;
		for (int i = 0; i <= N; i++) {
			res = Math.max(res, prefixes[i] - positions[i]);
			res = Math.max(res, suffixes[i] - (C - positions[i]));
			if (i != N)
				res = Math.max(res, prefixes[i] + maxs1[i + 1] - 2 * positions[i]);
			if (i != 0)
				res = Math.max(res, suffixes[i] + maxs2[i - 1] - 2 * (C - positions[i]));
		}
		System.out.println(res);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    private static final BufferedReader input = new BufferedReader(new InputStreamReader(System.in));

    public static void main(String[] args) {
        String str = readLineStandardInput();
        String[] mem = str.split(" ");
        int N = Integer.parseInt(mem[0]);
        long C = Long.parseLong(mem[1]);
        String[] strs = readLinesStandardInput(N);
        long[] x = new long[N];
        int[] v = new int[N];
        boolean[] isSetSushi = new boolean[N];
        for(int i = 0; i < x.length; i++){
            String[] mems = strs[i].split(" ");
            x[i] = Long.parseLong(mems[0]);
            v[i] = Integer.parseInt(mems[1]);
            isSetSushi[i] = true;
        }

        long totalCalTmp = 0;
        long clockMax = 0;
        long invClockMax = 0;
        long[] clockVList = new long[N];
        long[] clockVRTList = new long[N];
        long[] invClockVList = new long[N];
        long[] invClockVRTList = new long[N];
        /* calc clock max */
        for(int i = 0; i < x.length; i++){
            totalCalTmp += v[i];
            long totalCal = totalCalTmp - x[i];
            clockVList[i] = totalCal;
            if(totalCal > clockMax){
                clockMax = totalCal;
            }
            long tmp = totalCal - x[i];
            clockVRTList[i] = tmp;
        }
        /* calc inv clock max */
        totalCalTmp = 0;
        for(int i = x.length - 1; i >= 0; i--){
            totalCalTmp += v[i];
            long totalCal = totalCalTmp - C + x[i];
            invClockVList[i] = totalCal;
            if(totalCal > invClockMax) {
                invClockMax = totalCal;
            }
            long tmp = totalCal - (C - x[i]);
            invClockVRTList[i] = tmp;
        }
        /* calc clock and inv clock max */
        long maxValue;
        if(clockMax > invClockMax){
            maxValue = clockMax;
        }
        else{
            maxValue = invClockMax;
        }
        if(maxValue <= 0){
            System.out.println(0);
            return;
        }
        long maxTmp = -1; long invMaxTmp = -1;
        for(int i = 0; i < N; i++){
            if(clockVList[i] > 0) {
                maxTmp = clockVList[i];
                for (int j = i + 1; j < N; j++) {
                    if (invClockVRTList[j] > 0) {
                        invMaxTmp = invClockVRTList[j];
                        long tmp = maxTmp + invMaxTmp;
                        if (tmp > maxValue) {
                            maxValue = tmp;
                        }
                    }
                }
            }
        }

        for(int i = N - 1; i >= 0; i--){
            if(invClockVList[i] > 0) {
                maxTmp = invClockVList[i];
                for (int j = i - 1; j >= 0; j--) {
                    if (clockVRTList[j] > 0) {
                        invMaxTmp = clockVRTList[j];
                        long tmp = maxTmp + invMaxTmp;
                        if (tmp > maxValue) {
                            maxValue = tmp;
                        }
                    }
                }
            }
        }
        System.out.println(maxValue);
    }

    private static String readLineStandardInput() {
        String str;
        try {
            str = input.readLine();
        } catch(IOException e){
            str = null;
            System.out.println(e);
        }
        return str;
    }

    private static String[] readLinesStandardInput(int lineNum) {
        String[] str = new String[lineNum];
        try {
            for(int i = 0; i < lineNum; i++)
                str[i] = input.readLine();
        } catch(IOException e){
            str = null;
            System.out.println(e);
        }
        return str;
    }
}

