				break;
			}
			if(right) {
				long i = now +1;
				while(i !=best) {
					kal+=v[(int)i];
					now = best;
					i++;
				}
			}else {
				long i = now -1;
				if(i==-1) {
					i = N;
				}
				while(i!=best) {
					kal+=v[(int)i];
					now = best;
					i--;
					if(i==-1) {
						i =N;
					}
				}
			}

		}
		sc.close();
	}
}

