            v[i] = in.nextLong();
        }
        long[] sum = new long[n+1], max = new long[n+1], maxx = new long[n+1];
        sum[0] = max[0] = 0;
        for(int i = 1; i <= n; i++) {
            sum[i] = sum[i-1] + v[i];
            if(max[i - 1] > sum[i] - x[i]) {
                max[i] = max[i-1];
                maxx[i] = maxx[i-1];
            }else {
                max[i] = sum[i] - x[i];
                maxx[i] = x[i];
            }
        }
        long[] sumb = new long[n+1];
