import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class Main {
    static int n;
    static long c;
    static long[] xs, vs;
    static Map<Long, Integer> compressedX;
    static long[][][] dp;
    public static void main(String args[]) {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        c = sc.nextLong();
        xs = new long[n + 2];
        vs = new long[n + 2];
        xs[0] = 0;
        xs[n + 1] = c;
        vs[0] = 0;
        vs[n + 1] = 0;
        dp = new long[n + 2][n + 2][n + 2];
        compressedX = new HashMap<>();
        compressedX.put(0l, 0);
        for (int i = 1; i <= n; i++) {
            xs[i] = sc.nextLong();
            compressedX.put(xs[i], i);
            vs[i] = sc.nextLong();
        }

        System.out.println(rec(1, n, 0));
        /*
        // counterclockwise
        long counterClockSum = 0;
        long[] counterClockDP = new long[n + 1];
        for (int i = 0; i < n; i++) {
            counterClockDP[i + 1] = Math.max(counterClockDP[i + 1],
                    counterClockDP[i] + vs[i] - xs[i] + xs[i - 1]);
        }
        for (int i = n - 1; i > 0; i--) {
            if (vs[i] > xs[i] - xs[i - 1]) {
                counterClockSum += vs[i] - xs[i] + xs[i - 1];
            }
        }
        */
    }

    static long rec(int next, int prev, long now) {
        if (next > prev) return 0;
        int compressedNow = compressedX.get(now);
        if (dp[next][prev][compressedNow] > 0) return dp[next][prev][compressedNow];
        long nextDistance = (xs[next] + c - now) % c;
        long prevDistance = (now + c - xs[prev]) % c;
        long ans = Math.max(0, Math.max(
                rec(next + 1, prev, xs[next]) + vs[next] - nextDistance,
                rec(next, prev - 1, xs[prev]) + vs[prev] - prevDistance));
        dp[next][prev][compressedNow] = ans;
        return ans;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.lang.Math;
import java.util.Scanner;
import java.util.Arrays;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt() + 1;
        long C = sc.nextLong();

        long costs[] = new long[N];   // x_i
        int values[] = new int[N];  // v_i
        costs[0] = 0;  // 初期位置
        values[0] = 0;

        for (int i = 1; i < N; i++) {
            costs[i] = sc.nextLong();
            values[i] = sc.nextInt();
        }

        long value_accum[] = new long[N];
        long value_accum_rev[] = new long[N];
        value_accum[0] = 0;  // 初期位置
        value_accum_rev[0] = 0;
        for (int i = 1; i < N; i++) {
            value_accum[i] = value_accum[i-1] + values[i];
            value_accum_rev[i] = value_accum_rev[i-1] + values[N-i];
        }
        // //System.out.println(Arrays.toString(values));
        // //System.out.println(Arrays.toString(value_accum));
        // //System.out.println(Arrays.toString(value_accum_rev));

        // 時計回り側のコスパ
        long cw_cospa[] = new long[N];
        for (int i = 0; i < N; i++) {
            long cw_value = value_accum[i];
            long cw_cost = costs[i];
            cw_cospa[i] = cw_value - cw_cost;
        }

        // cw_cospa_bestpos[N] = 時計回り側の N までのコスパのなかで一番いいやつの位置
        int cw_cospa_bestpos[] = new int[N];
        cw_cospa_bestpos[0] = 0;
        for (int i = 1; i < N; i++) {
            if (cw_cospa[i] > cw_cospa[cw_cospa_bestpos[i-1]]) {
                cw_cospa_bestpos[i] = i;
            }
            else {
                cw_cospa_bestpos[i] = cw_cospa_bestpos[i-1];
            }
        }

        // 時計回り側のコスパ
        long cw_cospa2[] = new long[N];
        for (int i = 0; i < N; i++) {
            long cw_value = value_accum[i];
            long cw_cost = costs[i];
            cw_cospa2[i] = cw_value - cw_cost * 2;
        }

        // cw_cospa_bestpos[N] = 時計回り側の N までのコスパのなかで一番いいやつの位置
        int cw_cospa_bestpos2[] = new int[N];
        cw_cospa_bestpos2[0] = 0;
        for (int i = 1; i < N; i++) {
            if (cw_cospa2[i] > cw_cospa2[cw_cospa_bestpos[i-1]]) {
                cw_cospa_bestpos2[i] = i;
            }
            else {
                cw_cospa_bestpos2[i] = cw_cospa_bestpos2[i-1];
            }
        }
        //System.out.println(Arrays.toString(cw_cospa_bestpos));

        long score_max = 0;
        for (int i = 0; i < N; i++) {
            //System.out.println("cw, ccw = " + cw_cospa_bestpos[N-1-i] + ", " + i);

            // 反時計回り側のコスパ
            long ccw_value = value_accum_rev[i];
            long ccw_cost = (i == 0) ? 0 : (C - costs[N-i]);

            long score_cw  = cw_cospa2[cw_cospa_bestpos2[N-1-i]] + ccw_value - ccw_cost;
            //System.out.println("score_cw = " + score_cw);
            long score_ccw = cw_cospa[cw_cospa_bestpos[N-1-i]] + (ccw_value - ccw_cost * 2);
            //System.out.println("score_ccw = " + score_ccw);
            score_max = Math.max(score_max, score_cw);
            score_max = Math.max(score_max, score_ccw);
        }

        System.out.println(score_max);
    }
}

import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());
    long C = Long.parseLong(sc.next());

    long x[] = new long[N];
    long v[] = new long[N];

    long getCalorieForward[] = new long[N];
    long sumV = 0;
    long maxForward = -1;
    int maxIndexForward = 0;

    for (int i = 0; i < N; i++) {
      x[i] = Long.parseLong(sc.next());
      v[i] = Long.parseLong(sc.next());
      sumV += v[i];
      getCalorieForward[i] = sumV - x[i];
      if (getCalorieForward[i] > maxForward) {
        maxForward = getCalorieForward[i];
        maxIndexForward = i;
      }
    }

    long getCalorieBack[] = new long[N];
    sumV = 0;
    long maxBack = -1;
    int maxIndexBack = 0;
    for (int i = 0; i < N; i++) {
      sumV += v[N - 1 - i];
      getCalorieBack[i] = sumV - C - x[N - 1 - i];
      if (getCalorieBack[i] > maxBack) {
        maxBack = getCalorieBack[i];
        maxIndexBack = N - 1 - i;
      }
    }

    if (maxForward < 0 && maxBack < 0) {
      System.out.println(0);
    } else if (maxForward < 0) {
      System.out.println(maxBack);
    } else if (maxBack < 0) {
      System.out.println(maxForward);
    } else if (maxIndexForward < maxIndexBack) {
      System.out.println(maxForward + maxBack);
    } else {
      System.out.println(Math.max(maxForward, maxBack));
    }

  }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static int N;
	public static long C;
	public static long[] positions, values;
	public static boolean[][][] visited = new boolean[102][102][2];

	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(f.readLine());
		N = Integer.parseInt(st.nextToken());
		C = Long.parseLong(st.nextToken());
		positions = new long[N + 1];
		values = new long[N + 1];
		positions[0] = 0;
		values[0] = 0;
		for (int i = 0; i < N; i++) {
			st = new StringTokenizer(f.readLine());
			long x = Long.parseLong(st.nextToken());
			long v = Long.parseLong(st.nextToken());
			positions[i + 1] = x;
			values[i + 1] = v;
		}
		long res = Math.max(dfs(N, 0, 1, 0, 0) - distance(N, 0), dfs(0, 1, 0, 0, 0) - distance(0, 1));
		res = Math.max(res, 0);
		System.out.println(res);
	}

	public static long dfs(int left, int right, int isLeft, long lastDistance, int depth) {
		// System.out.println(left + " " + right + " " + isLeft + " " + depth);
		if (left == -1) {
			return dfs(N, right, isLeft, lastDistance, depth);
		}
		if (right == N + 1) {
			return dfs(left, 0, isLeft, lastDistance, depth);
		}
		if (left == right) {
			return lastDistance;
		}
		if (visited[left][right][isLeft]) {
			return 0;
		}
		visited[left][right][isLeft] = true;
		if (isLeft == 1) {
			return values[left] + Math.max(0,
					Math.max(dfs(left - 1, right, 1, distance(left - 1, left), depth + 1) - distance(left - 1, left),
							dfs(left, right + 1, 0, distance(right + 1, left), depth + 1) - distance(right + 1, left)));
		} else {
			return values[right] + Math.max(0,
					Math.max(
							dfs(left, right + 1, 0, distance(right + 1, right), depth + 1) - distance(right + 1, right),
							dfs(left - 1, right, 1, distance(left - 1, right), depth + 1) - distance(left - 1, right)));
		}
	}

	public static long distance(int i, int j) {
		if (i == -1) {
			i = N;
		}
		if (j == -1) {
			j = N;
		}
		if (i == N + 1) {
			i = 0;
		}
		if (j == N + 1) {
			j = 0;
		}
		long max = Math.max(positions[i], positions[j]);
		long min = Math.min(positions[i], positions[j]);
		return Math.min(max - min, C - max + min);
	}
}

