using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Practice
{
    class Program
    {
        private static int ReadAndParseInt()
        {
            return int.Parse(Console.ReadLine());
        }
        private static int[] ReadAndParseIntArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        }
        private static long ReadAndParseLong()
        {
            return long.Parse(Console.ReadLine());
        }
        private static long[] ReadAndParseLongArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
        }
        static void Main(string[] args)
        {
            SolveA(args);
            //SolveB(args);
            //SolveC(args);
            //SolveD(args);


        }

        public struct Node
        {
            public long idx;
            public long v;// kcal接種
            public long x;// kcal消費
        }
        static void SolveA(string[] args)
        {
            long[] nc = ReadAndParseLongArr();
            long n = nc[0];
            long c = nc[1];
            long[] x = new long[n];
            long[] v = new long[n];
            long[] dist = new long[n+1];

            for (int i = 0; i < n; ++i)
            {
                long[] xv = ReadAndParseLongArr();
                x[i] = xv[0];
                v[i] = xv[1];
                if (i == 0)
                {
                    dist[i] = x[i];
                }

                else
                {
                    dist[i] = x[i] - x[i - 1];
                }
            }
            dist[n] = c - x[n - 1];
            // 

            // 無向グラフの隣接リスト表現
            Node[] cw = new Node[n+1];
            // clockwise
            for (int i = 0; i < n; ++i)
            {
                var node = new Node() {idx = (i+1)%dist.Length, x = dist[i], v = v[i] };
                cw[i] = node;
            }
            cw[n] = new Practice.Program.Node() {idx =0, x = dist[n], v = 0 };

            Node[] countercw = new Practice.Program.Node[n + 1];
            for(int i=0;i<n;++i)
            {
                var node = new Node() {idx=n-i, x = dist[n - i], v = v[n - 1 - i] };
                countercw[i] = node;
            }
            countercw[n] = new Node() {idx =0, x = dist[0], v = 0 };
            bool[] color = new bool[n+1];// true 食べた
            color[0] = true;

            long getCal = 0;
            long idx = 0;
            while (true)
            {

                idx = FindNextNode(idx, cw,countercw, color, ref getCal);
                if (idx == -1) { break; }
                color[idx] = true;
            }

            Console.WriteLine(getCal);
        }
        private static long FindNextNode(long pos, Node[] cw, Node[] ccw, bool[] color, ref long getCal)
        {
            long nodeIdxCW = -1;
            // 型方向                
            long cnt = 0;
            long calPlus = 0;
            long calMinus = 0;
            long getCalCw =0;
            while (cnt < cw.Length)
            {

                long idx = (pos + cnt) % cw.Length;
                Node node = cw[idx];
                if( !color[node.idx] ) calPlus += node.v;
                calMinus += node.x;
                if (!color[node.idx] && calPlus > calMinus)
                {
                    getCalCw += calPlus - calMinus;
                    nodeIdxCW = node.idx;
                    break;
                }

                cnt++;
            }

            // 反対方向
            long nodeIdxCCW = -1;
            long getCalCCW = 0;
            pos = (cw.Length - pos) % cw.Length;
            cnt = 0;
            calPlus = 0;
             calMinus = 0;
            while (cnt < ccw.Length)
            {
                long idx = (pos - cnt + ccw.Length) % ccw.Length;
                Node node = ccw[idx];
                if (!color[node.idx]) calPlus += node.v;
                calMinus += node.x;
                if (!color[node.idx] && calPlus > calMinus)
                {
                    getCalCCW += calPlus - calMinus;
                    nodeIdxCCW = node.idx;
                    break;
                }

                cnt++;

            }

            if(nodeIdxCW >= 0 && getCalCw > getCalCCW)
            {
                getCal += getCalCw;
                return nodeIdxCW;
            }
            else if(nodeIdxCCW >= 0 && getCalCCW > getCalCw)
            {
                getCal += getCalCCW;
                return nodeIdxCCW;
            }

            getCal += 0;
            return -1;
        }
    }
}

