namespace AtCoder.ABC095
{
    class d
    {
        static void Main(string[] args)
        {
            var line = Console.ReadLine().Trim();
            var spl = line.Split(' ');
            var N = int.Parse(spl[0]);
            var C = long.Parse(spl[1]);
            Tuple<long, int>[] xv = new Tuple<long, int>[N];
            for (var i = 0; i < N; ++i)
            {
                line = Console.ReadLine().Trim();
                spl = line.Split(' ');
                xv[i] = Tuple.Create(long.Parse(spl[0]), int.Parse(spl[1]));
            }
            var max = Math.Max(Search(xv, -1, 0, N - 1, 0L, 0L, C), 0);
            Console.WriteLine(max);
        }

        private static long Search(Tuple<long, int>[] xv, int nowP, int minP, int maxP, long cal, long maxCal, long C)
        {
            if(nowP == -1)
            {
                if(minP == maxP)
                {
                    return xv[0].Item2 - xv[0].Item1;
                }
                else
                {
                    var a = Search(xv, minP, minP + 1, maxP, cal - xv[minP].Item1 + xv[minP].Item2, Math.Max(maxCal, cal - xv[minP].Item1 + xv[minP].Item2), C);
                    var b = Search(xv, maxP, minP, maxP - 1, cal - C + xv[maxP].Item1 + xv[maxP].Item2, Math.Max(maxCal, cal - C + xv[maxP].Item1 + xv[maxP].Item2), C);
                    return Math.Max(a, b);
                }
            }
            else
            {
                if(minP == maxP)
                {
                    return Math.Max(maxCal, maxCal - CalcDistance(xv[nowP].Item1, xv[minP].Item1, C) + xv[minP].Item2);
                }
                else
                {
                    var a = Search(xv, minP, minP + 1, maxP, cal - (CalcDistance(xv[nowP].Item1, xv[minP].Item1, C)) + xv[minP].Item2, Math.Max(maxCal, cal - (CalcDistance(xv[nowP].Item1, xv[minP].Item1, C)) + xv[minP].Item2), C);
                    var b = Search(xv, maxP, minP, maxP - 1, cal - (CalcDistance(xv[nowP].Item1, xv[maxP].Item1, C)) + xv[maxP].Item2, Math.Max(maxCal, cal - (CalcDistance(xv[nowP].Item1, xv[maxP].Item1, C)) + xv[maxP].Item2), C);
                    return Math.Max(a, b);
                }
            }
        }

        private static long CalcDistance(long point, long target, long C)
        {
            return Math.Min(Math.Abs(target - point), C - Math.Abs(target - point));
        }
    }
}

