namespace atcorder
{
    public class Pair{
        public Pair(){
            a = b = 0;
        }
        public Pair(long _a,long _b){
            a = _a;b = _b;
        }
        public long a, b;
    }
    class MainClass
    {
        public static void Main(string[] args)
        {
                        string s = Console.ReadLine();
            int N = int.Parse(s.Split(' ')[0]);
            long C = long.Parse(s.Split(' ')[1]);
            Pair[] pairs = new Pair[N];
            int j = 0;
            for (int i = 0; i < N;i++){
                s = Console.ReadLine();
                pairs[i]=new Pair(long.Parse(s.Split(' ')[0]), long.Parse(s.Split(' ')[1]));
                if (pairs[i].a < C / 2) j = i;
            }
            //p,qは次に行けるポインタ
            long x = 0;
            long cal = 0;
            long hcal=0;
            long max = 0;
            long arg_max = 0;
            //おそらく一回しか引き返さない？
            //時計回りから考える
            for (int i = 0; i < j; i++)
            {//半周まで考える(半周以降はそのまま回る
                cal += pairs[i].b - (pairs[i].a - x);//現在の位置での利得
                x = pairs[i].a;
                hcal = pairs[N - 1].b - (C - pairs[N - 1].a + x);//この位置から引き返した時の利得
                if (max < cal+hcal){
                    max = cal + hcal;
                    arg_max = i;
                } 
            }
            //引き返した場合
            hcal = max;
            long hx = pairs[N - 1].a;
            for (int i = N - 2; i > arg_max;i--){
                hcal += pairs[i].b - (hx - pairs[i].a);//現在の位置での利得
                hx = pairs[i].a;
                if (max < hcal){
                    max = hcal;
                } 
            }
            //引き返さなかった場合
            long nhmax = 0;
            for (int i = j; i < N;i++){
                cal += pairs[i].b - (pairs[i].a - x);//現在の位置での利得
                x = pairs[i].a;
                if (nhmax < cal){
                    nhmax = cal;
                } 
            }

            //反時計回りから考える
            x = C;
            long htmax = 0;
            cal = 0;
            arg_max = 0;
            hcal = 0;
            for (int i = N-1; i > j; i--)
            {//半周まで考える(半周以降はそのまま回る
                cal += pairs[i].b - (x - pairs[i].a);//現在の位置での利得
                x = pairs[i].a;
                hcal = pairs[N - 1].b - (C - x + pairs[0].a);//この位置から引き返した時の利得
                if (htmax < cal + hcal)
                {
                    htmax = cal + hcal;
                    arg_max = i;
                }
            }
            //引き返した場合
            hcal = htmax;
            hx = pairs[0].a;
            for (int i = 1; i < arg_max; i++)
            {
                hcal += pairs[i].b - (pairs[i].a - hx);//現在の位置での利得
                hx = pairs[i].a;
                if (htmax < hcal)
                {
                    htmax = hcal;
                }
            }
            //引き返さなかった場合
            long nhtmax = 0;
            for (int i = j; i >= 0; i--)
            {
                cal += pairs[i].b - (x-pairs[i].a);//現在の位置での利得
                x = pairs[i].a;
                if (nhtmax < cal)
                {
                    nhtmax = cal;
                }
            }
            Console.WriteLine(Math.Max(Math.Max(max, nhmax), Math.Max(htmax, nhtmax)) );
        }
    }
}

