// 円周上の移動距離問題
// https://atcoder.jp/contests/abc095/tasks/arc096_b
namespace ABC095_ARC096.D
{
	using static Util;

	public class Solver : SolverBase
	{
		public void Run() {
			var ary = ReadLongArray();
			int N = (int)ary[0];
			long C = ary[1];

			var AryS = new long[N][];
			for (int i = 0; i < N; i++) {
				AryS[i] = ReadLongArray();
			}

			// 時計回り側
			// CW[i] = maxV
			// i番目までの寿司を食べられるとしたときに得られる最大のカロリーmaxVの配列
			var CW = new long[N];
			long lastPos = 0;
			long maxCal = 0;
			long curCal = 0;
			for (int i = 0; i < N; i++) {
				var x = AryS[i][0];
				var v = AryS[i][1];
				// 追加カロリー = 寿司カロリー - 消費カロリー（距離）
				long addCal = v - (x - lastPos);
				lastPos = x;
				// iまでに得られるカロリー
				curCal += addCal;

				// iまでに得られる最大カロリーを更新
				if (maxCal < curCal) {
					maxCal = curCal;
				}

				CW[i] = maxCal;
			}
			// 反時計回り側
			// CCW[i] = maxV
			// 反時計回りにi番目までの寿司を食べられるとしたときに得られる最大のカロリーmaxVの配列
			var CCW = new long[N];
			lastPos = C;
			maxCal = 0;
			curCal = 0;
			for (int i = 0; i < N; i++) {
				var x = AryS[N-i-1][0];
				var v = AryS[N-i-1][1];
				// 追加カロリー = 寿司カロリー - 消費カロリー（距離）
				long addCal = v - (lastPos - x);
				lastPos = x;
				// iまでに得られるカロリー
				curCal += addCal;

				// iまでに得られる最大カロリーを更新
				if (maxCal < curCal) {
					maxCal = curCal;
				}

				CCW[i] = maxCal;
			}

			// 反時計回りに全探索 ※最初に反時計回りに進む場合
			lastPos = C;
			curCal = 0;
			maxCal = 0;
			// 0個〜N-1個 取るパターンを検討 ※N個＝全部とる場合は考えない。それは帰ってこなくていいパターンなので、CW first 検討に含まれる
			for (int i = 0; i <= N-1; i++) {
				if (0 < i) {
					var x = AryS[N-i][0];
					var v = AryS[N-i][1];
					// 追加カロリー = 寿司カロリー - 消費カロリー（距離 * 2)
					long addCal = v - (lastPos - x) * 2;
					lastPos = x;
					// iまでに得られるカロリー
					curCal += addCal;
				}
				// 反時計回り側の現在カロリー ＋ 時計回り側で得られる最大カロリー
				if (maxCal < curCal + CW[N - 1 - i])
					maxCal = curCal + CW[N - 1 - i];
			}

			// 時計回りに全探索 ※最初に時計回りに進む場合
			lastPos = 0;
			curCal = 0;
			// 0個〜N-1個 取るパターンを検討 ※N個＝全部とる場合は考えない。それは帰ってこなくていいパターンなので、CCW first 検討に含まれる
			for (int i = 0; i <= N - 1; i++) {
				if (0 < i) {
					var x = AryS[i-1][0];
					var v = AryS[i-1][1];
					// 追加カロリー = 寿司カロリー - 消費カロリー（距離 * 2)
					long addCal = v - (x - lastPos) * 2;
					lastPos = x;
					// iまでに得られるカロリー
					curCal += addCal;
				}
				// 時計回り側の現在カロリー ＋ 反時計回り側で得られる最大カロリー
				if (maxCal < curCal + CCW[N - 1 - i])
					maxCal = curCal + CCW[N - 1 - i];
			}

			WriteLine(maxCal);
		}

#if !MYHOME
		public static void Main(string[] args) {
			new Solver().Run();
		}
#endif
