			//}

			long ans = 0;
			for (int i = 1; i <= n; i++) {
				System.Diagnostics.Debug.WriteLine($"          0 --> {i}:{sushi[i, 3],3}");
				ans = Math.Max(ans, sushi[i, 3]);
				for (int j = n; j > i; j--) {
					System.Diagnostics.Debug.WriteLine($"{j}:{sushi[j, 7],3} <-> 0 --> {i}:{sushi[i, 3],3}");
					ans = Math.Max(ans, sushi[j, 7] + sushi[i, 3]);
				}
			}

			for (int i = n; i >= 1; i--) {
				System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 6],3} <-- 0");
				ans = Math.Max(ans, sushi[i, 6]);
				for (int j = 1; j < i; j++) {
					System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 6],3} <-- 0 <-> {j}:{sushi[j, 4],3}");
					ans = Math.Max(ans, sushi[i, 6] + sushi[j, 4]);
				}
			}

			Console.WriteLine(ans);
		}
	}
}

