public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        long C = cr.Long;
        var sushis = new Sushi[N];
        for (int i = 0; i < N; i++)
        {
            sushis[i] = new Sushi { x = cr.Long, v = cr.Long };
            //sushis[i + N] = new Sushi { x = sushis[i].x + C, v = sushis[i].v };
        }
        var sums = new long[N];
        sums[0] = sushis[0].v;
        for (int i = 1; i < sushis.Length; i++)
            sums[i] = sums[i - 1] + sushis[i].v;
        for (int i = 0; i < sushis.Length; i++)
            sums[i] -= sushis[i].x;
        var seg1 = new SegmentTree(sums);


        var sums2 = new long[N];
        sums2[N - 1] = sushis[N - 1].v;
        for (int i = sums2.Length - 2; i >= 0; i--)
            sums2[i] = sums2[i + 1] + sushis[i].v;
        for (int i = 0; i < sushis.Length; i++)
            sums2[i] -= C - sushis[i].x;
        var max = Math.Max(0, Math.Max(sums.Max(), sums2.Max()));

        var sums3 = new long[N];
        var sums4 = new long[N];

        for (int i = 0; i < sushis.Length; i++)
        {
            sums3[i] = sums[i] - sushis[i].x;
            sums4[i] = sums2[i] - C + sushis[i].x;
        }

        var seg2 = new SegmentTree(sums2);
        var seg3 = new SegmentTree(sums3);
        var seg4 = new SegmentTree(sums4);
        for (int i = 1; i < N; i++)
        {
            UpdateMax(ref max, seg1.Query(0, i) + seg4.Query(i, N));
            UpdateMax(ref max, seg3.Query(0, i) + seg2.Query(i, N));
        }

        return max;
    }
}
