	static class Program
	{
		public static void Solve(Scanner cin)
		{
			var (n, c) = cin.ReadValue<int, long>();
			var (_x, _v) = cin.ReadValueArray<long, long>(n);
			var x = new List<long>();
			var v = new List<long>();
			x.Add(0); v.Add(0);
			for (int i = 0; i < n; i++)
			{
				x.Add(_x[i]); v.Add(_v[i]);
			}
			x.Add(c); v.Add(0);

			var sumleft = new long[n + 2];
			var sumright = new long[n + 2];
			for (int i = 0; i < n + 2; i++)
			{
				if (i == 0)
				{
					sumleft[i] = v[i];
					sumright[i] = v[n + 1 - i];
				}
				else
				{
					sumleft[i] = v[i] + sumleft[i - 1];
					sumright[i] = v[n + 1 - i] + sumright[i - 1];
				}
			}
			var l1 = new long[n + 2];
			var l2 = new long[n + 2];
			var r1 = new long[n + 2];
			var r2 = new long[n + 2];

			for (int i = 0; i < n + 2; i++)
			{
				l1[i] = sumleft[i] - x[i];
				l2[i] = sumleft[i] - x[i] * 2;
				r1[i] = sumright[i] - (c - x[n + 1 - i]);
				r2[i] = sumright[i] - (c - x[n + 1 - i]) * 2;
			}

			var maxl1 = new long[n + 2];
			var maxl2 = new long[n + 2];
			var maxr1 = new long[n + 2];
			var maxr2 = new long[n + 2];

			for (int i = 0; i < n + 2; i++)
			{
				if (i == 0)
				{
					maxl1[i] = l1[i];
					maxl2[i] = l2[i];
					maxr1[i] = r1[i];
					maxr2[i] = r2[i];
				}
				else
				{
					maxl1[i] = Math.Max(maxl1[i - 1], l1[i]);
					maxl2[i] = Math.Max(maxl2[i - 1], l2[i]);
					maxr1[i] = Math.Max(maxr1[i - 1], r1[i]);
					maxr2[i] = Math.Max(maxr2[i - 1], r2[i]);
				}				
			}

			long ans = 0;

			for (int i = 1; i < n + 1; i++)
			{
				ans = Math.Max(ans, l1[i] + maxr2[n - i]);
				ans = Math.Max(ans, r1[i] + maxl2[n - i]);
			}

			Console.WriteLine(ans);
		}

