using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;
using static System.Math;
using System.Numerics;

namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {

            var NC = Sarray();
            var N = NC[0];
            var C = NC[1];
            var x = new long[N];
            var v = new long[N];
            for (var i = 0; i < N; ++i)
            {
                var xv = Sarray();
                x[i] = xv[0];
                v[i] = xv[1];
            }
            var ruiVCw = new long[N + 1];
            var ruiVCcw = new long[N + 1];
            var maxVCw = new long[N + 1];
            var maxVCcw = new long[N + 1];
            for (var i = 1; i <= N; ++i)
            {
                ruiVCw[i] = ruiVCw[i - 1] + v[i - 1];
                ruiVCcw[i] = ruiVCcw[i - 1] + v[N - i];
                maxVCw[i] = Max(maxVCw[i - 1], ruiVCw[i] - x[i - 1]);
                maxVCcw[i] = Max(maxVCcw[i - 1], ruiVCcw[i] - (C - x[N - i]));
            }

            var maxCw2Ccw = maxVCw.Max();
            var maxCcw2Cw = maxVCcw.Max();
            for (var i = 1; i <= N; ++i)
            {
                maxCw2Ccw = Max(maxCw2Ccw, ruiVCw[i] - 2 * x[i - 1] + maxVCcw[N - i]);
                maxCcw2Cw = Max(maxCcw2Cw, ruiVCcw[i] - 2 * (C - x[N - i]) + maxVCw[N - i]);
            }
            WriteLine(Max(maxCw2Ccw, maxCcw2Cw));
        }
    }
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		long N = long.Parse(str[0]);
		long C = long.Parse(str[1]);
		long[,] X = new long[N+2,2];
		X[0,0] = 0;
		X[0,1] = 0;
		X[N+1,0] = C;
		X[N+1,1] = 0;
		for(var i=1;i<=N;i++){
			string[] str2 = Console.ReadLine().Split();
			X[i,0] = long.Parse(str2[0]);
			X[i,1] = long.Parse(str2[1]);
		}
		long[] ncsum1 = new long[N+2];
		long[] ncmax1 = new long[N+2];
		ncsum1[0] = 0;
		ncmax1[0] = 0;
		long[] ncsum2 = new long[N+2];
		long[] ncmax2 = new long[N+2];
		ncsum2[0] = 0;
		ncmax2[0] = 0;
		for(var i=1;i<=N;i++){
			ncsum1[i] = ncsum1[i-1] + X[i,1] - (X[i,0] - X[i-1,0]);
			ncmax1[i] = Math.Max(ncmax1[i-1],ncsum1[i]);
		}
		for(var i=N;i>=1;i--){
			ncsum2[i] = ncsum2[i+1] + X[i,1] - ((C-X[i,0]) - (C-X[i+1,0]));
			ncmax2[i] = Math.Max(ncmax2[i+1],ncsum2[i]);
		}
		long max = 0;
		for(var i=0;i<=N;i++){
			long tmp = ncmax1[i] + ncmax2[i+1] - Math.Min(X[i,0], C-X[i+1,0]);
			max = Math.Max(max,tmp);
		}
		Console.WriteLine(max);
	}
}

