			t[0, i] = t[0, i - 1] + s[i - 1][1];
			t[1, i] = t[1, i - 1] + s[n - i][1];
		}
		for (int i = 1; i <= n; i++)
		{
			t[0, i] -= s[i - 1][0];
			t[1, i] -= c - s[n - i][0];
			t[2, i] = Math.Max(t[2, i - 1], t[0, i]);
			t[3, i] = Math.Max(t[3, i - 1], t[1, i]);
		}
		var M0 = Enumerable.Range(0, (int)n + 1).Max(i => t[0, i] - (i > 0 ? s[i - 1][0] : 0) + t[3, n - i]);
		var M1 = Enumerable.Range(0, (int)n + 1).Max(i => t[1, i] - (i > 0 ? c - s[n - i][0] : 0) + t[2, n - i]);
		Console.WriteLine(Math.Max(M0, M1));
	}
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var C = sc.ReadLong();
        var XV = sc.ReadTupLongArray(N);

        // 累積和的な奴
        var maxSum = new Tuple<long, long>[N + 1];
        maxSum[0] = Tuple.Create(0L, 0L);
        var tot = 0L;
        for (int i = 0; i < N; i++)
        {
            tot += XV[i].Item2;
            var now = tot - XV[i].Item1;
            maxSum[i + 1] = Tuple.Create(XV[i].Item1, Math.Max(maxSum[i].Item2, now));
        }

        var maxSumR = new Tuple<long, long>[N + 1];
        maxSumR[0] = Tuple.Create(0L, 0L);
        tot = 0L;
        for (int i = N - 1; i >= 0; i--)
        {
            var index = N - i - 1;
            tot += XV[i].Item2;
            var now = tot - (C - XV[i].Item1);
            maxSumR[index + 1] = Tuple.Create((C - XV[i].Item1), Math.Max(maxSumR[index].Item2, now));
        }

        var ans = 0L;
        for (int i = 0; i <= N; i++)
        {
            var res = maxSum[i].Item2 + maxSumR[N-i].Item2;
            res -= Math.Min(maxSum[i].Item1, maxSumR[N - i].Item1);
            ans = Math.Max(ans, res);
        }
        Console.WriteLine(ans);
    }

    static Scanner sc = new Scanner();
}
