            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }

        static void Solve()
        {
            var (N, C) = Slice2<long>();
            var dsts = new long[N];
            var cals = new long[N];
            for (var i = 0; i < N; ++i)
                (dsts[i], cals[i]) = Slice2<long>();

            var ruiDstCW = new long[N + 1];
            var ruiCalCW = new long[N + 1];
            var maxCW = new long[N + 1];
            for (var i = 1; i <= N; ++i)
            {
                ruiDstCW[i] = dsts[i - 1];
                ruiCalCW[i] = ruiCalCW[i - 1] + cals[i - 1];
                maxCW[i] = Max(maxCW[i - 1], ruiCalCW[i] - ruiDstCW[i]);
            }
            var ruiDstCCW = new long[N + 1];
            var ruiCalCCW = new long[N + 1];
            var maxCCW = new long[N + 1];
            for (var i = 1; i <= N; ++i)
            {
                var n = N - 1 - i + 1;
                ruiDstCCW[i] = C - dsts[n];
                ruiCalCCW[i] = ruiCalCCW[i - 1] + cals[n];
                maxCCW[i] = Max(maxCCW[i - 1], ruiCalCCW[i] - ruiDstCCW[i]);
            }
            var maxCal = 0L;
            for (var i = 0; i <= N; ++i)//[0,i)で回る方向を変える
            {
                maxCal = Max(maxCal, maxCW[i] - ruiDstCW[i] + maxCCW[N - i]);
                maxCal = Max(maxCal, maxCCW[i] - ruiDstCCW[i] + maxCW[N - i]);
            }
            WriteLine(maxCal);
        }

