			// sushi[i,5] ccw 熱量 
			// sushi[i,6] ccw 片道収支
			// sushi[i,7] ccw 往復収支
			for (int i = 1; i <= n; i++) {
				vs = Console.ReadLine().Split().Select(long.Parse).ToArray();
				sushi[i, 0] = vs[0];
				sushi[i, 1] = vs[1];
				sushi[i, 2] = sushi[i, 1] + sushi[i - 1, 2];
				sushi[i, 3] = sushi[i, 2] - sushi[i, 0];
				sushi[i, 4] = sushi[i, 2] - sushi[i, 0] * 2;
			}
			for (int i = n; i > 0; i--) {
				sushi[i, 5] = sushi[i, 1] + (i < n ? sushi[i + 1, 5] : 0);
				sushi[i, 6] = sushi[i, 5] - (c - sushi[i, 0]);
