				//System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 6],3} <-- 0");
				ans = Math.Max(ans, sushi[i, 6]);
				for (int j = 1; j < i; j++) {
					//System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 6],3} <-- 0 <-> {j}:{sushi[j, 4],3}");
					ans = Math.Max(ans, sushi[i, 6] + sushi[j, 4]);
				}
			}

			Console.WriteLine(ans);
		}
	}
}

