        public void Solve()
        {
            int  N = cin.ReadInt;
            long C = cin.ReadLong;

            long[] X = new long[N];
            long[] V = new long[N];

            for (int i = 0; i < N; i++)
            {
                X[i] = cin.ReadLong;
                V[i] = cin.ReadLong;
            }

            long[] l1Max = new long[N + 1];
            long[] r1Max = new long[N + 1];
            long[] l2Max = new long[N + 1];
            long[] r2Max = new long[N + 1];

            long sum = 0;

            for (int i = 0; i < N; i++)
            {
                sum += V[i];
                l1Max[i + 1] = Math.Max(l1Max[i], sum - X[i]);
                l2Max[i + 1] = Math.Max(l2Max[i], sum - X[i] * 2);
            }

            sum = 0;

            for (int i = N - 1; i >= 0; i--)
            {
                sum += V[i];
                r1Max[i] = Math.Max(r1Max[i + 1], sum - (C - X[i]));
                r2Max[i] = Math.Max(r2Max[i + 1], sum - (C - X[i]) * 2);
            }

            long ans = 0;

            for (int i = 0; i <= N; i++)
            {
                ans = Math.Max(ans, Math.Max(l1Max[i] + r2Max[i], r1Max[i] + l2Max[i]));
            }

            cou.WriteLine(ans);
        }

