class Program
{
    static void Main(string[] args)
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        long c = sc.NextLong();
        long[] x = new long[n + 2];
        int[] v = new int[n + 2];
        for (int i = 1; i <= n; i++)
        {
            x[i] = sc.NextLong();
            v[i] = sc.NextInt();
        }
        x[n + 1] = c;

        long[,] sum = new long[2, n * 2 + 10];
        long d = 0;
        for (int i = 1; i <= n; i++)
        {
            d += v[i] - (x[i] - x[i - 1]);
            sum[0, i] = Math.Max(sum[0, i - 1], d);
        }

        d = 0;
        for (int i = n; i >= 1; i--)
        {
            d += v[i] - (x[i + 1] - x[i]);
            sum[1, i] = Math.Max(sum[1, i + 1], d);
        }

        long max = 0;
        for (int i = 0; i <= n; i++)
        {
            long res = sum[0, i] + sum[1, i + 1] - x[i];
            max = Math.Max(max, res);

            res = sum[0, i] + sum[1, i + 1] - c + x[i + 1];
            max = Math.Max(max, res);
        }
        Console.WriteLine(max);
    }

    static long Gcd(long a, long b)
    {
        if (a < b) return Gcd(b, a);
        if (b == 0) return a;
        return Gcd(b, a % b);
    }
}

