	static class Program
	{
		public static void Solve(Scanner cin)
		{
			var (n, c) = cin.ReadValue<int, long>();
			var x = new List<long>();
			var v = new List<long>();
			x.Add(0);
			v.Add(0);
			for (int i = 0; i < n; i++)
			{
				var (_x, _v) = cin.ReadValue<long, long>();
				x.Add(_x);
				v.Add(_v);
			}
			x.Add(c);
			v.Add(0);

			var sum = new List<long>();
			var sumr = new List<long>();
			sum.Add(0);
			sumr.Add(0);
			for (int i = 1; i < x.Count; i++)
			{
				sum.Add(sum[i - 1] + v[i]);
			}
			for (int i = x.Count - 2; i >= 0; i--)
			{
				sumr.Add(sumr[x.Count - 1 - i - 1] + v[i]);
			}
			sumr.Reverse();

			var clock = new List<long>();
			var clock2 = new List<long>();
			var counter = new List<long>();
			var counter2 = new List<long>();

			for (int i = 0; i < x.Count; i++)
			{
				clock.Add(sum[i] - x[i]);
				clock2.Add(sum[i] - x[i] * 2);
				counter.Add(sumr[i] - (c - x[i]));
				counter2.Add(sumr[i] - (c - x[i]) * 2);
			}

			var clock2max = new List<long>();
			var counter2max = new List<long>();
			clock2max.Add(clock2[0]);
			for (int i = 1; i < x.Count - 1; i++)
			{
				clock2max.Add(Math.Max(clock2[i], clock2max[i - 1]));
			}
			counter2max.Add(0);
			for (int i = 1; i < x.Count - 1; i++)
			{
				counter2max.Add(Math.Max(counter2[x.Count - 1 - i], counter2max[i - 1]));
			}
			counter2max.Reverse();

			long ans = 0;

			for (int i = 0; i < x.Count - 1; i++)
			{
				var tmp = clock[i] + counter2max[i];
				Chmax(ref ans, tmp);
			}
			for (int i = x.Count - 1; i >= 1; i--)
			{
				var tmp = counter[i] + clock2max[i - 1];
				Chmax(ref ans, tmp);
			}
			Console.WriteLine(ans);
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}

