        static void SolveA(string[] args)
        {
            long[] nc = ReadAndParseLongArr();
            long n = nc[0];
            long c = nc[1];
            long[] x = new long[n];
            long[] v = new long[n];
            for (int i = 0; i < n; ++i)
            {
                long[] xv = ReadAndParseLongArr();
                x[i] = xv[0];
                v[i] = xv[1];
            }
            // sigma vの事前計算
            long[] va = new long[n+1];// 先頭はダミー
            for(int i=1;i<va.Length;++i)
            {
                va[i] = va[i - 1] + v[i-1];
            }
            long[] vb = new long[n+1];// 先頭はダミー
            vb[n] = v[n-1];
            for(long i=n-1;i>=1;--i)
            {
                vb[i] = vb[i + 1] + v[i-1];
            }
            // f(a)を事前計算 aまで取得したときのカロリー
            long[] f = new long[n+1];
            long[] f2 = new long[n + 1];
            f[0] = 0;
            f2[0] = 0;
            for(int i=1;i<f.Length;++i)
            {
                f[i] = va[i] - x[i-1];
                f2[i] = va[i] - 2 * x[i - 1];
            }
            // さらにg(a)の事前計算
            long[] g = new long[n+1];
            long[] g2 = new long[n + 1];
            g[0] = f[0];
            g2[0] = f2[0];
            for(int i=1;i<g.Length;++i)
            {
                g[i] = Math.Max(f[i], g[i - 1]);
                g2[i] = Math.Max(f2[i], g2[i - 1]);
            }

            // ついでにh(b)を事前計算
            long[] h = new long[n+1];
            long[] h2 = new long[n + 1];
            h[0] = 0;
            h2[n] = 0;
            for(long b = n;b >= 1 ;--b)
            {
                h[b] = vb[b] - (c - x[b - 1]);
                h2[b] = vb[b] - 2*(c - x[b - 1]);
            }

            long max = 0;

            for(int b=0;b<=n;++b)
            {
                long a = b - 1;
                if( a < 0) { a = n; }
                max = Math.Max(max, g2[a] + h[b]);
                max = Math.Max(max, g[a] + h2[b]);

            }


            Console.WriteLine(max);
        }
        private static long CalcH(long b, long c, long [] x, long[] vb)
        {
            return vb[b] - (c - x[b]);
        }


