namespace AtCoder
{
	public class ABC
	{
		static public void Main(string[] args)
		{
			Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
			Solve();
			Console.Out.Flush();
		}

		const int mod = 1000000007;  // 10^9+7
		static int Mod(long x, int m) { return (int)((x % m + m) % m); }
		static long Mod(long x, long m) { return (x % m + m) % m; }

		static public void Solve()
		{
			//string s = Console.ReadLine();
			//int n = int.Parse(Console.ReadLine());
			//long x = long.Parse(Console.ReadLine());
			//int[] vs = Console.ReadLine().Split().Select(int.Parse).ToArray();
			//long[] vs = Console.ReadLine().Split().Select(long.Parse).ToArray();

			long[] vs = Console.ReadLine().Split().Select(long.Parse).ToArray();
			int n = (int)vs[0];
			long c = vs[1];
			long[,] sushi = new long[n + 1, 10];
			// sushi[i,0] 距離
			// sushi[i,1] 熱量

			// sushi[i,2] cw 熱量 累積和
			// sushi[i,3] cw 片道収支
			// sushi[i,4] cw 往復収支
			// sushi[i,5] cw 往復収支 最大

			// sushi[i,6] ccw 熱量 
			// sushi[i,7] ccw 片道収支
			// sushi[i,8] ccw 往復収支
			// sushi[i,9] ccw 往復収支 最大

			for (int i = 1; i <= n; i++) {
				vs = Console.ReadLine().Split().Select(long.Parse).ToArray();
				sushi[i, 0] = vs[0];
				sushi[i, 1] = vs[1];
				sushi[i, 2] = sushi[i, 1] + sushi[i - 1, 2];
				sushi[i, 3] = sushi[i, 2] - sushi[i, 0];
				sushi[i, 4] = sushi[i, 2] - sushi[i, 0] * 2;
				sushi[i, 5] = Math.Max(sushi[i - 1, 5], sushi[i, 4]);
			}
			for (int i = n; i > 0; i--) {
				sushi[i, 6] = sushi[i, 1] + (i < n ? sushi[i + 1, 6] : 0);
				sushi[i, 7] = sushi[i, 6] - (c - sushi[i, 0]);
				sushi[i, 8] = sushi[i, 6] - (c - sushi[i, 0]) * 2;
				sushi[i, 9] = Math.Max((i < n ? sushi[i + 1, 9] : 0), sushi[i, 8]);
			}
			//for (int i = 0; i < sushi.GetLength(0); i++) {
			//	System.Diagnostics.Debug.Write($"{i}:");
			//	for (int j = 0; j < sushi.GetLength(1); j++) {
			//		System.Diagnostics.Debug.Write($"{sushi[i, j],3} ");
			//	}
			//	System.Diagnostics.Debug.WriteLine("");
			//}
			long ans = 0;
			for (int i = 1; i <= n; i++) {
				//System.Diagnostics.Debug.WriteLine($"          0 --> {i}:{sushi[i, 3],3}");
				ans = Math.Max(ans, sushi[i, 3]);
				int j = i + 1;
				if (j <= n) {
					//System.Diagnostics.Debug.WriteLine($"{j}:{sushi[j, 9],3} <-> 0 --> {i}:{sushi[i, 3],3} {sushi[j, 9] + sushi[i, 3]}");
					ans = Math.Max(ans, sushi[j, 9] + sushi[i, 3]);
				}
			}
			for (int i = n; i >= 1; i--) {
				//System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 7],3} <-- 0");
				ans = Math.Max(ans, sushi[i, 7]);
				int j = i - 1;
				if (j >= 0) {
					//System.Diagnostics.Debug.WriteLine($"{i}:{sushi[i, 7],3} <-- 0 <-> {j}:{sushi[j, 5],3} {sushi[i, 7] + sushi[j, 5]}");
					ans = Math.Max(ans, sushi[i, 7] + sushi[j, 5]);
				}
			}
			Console.WriteLine(ans);
		}
	}
}

