class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;


    void solve()
    {
        int N = cin.nextint;
        var C = cin.nextlong;
        var X = new long[N];
        var V = new long[N];
        var R = new long[N];
        var L = new long[N];
        var VR = new long[N];
        var VL = new long[N];
        var memoR = new long[N];
        var memoL = new long[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.nextlong;
            V[i] = cin.nextlong;
        }

        for (int i = 0; i < N; i++)
        {
            if (i == 0) VR[i] = V[i];
            else VR[i] = V[i] + VR[i - 1];
            R[i] = -X[i] + VR[i];

            memoR[i] = Math.Max(memoR[Math.Max(0, i - 1)], -X[i] * 2 + VR[i]);
        }


        for (int u = 0; u < N; u++)
        {
            int i = N - u - 1;
            if (i == N - 1) VL[i] = V[i];
            else VL[i] = V[i] + VL[i + 1];
            L[i] = -(C - X[i]) + VL[i];

            memoL[i] = Math.Max(memoL[Math.Min(N - 1, i + 1)], -(C - X[i]) * 2 + VL[i]);
        }

        var ans = new long[N];
        for (int i = 0; i < N; i++)
        {
            if (i < N - 1) ans[i] = R[i] + memoL[i + 1];
            if (i > 0) ans[i] = Math.Max(ans[i], L[i] + memoR[i - 1]);
        }
        WriteLine(ans.Max());


    }

}

