	class SegmentTree
	{
		// 元の配列の大きさ
		public int N { get; set; }
		// セグメント木のデータ(2^n-1)
		public long[] Node { get; set; }

		// 元データの配列を引数で渡す
		public SegmentTree(long[] a)
		{
			// 要素数を2のべき乗とする
			N = 1;
			while (N < a.Length) N *= 2;

			// セグメント木の管理する要素数を 2^n-1 で初期化する
			this.Node = new long[2 * N - 1];
			for (int i = 0; i < this.Node.Length; i++) this.Node[i] = -1;

			// 各ノードの値を初期化する
			// 葉は元の配列のデータ
			for (int i = 0; i < a.Length; i++) this.Node[N + i - 1] = a[i];
			// 子ノードを比較して親ノードの値を決めていく
			for (int i = N - 2; i >= 0; i--)
			{
				this.Node[i] = this.Compare(this.Node[2 * i + 1], this.Node[2 * i + 2]);
			}
		}

		// x番目のデータをvに更新する
		public void Update(int x, long v)
		{
			// 元の配列のデータが格納される葉のデータを更新する
			x += (this.N - 1);
			this.Node[x] = v;

			// 更新したノードの親をさかのぼってルートまで更新する
			while (x > 0)
			{
				// 親ノードのインデックス
				x = (x - 1) / 2;
				this.Node[x] = this.Compare(this.Node[2 * x + 1], this.Node[2 * x + 2]);
			}
		}
		// [a, b) の区間最小値を求める
		public long GetMax(int a, int b)
		{
			return this.GetMax(a, b, 0, 0, this.N);
		}
		// [a, b) の区間最小値を求める
		// 現在のノードはk番目、[l, r)
		private long GetMax(int a, int b, int k, int l, int r)
		{
			// 1. 現在のノードの対応区間が、求める区間に含まれない場合
			//    対象外の区間のデータなので、最小値に関係のない値(INF)を返す
			if (r <= a || b <= l) return -1;

			// 2. 現在のノードの対応区間が、求める区間に完全に含まれる場合
			//    現在のノードの値が最小値の候補になるのでそのまま返す
			if (a <= l && r <= b) return this.Node[k];

			// 3. 上記以外の場合、現在のノードの対応区間が、求める区間を一部を含む場合
			//    子ノードを評価し、比較した結果を返す
			var vl = this.GetMax(a, b, 2 * k + 1, l, (l + r) / 2);
			var vr = this.GetMax(a, b, 2 * k + 2, (l + r) / 2, r);
			return this.Compare(vl, vr);
		}

		// 2要素を比較して小さい値を返す
		private long Compare(long a, long b) { return Math.Max(a, b); }
	}

	class Scanner
	{
		string[] s;
		int i;

		char[] separator = new char[] { ' ' };

		public Scanner()
		{
			s = new string[0];
			i = 0;
		}

		public string Read() => ReadString();

		public string ReadString()
		{
			if (i < s.Length) return s[i++];
			string st = Console.ReadLine();
			while (st == "") st = Console.ReadLine();
			s = st.Split(separator, StringSplitOptions.RemoveEmptyEntries);
			if (s.Length == 0) return ReadString();
			i = 0;
			return s[i++];
		}

		public string[] ReadStringArray(int N)
		{
			string[] Array = new string[N];
			for (int i = 0; i < N; i++)
