        public static void Main() {
            long N = NextLong, C = NextLong;
            var list = new List<Point>();
            for (int i = 0; i < N; i++) {
                list.Add(new Point { X = NextLong, C = NextLong });
            }

            long[] one = new long[N], two = new long[N], three = new long[N], four = new long[N];
            long now = 0, nowVal = 0;
            for (int i = 0; i < N; i++) {
                one[i] = list[i].C + nowVal - list[i].X + now;
                now = list[i].X;
                nowVal = one[i];
            }

            now = C;
            nowVal = 0;
            for (int i = (int)N - 1; i >= 0; i--) {
                two[i] = list[i].C + nowVal - now + list[i].X;
                now = list[i].X;
                nowVal = two[i];
            }

            now = 0;
            nowVal = 0;
            for (int i = 0; i < N; i++) {
                three[i] = list[i].C + nowVal - (list[i].X - now) * 2;
                now = list[i].X;
                nowVal = three[i];
            }

            now = C;
            nowVal = 0;
            for (int i = (int)N - 1; i >= 0; i--) {
                four[i] = list[i].C + nowVal - (now - list[i].X) * 2;
                now = list[i].X;
                nowVal = four[i];
            }

            long sum = Math.Max(one.Max(), two.Max());

            if(N == 1) {
                Console.WriteLine(Math.Max(0, sum));
                return;
            }

            int id2 = (int)N - 1;
            int id3 = (int)N - 2;
            long tmp = three[id3] + two[id2];
            for (id3 = id3 - 1; id3 >= 0; id3--) {
                if (two[id3 + 1] > two[id2]) {
                    id2 = id3 + 1;
                }
                if (tmp < three[id3] + two[id2]) {
                    tmp = three[id3] + two[id2];
                }
            }
            sum = Math.Max(sum, tmp);

            int id1 = 0, id4 = 1;
            tmp = one[id1] + four[id4];
            for (id4 = id4 + 1; id4 < (int)N; id4++) {
                if (one[id1] < one[id4 - 1]) {
                    id1 = id4 - 1;
                }
                if(tmp < one[id1] + four[id4]) {
                    tmp = one[id1] + four[id4];
                }
            }
            sum = Math.Max(sum, tmp);

            Console.WriteLine(Math.Max(sum, 0));
        }
