                v[i] = xv[1];
            }
            // sigma vの事前計算
            long[] va = new long[n];
            va[0] = v[0];
            for(int i=1;i<n;++i)
            {
                va[i] = va[i - 1] + v[i];
            }
            long[] vb = new long[n];
            vb[n - 1] = v[n - 1];
            for(long i=n-2;i>=0;--i)
            {
                vb[i] = vb[i + 1] + v[i];
            }

            long max = 0;
            for(int i=-1;i<=n-1;++i)
            {
                for(int j=i+1;j<=n;++j)
                {
                    max = Math.Max(max, CalcCal(i, j, x, v, c,va,vb));
                    max = Math.Max(max, CalcCalAnother(i, j, x, v, c,va,vb));
                }
