            //if (b >= 0)
            //{
            //    for (long i = b; i < v.Length; ++i)
            //    {
            //        tmp0 += v[i];
            //    }
            //}
            if (0 <= b && b < x.Length)
            {
                tmp0 += vb[b];
                tmp0 -= (c - x[b]); }
            return tmp0;
        }
        private static long CalcCalAnother(long a, long b, long[] x, long[] v, long c, long[] va, long[] vb)
        {
            long tmp0 = 0;
            //for (long i = 0; i <= a; ++i)
            //{
            //    tmp0 += v[i];
