        for (int i = N; i >= 0; i--)
        {
            R[i] = R[i + 1] - Abs(XV[i + 1][0] - XV[i][0]) + XV[i][1];
        }
        var max = 0L;var res = 0L;
        for (int i = N; i >= 0; i--)
        {
            chmax(ref max, R[i + 1]);
            chmax(ref res, max + L[i] - XV[i][0]);
        }
        max = 0;
        for (int i = 0; i < N+1; i++)
        {
            chmax(ref max, L[i]);
            chmax(ref res, max + R[i + 1] - C + XV[i + 1][0]);
        }
        WriteLine(res);
    }
}

