        {
            SolveA(args);
            //SolveB(args);
            //SolveC(args);
            //SolveD(args);


        }
        static void SolveA(string[] args)
        {
            long[] nc = ReadAndParseLongArr();
            long n = nc[0];
            long c = nc[1];
            long[] x = new long[n];
            long[] v = new long[n];

            for (int i = 0; i < n; ++i)
            {
                long[] xv = ReadAndParseLongArr();
                x[i] = xv[0];
                v[i] = xv[1];
            }

            long max = 0;
            for(int i=-1;i<=n-1;++i)
            {
                for(int j=i+1;j<=n;++j)
                {
                    max = Math.Max(max, CalcCal(i, j, x, v, c));
                    max = Math.Max(max, CalcCalAnother(i, j, x, v, c));
                }
            }

            Console.WriteLine(max);
        }

        private static long CalcCal(long a, long b, long[] x, long [] v, long c)
        {
            long tmp0 = 0;
            for(long i=0; i<=a;++i)
            {
                tmp0 += v[i] ;
            }
            if (0 <= a && a < x.Length)
            { tmp0 -= 2 * x[a]; }
            if (b >= 0)
            {
                for (long i = b; i < v.Length; ++i)
                {
                    tmp0 += v[i];
                }
            }
            if (0 <= b && b < x.Length)
            { tmp0 -= (c - x[b]); }
            return tmp0;
        }
        private static long CalcCalAnother(long a, long b, long[] x, long[] v, long c)
        {
            long tmp0 = 0;
            for (long i = 0; i <= a; ++i)
            {
                tmp0 += v[i];
            }
            if (0 <= a && a < x.Length)
            { tmp0 -= x[a]; }
            if (b >= 0)
            {
                for (long i = b; i < v.Length; ++i)
                {
                    tmp0 += v[i];
                }
            }
            if (0 <= b && b < x.Length)
            { tmp0 -= 2*(c - x[b]); }
            return tmp0;
        }
    }
