    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var C = consoleReader.Long;
            var sushis = consoleReader.Repeat(N).Select(cr => new Sushi { x = cr.Long, v = cr.Long }).ToArray();

            var leftSum = new long[N];
            var rightSum = new long[N];
            var leftSum2 = new long[N];
            var rightSum2 = new long[N];
            var leftSum2m = new long[N];
            var rightSum2m = new long[N];
            leftSum[N - 1] = sushis[N - 1].v - (C - sushis[N - 1].x);
            leftSum2[N - 1] = leftSum[N - 1] - (C - sushis[N - 1].x);
            rightSum[0] = sushis[0].v - sushis[0].x;
            rightSum2[0] = rightSum[0] - sushis[0].x;
            long leftMax = leftSum2m[N - 1] = Math.Max(0, leftSum2[N - 1]);
            long rightMax = rightSum2m[0] = Math.Max(0, rightSum2[0]);
            for (int i = 1; i < N; i++)
            {
                var leftDistance = sushis[N - i].x - sushis[N - i - 1].x;
                leftSum[N - i - 1] = sushis[N - i - 1].v + leftSum[N - i] - leftDistance;
                leftSum2[N - i - 1] = leftSum[N - i - 1] - (C - sushis[N - i - 1].x);
                if (leftMax < leftSum2[N - i - 1])
                {
                    leftMax = leftSum2[N - i - 1];
                }
                leftSum2m[N - i - 1] = leftMax;

                var rightDistance = sushis[i].x - sushis[i - 1].x;
                rightSum[i] = sushis[i].v + rightSum[i - 1] - rightDistance;
                rightSum2[i] = rightSum[i] - sushis[i].x;
                if (rightMax < rightSum2[i])
                {
                    rightMax = rightSum2[i];
                }
                rightSum2m[i] = rightMax;
            }

            long max = new[] { leftSum[0], rightSum[N - 1], 0 }.Max();
            for (int i = 1; i < N; i++)
            {
                max = Math.Max(Math.Max(
                    leftSum[i] + rightSum2m[i - 1],
                    rightSum[N - i - 1] + leftSum2m[N - i]
                    ), max);
            }

            Console.WriteLine("leftSum   :{0}", string.Join(" ", leftSum));
            Console.WriteLine("leftSum2  :{0}", string.Join(" ", leftSum2));
            Console.WriteLine("leftSum2m :{0}", string.Join(" ", leftSum2m));
            Console.WriteLine("rightSum  :{0}", string.Join(" ", rightSum));
            Console.WriteLine("rightSum2 :{0}", string.Join(" ", rightSum2));
            Console.WriteLine("rightSum2m:{0}", string.Join(" ", rightSum2m));
            return max;
        }

        struct Sushi
        {
            public long x;
            public long v;
        }

