using System;
using System.Text;
using System.Collections.Generic;
using static System.Math;
using System.Linq;
using static System.Array;

namespace AtcoderExpress
{


    class Program
    {

        static void Main(string[] args)
        {
            var NC = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();

            var N = NC[0];
            var C = NC[1];

            var RightOnly = new long[N+1];
            var RightOnlyRepeat = new long[N + 1];
            var LeftOnly = new long[N + 1];
            var LeftOnlyRepeat = new long[N + 1];
            var CumValueRight = new long[N + 1];
            var LeftX = new long[N];
            var LeftV = new long[N];

            for (int i = 1; i <= N; i++)
            {
                var XV = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var X = XV[0];
                var V = XV[1];
                CumValueRight[i] = CumValueRight[i-1] + V; 
                //右回りでのみi個まで取得を許した場合の価値の最大値
                RightOnly[i] = Max(RightOnly[i - 1],CumValueRight[i] - X);
                //右回りで往復を考慮した時のi個まで取得可能とした場合の最大値
                RightOnlyRepeat[i] = Max(RightOnlyRepeat[i-1], CumValueRight[i] - 2*X);
                //左回り用の配列を用意
                LeftX[N - i] = X;
                LeftV[N - i] = V;
            }

            var CumValueLeft = new long[N + 1];
            for (int i = 1; i <= N; i++)
            {
                var X = C-LeftX[i-1];
                var V = LeftV[i-1];
                CumValueLeft[i] = CumValueLeft[i - 1]+V;
                //左回りでのみi個まで取得を許した場合の価値の最大値
                LeftOnly[i] = Max(LeftOnly[i - 1], CumValueLeft[i] - X);
                //左回りで往復を考慮したときのi個まで取得可能とした場合の最大値
                LeftOnlyRepeat[i] = Max(LeftOnlyRepeat[i-1],CumValueLeft[i]-2*X);
            }

            var ans = Max(RightOnly.Max(), LeftOnly.Max());

            //右回りから左回りに移行する場合
            for (int i = 1; i <= N; i++)
            {
                ans = Max(ans, RightOnlyRepeat[i] + LeftOnly[N - i]);
            }

            //左回りから右回りに移行する場合
            for (int i = 1; i <= N; i++)
            {
                ans = Max(ans, LeftOnlyRepeat[i] + RightOnly[N - i]);
            }

            Console.WriteLine(ans);
        }


    }
}

