using Assistant;

namespace ABC095D
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = ReadLong;
            var C = ReadLong;

            long[] xr = new long[N];
            long[] xl = new long[N];
            long[] vr = new long[N];
            long[] vl = new long[N];
            for (int i = 0; i < N; i++)
            {
                long index = N - i - 1;
                long x = ReadLong;
                long v = ReadLong;
                xr[i] = x;
                xl[index] = C - x;
                vr[i] = v;
                vl[index] = v;
            }

            for (int i = 0; i < N - 1; i++)
            {
                vr[i + 1] += vr[i];
                vl[i + 1] += vl[i];
            }

            long[] gr = new long[N];
            long[] gl = new long[N];
            for (int i = 0; i < N; i++)
            {
                gr[i] = vr[i] - xr[i];
                gl[i] = vl[i] - xl[i];
            }
            for (int i = 0; i < N - 1; i++)
            {
                gr[i + 1] = Math.Max(gr[i], gr[i + 1]);
                gl[i + 1] = Math.Max(gl[i], gl[i + 1]);
            }

            long ans = 0;
            for (int i = 0; i < N - 1; i++)
            {
                long[] cand = new long[4];
                cand[0] = vr[i] - 2 * xr[i] + gl[N - 2 - i];
                cand[1] = vl[i] - 2 * xl[i] + gr[N - 2 - i];

                ans = Math.Max(ans, cand.Max());
            }
            ans = Math.Max(ans, Math.Max(gr[N - 1], gl[N - 1]));

            Console.WriteLine(ans);
        }


    }


}

