        public const string SiteName    = "AtCoder";
        public const string ContestName = "arc096";
        public const string ProblemName = "B";

        public void Solve()
        {
            int  N = cin.ReadInt;
            long C = cin.ReadLong;

            long[] X = new long[N];
            long[] V = new long[N];

            for (int i = 0; i < N; i++)
            {
                X[i] = cin.ReadLong;
                V[i] = cin.ReadLong;
            }

            // leftCost[i] : i番目のスシに左から向かったときのコスト
            // right : 右
            long[] lCost = new long[N];
            long[] rCost = new long[N];

            for (int i = 0; i < N; i++)
            {
                lCost[i] = X[i];
                rCost[i] = C - lCost[i];
            }

            long[] lScore = new long[N + 1];
            long[] rScore = new long[N + 1];

            for (int i = 0; i < N; i++)
            {
                lScore[i + 1] = lScore[i] + V[i];
            }

            for (int i = 0; i < N; i++)
            {
                rScore[i + 1] = rScore[i] + V[N - 1 - i];
            }

            long ans = 0;

            // 左回りだけのとき

            for (int i = 0; i < N; i++)
            {
                long score = lScore[i + 1] - lCost[i];
                ans = Math.Max(ans, score);
            }

            // 右回りだけのとき

            for (int i = 0; i < N; i++)
            {
                long score = rScore[i + 1] - rCost[N - 1 - i];
                ans = Math.Max(ans, score);
            }

            // まず左で次右

            int midIndex = UpperBound(X, C / 2);

            if (midIndex == X.Length)
            {
                // 中間より先はない。よって、左と右のパターンはなし
                cou.WriteLine(ans);
                return;
            }

            int ind = 0;

            long left2Max = 0;

            for (int i = 0; i < midIndex; i++)
            {
                long score = lScore[i + 1] - lCost[i] * 2;
                left2Max = Math.Max(left2Max, score);
            }

            long left1Max = 0;

            for (int i = 0; i < midIndex; i++)
            {
                long score = lScore[i + 1] - lCost[i];
                left1Max = Math.Max(left1Max, score);
            }

            long right2Max = 0;

            for (int i = 0; i < N - midIndex; i++)
            {
                long score = rScore[i + 1] - rCost[N - 1 - i] * 2;
                right2Max = Math.Max(right2Max, score);
            }

            long right1Max = 0;

            for (int i = 0; i < N - midIndex; i++)
            {
                long score = rScore[i + 1] - rCost[N - 1 - i];
                right1Max = Math.Max(right1Max, score);
            }

            ans = Math.Max(ans, left1Max + right2Max);
            ans = Math.Max(ans, left2Max + right1Max);

            cou.WriteLine(ans);
        }
    }

