	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			long c = cin.Long();
			var xv = new Tuple<long, long>[n];
			for (int i = 0; i < n; i++) {
				long x = cin.Long();
				long v = cin.Long();
				xv[i] = new Tuple<long, long>(x, v);
			}

			long[] right = new long[n + 1];
			long[] left = new long[n + 1];

			long[] rightDist = new long[n + 1];
			long max = long.MinValue;
			long cal = 0;
			long current = 0;
			for (int i = 0; i < n; i++) {
				rightDist[i + 1] = xv[i].Item1;
				cal += xv[i].Item2 - (xv[i].Item1 - current);
				current = xv[i].Item1;
				max = Math.Max(max, cal);
				right[i + 1] = max;
			}

			long[] leftDist = new long[n + 1];
			max = long.MinValue;
			cal = 0;
			current = 0;
			for (int i = 0; i < n; i++) {
				int j = n - 1 - i;
				leftDist[i + 1] = c - xv[j].Item1;
				cal += xv[j].Item2 - (leftDist[i + 1] - current);
				current = leftDist[i + 1];
				max = Math.Max(max, cal);
				left[i + 1] = max;
			}

			long ans = 0;
			for (int i = 0; i <= n; i++) {
				ans = Math.Max(ans, left[i]);
				ans = Math.Max(ans, right[i]);
				ans = Math.Max(
					ans,
					left[i] + right[n - i] - leftDist[i]);
				ans = Math.Max(
					ans,
					right[i] + left[n - i] - rightDist[i]);
			}

			Console.WriteLine(ans);
		}
	}

	public class HashMap<TKey, TValue> : Dictionary<TKey, TValue>
