partial class Solver
{

    public void Run()
    {
        var N = ni();
        var C = nl();
        var x = new long[N];
        var v = new long[N];

        for (int i = 0; i < N; i++)
        {
            x[i] = nl();
            v[i] = nl();
        }

        long ans = 0;

        ans = Math.Max(ans, v.Sum() - C); // 1-loop

        var leftMax = new long[N];
        var leftReturnMax = new long[N];
        long leftSum = 0;
        var rightMax = new long[N];
        var rightReturnMax = new long[N];
        long rightSum = 0;

        for (int i = 0; i < N; i++)
        {
            leftSum += v[i];
            if (i - 1 >= 0)
            {
                leftMax[i] = leftMax[i - 1];
                leftReturnMax[i] = leftReturnMax[i - 1];
            }
            leftMax[i] = Math.Max(leftMax[i], leftSum - x[i]);
            leftReturnMax[i] = Math.Max(leftReturnMax[i], leftSum - x[i] * 2);
        }
        for (int i = N - 1; i >= 0; i--)
        {
            rightSum += v[i];
            if (i + 1 < N)
            {
                rightMax[i] = rightMax[i + 1];
                rightReturnMax[i] = rightReturnMax[i + 1];
            }
            rightMax[i] = Math.Max(rightMax[i], rightSum - (C - x[i]));
            rightReturnMax[i] = Math.Max(rightReturnMax[i], rightSum - (C - x[i]) * 2);
        }


        for (int i = 0; i < N; i++)
        {
            if (i + 1 < N)
                ans = Math.Max(ans, leftReturnMax[i] + rightMax[(i + 1)]);
            if (i - 1 >= 0)
                ans = Math.Max(ans, rightReturnMax[i] + leftMax[(i - 1)]);
        }

        cout.WriteLine(ans);
    }
}

