        public const string ContestName = "arc096";
        public const string ProblemName = "B";

        public void Solve()
        {
            int  N = cin.ReadInt;
            long C = cin.ReadLong;

            long[] X = new long[N];
            long[] V = new long[N];

            for (int i = 0; i < N; i++)
            {
                X[i] = cin.ReadLong;
                V[i] = cin.ReadLong;
            }

            long[] l1Max = new long[N + 1];
            long[] l2Max = new long[N + 1];
            long[] r1Max = new long[N + 1];
            long[] r2Max = new long[N + 1];

            long sumL = 0;

            for (int i = 0; i < N; i++)
            {
                sumL         += V[i];
                l1Max[i + 1] =  Math.Max(l1Max[i], sumL - X[i]);
                l2Max[i + 1] =  Math.Max(l2Max[i], sumL - X[i] * 2);
            }

            long sumR = 0;

            for (int i = N - 1; i >= 0; i--)
            {
                sumR     += V[i];
                r1Max[i] =  Math.Max(r1Max[i + 1], sumR - (C - X[i]));
                r2Max[i] =  Math.Max(r2Max[i + 1], sumR - (C - X[i]) * 2);
            }

            long ans = 0;

            for (int i = 0; i <= N; i++)
            {
                ans = Math.Max(ans, l1Max[i] + r2Max[i]);
                ans = Math.Max(ans, l2Max[i] + r1Max[i]);
            }

            cou.WriteLine(ans);
        }
    }


