			x[i] = GetLong();
			v[i] = GetLong();

			y[N - 1 - i] = C - x[i];
			u[N - 1 - i] = v[i];
		}

		Console.WriteLine(Math.Max(cw(N, C, x, v), cw(N, C, y, u)));
	}

	private static long cw(int N, long C, long[] x, long[] v)
	{
		long[] vSum = new long[N + 1];
		for(int i = 0; i < N; i++)
			vSum[i + 1] = vSum[i] + v[i];

		long[] preMax = new long[N + 1];
		for(int i = 0; i < N; i++)
			preMax[i + 1] = Math.Max(preMax[i], vSum[i + 1] - 2 * x[i]);

		long res = 0;
		for(int i = 0; i < N; i++)
		{
			long tmp = vSum[N] - vSum[i] - (C - x[i]);
			res = Math.Max(res, preMax[i] + tmp);
		}

		return res;
	}
}


