function Main(input) {
    let cin = new Inputer(input);
    let N = cin.getInt(), C = cin.getInt();
    let X = new Array(N+1); X[0] = 0;
    let V = new Array(N+1); V[0] = 0;
    for (let n = 1; n <= N; n++) {
        X[n] = cin.getInt(); V[n] = cin.getInt();
    }
    X.push(C);
//時計回り
    let L = new Array(N+1);
    L[0] = 0;
    for (let n = 1; n <= N; n++) {
        L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
    }
    let R = new Array(N+1);
    R[N] = 0;
    for (let n = N-1; n >= 0; n--) {
        R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
    }
    let ans = Number.MIN_SAFE_INTEGER;
    for (let n = 0; n <= N; n++) {
        ans = Math.max(ans, L[n]);
        for (let m = n; m < N; m++) {
            let s = L[n] - X[n] + R[m];
            ans = Math.max(ans, s);
        }
    }
//反時計回り
    for (let n = 0; n < X.length; n++) {
        X[n] = C - X[n];
    }
    X.reverse();
    V.shift(); V.push(0); V.reverse();
    L[0] = 0;
    for (let n = 1; n <= N; n++) {
        L[n] = L[n-1] + V[n] - (X[n] - X[n-1]);
    }
    R[N] = 0;
    for (let n = N-1; n >= 0; n--) {
        R[n] = R[n+1] + V[n+1] - (X[n+2] - X[n+1]);
    }
    for (let n = 0; n <= N; n++) {
        ans = Math.max(ans, L[n]);
        for (let m = n; m < N; m++) {
            let s = L[n] - X[n] + R[m];
            ans = Math.max(ans, s);
        }
    }
    console.log(ans);
}
