class Problem
  attr_accessor *(?a..?z).to_a.map(&:to_sym)
  def initialize
    @n,@c = gets.split.map(&:to_i)
    @x,@v = Array.new(n){ gets.split.map(&:to_i) }.transpose
  end

  def init
    init_left
    init_right
  end

  def cs(a)
    a.each_with_object([0]) { |v, h| h << h[-1] + v }
  end

  def cs_max(a)
    ans = a.each_with_object([-10**15]) { |v,h| h << [h[-1], v].max }
    ans[1..]
  end

  def init_left
    @left_x = [0] + x
    @left = cs(v)
    @left_d = @left.zip(@left_x).map{|a,b|a-b}
    @left_2d = @left_d.zip(@left_x).map{|a,b|a-b}
    @left_d_max = cs_max(@left_d)
    @left_2d_max = cs_max(@left_2d)
  end

  def init_right
    @right_x = [0] + x.reverse.map { c - _1 }
    @right = cs(v.reverse)
    @right_d = @right.zip(@right_x).map{|a,b|a-b}
    @right_2d = @right_d.zip(@right_x).map{|a,b|a-b}
    @right_d_max = cs_max(@right_d)
    @right_2d_max = cs_max(@right_2d)
  end

  def solve
    init
    ans = 0
    0.upto(n) do |i|
      j = n - i
      ans = max(ans, @left_2d_max[i] + @right_d_max[j])
      ans = max(ans, @left_d_max[i] + @right_2d_max[j])
    end
    ans
  end

  def show(ans)
    pp ans
  end

  def max(a,b)
    a < b ? b : a
  end

  def max_with_index(a)
    maxi = a.max
    [maxi, a.index(maxi)]
  end
end

