int main() {
  ll N, C;

  cin >> N >> C;

  vector<ll> forOnlyLst;
  vector<ll> forTurnLst;
  vector<ll> bakOnlyLst;
  vector<ll> bakTurnLst;

  vector<P> xvs(N);
  for (ll i = 0; i < N; i++) {
    cin >> xvs[i].first >> xvs[i].second;
  }

  sort(xvs.begin(), xvs.end());

  ll acc = 0;
  for (ll i = 0; i < N; i++) {
    if (2 * xvs[i].first > C) break;
    acc += xvs[i].second;
    forOnlyLst.emplace_back(acc - xvs[i].first);
    forTurnLst.emplace_back(acc - 2 * xvs[i].first);
  }

  acc = 0;
  for (ll i = 0; i < N; i++) {
    if (2 * (C - xvs[N - 1 - i].first) > C) break;
    acc += xvs[N - 1 - i].second;
    bakOnlyLst.emplace_back(acc - (C - xvs[N - 1 - i].first));
    bakTurnLst.emplace_back(acc - 2 * (C - xvs[N - 1 - i].first));
  }

  ll max_fO = LONG_LONG_MIN;
  if (!forOnlyLst.empty())
    max_fO = *max_element(forOnlyLst.begin(), forOnlyLst.end());
  ll max_fT = LONG_LONG_MIN;
  if (!forTurnLst.empty())
    max_fT = *max_element(forTurnLst.begin(), forTurnLst.end());
  ll max_bO = LONG_LONG_MIN;
  if (!bakOnlyLst.empty())
    max_bO = *max_element(bakOnlyLst.begin(), bakOnlyLst.end());
  ll max_bT = LONG_LONG_MIN;
  if (!bakTurnLst.empty())
    max_bT = *max_element(bakTurnLst.begin(), bakTurnLst.end());

  ll ans = max(max_fO, max_fT + max_bO);
  ans = max(ans, max_bO);
  ans = max(ans, max_bT + max_fO);

  cout << ans << endl;

  return 0;
}

