		vSum[i] = vSum[i-1] + v[i]
	}

	// s1[i] = 時計回りにi個以下を食べる場合の最適値
	s1 := make([]int, N+1)
	max := 0
	for i := 1; i <= N; i++ {
		max = Max(max, vSum[i]-x[i])
		s1[i] = max
	}
	// s2[i] = 反時計回りにi個以下を食べる場合の最適値
	s2 := make([]int, N+1)
	max = 0
	for i := 1; i <= N; i++ {
		idx := N + 1 - i
		max = Max(max, vSum[N]-vSum[idx-1]-(C-x[idx]))
		s2[i] = max
	}

	ans := Max(Max(s1...), Max(s2...))
	for i := 1; i < N; i++ {
		// 時計回りにi個食べてからスタートに戻って、反時計周りにN-i個食べる場合の最適値
		localAns := vSum[i] - 2*x[i] + s2[N-i]
		ans = Max(ans, localAns)
	}
	for i := 1; i < N; i++ {
