func Solve(in io.Reader, out io.Writer) {
	var n, c int64
	fmt.Fscan(in, &n, &c)

	var pos = make([]int64, n+1)
	var cal = make([]int64, n+1)

	var i, j, x, v int64
	for i = 0; i < n; i++ {
		fmt.Fscan(in, &x, &v)

		pos[i+1] = pos[i]
		cal[i+1] = cal[i]
		for j = i; j >= 0; j-- {
			m1 := x - pos[j]
			m2 := pos[j] + (c - x)
			m := min(m1, m2)

			if v-m+cal[j] >= cal[i+1] {
				pos[i+1] = x
				cal[i+1] = v - m + cal[j]
			}
		}
	}

	fmt.Fprintln(out, cal[n])
}

func min(x, y int64) int64 {
	if x < y {
		return x
	}
	return y
}

