func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	c := getNextInt64(scanner)

	sushi := make([]Sushi, n)
	for i := 0; i < n; i++ {
		sushi[i].x = getNextInt64(scanner)
		sushi[i].v = getNextInt64(scanner)
	}
	sumL := make([]int64, n+1)
	sumR := make([]int64, n+1)
	ml := make([]Max, n+1)
	mr := make([]Max, n+1)

	var ans, maxL, maxR int64

	for i := 0; i < n; i++ {
		sumL[i+1] = sumL[i] + sushi[i].v - sushi[i].x
		if i > 0 {
			sumL[i+1] += sushi[i-1].x
		}
		ml[i+1] = ml[i]
		if sumL[i+1] > maxL {
			maxL = sumL[i+1]
			ml[i+1].v = maxL
			ml[i+1].i = i
		}

		sumR[i+1] = sumR[i] + sushi[n-i-1].v - (c - sushi[n-i-1].x)
		if i > 0 {
			sumR[i+1] += c - sushi[n-i].x
		}
		mr[i+1] = mr[i]

		if sumR[i+1] > maxR {
			maxR = sumR[i+1]
			mr[i+1].v = maxR
			mr[i+1].i = i
		}
	}

	ans = 0

	for i := 0; i < n; i++ {
		if ans < ml[i+1].v {
			ans = ml[i+1].v
		}
		if ans < ml[i+1].v+mr[n-i-1].v-sushi[i].x {
			ans = ml[i+1].v + mr[n-i-1].v - sushi[i].x
		}
		if ans < mr[i+1].v {
			ans = mr[i+1].v
		}
		if ans < mr[i+1].v+ml[n-i-1].v-(c-sushi[n-i-1].x) {
			ans = mr[i+1].v + ml[n-i-1].v - (c - sushi[n-i-1].x)
		}
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

