	for i := 1; i < N+1; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d %d", &xs[i], &vs[i])
		sumv[i] = sumv[i-1] + vs[i]
	}
	xs[N+1] = C
	vs[N+1] = 0
	sumv[N+1] = sumv[N]

	leftMax := make([]int, N+2)
	left2Max := make([]int, N+2)
	for left := 1; left < N+1; left++ {
		v := sumv[left]
		d := xs[left]
		leftMax[left] = max(leftMax[left-1], v-d)
		left2Max[left] = max(left2Max[left-1], v-2*d)
	}

	rightMax := make([]int, N+2)
	right2Max := make([]int, N+2)
	for right := N; right > 0; right-- {
		v := sumv[N] - sumv[right-1]
		d := C - xs[right]
		rightMax[right] = max(rightMax[right+1], v-d)
		right2Max[right] = max(right2Max[right+1], v-2*d)
	}

	ans := 0
	for i := 0; i <= N; i++ {
		c1 := left2Max[i] + rightMax[i+1]
		c2 := leftMax[i] + right2Max[i+1]
