const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N, C := sc.nextInt(), sc.nextInt()
	X := make([]int, N)
	V := make([]int, N)
	D := make([]int, N+1)
	now := 0
	for i := 0; i < N; i++ {
		X[i] = sc.nextInt()
		V[i] = sc.nextInt()
		D[i] = X[i] - now
		now += D[i]
	}
	D[N] = C - now
	Left := make([]int, N)
	Right := make([]int, N)
	best, d, v := 0, 0, 0
	for i := 0; i < N; i++ {
		d += D[i]
		v += V[i]
		best = max(best, v-d)
		Left[i] = best
	}
	best, d, v = 0, 0, 0
	for i := N; i > 0; i-- {
		d += D[i]
		v += V[i-1]
		best = max(best, v-d)
		Right[N-i] = best
	}
	//fmt.Fprintln(wtr, Left, Right)
	ans := 0
	d, v = 0, 0
	// Left -> Right
	for i := 0; i < N; i++ {
		v += V[i]
		d += D[i]
		sum := v - d
		if i < N-1 && 0 < Right[N-i-2]-d {
			sum += Right[N-i-2] - d
		}
		//fmt.Fprintln(wtr, Left[i], d, sum)
		ans = max(ans, sum)
	}
	// Right -> Left
	d, v = 0, 0
	for i := 0; i < N; i++ {
		v += V[N-1-i]
		d += D[N-i]
		sum := v - d
		if i < N-1 && 0 < Left[N-i-2]-d {
			sum += Left[N-i-2] - d
		}
		//fmt.Fprintln(wtr, v, d, sum)
		ans = max(ans, sum)
	}

	fmt.Fprintln(wtr, ans)
}

