package main

import (
	"fmt"
	"sort"
)

type pair struct {
	x, v int
}

func max(slice ...int) int {
	sort.Ints(slice)
	return slice[len(slice)-1]
}

func main() {
	var N, C int
	fmt.Scan(&N, &C)

	ps := make([]pair, N)
	for i := range ps {
		fmt.Scan(&ps[i].x, &ps[i].v)
	}

	rV := make([]int, N)
	for i := range ps {
		if i == 0 {
			rV[i] = ps[i].v
		} else {
			rV[i] = rV[i-1] + ps[i].v
		}
	}

	rV2 := make([]int, N)
	for i := range rV {
		rV[i] -= ps[i].x
		rV2[i] = rV[i] - ps[i].x
	}

	maxRV := make([]int, N)
	for i := range maxRV {
		if i == 0 {
			maxRV[i] = rV[i]
		} else {
			maxRV[i] = max(rV[i], maxRV[i-1])
		}
	}

	lV := make([]int, N)
	for i := range ps {
		if i == 0 {
			lV[i] = ps[len(ps)-1-i].v
		} else {
			lV[i] = lV[i-1] + ps[len(ps)-1-i].v
		}
	}

	lV2 := make([]int, N)
	for i := range lV {
		lV[i] -= C - ps[len(ps)-1-i].x
		lV2[i] = lV[i] - (C - ps[len(ps)-1-i].x)
	}

	maxLV := make([]int, N)
	for i := range maxLV {
		if i == 0 {
			maxLV[i] = lV[i]
		} else {
			maxLV[i] = max(lV[i], maxLV[i-1])
		}
	}

	ans := max(0, maxRV[len(rV)-1], maxLV[len(lV)-1])
	for i := range rV {
		if i < len(rV)-1 {
			ans = max(ans, rV2[i]+maxLV[len(lV)-2-i], lV2[i]+maxRV[len(rV)-2-i])
		}
	}

	fmt.Println(ans)
}

