func main() {
	var N int
	var C int64
	fmt.Scanf("%d%d", &N, &C)
	x, v := make([]int64, N), make([]int64, N)
	for i := 0; i < N; i++ {
		fmt.Scanf("%d%d", &x[i], &v[i])
	}

	q1x, q2Cmx := make([]int64, N), make([]int64, N)
	svi, I1, I2, q1xI1, q2CmxI2 := int64(0), -1, N, int64(0), int64(0)
	for i := 0; i < N; i++ {
		svi += v[i]
		q1x[i] = svi - x[i]
		if q1x[i] > q1xI1 {
			I1 = i
			q1xI1 = q1x[i]
		}
	}
	svi = 0
	for i := N - 1; i >= 0; i-- {
		svi += v[i]
		q2Cmx[i] = svi - (C-x[i])
		if q2Cmx[i] > q2CmxI2 {
			I2 = i
			q2CmxI2 = q2Cmx[i]
		}
	}

	max := map[bool]int64{true: q1xI1, false: q2CmxI2}[q1xI1 > q2CmxI2]
	for i2 := N - 1; i2 >= I2; i2-- {
		for i1 := 0; i1 < I1 && i1 < i2 && x[i1] < C-x[i2]; i1++ {
			if q1x[i1] + q2Cmx[i2] - x[i1] > max {
				max = q1x[i1] + q2Cmx[i2] - x[i1]
			}
		}
		if I1 < i2 {
			if q1x[I1] + q2Cmx[i2] - map[bool]int64{true: x[I1], false: C-x[i2]}[x[I1] < C-x[i2]] > max {
				max = q1x[I1] + q2Cmx[i2] - map[bool]int64{true: x[I1], false: C-x[i2]}[x[I1] < C-x[i2]]
			}
		}
	}
	fmt.Printf("%d\n", max)
}

