        s = append([]sushi{sushi{0, 0}}, s...)
        s = append(s, sushi{c, 0})

        var eatr, eatl, maxr, maxr2 []int64
        wg := &sync.WaitGroup{}
        wg.Add(2)
        go func() {
                eatr = make([]int64, len(s))
                eatr[0] = s[0].v
                for i := 1; i < len(s); i++ {
                        eatr[i] = eatr[i-1] + s[i].v
                }

                wg.Add(2)
                go func() {
                        maxr = make([]int64, len(s))
                        maxr[0] = eatr[0] - s[0].x
                        for i := 1; i < len(s); i++ {
                                maxr[i] = eatr[i] - s[i].x
                                if maxr[i-1] > maxr[i] {
                                        maxr[i] = maxr[i-1]
                                }
                        }
                        wg.Done()
                }()
                go func() {
                        maxr2 = make([]int64, len(s))
                        maxr2[0] = eatr[0] - 2*s[0].x
                        for i := 1; i < len(s); i++ {
                                maxr2[i] = eatr[i] - 2*s[i].x
                                if maxr2[i-1] > maxr2[i] {
                                        maxr2[i] = maxr2[i-1]
                                }
                        }
                        wg.Done()
                }()
                wg.Done()
        }()
        go func() {
                eatl = make([]int64, len(s))
                eatl[len(s)-1] = s[len(s)-1].v
                for i := len(s) - 2; i >= 0; i-- {
                        eatl[i] = eatl[i+1] + s[i].v
                }
                wg.Done()
        }()
        wg.Wait()

        var max int64
        for i := 1; i < len(s); i++ {
                call := eatl[i] - c + s[i].x
                cal := maxr2[i-1] + call
                if cal > max {
                        max = cal
                }
                call = eatl[i] - 2*c + 2*s[i].x
                cal = maxr[i-1] + call
                if cal > max {
                        max = cal
                }
        }
        fmt.Println(max)
}

