		x, v := ReadInt2()
		X = append(X, x)
		V = append(V, v)
	}

	revX, revV := make([]int, n), make([]int, n)
	for i := 0; i < n; i++ {
		revV[i] = V[n-1-i]
		revX[i] = c - X[n-1-i]
	}

	sumX, sumV, revSumX, revSumV := make([]int, n), make([]int, n), make([]int, n), make([]int, n)
	sumX[0], sumV[0], revSumX[0], revSumV[0] = X[0], V[0], revX[0], revV[0]
	for i := 1; i < n; i++ {
		sumX[i] = sumX[i-1] + X[i]
		sumV[i] = sumV[i-1] + V[i]
		revSumX[i] = revSumX[i-1] + revX[i]
		revSumV[i] = revSumV[i-1] + revV[i]
	}

	maxCal, revMaxCal := make([]int, n), make([]int, n)
	for i := 0; i < n; i++ {
		ChMax(&maxCal[i], sumV[i]-X[i])
		ChMax(&revMaxCal[i], revSumV[i]-revX[i])
		if i >= 1 {
			ChMax(&maxCal[i], maxCal[i-1])
			ChMax(&revMaxCal[i], revMaxCal[i-1])
		}
	}

	ans := 0
	ChMax(&ans, maxCal[n-1])
	ChMax(&ans, revMaxCal[n-1])

	// 時計回り→反時計回り
	for i := 0; i <= n-2; i++ {
		tmpAns := sumV[i] - 2*X[i]
		tmpAns += revMaxCal[n-1-(i+1)]
		ChMax(&ans, tmpAns)
	}
	// 反時計回り→時計回り
	for i := 0; i <= n-2; i++ {
		tmpAns := revSumV[i] - 2*revX[i]
		tmpAns += maxCal[n-1-(i+1)]
		ChMax(&ans, tmpAns)
	}

	fmt.Println(ans)
}

// ChMax accepts a pointer of integer and a target value.
// If target value is LARGER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMax(updatedValue *int, target int) bool {
	if *updatedValue < target {
		*updatedValue = target
		return true
	}
	return false
}

