func solve() {
	n, c := ri(), ri()
	x, v := riis(n)
	intsPushFront(&x, 0)
	intsPushFront(&v, 0)
	intsPushBack(&x, c)
	intsPushBack(&v, 0)

	f := func(x, v []int) int {
		m := len(x)
		vCumsum := make([]int, m)
		for i := 1; i < m; i++ {
			vCumsum[i] = vCumsum[i-1] + v[i]
		}
		leftScore := make([]int, m)
		for i := 1; i < m; i++ {
			leftScore[i] = vCumsum[i] - x[i]*2
		}
		bestLeftScore := make([]int, m)
		for i := 1; i < m; i++ {
			bestLeftScore[i] = larger(bestLeftScore[i-1], leftScore[i])
		}

		maxScore := 0
		for r := 1; r < m; r++ {
			score := 0
			score += bestLeftScore[r-1]
			score += (vCumsum[m-1] - vCumsum[r-1]) - (x[m-1] - x[r])
			chmax(&maxScore, score)
		}
		return maxScore
	}

	mx := 0
	clockwise := f(x, v)
	chmax(&mx, clockwise)

	intsReverse(x)
	for i := range x {
		x[i] = c - x[i]
	}
	intsReverse(v)
	reverse := f(x, v)
	chmax(&mx, reverse)
	pln(mx)
}

