	auto C = RD!long;

	auto x = new long[](N);
	auto v = new long[](N);
	foreach (i; 0..N)
	{
		x[i] = RD!long;
		v[i] = RD!long;
	}
	auto dp = new long[2][2][](N+1);
	foreach (i; 0..N)
	{
		dp[i+1][0][0] = dp[i][0][0] + v[i];
	}
	foreach (i; 0..N)
	{
		dp[i+1][0][1]  = dp[i+1][0][0] - x[i] * 2;
		dp[i+1][0][0] -= x[i];
	}
	foreach_reverse (i; 0..N)
	{
		dp[i][1][0] = dp[i+1][1][0] + v[i];
	}
	foreach_reverse (i; 0..N)
	{
		dp[i][1][1]  = dp[i][1][0] - (C - x[i]) * 2;
		dp[i][1][0] -= C - x[i];
	}

	long[2][2] best, bestPos;
	foreach (i; 0..N)
	{
		foreach (j; 0..2)
		{
			if (dp[i][0][j] > best[0][j])
			{
				best[0][j] = dp[i][0][j];
				bestPos[0][j] = i;
			}
		}
	}
	foreach (j; 0..2)
	{
		long best2;
		foreach_reverse (i; bestPos[0][j^1]+1..N)
		{
			if (dp[i][1][j] > best2)
			{
				best2 = dp[i][1][j];
			}
		}
		if (best2 > 0)
			best[0][j^1] += best2;
	}

	foreach_reverse (i; 0..N)
	{
		foreach (j; 0..2)
		{
			if (dp[i][1][j] > best[1][j])
			{
				best[1][j] = dp[i][1][j];
				bestPos[1][j] = i;
			}
		}
	}
	foreach (j; 0..2)
	{
		long best2;
		foreach (i; 0..bestPos[1][j^1])
		{
			if (dp[i][0][j] > best2)
			{
				best2 = dp[i][0][j];
			}
		}
		if (best2 > 0)
			best[1][j^1] += best2;
	}

	long ans;
	foreach (i; 0..2)
	{
		foreach (j; 0..2)
		{
			ans = max(ans, best[i][j]);
		}
	}

	writeln(ans);
	stdout.flush();
}

