class StopSushi(object):
    """docstring for StopSushi"""
    def __init__(self):
        self.N, self.C = get_next_ints()
        self.sushi = []
        half_point = int(self.C/2)
        over_half = False
        self.half_index = -1
        for i in range(self.N):
            sushi = get_next_ints()
            self.sushi.append(sushi)
            if not over_half and sushi[0] > half_point:
                self.half_index = i-1 if i > 0 else 0
                over_half = True
        pass

    def calc_dist(self, p1, p2):
        clockwise = abs(p2 - p1)
        counter_clock = p1 + abs(p2 - self.C)
        return min(clockwise, counter_clock)


    def solve(self):
        self.clock_dp = np.zeros(self.N, dtype=np.int)
        self.clock_dp[0] = self.sushi[0][1] - self.sushi[0][0]
        for i in range(1, self.N):
            dist = self.sushi[i][0] - self.sushi[i-1][0]
            self.clock_dp[i] = self.clock_dp[i-1] + self.sushi[i][1] - dist
        # print('clock', self.clock_dp)
        # print('clock_right', self.clock_dp[:self.half_index+1])
        clock_max = self.clock_dp[np.argmax(self.clock_dp)]
        # print(clock_max)

        self.counter_clock_dp = np.zeros(self.N, dtype=np.int)
        self.counter_clock_dp[self.N-1] = self.sushi[self.N-1][1] - abs(self.sushi[self.N-1][0] - self.C)
        for i in range(self.N - 1)[::-1]:
            # dist = self.sushi[i][0] - self.sushi[i+1][0]
            dist = self.sushi[i+1][0] - self.sushi[i][0]
            self.counter_clock_dp[i] = self.counter_clock_dp[i+1] + self.sushi[i][1] - dist

        # print('counter', self.counter_clock_dp)
        # print('counter_left', self.counter_clock_dp[self.half_index+1:])
        counter_max = self.counter_clock_dp[np.argmax(self.counter_clock_dp)]
        # print(counter_max)

