class Cell(object):
    def __init__(self, pos, value, left, right):
        self.pos = pos
        self.value = value
        self.left = left
        self.right = right

    def left_distance(self, c):
        d = self.pos - self.left.pos
        if d < 0:
            d += c
        return d

    def right_distance(self, c):
        d = self.right.pos - self.pos
        if d < 0:
            d += c
        return d

    def __repr__(self):
        return repr((self.pos, self.value))

def solve(current, c):
    if current.left == current.right:
        # rest 1 sushi
        l_val = current.left.value - current.left_distance(c)
        r_val = current.right.value - current.right_distance(c)
        return max(l_val, r_val, 0)
    else:
        l_cell = Cell(current.left.pos, 0, current.left.left, current.right)
        r_cell = Cell(current.right.pos, 0, current.left, current.right.right)

        l_val = solve(l_cell, c) + current.left.value - current.left_distance(c)
        r_val = solve(r_cell, c) + current.right.value - current.right_distance(c)
        return max(l_val, r_val, 0)

