def solve(N: int, C: int, x: "List[int]", v: "List[int]"):

    # 時計回り
    m = -INF
    for i in range(N):
        cost = []
        benefit = []
        # i番目でターン
        for j in range(i+1):
            if j == 0:
                cost.append(x[j])
                benefit.append(v[j])
            else:
                cost.append(cost[-1]+x[j]-x[j-1])
                benefit.append(benefit[-1]+v[j])
        turn = x[j]
        for j in range(N-1, i, -1):
            if j == N-1:
                cost.append(cost[-1]+(C-x[j])+turn)
                benefit.append(benefit[-1]+v[j])
            else:
                cost.append(cost[-1]+(C-x[j])-(C-x[j+1]))
                benefit.append(benefit[-1]+v[j])
        callory = [b-c for c, b in zip(cost, benefit)]
        # print(callory, cost, benefit)
        m = max(m, max(callory))

    # 半時計回りな
    x = list(reversed([C-v for v in x]))
    v = list(reversed(v))
    for i in range(N):
        cost = []
        benefit = []
        # i番目でターン
        for j in range(i+1):
