fn _solve(c: i64, pos: i64, s: usize, e:usize, xv: &Vec<(i64, i64)>, cal: i64) -> i64 {
    use std::cmp::max;

    if s==e {
        cal
    } else {
        let (rx, rv) = xv[s];
        let (lx, lv) = xv[e-1];

        let rd = if pos > rx {
            c - pos + rx
        } else {
            rx - pos
        };

        let ld = if pos > lx {
            pos - lx
        } else {
            c - lx + pos
        };

        max(cal, max(_solve(c, rx, s+1, e, xv, cal + rv - rd),
                     _solve(c, lx, s, e-1, xv, cal + lv - ld)))
    }
}

fn solve(c: i64, mut xv: Vec<(i64, i64)>) -> i64 {
    use std::cmp::max;

    xv.sort();

    _solve(c, 0, 0, xv.len(), &xv, 0)
}

fn main() {
    let (n, c) = parse_line!(usize, i64);

    println!("{}", solve(c, (0..n).map(|_| parse_line!(i64, i64)).collect()));
}

