fn solve(sushi: &Vec<(i64, i64)>, c: i64) -> i64 {
    let n = sushi.len();
    let mut imo_value = vec![];

    {
        imo_value.push(0);
        let mut sum = 0;
        for &(pos, val) in sushi.iter() {
            sum += val;
            imo_value.push(sum);
        }
    }

    let mut imo_back_reverse = vec![];
    imo_back_reverse.push((0, 0, 0));
    for i in (0..n).rev() {
        let &(_, sum, best) = imo_back_reverse.last().unwrap();
        let to_dist = (c - sushi[i].0) * 2;
        let value = sum + sushi[i].1;
        imo_back_reverse.push((to_dist, value, max(best, value - to_dist)));
    }

    let mut max_value = 0;
    for i in 0..n+1 {
        let (_, _, back) = imo_back_reverse[n-i];
        let mut go = imo_value[i];
        if i >= 1 {
            go -= sushi[i-1].0;
        }
        max_value = max(max_value, back + go);
    }
    max_value
}

