fn main() {
    let (n, c) = get!(usize, i64);
    let mut sushis = get!(i64, i64; n);

    // clockwise
    let cw_ds_max = {
        let mut v_sum = 0;
        let (mut c_max1, mut c_max2) = (0, 0);

        sushis
            .iter()
            .map(|(x, v)| {
                v_sum += v;
                c_max1 = max(c_max1, v_sum - x);
                c_max2 = max(c_max2, v_sum - 2 * x);
                (c_max1, c_max2)
            })
            .collect::<Vec<_>>()
    };

    // anti-clockwise
    sushis.reverse();
    let mut acw_ds_max = {
        let mut v_sum = 0;
        let (mut c_max1, mut c_max2) = (0, 0);

        sushis
            .iter()
            .map(|(x, v)| {
                v_sum += v;
                c_max1 = max(c_max1, v_sum - (c - x));
                c_max2 = max(c_max2, v_sum - 2 * (c - x));
                (c_max1, c_max2)
            })
            .collect::<Vec<_>>()
    };
    acw_ds_max.reverse();

    let ans = cw_ds_max
        .into_iter()
        .enumerate()
        .map(|(i, (cw_c_max1, cw_c_max2))| {
            if i != n - 1 {
                let (acw_c_max1, acw_c_max2) = acw_ds_max[(i + 1) % n];
                max(cw_c_max1 + acw_c_max2, acw_c_max1 + cw_c_max2)
            } else {
                cw_c_max1
            }
        })
        .max()
        .unwrap();

    with_bufwriter(|mut out| writeln!(out, "{}", ans).unwrap());
}

