fn solve(N: usize, C: i64, xv: &Vec<(i64, i64)>) -> i64 {
    let mut rmax = vec![0; N];
    for i in 0..N {
        if i == 0 {
            rmax[0] = xv[0].1 - xv[0].0;
        } else {
            rmax[i] = rmax[i - 1] + xv[i].1 - (xv[i].0 - xv[i - 1].0);
        }
    }
    for i in 1..N {
        rmax[i] = std::cmp::max(rmax[i], rmax[i - 1]);
    }

    let mut ret = std::cmp::max(0, rmax[N - 1]);
    let mut cost_left = 0;
    for left in (1..N).rev() {
        cost_left += xv[left].1;
        let x_prev = if left == N - 1 {
            C
        } else {
            xv[left + 1].0
        };
        cost_left -= 2 * (x_prev - xv[left].0);
        chmax!(ret, cost_left + rmax[left - 1]);
    }
    ret
}

fn main() {
    input! {
        N: usize,
        C: i64,
        xv: [(i64, i64); N],
    }

    let mut ret = solve(N, C, &xv);

    let mut rev_xv = vec![];
    for (x, v) in xv.iter() {
        rev_xv.push((C - x.clone(), v.clone()));
    }
    rev_xv.reverse();
    chmax!(ret, solve(N, C, &rev_xv));

    println!("{}", ret);
}

