        let mut r_max = 0;
        for &xv in xv.iter().rev() {
            v += xv.1;
            let r = v - (c - xv.0);
            r_max = max(r_max, r);
            results_l.push(r_max);
        }
    }
    let mut r_max = max(results_r.pop().unwrap(), results_l.pop().unwrap());
    r_max = max(0, r_max);
    {
        let mut v = 0;
        for n in 0..xv.len() {
            let xv = xv[n];
            v += xv.1;
            let r = v - xv.0 * 2 + results_l.pop().unwrap();
            r_max = max(r_max, r);
        }
    }

    {
        let mut v = 0;
        for n in (0..xv.len()).rev() {
            let xv = xv[n];
            v += xv.1;
            let r = v - (c - xv.0) * 2 + results_r.pop().unwrap();
            r_max = max(r_max, r);
        }
    }
    r_max
}

