fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let c: i64 = itr.next().unwrap().parse().unwrap();
    let mut rx = vec![0i64; n];
    let mut rv = vec![0i64; n];
    for i in 0..n {
        rx[i] = itr.next().unwrap().parse().unwrap();
        rv[i] = itr.next().unwrap().parse().unwrap();
    }
    let mut lx = vec![0; n];
    let mut lv = rv.clone();
    let mut lmax = vec![0; n];
    let mut rmax = vec![0; n];
    lv.reverse();
    for i in 0..n {
        lx[i] = c - rx[n - 1 - i];
    }
    for i in 0..n - 1 {
        lv[i + 1] += lv[i];
        rv[i + 1] += rv[i];
        lmax[i + 1] = max(lmax[i], lv[i] - lx[i]);
        rmax[i + 1] = max(rmax[i], rv[i] - rx[i]);
    }

    let mut ans = 0i64;
    for i in 0..n {
        ans = max(ans, lv[i] - lx[i]);
        ans = max(ans, lv[i] - lx[i] * 2 + rmax[n - 1 - i]);
    }
    for i in 0..n {
        ans = max(ans, rv[i] - rx[i]);
        ans = max(ans, rv[i] - rx[i] * 2 + lmax[n - 1 - i]);
    }
    println!("{}", ans);
}

