        let (mut c_max1, mut c_max2) = (0, 0);

        sushis
            .iter()
            .map(|&(x, v)| {
                v_sum += v;
                c_max1 = max(c_max1, v_sum - x);
                c_max2 = max(c_max2, v_sum - 2 * x);
                (c_max1, c_max2)
            })
            .collect::<Vec<_>>()
    };

    // anti-clockwise
    sushis.reverse();
    let mut acw_ds_max = {
        let mut v_sum = 0;
        let (mut c_max1, mut c_max2) = (0, 0);

        sushis
