        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, c) = parse!(it, 2);
    let xv: Vec<(i64, i64)> = (0..n).map(|_| parse!(it, 2)).collect();
    let mut ret = 0i64;

    let mut pret = 0i64;
    let mut cur = 0i64;
    let mut curx = 0i64;
    for &(x, v) in xv.iter() {
        cur += v - (x - curx);
        pret = max(cur, pret);
        curx = x;
    }
    ret = max(ret, pret);

    let mut pret = 0i64;
    let mut cur = 0i64;
    let mut curx = c;
    for &(x, v) in xv.iter().rev() {
        cur += v - (curx - x);
        pret = max(cur, pret);
        curx = x;
    }
    ret = max(ret, pret);

    let mut pret = 0i64;
    let mut cur = 0i64;
    let mut curx = 0i64;
    for &(x, v) in xv.iter() {
        if x > (c / 2) {
            break;
        }
        cur += v - 2 * (x - curx);
        pret = max(cur, pret);
        curx = x;
    }
    let mut cur = pret;
    let mut curx = c;
    for &(x, v) in xv.iter().rev() {
        if x <= (c / 2) {
            break;
        }
        cur += v - (curx - x);
        pret = max(cur, pret);
        curx = x;
    }
    ret = max(ret, pret);

    let mut pret = 0i64;
    let mut cur = 0i64;
    let mut curx = c;
    for &(x, v) in xv.iter().rev() {
        if x <= (c / 2) {
            break;
        }
        cur += v - 2 * (curx - x);
        pret = max(cur, pret);
        curx = x;
    }
    let mut cur = pret;
    let mut curx = 0i64;
    for &(x, v) in xv.iter() {
        if x > (c / 2) {
            break;
        }
        cur += v - (x - curx);
        pret = max(cur, pret);
        curx = x;
    }
    ret = max(ret, pret);

    println!("{}", ret);
}

