fn main() {
    let mut scanner = Scanner::new(stdin());
    let params = scanner.read_vector::<i64>().unwrap();
    let (n, c) = (params[0] as usize, params[1]);
    let mut arr = vec![];
    for _ in 0..n {
        let line = scanner.read_vector::<i64>().unwrap();
        let (x, v) = (line[0], line[1]);
        arr.push((x, v));
    }
    let mut cumsum = vec![arr[0].1];
    for i in 0..(n - 1) {
        let prv = cumsum[i];
        cumsum.push(prv + arr[i + 1].1);
    }
    let mut left_maximum = vec![];
    let mut right_maximum = vec![];
    for i in 0..n {
        let prv_left = if i == 0 { 0 } else { left_maximum[i - 1] };
        let prv_right = if i == 0 { 0 } else { right_maximum[i - 1] };
        left_maximum.push(max(cumsum[i] - arr[i].0, prv_left));
        right_maximum.push(max(cumsum[i] - 2 * arr[i].0, prv_right));
    }
    let mut ans = left_maximum[n - 1];
    let mut sum = 0;
    for i in 1..(n + 1) {
        sum += arr[n - i].1;
        let left_sum = if i < n { sum - 2 * (c - arr[n - i].0) + left_maximum[n - i - 1] } else { 0 };
        let right_sum = if i < n { sum - (c - arr[n - i].0) + right_maximum[n - i - 1] } else { sum - (c - arr[n - i].0) };
        let best = max(left_sum, right_sum);
        ans = max(best, ans);
    }
    println!("{}", ans);
}


