macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize,
        c: isize,
        sushi: [(isize, isize); n]
    };

    let mut fwd_max:Vec<isize> = vec![0;n+1];
    let mut fwd_v:Vec<isize> = vec![0;n+1];
    let mut fwd_va:isize = 0;
    for i in 0..n {
        fwd_va += sushi[i].1;
        let fwd_vi = fwd_va - sushi[i].0;
        fwd_v[i+1] = fwd_vi - sushi[i].0;
        fwd_max[i+1] = std::cmp::max(fwd_max[i], fwd_vi);
    }

    let mut rev_max:Vec<isize> = vec![0;n+1];
    let mut rev_v:Vec<isize> = vec![0;n+1];
    let mut rev_va:isize = 0;
    for i in 0..n {
        let ii = n-1-i;
        rev_va += sushi[ii].1;
        let rev_vi = rev_va - (c - sushi[ii].0);
        rev_v[i+1] = rev_vi - (c - sushi[ii].0);
        rev_max[i+1] = std::cmp::max(rev_max[i], rev_vi);
    }

    let fmax = (0..n+1).map(|i| {
        rev_v[i] + fwd_max[n-i]
    }).max().unwrap();
    let rmax = (0..n+1).map(|i| {
        fwd_v[i] + rev_max[n-i]
    }).max().unwrap();

    println!("{}", std::cmp::max(fmax,rmax));
}

