}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let (n, c) = i.read2::<usize, isize>();
    let mut xv = Vec::new();
    for _ in 0..n {
        xv.push(i.read2::<isize, isize>());
    }
    writeln!(o, "{}", solve(c, &xv)).unwrap();
}
fn solve(c: isize, xv: &[(isize, isize)]) -> isize {
    let mut results_r = vec![0];
    {
        let mut v = 0;
        let mut r_max = 0;
        for &xv in xv {
            v += xv.1;
            r_max = max(r_max, v - xv.0);
            results_r.push(r_max);
        }
    }

    let mut results_l = vec![0];
    {
        let mut v = 0;
        let mut r_max = 0;
        for &xv in xv.iter().rev() {
            v += xv.1;
            r_max = max(r_max, v - (c - xv.0));
            results_l.push(r_max);
        }
    }
    let mut r_max = max(results_r.pop().unwrap(), results_l.pop().unwrap());
    {
        let mut v = 0;
        for xv in xv {
            v += xv.1;
            r_max = max(r_max, v - xv.0 * 2 + results_l.pop().unwrap());
        }
    }

    {
        let mut v = 0;
        for xv in xv.iter().rev() {
            v += xv.1;
            r_max = max(r_max, v - (c - xv.0) * 2 + results_r.pop().unwrap());
        }
    }
    max(0, r_max)
}

