fn solve(input: String) -> String {
    input!(input=>(n:usize c:i64){n;list:(i64,i64)});
    let mut max = 0;

    //時計回りにi、向き変えてj
    for i in 0..n + 1 {
        //時計回り分
        let a = if i != 0 {
            list.clone()
                .into_iter()
                .take(i)
                .map(|(_, v)| v)
                .sum::<i64>()
        } else {
            0
        };

        for j in 0..n - i + 1 {
            //反時計回り分
            let b = if j != 0 {
                list.clone()
                    .into_iter()
                    .skip(n - j)
                    .map(|(_, v)| v)
                    .sum::<i64>()
            } else {
                0
            };

            let cost1 = if i != 0 { list[i - 1].0 } else { 0 };
            let cost2 = if j != 0 { c - list[n - j].0 } else { 0 };
            let cost = std::cmp::min(cost1 * 2 + cost2, cost1 + cost2 * 2);
            let res = a + b - cost;
            if max < res {
                max = res
            }
        }
    }
    max.to_string()
}

