struct SegTree<T, F> {
    n: usize,
    node: Vec<T>,
    acc: F,
    init: T,
}

impl<T: Clone, F> SegTree<T, F> where F: Fn(&T, &T) -> T {
    pub fn new(n: usize, init: T, acc: F) -> SegTree<T, F> {
        let mut m = 1;
        while m < n {
            m *= 2;
        }
        SegTree {
            n: m,
            node: vec![init.clone(); m * 2],
            acc: acc,
            init: init,
        }
    }

    pub fn add(&mut self, pos: usize, val: T) {
        let mut x = pos + self.n - 1;
        self.node[x] = (self.acc)(&self.node[x], &val);
        while x > 0 {
            x = (x-1)/2;
            self.node[x] = (self.acc)(&self.node[x], &val);
        }
    }

    fn sum_inner(&self, pos: usize, x: usize, y: usize, p: usize, q: usize) -> T {
        if x<= p && q <= y {
            return self.node[pos].clone();
        }
        if y <= p || q <= x {
            return self.init.clone();
        }

        let left = pos * 2 + 1;
        let mid = (p + q) / 2;
        let right = pos * 2 + 2;
        (self.acc)(&self.sum_inner(left, x, y, p, mid), &self.sum_inner(right, x, y, mid, q))
    }

    pub fn sum(&self, x: usize, y: usize) -> T {
        self.sum_inner(0, x, y, 0, self.n)
    }
}

fn main() {
    let line: Vec<i64> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let n = line[0] as usize;
    let c = line[1];
    let mut memo = SegTree::new(n, 0i64, |a,b| cmp::max(*a,*b));
    let mut memo2 = SegTree::new(n, 0i64, |a,b| cmp::max(*a,*b));
    let mut xs = Vec::with_capacity(n+2);
    let mut vs = Vec::with_capacity(n+2);
    for i in 0..n {
        let line: Vec<i64> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let x = line[0];
        let v = line[1];
        xs.push(x);
        vs.push(v);
    }

    let mut sum = 0;
    for i in 0..n {
        sum += vs[i];
        memo.add(i, sum - xs[i]);
    }
    sum = 0;
    for i in (0..n).rev() {
        sum += vs[i];
        memo2.add(i, sum - (c- xs[i]));
    }

    let mut ans = cmp::max(memo.sum(0, n), memo2.sum(0, n));

    let mut sum = 0;
    for i in 0..n {
        sum += vs[i];
        let tmp = sum - xs[i] * 2 + memo2.sum(i + 1, n);
        ans = cmp::max(ans, tmp);
    }
    sum = 0;
    for i in (0..n).rev() {
        sum += vs[i];
        let tmp = sum - (c - xs[i]) * 2 + memo.sum(0, i);
        ans = cmp::max(ans, tmp);
    }
    println!("{}", ans);

}

use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect::<String>();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let c: i64 = input();
    let mut x = vec![0i64; n + 2];
    let mut v = vec![0i64; n + 2];
    for i in 1..n + 1 {
        x[i] = input();
        v[i] = input();
    }
    x[n + 1] = c;

    let mut sum_l = vec![0i64; n + 2];
    let mut sum_r = vec![0i64; n + 2];
    let mut temp_l = 0;
    let mut temp_r = 0;
    for i in 1..n + 1 {
        temp_l += v[i] - (x[i] - x[i - 1]);
        sum_l[i] = std::cmp::max(sum_l[i - 1], temp_l);
        temp_r += v[n - i + 1] - (x[n - i + 2] - x[n - i + 1]);
        sum_r[n - i + 1] = std::cmp::max(sum_r[n - i + 2], temp_r);
    }

    let mut ans = 0;
    for i in 0..n + 1 {
        ans = std::cmp::max(ans, sum_l[i] - x[i] + sum_r[i + 1]);
        ans = std::cmp::max(ans, sum_r[i + 1] - (c - x[i + 1]) + sum_l[i]);
    }
    println!("{}", ans);
}

