fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let C = buf_it.next().unwrap().parse::<isize>().unwrap();
    let XV = (0..N).map(|_| 
        (buf_it.next().unwrap().parse::<isize>().unwrap(),
         buf_it.next().unwrap().parse::<isize>().unwrap())
    ).collect::<Vec<_>>();

    let mut R = (0..N).map(|_| 0).collect::<Vec<_>>();
    let mut L = (0..N).map(|_| 0).collect::<Vec<_>>();
    R[0] = XV[0].1 - XV[0].0;
    L[N-1] = XV[N-1].1 - (C - XV[N-1].0);
    let mut ans = max(0,max(R[0],L[N-1]));
    for i in 1..N{
        R[i] = R[i-1] + XV[i].1 - (XV[i].0 - XV[i-1].0);
        let j = N-1-i;
        L[j] = L[j+1] + XV[j].1 - (XV[j+1].0 - XV[j].0);
        ans = max(ans,max(R[i],L[j]));
    }
    for i in 1..N{
        R[i] = max(R[i-1],R[i]);
        let j = N-1-i;
        L[j] = max(L[j+1],L[j]);
    }

    for i in 0..N-1{
        let tmp = R[i] - XV[i].0 + L[i+1];
        ans = max(ans,tmp);
    }
    for i in 0..N-1{
        let j = N-1-i;
        let tmp = L[j] - (C - XV[j].0) + R[j-1];
        ans = max(ans,tmp);
    }
    println!("{}",ans);
}

