fn main() {
    let n: usize;
    let c: isize;
    input!(n, c);
    let mut score_1: Vec<isize> = vec![0];
    let mut score_2: Vec<isize> = vec![0];
    let mut score_3: Vec<isize> = vec![0; n + 1];
    let mut score_4: Vec<isize> = vec![0; n + 1];
    let v: Vec<Vec<isize>> = input_vector2d(n);
    let mut ans = 0;

    for z in 0..n {
        if z == 0 {
            score_1.push(score_1.last().unwrap() - (v[z][0]) + v[z][1]);
        } else {
            score_1.push(score_1.last().unwrap() - (v[z][0] - v[z - 1][0]) + v[z][1]);
        }
        ans = cmp::max(ans, *score_1.last().unwrap());
    }

    for z in 1..n + 1 {
        if z == 1 {
            score_2.push(score_2.last().unwrap() + v[n - z][0] - c + v[n - z][1]);
        } else {
            score_2.push(score_2.last().unwrap() - (v[n - z + 1][0] - v[n - z][0]) + v[n - z][1]);
        }
        ans = cmp::max(ans, *score_2.last().unwrap());
    }

    for z in 1..n + 1 {
        if score_2[score_3[z - 1] as usize] < score_2[z] {
            score_3[z] = z as isize;
        } else {
            score_3[z] = score_3[z - 1];
        }
    }

    for z in 1..n + 1 {
        if score_1[score_4[z - 1] as usize] < score_1[z] {
            score_4[z] = z as isize;
        } else {
            score_4[z] = score_4[z - 1];
        }
    }

    for z in 1..n {
        let ansbuf = score_1[z] - v[z - 1][0] + score_2[score_3[n - z] as usize];
        println!("{}",ansbuf);
        ans = cmp::max(ans, ansbuf);
    }

    for z in 1..n {
        let ansbuf = score_2[z] - c + v[n-z][0] + score_1[score_4[n - z] as usize];
        println!("{}",ansbuf);
        ans = cmp::max(ans, ansbuf);
    }


    println!("{}", ans);
}

