        solve();
    }
}
fn solve() {
    let (N, C) = get!((usize, i64));
    let xv = get!([(i64, i64); N]);

    let mut anti_cummax = Vec::with_capacity(N + 1);
    let mut clock_cummax = Vec::with_capacity(N + 1);
    anti_cummax.push(0);
    clock_cummax.push(0);
    let mut anti_val = 0;
    let mut clock_val = 0;
    for i in 0..N {
        {
            let i = N - 1 - i;
            anti_val += xv[i].1;
            let last = *anti_cummax.last().unwrap();
            let curmax = max(last, anti_val - (C - xv[i].0));
            anti_cummax.push(curmax);
        }
        {
            clock_val += xv[i].1;
            let last = *clock_cummax.last().unwrap();
            let curmax = max(last, clock_val - xv[i].0);
            clock_cummax.push(curmax);
        }
    }
    debug!(clock_cummax);
    debug!(anti_cummax);

    let mut ans = 0;

    chmax!(ans, *clock_cummax.last().unwrap());
    chmax!(ans, *anti_cummax.last().unwrap());

    // clockwise -> anti-clockwise
    let mut val = 0;
    for i in 0..N {
        val += xv[i].1;
        let clockwise_result = val - 2 * xv[i].0;
        debug!(clockwise_result);
        chmax!(ans, clockwise_result + anti_cummax[N - i - 1]);
    }

    let mut val = 0;
    // anti-clockwise -> clockwise
    for i in 0..N {
        let j = N - 1 - i;
        val += xv[j].1;
        let anti_result = val - 2 * (C - xv[j].0);
        debug!(anti_result);
        chmax!(ans, anti_result + clock_cummax[N - i - 1]);
    }

    echo!(ans);
}

