use std::cmp::max;

fn main() {
    let nc: Vec<u64> = read_vec();
    let n = nc[0] as usize;
    let c = nc[1];
    let xv: Vec<Vec<u64>> = read_vec2(n);

    let mut v: Vec<u64> = vec![0; n];
    let mut l: Vec<u64> = vec![0; n];
    let mut r: Vec<u64> = vec![0; n];
    for i in 0..n {
        v[i] = xv[i][1];
        r[i] = xv[i][0];
        l[i] = c - xv[i][0];
    }

    let mut rmax: Vec<u64> = vec![0; n];
    let mut rmax2: Vec<u64> = vec![0; n];
    let mut vsum = v[0];
    rmax[0] = sub(vsum, r[0]);
    rmax2[0] = sub(vsum, 2 * r[0]);
    for i in 1..n {
        vsum += v[i];
        let t = sub(vsum, r[i]);
        rmax[i] = max(t, rmax[i - 1]);
        let t2 = sub(vsum, 2 * r[i]);
        rmax2[i] = max(t2, rmax2[i - 1]);
    }

    let mut lmax: Vec<u64> = vec![0; n];
    let mut lmax2: Vec<u64> = vec![0; n];
    let mut vsum = v[n - 1];
    lmax[n - 1] = sub(vsum, l[n - 1]);
    lmax2[n - 1] = sub(vsum, 2 * l[n - 1]);
    for i in (0..n - 1).rev() {
        vsum += v[i];
        let t = sub(vsum, l[i]);
        lmax[i] = max(t, lmax[i + 1]);
        let t2 = sub(vsum, 2 * l[i]);
        lmax2[i] = max(t2, lmax2[i + 1]);
    }

    let mut rl = 0;
    for i in 0..n - 1 {
        let t = rmax2[i] + lmax[i + 1];
        if t > rl {
            rl = t;
        }
    }

    let mut lr = 0;
    for i in (1..n).rev() {
        let t = lmax2[i] + rmax[i - 1];
        if t > lr {
            lr = t;
        }
    }

    let t1 = max(lr, rl);
    let t2 = max(rmax[n - 1], lmax[0]);
    let ans = max(t1, t2);
    println!("{}", ans);
}

