fn main() {
    let n = parse_word::<usize>();
    let circum = parse_line::<i64>();

    let (pos, cal) = {
        let mut pos = Vec::with_capacity(n);
        let mut cal = Vec::with_capacity(n);

        for _ in 0..n {
            let x = parse_word::<i64>();
            let v = parse_word::<i64>();

            pos.push(x);
            cal.push(v);
        }

        (pos, cal)
    };

    let pos_right = pos.iter().rev().map(|p| circum - p).collect::<Vec<_>>();

    let cal_prefixsum_left = cal.iter()
        .scan(0, |accum, &c| {
            *accum += c;
            Some(*accum)
        })
        .collect::<Vec<_>>();
    let cal_prefixsum_right = cal.iter()
        .rev()
        .scan(0, |accum, &c| {
            *accum += c;
            Some(*accum)
        })
        .collect::<Vec<_>>();

    let mut max_cal = 0;

    for right_i in 0..n {
        let (mut net_cal, right_pos) = if right_i == 0 {
            (0, 0)
        } else {
            let right_pos = circum - pos[n - right_i];
            (cal_prefixsum_right[right_i - 1] - right_pos, right_pos)
        };

        let net_cal_left = cal_prefixsum_left
            .iter()
            .take(n - right_i)
            .zip(pos.iter())
            .map(|(c, p)| c - p - right_pos);
        net_cal += cmp::max(0, net_cal_left.max().unwrap());

        max_cal = cmp::max(max_cal, net_cal);
    }

    for left_i in 0..n {
        let (mut net_cal, left_pos) = if left_i == 0 {
            (0, 0)
        } else {
            let left_pos = pos[left_i - 1];
            (cal_prefixsum_left[left_i - 1] - left_pos, left_pos)
        };

        let net_cal_right = cal_prefixsum_right
            .iter()
            .take(n - left_i)
            .zip(pos_right.iter())
            .map(|(c, p)| c - p - left_pos);
        net_cal += cmp::max(0, net_cal_right.max().unwrap());

        max_cal = cmp::max(max_cal, net_cal);
    }

    println!("{}", max_cal);
}

