fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let c: usize = itr.next().unwrap().parse().unwrap();
    let xv: Vec<(usize, usize)> = (0..n)
        .map(|_| {
            (
                itr.next().unwrap().parse().unwrap(),
                itr.next().unwrap().parse().unwrap(),
            )
        })
        .collect();

    let mut lx = vec![0; n + 1];
    let mut rx = vec![0; n + 1];
    let mut lv = vec![0; n + 1];
    let mut rv = vec![0; n + 1];
    for i in 0..n {
        lv[i + 1] = lv[i] + xv[i].1;
        lx[i + 1] = xv[i].0;
    }
    for i in 0..n {
        rv[i + 1] = rv[i] + xv[n - 1 - i].1;
        rx[i + 1] = c - xv[n - 1 - i].0;
    }

    let mut ans = 0;
    for l in 0..n + 1 {
        for r in 0..n - l {
            let d = min(lx[l], rx[r]);
            let vl = lv[l].saturating_sub(lx[l]);
            let vr = rv[r].saturating_sub(rx[r]);
            ans = max(ans, (vl + vr).saturating_sub(d));
        }
    }

    println!("{}", ans);
}

