fn solve(c: i64, mut xv: Vec<(i64, i64)>) -> i64 {
    use std::cmp::min;

    let n = xv.len();

    let mut av = vec![0; n+1];
    for (i, &(x,v)) in xv.iter().enumerate() {
        av[i+1] = av[i] + v;
    }

    let mut bv = vec![0; n+1];
    for (i, &(x,v)) in xv.iter().rev().enumerate() {
        bv[i+1] = bv[i] + v;
    }


    let mut maxc = 0;

    for a in 0..n+1 {
        let oa = if a == 0 {0} else {
            let (x, _) = xv[a-1];
            x
        };

        for b in 0..(n+1-a) {
            let ob = if b == 0 {0} else{
                let (x, _) = xv[n-b];
                c-x
            };
            let c = av[a] + bv[b] - min(2*oa+ob, 2*ob+oa);
            if maxc < c {
                maxc = c;
            }
        }
    }

    maxc
}

fn main() {
    let (n, c) = parse_line!(usize, i64);

    println!("{}", solve(c, (0..n).map(|_| parse_line!(i64, i64)).collect()));
}

#[test]
fn solve_test() {
    assert_eq!(solve(20, vec![(2,80), (9,120), (16, 1)]), 191);
    assert_eq!(solve(20, vec![(2,80), (9,1), (16, 120)]), 192);
    assert_eq!(solve(100000000000000, vec![(50000000000000, 1)]), 0);
}

