        let s = rv::<i64>();
        (s[0]as usize,s[1])
    };
    let mut xv = Vec::with_capacity(n);
    for _ in 0..n {
        let s = rv::<i64>();
        xv.push((s[0],s[1]));
    }
    let mut cw = vec![0;n+1];
    let mut cwr = vec![0;n+1];
    let mut w = 0;
    for (i,&(x,v)) in xv.iter().enumerate() {
        w+=v;
        cw[i+1] = max(cw[i], w-x);
        cwr[i+1] = max(cwr[i], w-x*2);
    }
    let mut ccw = vec![0;n+1];
    let mut ccwr = vec![0;n+1];
    let mut w = 0;
    for (i,&(x,v)) in xv.iter().enumerate().rev() {
        w+=v;
        ccw[i] = max(ccw[i+1],w-(c-x));
        ccwr[i] = max(ccwr[i+1],w-(c-x)*2);
    }
    let mut t=0;
    for i in 0..n+1 {
        t = max(t, max(cw[i]+ccwr[i],cwr[i]+ccw[i]));
    }
